async function sendBetaClientCrmDeliveryTest(client, baseUrl, body = {}, actor = "operator") {
  if (!client) {
    return { error: "beta_client_not_found", status: 404, message: "Beta client not found." };
  }

  const existingSettings = normalizeCrmDeliverySettings(client.crm_delivery || {}, { crm: client.crm, ownerEmail: client.owner_email });
  const settings = normalizeCrmDeliverySettings(
    {
      ...existingSettings,
      destination_name:
        stringFromBody(body, "destinationName", "destination_name", "crmDestinationName", "crm_destination_name") ||
        existingSettings.destination_name,
      webhook_url:
        stringFromBody(body, "webhookUrl", "webhook_url", "crmDeliveryWebhookUrl", "crm_delivery_webhook_url") ||
        existingSettings.webhook_url ||
        CRM_DELIVERY_WEBHOOK_URL,
      owner_email: stringFromBody(body, "ownerEmail", "owner_email", "crmDeliveryOwner", "crm_delivery_owner") || existingSettings.owner_email,
      notes: stringFromBody(body, "notes", "note", "crmDeliveryNotes", "crm_delivery_notes") || existingSettings.notes
    },
    { crm: client.crm, ownerEmail: client.owner_email }
  );

  if (!settings.enabled && !truthy(body.force || body.forceSend || body.force_send)) {
    return {
      error: "crm_delivery_disabled",
      status: 409,
      message: "CRM delivery is disabled for this beta client."
    };
  }

  const adapter = crmDeliveryAdapterStatus({ crm_delivery: settings });
  const payload = crmDeliveryTestPayload(client, settings, baseUrl, actor);
  const attemptedAt = now();
  const attempt = normalizeCrmDeliveryAttempt({
    id: id("cda"),
    mode: adapter.mode,
    provider: adapter.provider,
    status: "sent",
    response_status: adapter.mode === "dry_run" ? 202 : 0,
    provider_message_id: adapter.mode === "dry_run" ? `dry_run_crm_test_${client.id}` : null,
    dry_run: adapter.mode === "dry_run",
    destination_host: adapter.webhook_host,
    attempted_at: attemptedAt,
    attempted_by: actor
  });

  if (!adapter.configured) {
    attempt.status = "failed";
    attempt.error = "CRM_DELIVERY_WEBHOOK_URL or a client webhook URL is required when CRM_DELIVERY_MODE=webhook.";
  } else if (adapter.mode === "webhook") {
    try {
      const response = await fetch(adapter.webhook_url, {
        method: "POST",
        headers: {
          "content-type": "application/json",
          "x-deal-threads-event": "deal_threads.crm_webhook_test",
          "x-deal-threads-beta-client-id": client.id,
          "x-deal-threads-synthetic": "true",
          ...(CRM_DELIVERY_WEBHOOK_TOKEN ? { authorization: `Bearer ${CRM_DELIVERY_WEBHOOK_TOKEN}` } : {})
        },
        body: JSON.stringify(payload)
      });
      attempt.response_status = response.status;
      const text = await response.text();
      let parsed = null;
      try {
        parsed = text ? JSON.parse(text) : null;
      } catch {
        parsed = null;
      }
      attempt.provider_message_id = parsed?.message_id || parsed?.messageId || parsed?.id || null;
      if (!response.ok) {
        attempt.status = "failed";
        attempt.error = parsed?.error || parsed?.message || text.slice(0, 240) || `Webhook returned HTTP ${response.status}.`;
      }
    } catch (error) {
      attempt.status = "failed";
      attempt.error = error.message;
    }
  }

  const previousTest = normalizeCrmTestDelivery(settings.test_delivery);
  const attempts = [...(previousTest.send_attempts || []), attempt];
  const testDelivery = normalizeCrmTestDelivery({
    status: attempt.status,
    sent_at: attempt.status === "sent" ? attempt.attempted_at : null,
    sent_by: attempt.status === "sent" ? actor : null,
    sent_via: attempt.status === "sent" ? adapter.mode : null,
    provider_message_id: attempt.provider_message_id,
    last_error: attempt.status === "failed" ? attempt.error : null,
    last_attempt_at: attempt.attempted_at,
    response_status: attempt.response_status,
    destination_host: attempt.destination_host,
    payload_version: payload.version,
    send_attempts: attempts
  });

  client.crm_delivery = normalizeCrmDeliverySettings(
    {
      ...settings,
      test_delivery: testDelivery
    },
    { crm: client.crm, ownerEmail: client.owner_email }
  );
  client.updated_at = attemptedAt;
  state.betaClients.set(client.id, client);

  if (testDelivery.status === "sent") {
    markBetaChecklistSystem(client.id, "hubspot_ready", `Synthetic CRM webhook test sent via ${adapter.mode}.`);
    track("crm_delivery_test_sent", { betaClientId: client.id, mode: adapter.mode, actor });
  } else {
    track("crm_delivery_test_failed", { betaClientId: client.id, mode: adapter.mode, actor, error: testDelivery.last_error });
  }

  persistSoon();
  const result = {
    test_delivery: testDelivery,
    payload,
    crm_adapter: adapter,
    beta_client: betaClientDetail(client, baseUrl)
  };
  if (testDelivery.status === "failed") {
    return {
      ...result,
      error: adapter.configured ? "crm_delivery_test_failed" : "crm_delivery_adapter_not_configured",
      status: adapter.configured ? 502 : 503,
      message: testDelivery.last_error
    };
  }
  return result;
}

