function reportEmailAdapterStatus() {
  const mode = REPORT_EMAIL_MODE === "webhook" ? "webhook" : "dry_run";
  let webhookHost = null;
  if (REPORT_EMAIL_WEBHOOK_URL) {
    try {
      webhookHost = new URL(REPORT_EMAIL_WEBHOOK_URL).host;
    } catch {
      webhookHost = "invalid_url";
    }
  }
  return {
    mode,
    provider: mode === "webhook" ? "webhook" : "dry_run",
    configured: mode === "dry_run" || Boolean(REPORT_EMAIL_WEBHOOK_URL),
    transmits_external_email: mode === "webhook" && Boolean(REPORT_EMAIL_WEBHOOK_URL),
    from: REPORT_EMAIL_FROM,
    reply_to: REPORT_EMAIL_REPLY_TO || null,
    webhook_host: webhookHost
  };
}

async function sendEmailAdapterPayload(payload, options = {}) {
  const adapter = reportEmailAdapterStatus();
  const referenceId = options.referenceId || options.attemptId || id("mail");
  const attempt = {
    id: options.attemptId || id("eda"),
    mode: adapter.mode,
    provider: adapter.provider,
    status: "sent",
    response_status: adapter.mode === "dry_run" ? 202 : 0,
    provider_message_id: adapter.mode === "dry_run" ? `dry_run_${referenceId}` : null,
    dry_run: adapter.mode === "dry_run",
    attempted_at: now()
  };

  if (!adapter.configured) {
    attempt.status = "failed";
    attempt.error = "REPORT_EMAIL_WEBHOOK_URL is required when REPORT_EMAIL_MODE=webhook.";
    return {
      error: "report_email_adapter_not_configured",
      status: 503,
      message: attempt.error,
      adapter,
      attempt
    };
  }

  if (adapter.mode === "webhook") {
    try {
      const response = await fetch(REPORT_EMAIL_WEBHOOK_URL, {
        method: "POST",
        headers: {
          "content-type": "application/json",
          ...(REPORT_EMAIL_WEBHOOK_TOKEN ? { authorization: `Bearer ${REPORT_EMAIL_WEBHOOK_TOKEN}` } : {})
        },
        body: JSON.stringify(payload)
      });
      attempt.response_status = response.status;
      const text = await response.text();
      let parsed = null;
      try {
        parsed = text ? JSON.parse(text) : null;
      } catch {
        parsed = null;
      }
      attempt.provider_message_id = parsed?.message_id || parsed?.messageId || parsed?.id || null;
      if (!response.ok) {
        attempt.status = "failed";
        attempt.error = parsed?.error || parsed?.message || text.slice(0, 240) || `Webhook returned HTTP ${response.status}.`;
        return {
          error: "email_delivery_send_failed",
          status: 502,
          message: attempt.error,
          adapter,
          attempt
        };
      }
    } catch (error) {
      attempt.status = "failed";
      attempt.error = error.message;
      return {
        error: "email_delivery_send_failed",
        status: 502,
        message: attempt.error,
        adapter,
        attempt
      };
    }
  }

  return { adapter, attempt };
}

