async function sendLaunchPacket(client, baseUrl, body = {}, actor = "operator") {
  const defaultPacket = betaClientLaunchPacket(client, baseUrl);
  const recipients =
    normalizeOptionalList(body.recipients || body.to || body.launchRecipients || body.launch_recipients) || defaultPacket.recipients || [];

  if (!recipients.length) {
    return {
      error: "launch_packet_recipients_required",
      status: 400,
      message: "Add at least one launch packet recipient before sending."
    };
  }

  const packet = betaClientLaunchPacket(client, baseUrl, recipients);
  const result = await sendEmailAdapterPayload(launchPacketEmailPayload(client, packet), {
    attemptId: id("lpa"),
    referenceId: `launch_packet_${client.id}`
  });
  const attempt = normalizeLaunchPacketSendAttempt({
    ...(result.attempt || {}),
    recipients,
    subject: packet.subject,
    attempted_by: actor
  });
  const existingDelivery = normalizeLaunchPacketDelivery(client.launch_packet_delivery);
  const delivery = normalizeLaunchPacketDelivery({
    ...existingDelivery,
    status: attempt.status === "failed" ? "failed" : "sent",
    recipients,
    subject: packet.subject,
    sent_at: attempt.status === "sent" ? attempt.attempted_at : existingDelivery.sent_at,
    sent_by: attempt.status === "sent" ? actor : existingDelivery.sent_by,
    sent_via: attempt.status === "sent" ? result.adapter?.mode : existingDelivery.sent_via,
    provider_message_id: attempt.status === "sent" ? attempt.provider_message_id : existingDelivery.provider_message_id,
    last_send_error: attempt.status === "failed" ? attempt.error : null,
    last_send_attempt_at: attempt.attempted_at,
    send_attempts: [...existingDelivery.send_attempts, attempt]
  });

  client.launch_packet_delivery = delivery;
  client.updated_at = attempt.attempted_at;
  state.betaClients.set(client.id, client);

  if (attempt.status === "failed") {
    track("launch_packet_send_failed", { betaClientId: client.id, recipients: recipients.length, mode: result.adapter?.mode || attempt.mode, actor });
    persistSoon();
    return {
      error: result.error === "report_email_adapter_not_configured" ? "launch_packet_email_adapter_not_configured" : "launch_packet_send_failed",
      status: result.status || 502,
      message: result.message || attempt.error || "Launch packet send failed.",
      delivery,
      packet,
      email_adapter: result.adapter || reportEmailAdapterStatus()
    };
  }

  markBetaChecklistSystem(
    client.id,
    "install_snippet_sent",
    `Launch packet ${attempt.dry_run ? "dry-run sent" : "sent"} to ${recipients.join(", ")}.`
  );
  track("launch_packet_sent", { betaClientId: client.id, recipients: recipients.length, sentVia: delivery.sent_via, actor });
  persistSoon();
  return { delivery, packet, email_adapter: result.adapter };
}

function shouldQueueRepAlert(lead) {
  return ["high", "medium"].includes(lead.score?.priority) && Boolean(lead.routing?.assigned_owner_email);
}

function repAlertRecipientsForLead(lead) {
  const workflow = ensureLeadWorkflow(lead);
  return normalizeOptionalList(workflow.owner_email || lead.routing?.assigned_owner_email) || [];
}

function repAlertSubject(lead) {
  const priority = humanizeEnum(lead.score?.priority || "lead");
  return `Deal Threads ${priority} lead - ${lead.company?.name || lead.company?.domain || lead.id}`;
}

function repAlertForLead(leadId) {
  return allRepAlertsSorted().find((alert) => alert.lead_id === leadId) || null;
}

function repAlertsForLead(leadId) {
  return allRepAlertsSorted().filter((alert) => alert.lead_id === leadId);
}

function allRepAlertsSorted() {
  return [...state.repAlerts.values()].sort((a, b) => String(b.queued_at || "").localeCompare(String(a.queued_at || "")));
}

function queueRepAlertForLead(lead, actor = "system", options = {}) {
  if (!lead) {
    return { error: "lead_not_found", status: 404, message: "Lead not found." };
  }
  const existing = repAlertForLead(lead.id);
  if (existing && !options.forceNew) return { alert: existing, created: false };

  if (!options.force && !shouldQueueRepAlert(lead)) {
    return {
      error: "rep_alert_not_required",
      status: 409,
      message: "Rep alert is only queued automatically for high or medium priority leads with an assigned owner."
    };
  }

  const recipients = normalizeOptionalList(options.recipients) || repAlertRecipientsForLead(lead);
  if (!recipients.length) {
    return {
      error: "rep_alert_recipients_required",
      status: 400,
      message: "Add an owner or recipient before queueing a rep alert."
    };
  }

  const alert = normalizeRepAlert({
    id: id("alert"),
    lead_id: lead.id,
    beta_client_id: lead.source?.beta_client_id || null,
    status: "queued",
    alert_type: "rep_speed_to_lead",
    channel: "rep_email_alert",
    priority: lead.score?.priority || "medium",
    recipients,
    subject: repAlertSubject(lead),
    queued_by: actor,
    queued_at: now()
  });

  state.repAlerts.set(alert.id, alert);
  track("rep_alert_queued", { alertId: alert.id, leadProfileId: lead.id, priority: alert.priority, recipients: recipients.length, actor });
  persistSoon();
  return { alert, created: true };
}

function repAlertEmailPayload(alert, lead, baseUrl) {
  const brief = buildRepReadyBrief(lead, baseUrl);

  return {
    from: REPORT_EMAIL_FROM,
    reply_to: REPORT_EMAIL_REPLY_TO || undefined,
    to: alert.recipients,
    subject: alert.subject || repAlertSubject(lead),
    text: repReadyBriefMarkdown(brief),
    attachments: [
      {
        filename: `deal-threads-${slugify(lead.company?.name || lead.company?.domain || lead.id)}-rep-brief.md`,
        content_type: "text/markdown; charset=utf-8",
        content: repReadyBriefMarkdown(brief)
      }
    ],
    metadata: {
      alert_id: alert.id,
      alert_type: alert.alert_type,
      lead_profile_id: lead.id,
      beta_client_id: alert.beta_client_id,
      priority: alert.priority,
      queued_at: alert.queued_at,
      profile_url: brief.profile_url,
      brief_version: brief.version
    }
  };
}

async function sendRepAlert(alert, baseUrl, body = {}, actor = "operator") {
  if (alert.status === "sent") {
    return {
      error: "rep_alert_already_sent",
      status: 409,
      message: "This rep alert has already been sent."
    };
  }

  const lead = state.leads.get(alert.lead_id);
  if (!lead) {
    alert.status = "skipped";
    alert.last_send_error = "Lead profile no longer exists.";
    state.repAlerts.set(alert.id, alert);
    persistSoon();
    return {
      error: "lead_not_found",
      status: 404,
      message: "Lead profile no longer exists.",
      alert
    };
  }

  const recipients = normalizeOptionalList(body.recipients || body.to) || alert.recipients || repAlertRecipientsForLead(lead);
  if (!recipients.length) {
    return {
      error: "rep_alert_recipients_required",
      status: 400,
      message: "Add at least one recipient before sending this rep alert.",
      alert
    };
  }

  alert.recipients = recipients;
  alert.subject = stringFromBody(body, "subject") || alert.subject || repAlertSubject(lead);
  const result = await sendEmailAdapterPayload(repAlertEmailPayload(alert, lead, baseUrl), {
    attemptId: id("raa"),
    referenceId: alert.id
  });
  const attempt = normalizeRepAlertAttempt({
    ...(result.attempt || {}),
    recipients,
    subject: alert.subject,
    attempted_by: actor
  });
  alert.send_attempts = [...(alert.send_attempts || []), attempt];
  alert.last_send_attempt_at = attempt.attempted_at;

  if (attempt.status === "failed") {
    alert.status = "failed";
    alert.last_send_error = attempt.error;
    state.repAlerts.set(alert.id, alert);
    track("rep_alert_send_failed", { alertId: alert.id, leadProfileId: lead.id, mode: result.adapter?.mode || attempt.mode, actor });
    persistSoon();
    return {
      error: result.error === "report_email_adapter_not_configured" ? "rep_alert_email_adapter_not_configured" : "rep_alert_send_failed",
      status: result.status || 502,
      message: result.message || attempt.error || "Rep alert send failed.",
      alert,
      email_adapter: result.adapter || reportEmailAdapterStatus()
    };
  }

  alert.status = "sent";
  alert.sent_at = attempt.attempted_at;
  alert.sent_by = actor;
  alert.sent_via = result.adapter?.mode || attempt.mode;
  alert.provider_message_id = attempt.provider_message_id;
  alert.last_send_error = null;
  state.repAlerts.set(alert.id, alert);
  track("rep_alert_sent", { alertId: alert.id, leadProfileId: lead.id, sentVia: alert.sent_via, actor });
  persistSoon();
  return { alert, lead, email_adapter: result.adapter };
}

async function sendLeadRepAlert(lead, baseUrl, body = {}, actor = "operator") {
  const existing = lead ? repAlertForLead(lead.id) : null;
  const queueResult = queueRepAlertForLead(lead, actor, {
    recipients: body.recipients || body.to,
    force: true,
    forceNew: existing?.status === "sent" || truthy(body.forceNew || body.force_new)
  });
  if (queueResult.error) return queueResult;
  return sendRepAlert(queueResult.alert, baseUrl, body, actor);
}

async function sendQueuedRepAlerts(baseUrl, body = {}, actor = "operator") {
  const includeFailed = truthy(body.includeFailed || body.include_failed);
  const limit = Math.max(1, Math.min(50, Number(body.limit || 25)));
  const alerts = allRepAlertsSorted()
    .filter((alert) => alert.status === "queued" || (includeFailed && alert.status === "failed"))
    .sort((a, b) => String(a.queued_at || "").localeCompare(String(b.queued_at || "")))
    .slice(0, limit);
  const results = [];

  for (const alert of alerts) {
    const result = await sendRepAlert(alert, baseUrl, body, actor);
    results.push(result.error ? { alert_id: alert.id, lead_id: alert.lead_id, error: result.error, message: result.message } : repAlertListItem(result.alert));
  }

  return {
    generated_at: now(),
    considered: alerts.length,
    sent: results.filter((item) => item.status === "sent").length,
    errors: results.filter((item) => item.error).length,
    results,
    alerts: repAlertSummary()
  };
}

function repAlertListItem(alert) {
  const lead = state.leads.get(alert.lead_id);
  return {
    id: alert.id,
    lead_id: alert.lead_id,
    beta_client_id: alert.beta_client_id,
    status: alert.status,
    priority: alert.priority,
    recipients: alert.recipients,
    subject: alert.subject,
    queued_at: alert.queued_at,
    sent_at: alert.sent_at,
    sent_via: alert.sent_via,
    provider_message_id: alert.provider_message_id,
    send_attempt_count: alert.send_attempts.length,
    last_send_error: alert.last_send_error,
    lead: lead
      ? {
          company: lead.company?.name || "Unknown company",
          contact: lead.contact?.name || lead.contact?.email || "Unknown visitor",
          email: lead.contact?.email || null,
          owner_email: ensureLeadWorkflow(lead).owner_email,
          score: lead.score,
          profile_url: `/crm/${lead.id}`
        }
      : null
  };
}

function repAlertSummary() {
  const alerts = allRepAlertsSorted();
  return {
    generated_at: now(),
    count: alerts.length,
    email_adapter: reportEmailAdapterStatus(),
    summary: {
      queued: alerts.filter((alert) => alert.status === "queued").length,
      failed: alerts.filter((alert) => alert.status === "failed").length,
      sent: alerts.filter((alert) => alert.status === "sent").length,
      skipped: alerts.filter((alert) => alert.status === "skipped").length
    },
    alerts: alerts.map(repAlertListItem)
  };
}

function reportDeliverySummary() {
  const deliveries = [...state.reportDeliveries.values()].sort((a, b) => b.generated_at.localeCompare(a.generated_at));
  return {
    generated_at: now(),
    count: deliveries.length,
    email_adapter: reportEmailAdapterStatus(),
    summary: {
      queued: deliveries.filter((delivery) => delivery.status === "queued").length,
      failed: deliveries.filter((delivery) => delivery.status === "failed").length,
      sent: deliveries.filter((delivery) => delivery.status === "sent").length,
      skipped: deliveries.filter((delivery) => delivery.status === "skipped").length
    },
    due_clients: betaClientList("").filter((client) => client.report_due).map((client) => ({
      id: client.id,
      name: client.name,
      next_due_at: client.report_settings.next_due_at,
      recipients: client.report_settings.recipients
    })),
    deliveries: deliveries.map(reportDeliveryListItem)
  };
}

function createReportDeliveryForClient(client, body = {}, actor = "operator") {
  const days = parseReportDays(body.days || body.reportPeriodDays || body.report_period_days || client.report_settings?.period_days || 14);
  const recipients = normalizeOptionalList(body.recipients || body.reportRecipients || body.report_recipients) || client.report_settings?.recipients || [];
  if (!recipients.length) {
    return {
      error: "report_recipients_required",
      status: 400,
      message: "Add at least one report recipient before queueing a beta report."
    };
  }

  const params = new URLSearchParams({ days: String(days) });
  const report = buildBetaReport(params, { betaClientId: client.id });
  const generatedAt = now();
  const delivery = normalizeReportDelivery({
    id: id("del"),
    beta_client_id: client.id,
    beta_client_name: client.name,
    domain: client.domain,
    status: "queued",
    channel: "manual_email_queue",
    recipients,
    subject: `Deal Threads beta report - ${client.name} - ${report.period.days}d`,
    period: report.period,
    summary: {
      total_leads: report.summary.total,
      high_priority: report.summary.by_priority.high,
      overdue: report.summary.by_sla.overdue,
      meetings_booked: report.summary.conversion.meeting_booked,
      opportunities_created: report.summary.conversion.opportunities_created,
      closed_won: report.summary.conversion.closed_won,
      opportunity_value: report.summary.pipeline.opportunity_value,
      expected_value: report.summary.pipeline.expected_value,
      closed_won_value: report.summary.pipeline.closed_won_value,
      paid_provider_spend: report.enrichment.estimated_paid_provider_spend
    },
    markdown: betaReportMarkdown(report),
    csv: reportCsv(report),
    queued_by: actor,
    generated_at: generatedAt,
    queued_at: generatedAt
  });

  state.reportDeliveries.set(delivery.id, delivery);
  client.report_settings = {
    ...client.report_settings,
    recipients,
    period_days: days,
    last_delivery_id: delivery.id,
    last_queued_at: generatedAt,
    next_due_at: client.report_settings?.cadence === "weekly" ? nextReportDueAt(generatedAt) : client.report_settings?.next_due_at || null
  };
  client.updated_at = generatedAt;
  state.betaClients.set(client.id, client);
  track("report_delivery_queued", { deliveryId: delivery.id, betaClientId: client.id, recipients: recipients.length, actor });
  persistSoon();
  return { delivery, report };
}

function runDueReportDeliveries(actor = "operator") {
  const nowMs = Date.now();
  const results = [];
  for (const client of state.betaClients.values()) {
    const settings = client.report_settings || normalizeReportSettings({}, { ownerEmail: client.owner_email, createdAt: client.created_at });
    if (settings.cadence !== "weekly") continue;
    const dueAt = new Date(settings.next_due_at).getTime();
    if (Number.isNaN(dueAt) || dueAt > nowMs) continue;
    const result = createReportDeliveryForClient(client, {}, actor);
    results.push(result.error ? { beta_client_id: client.id, error: result.error, message: result.message } : reportDeliveryListItem(result.delivery));
  }
  return {
    generated_at: now(),
    queued: results.filter((item) => item.id).length,
    errors: results.filter((item) => item.error).length,
    results,
    deliveries: reportDeliverySummary()
  };
}

async function sendReportDelivery(delivery, body = {}, actor = "operator") {
  if (delivery.status === "sent") {
    return {
      error: "report_delivery_already_sent",
      status: 409,
      message: "This report delivery has already been sent."
    };
  }
  if (!delivery.recipients.length) {
    return {
      error: "report_recipients_required",
      status: 400,
      message: "Add at least one recipient before sending this report delivery."
    };
  }

  const adapter = reportEmailAdapterStatus();
  const attemptedAt = now();
  const attempt = normalizeReportSendAttempt({
    id: id("rda"),
    mode: adapter.mode,
    provider: adapter.provider,
    status: "sent",
    response_status: adapter.mode === "dry_run" ? 202 : 0,
    provider_message_id: adapter.mode === "dry_run" ? `dry_run_${delivery.id}` : null,
    dry_run: adapter.mode === "dry_run",
    attempted_at: attemptedAt
  });

  if (!adapter.configured) {
    attempt.status = "failed";
    attempt.error = "REPORT_EMAIL_WEBHOOK_URL is required when REPORT_EMAIL_MODE=webhook.";
    appendReportDeliveryAttempt(delivery, attempt);
    delivery.status = "failed";
    delivery.last_send_error = attempt.error;
    state.reportDeliveries.set(delivery.id, delivery);
    track("report_delivery_send_failed", { deliveryId: delivery.id, betaClientId: delivery.beta_client_id, mode: adapter.mode, actor });
    persistSoon();
    return {
      error: "report_email_adapter_not_configured",
      status: 503,
      message: attempt.error,
      delivery
    };
  }

  if (adapter.mode === "webhook") {
    const payload = reportDeliveryEmailPayload(delivery);
    try {
      const response = await fetch(REPORT_EMAIL_WEBHOOK_URL, {
        method: "POST",
        headers: {
          "content-type": "application/json",
          ...(REPORT_EMAIL_WEBHOOK_TOKEN ? { authorization: `Bearer ${REPORT_EMAIL_WEBHOOK_TOKEN}` } : {})
        },
        body: JSON.stringify(payload)
      });
      attempt.response_status = response.status;
      const text = await response.text();
      let parsed = null;
      try {
        parsed = text ? JSON.parse(text) : null;
      } catch {
        parsed = null;
      }
      attempt.provider_message_id = parsed?.message_id || parsed?.messageId || parsed?.id || null;
      if (!response.ok) {
        attempt.status = "failed";
        attempt.error = parsed?.error || parsed?.message || text.slice(0, 240) || `Webhook returned HTTP ${response.status}.`;
        appendReportDeliveryAttempt(delivery, attempt);
        delivery.status = "failed";
        delivery.last_send_error = attempt.error;
        state.reportDeliveries.set(delivery.id, delivery);
        track("report_delivery_send_failed", {
          deliveryId: delivery.id,
          betaClientId: delivery.beta_client_id,
          mode: adapter.mode,
          responseStatus: response.status,
          actor
        });
        persistSoon();
        return {
          error: "report_delivery_send_failed",
          status: 502,
          message: attempt.error,
          delivery
        };
      }
    } catch (error) {
      attempt.status = "failed";
      attempt.error = error.message;
      appendReportDeliveryAttempt(delivery, attempt);
      delivery.status = "failed";
      delivery.last_send_error = attempt.error;
      state.reportDeliveries.set(delivery.id, delivery);
      track("report_delivery_send_failed", { deliveryId: delivery.id, betaClientId: delivery.beta_client_id, mode: adapter.mode, actor });
      persistSoon();
      return {
        error: "report_delivery_send_failed",
        status: 502,
        message: attempt.error,
        delivery
      };
    }
  }

  appendReportDeliveryAttempt(delivery, attempt);
  return markReportDeliverySent(delivery, body, actor, {
    sentVia: adapter.mode,
    providerMessageId: attempt.provider_message_id,
    note: adapter.mode === "dry_run" ? "Dry-run send completed. No external email was transmitted." : ""
  });
}

async function sendQueuedReportDeliveries(body = {}, actor = "operator") {
  const includeFailed = truthy(body.includeFailed || body.include_failed);
  const deliveries = [...state.reportDeliveries.values()]
    .filter((delivery) => delivery.status === "queued" || (includeFailed && delivery.status === "failed"))
    .sort((a, b) => a.queued_at.localeCompare(b.queued_at));
  const results = [];
  for (const delivery of deliveries) {
    const result = await sendReportDelivery(delivery, body, actor);
    results.push(result.error ? { delivery_id: delivery.id, error: result.error, message: result.message } : reportDeliveryListItem(result));
  }
  return {
    generated_at: now(),
    sent: results.filter((item) => item.status === "sent").length,
    errors: results.filter((item) => item.error).length,
    results,
    deliveries: reportDeliverySummary()
  };
}

function appendReportDeliveryAttempt(delivery, attempt) {
  delivery.send_attempts = [...(delivery.send_attempts || []), normalizeReportSendAttempt(attempt)];
  delivery.last_send_attempt_at = attempt.attempted_at;
}

function markReportDeliverySent(delivery, body = {}, actor = "operator", options = {}) {
  delivery.status = "sent";
  delivery.sent_at = now();
  delivery.sent_by = actor;
  delivery.sent_via = options.sentVia || delivery.sent_via || "manual";
  delivery.provider_message_id = options.providerMessageId || delivery.provider_message_id || null;
  delivery.last_send_error = null;
  const note = stringFromBody(body, "notes", "note") || options.note || "";
  delivery.notes = note || delivery.notes;
  state.reportDeliveries.set(delivery.id, delivery);
  const client = state.betaClients.get(delivery.beta_client_id);
  if (client) {
    client.report_settings = {
      ...client.report_settings,
      last_sent_at: delivery.sent_at,
      last_delivery_id: delivery.id
    };
    state.betaClients.set(client.id, client);
    markBetaChecklistSystem(client.id, "first_report_sent", `Report delivery ${delivery.id} was marked sent.`);
  }
  track("report_delivery_sent", { deliveryId: delivery.id, betaClientId: delivery.beta_client_id, actor, sentVia: delivery.sent_via });
  persistSoon();
  return delivery;
}

function parseReportDays(value) {
  const days = Number(value || 14);
  return Number.isFinite(days) ? Math.max(1, Math.min(90, Math.round(days))) : 14;
}

function truthy(value) {
  return ["1", "true", "yes", "on"].includes(String(value || "").toLowerCase());
}

function betaClientEffectiveWidgetConfig(client) {
  const config = structuredClone(widgetConfig);
  if (!client) return config;

  config.betaClientId = client.id;
  config.tenant = {
    ...config.tenant,
    name: client.name || config.tenant.name,
    betaClient: {
      id: client.id,
      name: client.name,
      domain: client.domain,
      status: client.status
    }
  };
  config.version = `${widgetConfig.version}:${client.updated_at}`;

  if (client.widget_config.launcherText) config.conversation.launcherText = client.widget_config.launcherText;
  if (client.widget_config.welcomeMessage) config.conversation.welcomeMessage = client.widget_config.welcomeMessage;
  if (client.widget_config.quickReplies?.length) config.conversation.quickReplies = client.widget_config.quickReplies;
  if (client.widget_config.requiredFields?.length) config.conversation.requiredFields = client.widget_config.requiredFields;
  if (client.widget_config.questions?.length) {
    config.conversation.questions = client.widget_config.questions;
    if (!client.widget_config.requiredFields?.length) {
      config.conversation.requiredFields = requiredFieldsFromQuestions(client.widget_config.questions);
    }
  }
  if (client.widget_config.primaryColor) config.theme.primaryColor = client.widget_config.primaryColor;
  config.conversation.questions = normalizeConversationQuestions(config.conversation.questions);

  return config;
}

function routingForBetaClient(betaClientId) {
  const client = betaClientId ? state.betaClients.get(betaClientId) : null;
  const overrides = client?.routing_overrides || {};
  return {
    ...routingConfig,
    highPriorityOwner: overrides.highPriorityOwner || routingConfig.highPriorityOwner,
    mediumPriorityOwner: overrides.mediumPriorityOwner || routingConfig.mediumPriorityOwner,
    highPriorityAction: overrides.highPriorityAction || routingConfig.highPriorityAction,
    mediumPriorityAction: overrides.mediumPriorityAction || routingConfig.mediumPriorityAction,
    lowPriorityAction: overrides.lowPriorityAction || routingConfig.lowPriorityAction
  };
}

function ensureLeadWorkflow(lead) {
  const fallback = defaultLeadWorkflow(lead);
  const current = lead.workflow || {};
  lead.workflow = {
    ...fallback,
    ...current,
    notes: Array.isArray(current.notes) ? current.notes : fallback.notes,
    activity: Array.isArray(current.activity) && current.activity.length ? current.activity : fallback.activity
  };

  if (!LEAD_STAGE_LABELS[lead.workflow.stage]) lead.workflow.stage = fallback.stage;
  if (!lead.workflow.owner_email && lead.routing?.assigned_owner_email) lead.workflow.owner_email = lead.routing.assigned_owner_email;
  if (!lead.workflow.next_action) lead.workflow.next_action = lead.routing?.recommended_next_action || fallback.next_action;
  return lead.workflow;
}

function ensureLeadOutcome(lead) {
  const workflow = ensureLeadWorkflow(lead);
  const fallback = defaultLeadOutcome(lead);
  const current = lead.outcome || {};
  const status = LEAD_OUTCOME_STATUSES.includes(current.status) ? current.status : outcomeStatusFromWorkflowStage(workflow.stage);
  const value = Number(current.value ?? current.amount ?? current.deal_value ?? fallback.value);

  lead.outcome = {
    ...fallback,
    ...current,
    status,
    value: Number.isFinite(value) ? Math.max(0, value) : 0,
    probability: normalizeOutcomeProbability(current.probability ?? fallback.probability),
    currency: optionalString(current.currency) || "USD",
    source: optionalString(current.source) || "workflow",
    notes: Array.isArray(current.notes) ? current.notes : fallback.notes,
    updated_at: current.updated_at || workflow.last_activity_at || lead.updated_at || lead.created_at || now()
  };

  applyWorkflowToOutcome(lead, workflow, { preserveManualStatus: Boolean(current.status) });
  return lead.outcome;
}

function ensureRepFeedback(lead) {
  lead.rep_feedback = normalizeRepFeedback(lead.rep_feedback || lead.repFeedback || {}, lead);
  return lead.rep_feedback;
}

function normalizeRepFeedback(feedback = {}, lead = {}) {
  const createdAt = lead.created_at || now();
  const status = REP_FEEDBACK_LABELS[feedback.status] ? feedback.status : "not_reviewed";
  const confidence = REP_CONFIDENCE_LABELS[feedback.rep_confidence] ? feedback.rep_confidence : REP_CONFIDENCE_LABELS[feedback.repConfidence] ? feedback.repConfidence : "unknown";
  const usefulnessScore = normalizeRepUsefulnessScore(firstDefined(feedback, "usefulness_score", "usefulnessScore"));
  const missingFields = normalizeRepFeedbackMissingFields(firstDefined(feedback, "missing_fields", "missingFields"));
  const history = Array.isArray(feedback.history) ? feedback.history.map(normalizeRepFeedbackHistoryEntry).filter(Boolean).slice(0, 20) : [];
  return {
    status,
    status_label: REP_FEEDBACK_LABELS[status],
    usefulness_score: usefulnessScore,
    rep_confidence: confidence,
    rep_confidence_label: REP_CONFIDENCE_LABELS[confidence],
    used_on_call: Boolean(firstDefined(feedback, "used_on_call", "usedOnCall")),
    missing_fields: missingFields,
    missing_field_labels: missingFields.map((field) => REP_FEEDBACK_MISSING_FIELD_LABELS[field] || humanizeEnum(field)),
    missing_context_note: optionalString(firstDefined(feedback, "missing_context_note", "missingContextNote")),
    last_note: optionalString(firstDefined(feedback, "last_note", "lastNote")),
    reviewed_by: optionalString(firstDefined(feedback, "reviewed_by", "reviewedBy")),
    reviewed_at: optionalString(firstDefined(feedback, "reviewed_at", "reviewedAt")),
    updated_at: optionalString(firstDefined(feedback, "updated_at", "updatedAt")) || createdAt,
    history
  };
}

function normalizeRepFeedbackHistoryEntry(entry = {}) {
  if (!entry || typeof entry !== "object") return null;
  const status = REP_FEEDBACK_LABELS[entry.status] ? entry.status : "not_reviewed";
  return {
    id: optionalString(entry.id) || id("rfb"),
    status,
    usefulness_score: normalizeRepUsefulnessScore(firstDefined(entry, "usefulness_score", "usefulnessScore")),
    rep_confidence: REP_CONFIDENCE_LABELS[entry.rep_confidence] ? entry.rep_confidence : REP_CONFIDENCE_LABELS[entry.repConfidence] ? entry.repConfidence : "unknown",
    used_on_call: Boolean(firstDefined(entry, "used_on_call", "usedOnCall")),
    missing_fields: normalizeRepFeedbackMissingFields(firstDefined(entry, "missing_fields", "missingFields")),
    note: optionalString(entry.note || entry.body),
    actor: optionalString(entry.actor || entry.created_by || entry.createdBy) || "operator",
    created_at: optionalString(firstDefined(entry, "created_at", "createdAt")) || now()
  };
}

function normalizeRepUsefulnessScore(value) {
  if (value === null || value === undefined || String(value).trim() === "") return null;
  const number = Number(value);
  if (!Number.isFinite(number)) return null;
  return roundNumber(Math.max(0, Math.min(5, number)), 1);
}

function normalizeRepFeedbackMissingFields(value) {
  const allowed = new Set(REP_FEEDBACK_MISSING_FIELDS.map(([key]) => key));
  const values = Array.isArray(value) ? value : parseList(value);
  const normalized = values
    .map((item) => String(item || "").trim().toLowerCase().replace(/[^a-z0-9]+/g, "_").replace(/^_+|_+$/g, ""))
    .filter((item) => item && allowed.has(item));
  return [...new Set(normalized)];
}

function defaultLeadOutcome(lead) {
  const workflow = lead.workflow || defaultLeadWorkflow(lead);
  const status = outcomeStatusFromWorkflowStage(workflow.stage);
  return {
    status,
    first_contacted_at: null,
    meeting_booked_at: null,
    opportunity_created_at: null,
    closed_at: null,
    value: 0,
    currency: "USD",
    probability: defaultOutcomeProbability(status),
    source: "workflow",
    notes: [],
    updated_at: lead.updated_at || workflow.last_activity_at || lead.created_at || now()
  };
}

function normalizeOutcomeProbability(value) {
  const number = Number(value);
  if (!Number.isFinite(number)) return 0;
  return Math.max(0, Math.min(1, number > 1 ? number / 100 : number));
}

function defaultOutcomeProbability(status) {
  if (status === "closed_won") return 1;
  if (status === "closed_lost" || status === "disqualified") return 0;
  if (status === "opportunity_created") return 0.35;
  if (status === "meeting_booked") return 0.2;
  if (status === "contacted") return 0.1;
  return 0;
}

function outcomeStatusFromWorkflowStage(stage) {
  if (stage === "closed_won") return "closed_won";
  if (stage === "closed_lost") return "closed_lost";
  if (stage === "disqualified") return "disqualified";
  if (stage === "meeting_booked") return "meeting_booked";
  if (stage === "contacted") return "contacted";
  if (stage === "nurture") return "nurture";
  return "unworked";
}

function applyWorkflowToOutcome(lead, workflow = ensureLeadWorkflow(lead), options = {}) {
  const outcome = lead.outcome || defaultLeadOutcome(lead);
  const nowIso = workflow.last_activity_at || now();
  const stageOutcome = outcomeStatusFromWorkflowStage(workflow.stage);

  if (!options.preserveManualStatus || !outcome.status || outcome.status === "unworked") {
    outcome.status = stageOutcome;
  }

  if (["contacted", "meeting_booked", "closed_won", "closed_lost"].includes(workflow.stage) && !outcome.first_contacted_at) {
    outcome.first_contacted_at = nowIso;
  }
  if (["meeting_booked", "closed_won", "closed_lost"].includes(workflow.stage) && !outcome.meeting_booked_at) {
    outcome.meeting_booked_at = nowIso;
  }
  if (["contacted", "meeting_booked", "opportunity_created", "closed_won", "closed_lost"].includes(outcome.status) && !outcome.first_contacted_at) {
    outcome.first_contacted_at = nowIso;
  }
  if (["opportunity_created", "closed_won", "closed_lost"].includes(outcome.status) && !outcome.opportunity_created_at) {
    outcome.opportunity_created_at = nowIso;
  }
  if ((["closed_won", "closed_lost", "disqualified"].includes(workflow.stage) || ["closed_won", "closed_lost", "disqualified"].includes(outcome.status)) && !outcome.closed_at) {
    outcome.closed_at = workflow.completed_at || nowIso;
  }
  if (outcome.probability === null || outcome.probability === undefined || outcome.source === "workflow") {
    outcome.probability = defaultOutcomeProbability(outcome.status);
  }
  outcome.source = outcome.source || "workflow";
  outcome.updated_at = nowIso;
  lead.outcome = outcome;
  return outcome;
}

function defaultLeadWorkflow(lead) {
  const priority = lead.score?.priority || "medium";
  const stage = priority === "low" || lead.status === "low_priority" ? "nurture" : "new";
  const createdAt = lead.created_at || now();
  return {
    stage,
    owner_email: lead.routing?.assigned_owner_email || "",
    due_at: calculateWorkflowDueAt(priority, createdAt),
    next_action: lead.routing?.recommended_next_action || "Review this lead profile before follow-up.",
    last_activity_at: createdAt,
    completed_at: null,
    notes: [],
    activity: [
      {
        id: lead.id ? `act_${lead.id}_created` : id("act"),
        type: "created",
        actor: "system",
        message: `Lead created as ${priority} priority.`,
        created_at: createdAt
      }
    ]
  };
}

function calculateWorkflowDueAt(priority, fromIso = now()) {
  const dueMinutes = priority === "high" ? 15 : priority === "medium" ? 240 : 2880;
  return new Date(new Date(fromIso).getTime() + dueMinutes * 60 * 1000).toISOString();
}

function updateLeadWorkflow(lead, body, actor = "operator") {
  const outcome = ensureLeadOutcome(lead);
  const workflow = ensureLeadWorkflow(lead);
  const changes = [];
  const stage = stringFromBody(body, "stage");
  const ownerEmail = stringFromBody(body, "ownerEmail", "owner_email");
  const nextAction = stringFromBody(body, "nextAction", "next_action");
  const dueAt = stringFromBody(body, "dueAt", "due_at");
  const outcomeStatus = stringFromBody(body, "outcomeStatus", "outcome_status");
  const firstContactedAt = stringFromBody(body, "firstContactedAt", "first_contacted_at");
  const meetingBookedAt = stringFromBody(body, "meetingBookedAt", "meeting_booked_at");
  const opportunityCreatedAt = stringFromBody(body, "opportunityCreatedAt", "opportunity_created_at");
  const closedAt = stringFromBody(body, "closedAt", "closed_at");
  const outcomeValue = stringFromBody(body, "outcomeValue", "outcome_value", "dealValue", "deal_value", "value");
  const outcomeProbability = stringFromBody(body, "outcomeProbability", "outcome_probability", "probability");
  const note = stringFromBody(body, "note");

  if (stage && !LEAD_STAGE_LABELS[stage]) {
    return {
      error: "invalid_stage",
      status: 400,
      message: `Stage must be one of: ${LEAD_WORKFLOW_STAGES.join(", ")}`
    };
  }

  if (dueAt && Number.isNaN(new Date(dueAt).getTime())) {
    return {
      error: "invalid_due_at",
      status: 400,
      message: "Due date must be an ISO date or datetime-local value."
    };
  }

  if (outcomeStatus && !LEAD_OUTCOME_LABELS[outcomeStatus]) {
    return {
      error: "invalid_outcome_status",
      status: 400,
      message: `Outcome status must be one of: ${LEAD_OUTCOME_STATUSES.join(", ")}`
    };
  }

  for (const [field, value] of [
    ["first_contacted_at", firstContactedAt],
    ["meeting_booked_at", meetingBookedAt],
    ["opportunity_created_at", opportunityCreatedAt],
    ["closed_at", closedAt]
  ]) {
    if (value && Number.isNaN(new Date(value).getTime())) {
      return {
        error: `invalid_${field}`,
        status: 400,
        message: `${humanizeEnum(field)} must be an ISO date or datetime-local value.`
      };
    }
  }

  if (stage && stage !== workflow.stage) {
    changes.push(`Stage changed from ${LEAD_STAGE_LABELS[workflow.stage]} to ${LEAD_STAGE_LABELS[stage]}`);
    workflow.stage = stage;
    lead.status = leadStatusFromWorkflowStage(stage, lead.status);
    workflow.completed_at = isTerminalWorkflowStage(stage) ? now() : null;
  }

  if (ownerEmail && ownerEmail !== workflow.owner_email) {
    changes.push(`Owner changed to ${ownerEmail}`);
    workflow.owner_email = ownerEmail;
  }

  if (nextAction && nextAction !== workflow.next_action) {
    changes.push("Next action updated");
    workflow.next_action = nextAction;
  }

  if (dueAt) {
    const normalizedDueAt = new Date(dueAt).toISOString();
    if (normalizedDueAt !== workflow.due_at) {
      changes.push(`SLA due time changed to ${formatDateTime(normalizedDueAt)}`);
      workflow.due_at = normalizedDueAt;
    }
  }

  if (outcomeStatus && outcomeStatus !== outcome.status) {
    changes.push(`Outcome changed from ${LEAD_OUTCOME_LABELS[outcome.status] || humanizeEnum(outcome.status)} to ${LEAD_OUTCOME_LABELS[outcomeStatus]}`);
    outcome.status = outcomeStatus;
    outcome.source = "operator";
    outcome.probability = defaultOutcomeProbability(outcomeStatus);
  }

  for (const [field, value, label] of [
    ["first_contacted_at", firstContactedAt, "First contact time"],
    ["meeting_booked_at", meetingBookedAt, "Meeting booked time"],
    ["opportunity_created_at", opportunityCreatedAt, "Opportunity created time"],
    ["closed_at", closedAt, "Closed time"]
  ]) {
    if (!value) continue;
    const normalizedValue = new Date(value).toISOString();
    if (normalizedValue !== outcome[field]) {
      outcome[field] = normalizedValue;
      outcome.source = "operator";
      changes.push(`${label} updated`);
    }
  }

  if (outcomeValue) {
    const parsedValue = positiveNumber(outcomeValue, outcome.value || 0);
    if (parsedValue !== outcome.value) {
      outcome.value = parsedValue;
      outcome.source = "operator";
      changes.push(`Outcome value updated to $${parsedValue.toFixed(2)}`);
    }
  }

  if (outcomeProbability) {
    const parsedProbability = normalizeOutcomeProbability(outcomeProbability);
    if (parsedProbability !== outcome.probability) {
      outcome.probability = parsedProbability;
      outcome.source = "operator";
      changes.push(`Outcome probability updated to ${Math.round(parsedProbability * 100)}%`);
    }
  }

  if (note) {
    workflow.notes.unshift({
      id: id("note"),
      body: note.slice(0, 1200),
      actor,
      stage: workflow.stage,
      created_at: now()
    });
    changes.push("Note added");
  }

  if (!changes.length) return { workflow, outcome, changed: false };

  workflow.last_activity_at = now();
  applyWorkflowToOutcome(lead, workflow, { preserveManualStatus: outcome.source === "operator" });
  if (note) {
    outcome.notes.unshift({
      id: id("out"),
      body: note.slice(0, 1200),
      actor,
      status: outcome.status,
      created_at: workflow.last_activity_at
    });
    outcome.notes = outcome.notes.slice(0, 20);
  }
  workflow.activity.unshift({
    id: id("act"),
    type: "workflow_update",
    actor,
    message: changes.join("; "),
    stage: workflow.stage,
    created_at: workflow.last_activity_at
  });
  lead.updated_at = workflow.last_activity_at;
  rememberCompanyFromLead(lead);
  track("lead_workflow_updated", { leadProfileId: lead.id, stage: workflow.stage, outcomeStatus: outcome.status, outcomeValue: outcome.value, actor, changes });
  persistSoon();

  return { workflow, outcome, changed: true };
}

function updateRepFeedback(lead, body, actor = "operator") {
  const feedback = ensureRepFeedback(lead);
  const requestedStatus = stringFromBody(body, "status", "feedbackStatus", "feedback_status") || feedback.status;
  const confidence = stringFromBody(body, "repConfidence", "rep_confidence", "confidence") || feedback.rep_confidence;
  const note = stringFromBody(body, "missingContextNote", "missing_context_note", "feedbackNote", "note");
  const usefulnessRaw = firstDefined(body, "usefulnessScore", "usefulness_score");
  const usedOnCallRaw = firstDefined(body, "usedOnCall", "used_on_call");
  const missingFieldsRaw = firstDefined(body, "missingFields", "missing_fields");
  const checkboxMissingFields = REP_FEEDBACK_MISSING_FIELDS.filter(([key]) => booleanFromBody(body, `missingField_${key}`)).map(([key]) => key);
  const hasMissingFieldControl =
    missingFieldsRaw !== undefined || REP_FEEDBACK_MISSING_FIELDS.some(([key]) => body?.[`missingField_${key}`] !== undefined);
  const normalizedMissingFields = hasMissingFieldControl
    ? [...new Set([...normalizeRepFeedbackMissingFields(missingFieldsRaw), ...checkboxMissingFields])]
    : feedback.missing_fields;
  const changes = [];

  if (!REP_FEEDBACK_LABELS[requestedStatus]) {
    return {
      error: "invalid_feedback_status",
      status: 400,
      message: `Feedback status must be one of: ${REP_FEEDBACK_STATUSES.join(", ")}`
    };
  }

  if (!REP_CONFIDENCE_LABELS[confidence]) {
    return {
      error: "invalid_rep_confidence",
      status: 400,
      message: `Rep confidence must be one of: ${REP_CONFIDENCE_LEVELS.join(", ")}`
    };
  }

  let usefulnessScore = feedback.usefulness_score;
  if (usefulnessRaw !== undefined && String(usefulnessRaw).trim() !== "") {
    const parsedScore = Number(usefulnessRaw);
    if (!Number.isFinite(parsedScore) || parsedScore < 0 || parsedScore > 5) {
      return {
        error: "invalid_usefulness_score",
        status: 400,
        message: "Usefulness score must be a number from 0 to 5."
      };
    }
    usefulnessScore = normalizeRepUsefulnessScore(parsedScore);
  }

  const usedOnCall = usedOnCallRaw === undefined ? feedback.used_on_call : booleanFromBody(body, "usedOnCall") || booleanFromBody(body, "used_on_call");

  if (requestedStatus !== feedback.status) {
    changes.push(`Feedback changed from ${REP_FEEDBACK_LABELS[feedback.status]} to ${REP_FEEDBACK_LABELS[requestedStatus]}`);
    feedback.status = requestedStatus;
    feedback.status_label = REP_FEEDBACK_LABELS[requestedStatus];
  }

  if (usefulnessScore !== feedback.usefulness_score) {
    changes.push(`Usefulness scored ${usefulnessScore}/5`);
    feedback.usefulness_score = usefulnessScore;
  }

  if (confidence !== feedback.rep_confidence) {
    changes.push(`Rep confidence changed to ${REP_CONFIDENCE_LABELS[confidence]}`);
    feedback.rep_confidence = confidence;
    feedback.rep_confidence_label = REP_CONFIDENCE_LABELS[confidence];
  }

  if (usedOnCall !== feedback.used_on_call) {
    changes.push(usedOnCall ? "Marked used on call" : "Marked not used on call");
    feedback.used_on_call = usedOnCall;
  }

  const missingChanged = normalizedMissingFields.join("|") !== feedback.missing_fields.join("|");
  if (missingChanged) {
    feedback.missing_fields = normalizedMissingFields;
    feedback.missing_field_labels = normalizedMissingFields.map((field) => REP_FEEDBACK_MISSING_FIELD_LABELS[field] || humanizeEnum(field));
    changes.push(
      normalizedMissingFields.length
        ? `Missing context fields updated: ${feedback.missing_field_labels.join(", ")}`
        : "Missing context fields cleared"
    );
  }

  if (note) {
    feedback.missing_context_note = note.slice(0, 1200);
    feedback.last_note = feedback.missing_context_note;
    changes.push("Feedback note added");
  }

  if (!changes.length) return { feedback, changed: false };

  feedback.updated_at = now();
  feedback.reviewed_by = actor;
  feedback.reviewed_at = feedback.updated_at;
  feedback.history.unshift({
    id: id("rfb"),
    status: feedback.status,
    usefulness_score: feedback.usefulness_score,
    rep_confidence: feedback.rep_confidence,
    used_on_call: feedback.used_on_call,
    missing_fields: [...feedback.missing_fields],
    note: note ? note.slice(0, 1200) : null,
    actor,
    created_at: feedback.updated_at
  });
  feedback.history = feedback.history.slice(0, 20);

  const workflow = ensureLeadWorkflow(lead);
  workflow.last_activity_at = feedback.updated_at;
  workflow.activity.unshift({
    id: id("act"),
    type: "rep_feedback",
    actor,
    message: `Rep feedback: ${REP_FEEDBACK_LABELS[feedback.status]}${feedback.usefulness_score !== null ? ` (${feedback.usefulness_score}/5)` : ""}${
      feedback.missing_field_labels.length ? `; missing ${feedback.missing_field_labels.join(", ")}` : ""
    }`,
    stage: workflow.stage,
    created_at: feedback.updated_at
  });

  lead.updated_at = feedback.updated_at;
  track("rep_feedback_updated", {
    leadProfileId: lead.id,
    status: feedback.status,
    usefulnessScore: feedback.usefulness_score,
    missingFields: feedback.missing_fields,
    usedOnCall: feedback.used_on_call,
    actor
  });
  persistSoon();

  return { feedback, changed: true };
}

function ensureEnrichmentReview(lead) {
  const reasons = enrichmentReviewReasonsRaw(lead);
  const current = lead.enrichment_review || {};
  const createdAt = lead.created_at || now();
  let status = ENRICHMENT_REVIEW_LABELS[current.status] ? current.status : reasons.length ? "pending" : "not_needed";

  if (!reasons.length && OPEN_ENRICHMENT_REVIEW_STATUSES.has(status)) status = "not_needed";
  if (reasons.length && status === "not_needed") status = "pending";

  lead.enrichment_review = {
    status,
    reasons,
    last_note: current.last_note || null,
    reviewed_by: current.reviewed_by || null,
    reviewed_at: current.reviewed_at || null,
    updated_at: current.updated_at || createdAt,
    notes: Array.isArray(current.notes) ? current.notes : []
  };

  return lead.enrichment_review;
}

function updateEnrichmentReview(lead, body, actor = "operator") {
  const review = ensureEnrichmentReview(lead);
  const requestedStatus = stringFromBody(body, "status", "reviewStatus", "review_status") || review.status;
  const note = stringFromBody(body, "note", "reviewNote", "notes");
  const changes = [];

  if (!ENRICHMENT_REVIEW_LABELS[requestedStatus] || requestedStatus === "not_needed") {
    return {
      error: "invalid_review_status",
      status: 400,
      message: `Review status must be one of: ${ENRICHMENT_REVIEW_STATUSES.filter((item) => item !== "not_needed").join(", ")}`
    };
  }

  if (requestedStatus !== review.status) {
    changes.push(`Review status changed from ${ENRICHMENT_REVIEW_LABELS[review.status]} to ${ENRICHMENT_REVIEW_LABELS[requestedStatus]}`);
    review.status = requestedStatus;
  }

  if (note) {
    const entry = {
      id: id("revnote"),
      body: note.slice(0, 1200),
      status: review.status,
      actor,
      created_at: now()
    };
    review.notes.unshift(entry);
    review.last_note = entry.body;
    changes.push("Review note added");
  }

  if (!changes.length) return { review, changed: false };

  review.reasons = enrichmentReviewReasonsRaw(lead);
  review.updated_at = now();
  if (review.status === "reviewed" || review.status === "dismissed") {
    review.reviewed_by = actor;
    review.reviewed_at = review.updated_at;
  } else {
    review.reviewed_by = null;
    review.reviewed_at = null;
  }

  const workflow = ensureLeadWorkflow(lead);
  workflow.last_activity_at = review.updated_at;
  workflow.activity.unshift({
    id: id("act"),
    type: "enrichment_review",
    actor,
    message: changes.join("; "),
    stage: workflow.stage,
    created_at: review.updated_at
  });

  lead.updated_at = review.updated_at;
  track("enrichment_review_updated", { leadProfileId: lead.id, status: review.status, actor, reasons: review.reasons });
  persistSoon();

  return { review, changed: true };
}

function stringFromBody(body, ...keys) {
  for (const key of keys) {
    if (body instanceof URLSearchParams && body.has(key)) return String(body.get(key) || "").trim();
    if (body?.[key] !== undefined) return String(body[key]).trim();
  }
  return "";
}

function booleanFromBody(body, key) {
  if (body instanceof URLSearchParams) return booleanFromBody(Object.fromEntries(body), key);
  const value = body?.[key];
  if (Array.isArray(value)) return value.some((item) => booleanFromBody({ value: item }, "value"));
  return ["1", "true", "yes", "on", key].includes(String(value || "").toLowerCase());
}

function booleanFromAnyBody(body, ...keys) {
  return keys.some((key) => booleanFromBody(body, key));
}

function isTerminalWorkflowStage(stage) {
  return ["closed_won", "closed_lost", "disqualified"].includes(stage);
}

function leadStatusFromWorkflowStage(stage, fallback) {
  if (stage === "closed_won") return "closed_won";
  if (stage === "closed_lost") return "closed_lost";
  if (stage === "disqualified") return "disqualified";
  if (stage === "nurture") return "nurture";
  return fallback === "low_priority" ? "qualified" : fallback || "qualified";
}

function formatDateTime(value) {
  if (!value) return "Not set";
  const date = new Date(value);
  if (Number.isNaN(date.getTime())) return String(value);
  return new Intl.DateTimeFormat("en-US", {
    dateStyle: "medium",
    timeStyle: "short"
  }).format(date);
}

function toDatetimeLocal(value) {
  if (!value) return "";
  const date = new Date(value);
  if (Number.isNaN(date.getTime())) return "";
  const pad = (input) => String(input).padStart(2, "0");
  return `${date.getFullYear()}-${pad(date.getMonth() + 1)}-${pad(date.getDate())}T${pad(date.getHours())}:${pad(date.getMinutes())}`;
}

function allLeadsSorted() {
  return [...state.leads.values()].map(normalizeLead).sort((a, b) => b.created_at.localeCompare(a.created_at));
}

function parseLeadFilters(searchParams) {
  const stage = searchParams.get("stage") || "";
  const priority = searchParams.get("priority") || "";
  const owner = searchParams.get("owner") || "";
  const sla = searchParams.get("sla") || "";
  return {
    stage: LEAD_STAGE_LABELS[stage] ? stage : "",
    priority: ["high", "medium", "low"].includes(priority) ? priority : "",
    owner: owner.trim(),
    sla: ["overdue", "due_soon", "on_track", "complete", "unset"].includes(sla) ? sla : ""
  };
}

function parseCompanyMemoryFilters(searchParams = new URLSearchParams()) {
  const segment = searchParams.get("segment") || "";
  return {
    q: String(searchParams.get("q") || "").trim(),
    segment: ["imported", "corrected", "cache_hit", "low_confidence", "reusable", "no_leads"].includes(segment) ? segment : ""
  };
}

function companyMemoryExportParams(filters) {
  const params = new URLSearchParams();
  if (filters.q) params.set("q", filters.q);
  if (filters.segment) params.set("segment", filters.segment);
  return params;
}

function leadMatchesFilters(lead, filters) {
  const workflow = ensureLeadWorkflow(lead);
  if (filters.stage && workflow.stage !== filters.stage) return false;
  if (filters.priority && lead.score?.priority !== filters.priority) return false;
  if (filters.owner && !String(workflow.owner_email || "").toLowerCase().includes(filters.owner.toLowerCase())) return false;
  if (filters.sla && workflowSlaStatus(lead) !== filters.sla) return false;
  return true;
}

function workflowSlaStatus(lead) {
  const workflow = ensureLeadWorkflow(lead);
  if (isTerminalWorkflowStage(workflow.stage)) return "complete";
  if (!workflow.due_at) return "unset";
  const dueAt = new Date(workflow.due_at).getTime();
  if (Number.isNaN(dueAt)) return "unset";
  const minutesRemaining = (dueAt - Date.now()) / 60000;
  if (minutesRemaining < 0) return "overdue";
  if (minutesRemaining <= 60) return "due_soon";
  return "on_track";
}

function leadAnalytics(leads = allLeadsSorted()) {
  const summary = {
    total: leads.length,
    open: 0,
    by_priority: { high: 0, medium: 0, low: 0 },
    by_stage: Object.fromEntries(LEAD_WORKFLOW_STAGES.map((stage) => [stage, 0])),
    by_sla: { overdue: 0, due_soon: 0, on_track: 0, complete: 0, unset: 0 },
    conversion: {
      meeting_booked: 0,
      opportunities_created: 0,
      closed_won: 0,
      closed_lost: 0,
      disqualified: 0,
      win_rate: 0
    },
    pipeline: {
      opportunity_value: 0,
      expected_value: 0,
      closed_won_value: 0,
      closed_lost_value: 0,
      average_deal_value: 0
    },
    response: {
      contacted: 0,
      average_minutes_to_first_contact: null,
      average_minutes_to_meeting: null,
      average_minutes_to_close: null
    },
    rep_feedback: {
      reviewed_profiles: 0,
      helpful_profiles: 0,
      missing_context_profiles: 0,
      not_helpful_profiles: 0,
      needs_rework_profiles: 0,
      used_on_call_profiles: 0,
      scored_profiles: 0,
      average_usefulness_score: null,
      top_missing_fields: []
    }
  };
  const responseMinutes = [];
  const meetingMinutes = [];
  const closeMinutes = [];
  const opportunityValues = [];
  const usefulnessScores = [];
  const missingFeedbackFields = [];

  for (const lead of leads) {
    const workflow = ensureLeadWorkflow(lead);
    const outcome = ensureLeadOutcome(lead);
    const feedback = ensureRepFeedback(lead);
    const priority = lead.score?.priority || "low";
    if (summary.by_priority[priority] !== undefined) summary.by_priority[priority] += 1;
    summary.by_stage[workflow.stage] += 1;
    summary.by_sla[workflowSlaStatus(lead)] += 1;
    if (!isTerminalWorkflowStage(workflow.stage)) summary.open += 1;
    if (outcome.meeting_booked_at || ["meeting_booked", "opportunity_created", "closed_won", "closed_lost"].includes(outcome.status)) summary.conversion.meeting_booked += 1;
    if (outcome.opportunity_created_at || ["opportunity_created", "closed_won", "closed_lost"].includes(outcome.status)) summary.conversion.opportunities_created += 1;
    if (outcome.status === "closed_won") summary.conversion.closed_won += 1;
    if (outcome.status === "closed_lost") summary.conversion.closed_lost += 1;
    if (outcome.status === "disqualified") summary.conversion.disqualified += 1;

    const value = Number(outcome.value || 0);
    if (value > 0 && !["disqualified", "nurture"].includes(outcome.status)) {
      summary.pipeline.opportunity_value += value;
      summary.pipeline.expected_value += value * Number(outcome.probability || 0);
      opportunityValues.push(value);
    }
    if (outcome.status === "closed_won") summary.pipeline.closed_won_value += value;
    if (outcome.status === "closed_lost") summary.pipeline.closed_lost_value += value;

    const minutes = minutesToFirstContact(lead);
    if (minutes !== null) responseMinutes.push(minutes);
    const meeting = minutesBetween(lead.created_at, outcome.meeting_booked_at);
    if (meeting !== null) meetingMinutes.push(meeting);
    const close = minutesBetween(lead.created_at, outcome.closed_at);
    if (close !== null) closeMinutes.push(close);

    const hasFeedback =
      feedback.status !== "not_reviewed" ||
      feedback.usefulness_score !== null ||
      feedback.rep_confidence !== "unknown" ||
      feedback.used_on_call ||
      feedback.missing_fields.length ||
      feedback.last_note;
    if (hasFeedback) summary.rep_feedback.reviewed_profiles += 1;
    if (feedback.status === "helpful") summary.rep_feedback.helpful_profiles += 1;
    if (feedback.status === "missing_context") summary.rep_feedback.missing_context_profiles += 1;
    if (feedback.status === "not_helpful") summary.rep_feedback.not_helpful_profiles += 1;
    if (feedback.status === "needs_rework") summary.rep_feedback.needs_rework_profiles += 1;
    if (feedback.used_on_call) summary.rep_feedback.used_on_call_profiles += 1;
    if (feedback.usefulness_score !== null) usefulnessScores.push(feedback.usefulness_score);
    missingFeedbackFields.push(...feedback.missing_fields);
  }

  summary.response.contacted = responseMinutes.length;
  if (responseMinutes.length) {
    const average = responseMinutes.reduce((total, value) => total + value, 0) / responseMinutes.length;
    summary.response.average_minutes_to_first_contact = Number(average.toFixed(1));
  }
  if (meetingMinutes.length) {
    const average = meetingMinutes.reduce((total, value) => total + value, 0) / meetingMinutes.length;
    summary.response.average_minutes_to_meeting = Number(average.toFixed(1));
  }
  if (closeMinutes.length) {
    const average = closeMinutes.reduce((total, value) => total + value, 0) / closeMinutes.length;
    summary.response.average_minutes_to_close = Number(average.toFixed(1));
  }

  const closedDeals = summary.conversion.closed_won + summary.conversion.closed_lost;
  summary.conversion.win_rate = closedDeals ? Number((summary.conversion.closed_won / closedDeals).toFixed(2)) : 0;
  summary.pipeline.opportunity_value = Number(summary.pipeline.opportunity_value.toFixed(2));
  summary.pipeline.expected_value = Number(summary.pipeline.expected_value.toFixed(2));
  summary.pipeline.closed_won_value = Number(summary.pipeline.closed_won_value.toFixed(2));
  summary.pipeline.closed_lost_value = Number(summary.pipeline.closed_lost_value.toFixed(2));
  summary.pipeline.average_deal_value = opportunityValues.length
    ? Number((opportunityValues.reduce((total, value) => total + value, 0) / opportunityValues.length).toFixed(2))
    : 0;
  summary.rep_feedback.scored_profiles = usefulnessScores.length;
  if (usefulnessScores.length) {
    const average = usefulnessScores.reduce((total, value) => total + value, 0) / usefulnessScores.length;
    summary.rep_feedback.average_usefulness_score = roundNumber(average, 1);
  }
  summary.rep_feedback.top_missing_fields = topCounts(missingFeedbackFields.map((field) => REP_FEEDBACK_MISSING_FIELD_LABELS[field] || humanizeEnum(field)));
  return summary;
}

function companyMemoryForProfile(profile) {
  const domain = normalizeDomain(profile.company.domain || profile.company.website);
  return domain ? state.companyMemory.get(domain) : null;
}

function companyMemoryUsable(record) {
  if (!record?.domain) return false;
  const hasCorrectedFields = Boolean(record.corrected_fields?.length);
  const hasImportedFields = Boolean(record.imported_fields?.length);
  const hasUsefulSignals = Boolean(
    record.company_size ||
      record.industry ||
      record.tech_stack?.length ||
      record.signals?.length ||
      record.conversion_surface?.status === "detected" ||
      record.research_evidence?.length
  );
  return hasUsefulSignals && (hasCorrectedFields || hasImportedFields || Number(record.confidence || 0) >= ENRICHMENT_REVIEW_CONFIDENCE_THRESHOLD);
}

function enrichmentFromCompanyMemory(profile, record) {
  const nowIso = now();
  record.last_used_at = nowIso;
  record.updated_at = nowIso;
  state.companyMemory.set(record.domain, record);
  track("company_memory_used", { domain: record.domain, recordId: record.id });
  const techStack = mergeVisitorTechStack(profile.qualification.sales_stack, record.tech_stack);
  const buyerProfile = buyerProfileFromMemory(profile, record, techStack);

  return {
    status: "completed",
    completed_at: nowIso,
    provider: "internal_memory_cache",
    confidence: Math.max(Number(record.confidence || 0), record.corrected_fields.length ? 0.86 : 0.72),
    company_size: {
      value: profile.company.size_hint || record.company_size || "unknown",
      source: profile.company.size_hint ? "visitor" : "company_memory",
      confidence: profile.company.size_hint ? 0.9 : record.company_size ? 0.82 : 0.25
    },
    industry: {
      value: profile.company.industry_hint || record.industry || "unknown",
      source: profile.company.industry_hint ? "visitor" : "company_memory",
      confidence: profile.company.industry_hint ? 0.75 : record.industry ? 0.82 : 0.25
    },
    tech_stack: techStack,
    funding_events: [],
    decision_makers: buyerProfile.buying_committee,
    buyer_profile: buyerProfile,
    conversion_surface: record.conversion_surface || normalizeConversionSurface(),
    signals: record.signals || [],
    website: {
      final_url: record.website || profile.company.website || null,
      title: record.website_title || null,
      description: record.website_description || null,
      canonical: record.website || profile.company.website || null,
      social_links: record.social_links || [],
      signal_links: [],
      inspected_pages: []
    },
    cost: {
      paid_provider_used: false,
      estimated_usd: 0,
      billable_requests: 0,
      internal_requests: 0,
      note: "Company memory reused. No website crawl or paid provider was called."
    },
    memory: {
      record_id: record.id,
      domain: record.domain,
      corrected_fields: record.corrected_fields,
      last_used_at: nowIso
    },
    notes: [
      "Reused self-built company memory from prior Deal Threads leads or operator corrections.",
      "No paid enrichment provider was called."
    ]
  };
}

function buyerProfileFromMemory(profile, record, techStack = []) {
  const context = [
    profile.company.name,
    profile.company.domain,
    profile.company.size_hint,
    profile.qualification.business_need,
    profile.qualification.timeline,
    profile.qualification.budget_status,
    profile.visitor.authority_signal,
    record.industry,
    record.company_size,
    ...(record.signals || []).map((item) => item.value),
    ...(techStack || []).map((item) => item.value)
  ]
    .filter((item) => item?.[1])
    .join(" ")
    .toLowerCase();
  let score = 25;
  const reasons = [];

  if (record.company_size || profile.company.size_hint) {
    score += 18;
    reasons.push("Company size is available from visitor context or memory.");
  }
  if (record.industry || /saas|software|b2b|sales|revenue/.test(context)) {
    score += 18;
    reasons.push("Industry or account memory aligns with B2B revenue teams.");
  }
  if (/lead|demo|routing|handoff|crm|enrichment/.test(context)) {
    score += 18;
    reasons.push("Pain matches lead enrichment or CRM handoff.");
  }
  if (techStack.length || profile.qualification.crm !== "unknown") {
    score += 12;
    reasons.push("CRM or sales-stack context is known.");
  }
  if (["this_week", "this_month", "this_quarter"].includes(profile.qualification.timeline)) {
    score += 8;
    reasons.push("Timeline indicates an active project.");
  }
  if (["approved", "likely"].includes(profile.qualification.budget_status)) {
    score += 7;
    reasons.push("Budget signal is positive.");
  }

  const triggers = [
    /cold|slow|speed|response|handoff|route|routing/.test(context)
      ? { value: "Speed-to-lead or sales handoff pain", category: "acute_pain", source: "company_memory", confidence: 0.78 }
      : null,
    ...((record.signals || []).slice(0, 4).map((item) => ({
      value: item.value,
      category: item.category || "company_memory_signal",
      source: item.source || "company_memory",
      confidence: Number(item.confidence || 0.7)
    }))),
    ["this_week", "this_month", "this_quarter"].includes(profile.qualification.timeline)
      ? { value: `Active project timing: ${profile.qualification.timeline.replaceAll("_", " ")}`, category: "timing", source: "visitor_context", confidence: 0.8 }
      : null
  ].filter(Boolean);
  const committee = [
    { value: "RevOps leader", role: "RevOps leader", title: "VP Revenue Operations / Director RevOps", category: "buying_committee", source: "company_memory", confidence: 0.74, reason: "Owns routing quality, CRM process, and response SLAs." },
    { value: "Sales leader", role: "Sales leader", title: "VP Sales / CRO", category: "buying_committee", source: "company_memory", confidence: 0.68, reason: "Owns conversion rate and inbound pipeline outcomes." },
    techStack.length || profile.qualification.crm !== "unknown"
      ? { value: "CRM owner", role: "CRM owner", title: "Sales Operations / CRM Admin", category: "buying_committee", source: "company_memory", confidence: 0.66, reason: "Owns CRM fields, routing, and handoff acceptance." }
      : null
  ].filter(Boolean);
  const finalScore = Math.min(100, score);
  const segment = finalScore >= 75 ? "strong_mid_market_b2b_fit" : finalScore >= 55 ? "potential_b2b_fit" : "needs_more_research";

  return {
    icp_fit: {
      score: finalScore,
      segment,
      reasons: reasons.slice(0, 6)
    },
    buying_committee: committee,
    buying_triggers: dedupeMemoryItems(triggers).slice(0, 8),
    opening_angle: `Open by tying ${profile.company.name || record.company_name || record.domain}'s stated need to ${triggers[0]?.value || "the saved account context"}. Confirm whether ${committee[0]?.title || "the revenue owner"} owns the pilot decision, then use the ${segment.replaceAll("_", " ")} score to frame the next step.`
  };
}

function mergeCompanyMemoryIntoEnrichment(enrichment, profile, record) {
  if (!record) return enrichment;
  const merged = structuredClone(enrichment);
  merged.memory = {
    record_id: record.id,
    domain: record.domain,
    corrected_fields: record.corrected_fields,
    merged_at: now()
  };
  merged.notes = [...(merged.notes || []), "Merged available company memory into the current internal enrichment result."];

  if (record.company_size && (!knownValue(merged.company_size?.value) || record.corrected_fields.includes("company_size"))) {
    merged.company_size = {
      value: record.company_size,
      source: record.corrected_fields.includes("company_size") ? "operator_corrected_memory" : "company_memory",
      confidence: record.corrected_fields.includes("company_size") ? 0.9 : 0.75
    };
  }
  if (record.industry && (!knownValue(merged.industry?.value) || record.corrected_fields.includes("industry"))) {
    merged.industry = {
      value: record.industry,
      source: record.corrected_fields.includes("industry") ? "operator_corrected_memory" : "company_memory",
      confidence: record.corrected_fields.includes("industry") ? 0.9 : 0.75
    };
  }
  merged.tech_stack = dedupeMemoryItems([...(merged.tech_stack || []), ...(record.tech_stack || [])]);
  merged.signals = dedupeMemoryItems([...(merged.signals || []), ...(record.signals || [])]);
  if (record.conversion_surface?.status === "detected" && merged.conversion_surface?.status !== "detected") {
    merged.conversion_surface = record.conversion_surface;
  }
  merged.confidence = Math.max(Number(merged.confidence || 0), record.corrected_fields.length ? 0.8 : Number(record.confidence || 0));
  return merged;
}

function mergeVisitorTechStack(visitorStack = [], memoryStack = []) {
  return dedupeMemoryItems([
    ...visitorStack.map((value) => ({
      value,
      category: value === "HubSpot" || value === "Salesforce" ? "CRM" : "Visitor-provided",
      source: "visitor",
      confidence: 0.95
    })),
    ...(memoryStack || [])
  ]);
}

function rememberCompanyFromLead(lead) {
  const domain = normalizeDomain(lead.company?.domain || lead.company?.website);
  if (!domain) return null;

  const existing = state.companyMemory.get(domain) || normalizeCompanyMemoryRecord({ domain });
  const leadsForDomain = [...state.leads.values()]
    .map(normalizeLead)
    .filter((item) => normalizeDomain(item.company?.domain || item.company?.website) === domain);
  const latestLead = leadsForDomain.sort((a, b) => b.created_at.localeCompare(a.created_at))[0] || lead;
  const workflowCounts = leadsForDomain.reduce(
    (counts, item) => {
      const stage = ensureLeadWorkflow(item).stage;
      if (stage === "closed_won") counts.won += 1;
      if (stage === "closed_lost") counts.lost += 1;
      return counts;
    },
    { won: 0, lost: 0 }
  );

  const record = normalizeCompanyMemoryRecord({
    ...existing,
    company_name: memoryField(existing, "company_name", lead.company?.name),
    website: memoryField(existing, "website", lead.company?.website),
    industry: memoryField(existing, "industry", lead.company?.industry),
    company_size: memoryField(existing, "company_size", lead.company?.employee_range),
    confidence: Math.max(Number(existing.confidence || 0), Number(lead.enrichment?.confidence || 0)),
    source: ["operator_corrected_memory", "target_account_import"].includes(existing.source)
      ? existing.source
      : lead.enrichment?.provider || existing.source,
    tech_stack: dedupeMemoryItems([...(existing.tech_stack || []), ...(lead.enrichment?.tech_stack || [])]),
    signals: dedupeMemoryItems([...(existing.signals || []), ...(lead.enrichment?.signals || [])]),
    conversion_surface: lead.enrichment?.conversion_surface?.status === "detected" ? lead.enrichment.conversion_surface : existing.conversion_surface,
    social_links: Array.from(new Set([...(existing.social_links || []), ...(lead.enrichment?.website?.social_links || [])])),
    website_title: memoryField(existing, "website_title", lead.enrichment?.website?.title),
    website_description: memoryField(existing, "website_description", lead.enrichment?.website?.description),
    last_enriched_at: lead.enrichment?.completed_at || existing.last_enriched_at,
    latest_lead_id: latestLead.id,
    latest_lead_at: latestLead.created_at,
    lead_count: leadsForDomain.length,
    high_priority_count: leadsForDomain.filter((item) => item.score?.priority === "high").length,
    won_count: workflowCounts.won,
    lost_count: workflowCounts.lost,
    updated_at: now()
  });

  state.companyMemory.set(domain, record);
  track("company_memory_updated", { domain, recordId: record.id, leadProfileId: lead.id });
  return record;
}

function memoryField(record, field, fallback) {
  if (record.corrected_fields?.includes(field) && record[field]) return record[field];
  if (record.imported_fields?.includes(field) && record[field]) return record[field];
  const value = optionalString(fallback);
  if (value && value !== "unknown") return value;
  return record[field] || null;
}

function updateCompanyMemoryCorrection(lead, body = {}, actor = "operator") {
  const domain = normalizeDomain(stringFromBody(body, "domain") || lead.company?.domain || lead.company?.website);
  if (!domain) {
    return { error: "domain_required", status: 400, message: "Company domain is required to save enrichment memory." };
  }

  if (lead.company) {
    lead.company.domain = domain;
    lead.company.website = normalizeWebsiteUrl(stringFromBody(body, "website", "websiteUrl", "website_url") || lead.company.website, domain);
  }
  const existing = state.companyMemory.get(domain) || rememberCompanyFromLead(lead) || normalizeCompanyMemoryRecord({ domain });
  const updates = {
    company_name: stringFromBody(body, "companyName", "company_name", "name"),
    website: stringFromBody(body, "website", "websiteUrl", "website_url"),
    industry: stringFromBody(body, "industry"),
    company_size: stringFromBody(body, "companySize", "company_size", "employeeRange", "employee_range"),
    notes: stringFromBody(body, "notes", "note")
  };
  const correctedFields = new Set(existing.corrected_fields || []);

  for (const [field, value] of Object.entries(updates)) {
    if (!value) continue;
    existing[field] = field === "website" ? normalizeWebsiteUrl(value, domain) : value;
    if (field !== "notes") correctedFields.add(field);
  }

  const techStack = parseList(body.techStack || body.tech_stack);
  if (techStack.length) {
    existing.tech_stack = dedupeMemoryItems([
      ...(existing.tech_stack || []),
      ...techStack.map((value) => ({ value, category: "Operator-confirmed", source: "operator_corrected_memory", confidence: 0.92 }))
    ]);
    correctedFields.add("tech_stack");
  }

  const signals = parseList(body.signals);
  if (signals.length) {
    existing.signals = dedupeMemoryItems([
      ...(existing.signals || []),
      ...signals.map((value) => ({ value, category: "operator_signal", source: "operator_corrected_memory", confidence: 0.9 }))
    ]);
    correctedFields.add("signals");
  }

  existing.domain = domain;
  existing.source = "operator_corrected_memory";
  existing.confidence = Math.max(Number(existing.confidence || 0), 0.86);
  existing.corrected_fields = [...correctedFields];
  existing.corrections = [
    {
      id: id("corr"),
      actor,
      lead_id: lead.id,
      fields: [...correctedFields],
      note: updates.notes || "",
      created_at: now()
    },
    ...(existing.corrections || [])
  ].slice(0, 20);
  existing.updated_at = now();

  applyCompanyMemoryToLead(lead, existing);
  rememberCompanyFromLead(lead);
  track("company_memory_corrected", { domain, recordId: existing.id, leadProfileId: lead.id, actor, fields: [...correctedFields] });
  persistSoon();
  return { memory: state.companyMemory.get(domain), lead };
}

function addLeadResearchEvidence(lead, body = {}, actor = "operator") {
  if (!lead) {
    return { error: "lead_not_found", status: 404, message: "Lead not found." };
  }
  normalizeLeadEnrichment(lead);
  const value = stringFromBody(body, "value", "evidence", "body", "text");
  if (!value) {
    return { error: "research_evidence_required", status: 400, message: "Add a research finding before saving evidence." };
  }

  const domain = normalizeDomain(stringFromBody(body, "domain") || lead.company?.domain || lead.company?.website);
  const evidence = normalizeResearchEvidence({
    id: id("ev"),
    category: stringFromBody(body, "category", "type") || "icp_signal",
    value,
    source_url: stringFromBody(body, "sourceUrl", "source_url", "url"),
    source_label: stringFromBody(body, "sourceLabel", "source_label", "source"),
    confidence: stringFromBody(body, "confidence", "confidencePercent", "confidence_percent") || 75,
    reusable: body.reusable === undefined ? true : body.reusable,
    note: stringFromBody(body, "note", "notes"),
    lead_id: lead.id,
    domain,
    actor,
    created_by: actor,
    created_at: now()
  });

  lead.enrichment.research_evidence = normalizeResearchEvidenceList([evidence, ...(lead.enrichment.research_evidence || [])]);
  applyResearchEvidenceToLead(lead, evidence);
  const memory = evidence.reusable ? applyResearchEvidenceToCompanyMemory(lead, evidence, actor) : state.companyMemory.get(domain);
  const review = ensureLeadOutcomeAndResearchReview(lead, evidence, body, actor);

  lead.updated_at = evidence.created_at;
  state.leads.set(lead.id, lead);
  track("lead_research_evidence_added", {
    leadProfileId: lead.id,
    domain,
    category: evidence.category,
    reusable: evidence.reusable,
    actor
  });
  persistSoon();
  return { evidence, memory, lead, review };
}

function applyResearchEvidenceToLead(lead, evidence) {
  normalizeLeadEnrichment(lead);
  const value = evidence.value;
  const source = "operator_research";
  const item = {
    value,
    category: evidence.category,
    source,
    confidence: evidence.confidence,
    source_url: evidence.source_url,
    source_label: evidence.source_label,
    evidence: evidence.note,
    created_at: evidence.created_at
  };

  if (evidence.category === "company_size") {
    lead.company.employee_range = value;
    lead.enrichment.company_size = { value, source, confidence: evidence.confidence };
  } else if (evidence.category === "industry") {
    lead.company.industry = value;
    lead.enrichment.industry = { value, source, confidence: evidence.confidence };
  } else if (evidence.category === "tech_stack") {
    const techItems = parseList(value).map((tech) => ({ ...item, value: tech, category: "Operator-researched tech stack" }));
    lead.enrichment.tech_stack = dedupeMemoryItems([...(lead.enrichment.tech_stack || []), ...techItems]);
  } else if (evidence.category === "buying_committee") {
    const committeeItem = {
      ...item,
      role: value,
      title: value,
      category: "buying_committee",
      reason: evidence.note || "Confirmed through operator research."
    };
    lead.enrichment.decision_makers = [...(lead.enrichment.decision_makers || []), committeeItem];
    lead.enrichment.buyer_profile = normalizeBuyerProfile({
      ...(lead.enrichment.buyer_profile || {}),
      buying_committee: [committeeItem, ...(lead.enrichment.buyer_profile?.buying_committee || [])]
    }, lead.enrichment);
  } else if (evidence.category === "buying_trigger") {
    const trigger = { ...item, category: "operator_researched_trigger" };
    lead.enrichment.signals = dedupeMemoryItems([...(lead.enrichment.signals || []), trigger]);
    lead.enrichment.buyer_profile = normalizeBuyerProfile({
      ...(lead.enrichment.buyer_profile || {}),
      buying_triggers: [trigger, ...(lead.enrichment.buyer_profile?.buying_triggers || [])]
    }, lead.enrichment);
  } else if (evidence.category === "funding") {
    lead.enrichment.funding_events = [
      {
        ...item,
        round: value,
        evidence: evidence.note || evidence.source_label || evidence.source_url || "Operator research"
      },
      ...(lead.enrichment.funding_events || [])
    ];
  } else {
    lead.enrichment.signals = dedupeMemoryItems([...(lead.enrichment.signals || []), item]);
  }

  lead.enrichment.confidence = Math.max(Number(lead.enrichment.confidence || 0), Math.min(0.95, evidence.confidence + 0.05));
  if (lead.enrichment.status !== "completed") lead.enrichment.status = "completed";
  const profile = {
    visitor: lead.contact,
    company: {
      name: lead.company?.name,
      domain: lead.company?.domain,
      website: lead.company?.website,
      industry_hint: lead.company?.industry,
      size_hint: lead.company?.employee_range
    },
    qualification: lead.qualification
  };
  lead.enrichment.buyer_profile = normalizeBuyerProfile(lead.enrichment.buyer_profile, lead.enrichment);
  lead.summary = buildRepSummary(profile, lead.enrichment, lead.score, lead.routing);
  return lead;
}

function applyResearchEvidenceToCompanyMemory(lead, evidence, actor = "operator") {
  const domain = normalizeDomain(evidence.domain || lead.company?.domain || lead.company?.website);
  if (!domain) return null;
  const existing = state.companyMemory.get(domain) || rememberCompanyFromLead(lead) || normalizeCompanyMemoryRecord({ domain });
  const reusableFields = new Set(existing.corrected_fields || []);

  existing.research_evidence = normalizeResearchEvidenceList([evidence, ...(existing.research_evidence || [])]);
  existing.confidence = Math.max(Number(existing.confidence || 0), Math.min(0.9, evidence.confidence + 0.04));
  existing.source = ["operator_corrected_memory", "target_account_import"].includes(existing.source) ? existing.source : "operator_researched_memory";
  existing.notes = evidence.note || existing.notes;

  if (evidence.category === "company_size") {
    existing.company_size = evidence.value;
    reusableFields.add("company_size");
  } else if (evidence.category === "industry") {
    existing.industry = evidence.value;
    reusableFields.add("industry");
  } else if (evidence.category === "tech_stack") {
    existing.tech_stack = dedupeMemoryItems([
      ...(existing.tech_stack || []),
      ...parseList(evidence.value).map((value) => ({
        value,
        category: "operator_researched_tech_stack",
        source: "operator_research",
        confidence: evidence.confidence,
        source_url: evidence.source_url,
        source_label: evidence.source_label,
        evidence: evidence.note,
        created_at: evidence.created_at
      }))
    ]);
    reusableFields.add("tech_stack");
  } else {
    existing.signals = dedupeMemoryItems([
      ...(existing.signals || []),
      {
        value: evidence.value,
        category: evidence.category,
        source: "operator_research",
        confidence: evidence.confidence,
        source_url: evidence.source_url,
        source_label: evidence.source_label,
        evidence: evidence.note,
        created_at: evidence.created_at
      }
    ]);
    reusableFields.add("signals");
  }

  existing.corrected_fields = [...reusableFields];
  existing.corrections = [
    {
      id: id("corr"),
      actor,
      lead_id: lead.id,
      fields: ["research_evidence", evidence.category],
      note: evidence.note || evidence.value,
      created_at: evidence.created_at
    },
    ...(existing.corrections || [])
  ].slice(0, 20);
  existing.updated_at = evidence.created_at;
  state.companyMemory.set(domain, normalizeCompanyMemoryRecord(existing));
  applyCompanyMemoryToLead(lead, state.companyMemory.get(domain));
  track("company_memory_research_evidence_added", {
    domain,
    recordId: existing.id,
    leadProfileId: lead.id,
    category: evidence.category,
    actor
  });
  return state.companyMemory.get(domain);
}

function ensureLeadOutcomeAndResearchReview(lead, evidence, body = {}, actor = "operator") {
  const review = ensureEnrichmentReview(lead);
  const shouldMarkReviewed = truthy(body.markReviewed || body.mark_reviewed || body.closeReview || body.close_review);
  const note = evidence.note || `Research evidence added: ${evidence.value}`;
  if (shouldMarkReviewed || review.status === "research_needed" || review.status === "pending") {
    const requestedStatus = shouldMarkReviewed ? "reviewed" : "in_review";
    updateEnrichmentReview(
      lead,
      {
        status: requestedStatus,
        note
      },
      actor
    );
  }

  const workflow = ensureLeadWorkflow(lead);
  workflow.last_activity_at = evidence.created_at;
  workflow.activity.unshift({
    id: id("act"),
    type: "research_evidence",
    actor,
    message: `Research evidence added (${RESEARCH_EVIDENCE_LABELS[evidence.category] || evidence.category}): ${evidence.value}`,
    stage: workflow.stage,
    created_at: evidence.created_at
  });
  return ensureEnrichmentReview(lead);
}

function importCompanyMemoryCsv(body = {}, actor = "operator") {
  const rawCsv = String(body.csv || body.raw || "").trim();
  if (!rawCsv) {
    return { error: "csv_required", status: 400, message: "Paste CSV rows before importing target accounts." };
  }

  const parsed = parseCsv(rawCsv);
  if (parsed.length < 2) {
    return { error: "csv_rows_required", status: 400, message: "CSV must include a header row and at least one account row." };
  }

  const headers = parsed[0].map(normalizeCsvHeader);
  const imported = [];
  const errors = [];
  let created = 0;
  let updated = 0;

  for (const [index, row] of parsed.slice(1).entries()) {
    const rowNumber = index + 2;
    if (!row.some((cell) => String(cell || "").trim())) continue;
    const data = Object.fromEntries(headers.map((header, columnIndex) => [header, row[columnIndex] || ""]));
    const domain = normalizeDomain(csvValue(data, "domain", "company_domain", "account_domain", "website", "website_url", "url"));

    if (!domain) {
      errors.push({ row: rowNumber, error: "domain_required", message: "Domain or website is required." });
      continue;
    }

    const existing = state.companyMemory.get(domain);
    const importedFields = new Set(existing?.imported_fields || []);
    const updates = {
      company_name: csvValue(data, "company_name", "company", "account", "account_name", "name"),
      website: csvValue(data, "website", "website_url", "url"),
      industry: csvValue(data, "industry", "segment", "vertical"),
      company_size: csvValue(data, "company_size", "employee_range", "employees", "size"),
      website_title: csvValue(data, "website_title", "title"),
      website_description: csvValue(data, "website_description", "description"),
      notes: csvValue(data, "notes", "note", "source_notes")
    };
    const base = existing || normalizeCompanyMemoryRecord({ domain });
    const record = normalizeCompanyMemoryRecord({
      ...base,
      domain,
      company_name: importedFieldValue(base, "company_name", updates.company_name),
      website: importedFieldValue(base, "website", updates.website || `https://${domain}`),
      industry: importedFieldValue(base, "industry", updates.industry),
      company_size: importedFieldValue(base, "company_size", updates.company_size),
      website_title: importedFieldValue(base, "website_title", updates.website_title),
      website_description: importedFieldValue(base, "website_description", updates.website_description),
      notes: updates.notes || base.notes,
      source: base.source === "operator_corrected_memory" ? base.source : "target_account_import",
      confidence: Math.max(Number(base.confidence || 0), 0.78),
      imported_fields: [...importedFields],
      imports: [
        {
          id: id("imp"),
          actor,
          row: rowNumber,
          source: "target_account_csv",
          created_at: now()
        },
        ...(base.imports || [])
      ].slice(0, 20),
      updated_at: now()
    });

    for (const field of ["company_name", "website", "industry", "company_size", "website_title", "website_description"]) {
      if (updates[field]) importedFields.add(field);
    }

    const techStack = parseFlexibleList(csvValue(data, "tech_stack", "tech", "tools", "crm", "sales_stack"));
    if (techStack.length) {
      record.tech_stack = dedupeMemoryItems([
        ...(record.tech_stack || []),
        ...techStack.map((value) => ({ value, category: "Target account import", source: "target_account_import", confidence: 0.82 }))
      ]);
      importedFields.add("tech_stack");
    }

    const signals = parseFlexibleList(csvValue(data, "signals", "fit_signals", "intent_signals"));
    if (signals.length) {
      record.signals = dedupeMemoryItems([
        ...(record.signals || []),
        ...signals.map((value) => ({ value, category: "target_account_signal", source: "target_account_import", confidence: 0.78 }))
      ]);
      importedFields.add("signals");
    }

    record.social_links = Array.from(
      new Set([...(record.social_links || []), ...parseFlexibleList(csvValue(data, "social_links", "linkedin", "linkedin_url"))])
    );
    if (record.social_links.length) importedFields.add("social_links");
    record.imported_fields = [...importedFields];
    state.companyMemory.set(domain, normalizeCompanyMemoryRecord(record));
    imported.push({ row: rowNumber, domain, company_name: record.company_name, created: !existing });
    if (existing) updated += 1;
    else created += 1;
  }

  track("company_memory_imported", { actor, created, updated, errors: errors.length });
  persistSoon();
  return {
    imported_at: now(),
    summary: {
      parsed_rows: Math.max(0, parsed.length - 1),
      imported: imported.length,
      created,
      updated,
      errors: errors.length
    },
    imported,
    errors,
    memory: companyMemorySummary(allLeadsSorted())
  };
}

function importedFieldValue(record, field, value) {
  if (record.corrected_fields?.includes(field) && record[field]) return record[field];
  return optionalString(value) || record[field] || null;
}

function csvValue(row, ...keys) {
  for (const key of keys) {
    const value = row[normalizeCsvHeader(key)];
    if (value !== undefined && String(value).trim()) return String(value).trim();
  }
  return "";
}

function normalizeCsvHeader(value = "") {
  return String(value)
    .trim()
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, "_")
    .replace(/^_+|_+$/g, "");
}

function parseFlexibleList(value) {
  return String(value || "")
    .split(/[;,|]/)
    .map((item) => item.trim())
    .filter(Boolean);
}

function parseCsv(input) {
  const rows = [];
  let row = [];
  let cell = "";
  let inQuotes = false;
  const text = String(input || "").replace(/\r\n/g, "\n").replace(/\r/g, "\n");

  for (let index = 0; index < text.length; index += 1) {
    const char = text[index];
    const next = text[index + 1];

    if (char === '"' && inQuotes && next === '"') {
      cell += '"';
      index += 1;
      continue;
    }

    if (char === '"') {
      inQuotes = !inQuotes;
      continue;
    }

    if (char === "," && !inQuotes) {
      row.push(cell.trim());
      cell = "";
      continue;
    }

    if (char === "\n" && !inQuotes) {
      row.push(cell.trim());
      if (row.some((value) => value)) rows.push(row);
      row = [];
      cell = "";
      continue;
    }

    cell += char;
  }

  row.push(cell.trim());
  if (row.some((value) => value)) rows.push(row);
  return rows;
}

function applyCompanyMemoryToLead(lead, record) {
  lead.company.name = record.company_name || lead.company.name;
  lead.company.website = record.website || lead.company.website;
  lead.company.industry = record.industry || lead.company.industry;
  lead.company.employee_range = record.company_size || lead.company.employee_range;
  lead.enrichment.company_size = {
    ...(lead.enrichment.company_size || {}),
    value: record.company_size || lead.enrichment.company_size?.value || "unknown",
    source: record.corrected_fields.includes("company_size") ? "operator_corrected_memory" : lead.enrichment.company_size?.source || "company_memory",
    confidence: record.company_size ? 0.9 : lead.enrichment.company_size?.confidence || 0.25
  };
  lead.enrichment.industry = {
    ...(lead.enrichment.industry || {}),
    value: record.industry || lead.enrichment.industry?.value || "unknown",
    source: record.corrected_fields.includes("industry") ? "operator_corrected_memory" : lead.enrichment.industry?.source || "company_memory",
    confidence: record.industry ? 0.9 : lead.enrichment.industry?.confidence || 0.25
  };
  lead.enrichment.tech_stack = dedupeMemoryItems([...(lead.enrichment.tech_stack || []), ...(record.tech_stack || [])]);
  lead.enrichment.signals = dedupeMemoryItems([...(lead.enrichment.signals || []), ...(record.signals || [])]);
  lead.enrichment.memory = {
    record_id: record.id,
    domain: record.domain,
    corrected_fields: record.corrected_fields,
    applied_at: now()
  };
  lead.enrichment.confidence = Math.max(Number(lead.enrichment.confidence || 0), record.confidence);
  lead.updated_at = now();
  lead.summary = buildRepSummary(
    {
      visitor: lead.contact,
      company: {
        name: lead.company.name,
        domain: lead.company.domain,
        website: lead.company.website,
        industry_hint: lead.company.industry,
        size_hint: lead.company.employee_range
      },
      qualification: lead.qualification
    },
    lead.enrichment,
    lead.score,
    lead.routing
  );
}

function companyMemorySummary(leads = allLeadsSorted(), filters = {}, options = {}) {
  const normalizedFilters = {
    q: filters.q || "",
    segment: filters.segment || ""
  };
  const cacheHits = leads.filter((lead) => lead.enrichment?.provider === "internal_memory_cache");
  const cacheHitCounts = cacheHits.reduce((counts, lead) => {
    const domain = normalizeDomain(lead.company?.domain || lead.company?.website || lead.enrichment?.memory?.domain);
    if (domain) counts.set(domain, (counts.get(domain) || 0) + 1);
    return counts;
  }, new Map());
  const allRecords = [...state.companyMemory.values()].map((record) => {
    const normalized = normalizeCompanyMemoryRecord(record);
    normalized.cache_hits = cacheHitCounts.get(normalized.domain) || 0;
    return normalized;
  });
  const records = allRecords.filter((record) => companyMemoryMatchesFilters(record, normalizedFilters));
  const correctedRecords = allRecords.filter((record) => record.corrected_fields.length);
  const importedRecords = allRecords.filter((record) => record.imported_fields.length);
  const reusableRecords = allRecords.filter(companyMemoryUsable);
  const sortedRecords = records.sort((a, b) => b.updated_at.localeCompare(a.updated_at));
  const visibleRecords = options.limit === null ? sortedRecords : sortedRecords.slice(0, options.limit || 20);

  return {
    generated_at: now(),
    filters: normalizedFilters,
    total_records: allRecords.length,
    count: records.length,
    reusable_records: reusableRecords.length,
    corrected_records: correctedRecords.length,
    imported_records: importedRecords.length,
    research_evidence_count: allRecords.reduce((sum, record) => sum + record.research_evidence.length, 0),
    outreach_event_count: allRecords.reduce((sum, record) => sum + (record.outreach_events || []).length, 0),
    cache_hits: cacheHits.length,
    estimated_internal_requests_saved: cacheHits.length,
    top_tech_stack: topCounts(records.flatMap((record) => record.tech_stack.map((item) => item.value))),
    top_signals: topCounts(records.flatMap((record) => record.signals.map((item) => item.value))),
    top_research_categories: topCounts(records.flatMap((record) => record.research_evidence.map((item) => RESEARCH_EVIDENCE_LABELS[item.category] || item.category))),
    records: visibleRecords
      .map((record) => ({
        id: record.id,
        domain: record.domain,
        company_name: record.company_name,
        website: record.website,
        industry: record.industry,
        company_size: record.company_size,
        confidence: record.confidence,
        source: record.source,
        lead_count: record.lead_count,
        high_priority_count: record.high_priority_count,
        won_count: record.won_count,
        lost_count: record.lost_count,
        cache_hits: record.cache_hits || 0,
        corrected_fields: record.corrected_fields,
        imported_fields: record.imported_fields,
        tech_stack: record.tech_stack,
        signals: record.signals,
        research_evidence_count: record.research_evidence.length,
        latest_research_evidence: record.research_evidence[0] || null,
        research_evidence: record.research_evidence.slice(0, 5),
        outreach_event_count: record.outreach_events.length,
        latest_outreach_event: record.outreach_events[0] || null,
        outreach_events: record.outreach_events.slice(0, 5),
        latest_lead_id: record.latest_lead_id,
        latest_lead_at: record.latest_lead_at,
        updated_at: record.updated_at
      })),
    recommended_actions: companyMemoryRecommendedActions(allRecords, cacheHits)
  };
}

function companyMemoryMatchesFilters(record, filters = {}) {
  if (filters.segment === "imported" && !record.imported_fields.length) return false;
  if (filters.segment === "corrected" && !record.corrected_fields.length) return false;
  if (filters.segment === "cache_hit" && !record.cache_hits) return false;
  if (filters.segment === "low_confidence" && companyMemoryUsable(record)) return false;
  if (filters.segment === "reusable" && !companyMemoryUsable(record)) return false;
  if (filters.segment === "no_leads" && record.lead_count) return false;

  if (filters.q) {
    const query = filters.q.toLowerCase();
    const haystack = [
      record.company_name,
      record.domain,
      record.website,
      record.industry,
      record.company_size,
      record.source,
      record.notes,
      ...(record.tech_stack || []).map((item) => item.value),
      ...(record.signals || []).map((item) => item.value),
      ...(record.research_evidence || []).flatMap((item) => [
        item.value,
        item.category,
        item.source_url,
        item.source_label,
        item.note
      ])
    ]
      .filter(Boolean)
      .join(" ")
      .toLowerCase();
    if (!haystack.includes(query)) return false;
  }

  return true;
}

function companyMemoryRecommendedActions(records, cacheHits) {
  if (!records.length) return ["Capture the next five beta leads, then correct any weak company profiles once to build reusable memory."];
  const actions = [];
  const lowConfidence = records.filter((record) => !companyMemoryUsable(record));
  if (lowConfidence.length) actions.push(`Correct ${Math.min(lowConfidence.length, 5)} low-confidence company memories before buying enrichment data.`);
  if (!records.some((record) => record.imported_fields.length)) actions.push("Import a target-account CSV to seed known ICP context before the next outreach push.");
  if (!cacheHits.length) actions.push("Create a second lead from a known domain to confirm memory reuse before enabling paid lookups.");
  if (!actions.length) actions.push("Company memory is reusable. Keep paid enrichment as a manual fallback only.");
  return actions;
}

function inferredCrmFromMemory(record = {}) {
  const text = [
    record.notes,
    ...(record.tech_stack || []).map((item) => item.value),
    ...(record.signals || []).map((item) => item.value)
  ]
    .filter(Boolean)
    .join(" ")
    .toLowerCase();
  if (text.includes("salesforce")) return "salesforce";
  if (text.includes("pipedrive")) return "pipedrive";
  if (text.includes("hubspot")) return "hubspot";
  return "hubspot";
}

function pilotIntakePrefillUrl(baseUrl = "", record = {}) {
  const root = baseUrl.replace(/\/$/, "");
  const companyName = record.company_name || record.domain || "";
  const websiteUrl = record.website || normalizeWebsiteUrl("", record.domain);
  const businessNeed =
    record.signals?.[0]?.value ||
    `We want to test whether ${companyName || "this team"} can replace a static demo/contact form with an AI-built buyer profile before first rep follow-up.`;
  const params = new URLSearchParams({
    utm_source: "operator_outreach",
    utm_medium: "first_five_beta",
    companyName,
    websiteUrl,
    companySize: record.company_size || "",
    crm: inferredCrmFromMemory(record),
    businessNeed,
    targetPageUrl: websiteUrl ? `${websiteUrl.replace(/\/$/, "")}/demo` : "",
    timeline: "this_month",
    budgetStatus: "building_case",
    budgetRange: "30k_60k",
    authority: "decision_owner",
    notes: record.notes || "First-five beta target account."
  });
  return `${root}/pilot-intake?${params.toString()}`;
}

function firstFiveOutreachActivationProspectAction(baseUrl = "", record = {}) {
  const root = baseUrl.replace(/\/$/, "");
  const normalized = normalizeCompanyMemoryRecord(record);
  if (!normalized.domain) return null;
  const encodedDomain = encodeURIComponent(normalized.domain);
  const companyName = normalized.company_name || normalized.domain || "Target account";
  const websiteUrl = normalized.website || normalizeWebsiteUrl("", normalized.domain);
  const businessNeed =
    normalized.signals?.[0]?.value ||
    `Interested buyer reply from ${companyName}; qualify one page for the first-five Deal Threads beta.`;
  return {
    method: "POST",
    api_url: `${root}/api/v1/outreach/target-accounts/${encodedDomain}/activation-prospect`,
    html_action: `/outreach/target-accounts/${encodedDomain}/create-activation-prospect`,
    payload_preview: {
      contactName: "",
      contactEmail: "",
      replyNote: businessNeed,
      companyName,
      websiteUrl,
      targetPageUrl: websiteUrl ? `${websiteUrl.replace(/\/$/, "")}/demo` : "",
      timeline: "this_month",
      budgetStatus: "building_case",
      budgetRange: "30k_60k",
      authority: "influencer",
      buyerConfirmed: false,
      returnTo: "/outreach"
    },
    creates_activation_prospect: true,
    creates_beta_client: false,
    sends_from_server: false,
    transmits_external_crm: false,
    paid_provider_lookup: false,
    mutates_state: true,
    preview_only_on_get: true,
    confirmation_mode: "reply_captured_not_buyer_confirmed",
    required_operator_fields: ["contactEmail", "replyNote"],
    note:
      "Use after a real buyer reply. This creates a protected activation prospect and buyer-safe confirmation room, but does not create a beta client."
  };
}

function firstFiveOutreachStage(record, realClients = [], prospects = []) {
  const domain = normalizeDomain(record.domain);
  if (realClients.some((client) => normalizeDomain(client.domain || client.website_url) === domain)) return "beta_client";
  if (prospects.some((prospect) => normalizeDomain(prospect.domain || prospect.recommended_website_url) === domain)) return "activation_prospect";
  if (Number(record.lead_count || 0) > 0) return "crm_lead_captured";
  return "target_account";
}

function firstFiveOutreachPriority(record, stage) {
  let score = 50;
  const text = [
    record.industry,
    record.company_size,
    record.notes,
    ...(record.tech_stack || []).map((item) => item.value),
    ...(record.signals || []).map((item) => item.value)
  ]
    .filter(Boolean)
    .join(" ")
    .toLowerCase();
  if (/b2b|saas|fintech|software|revops|sales|crm|gtm/.test(text)) score += 18;
  if (/hubspot|salesforce|pipedrive|segment|marketo|pardot/.test(text)) score += 12;
  if (/funding|growth|hiring|tier 1|icp|demo|inbound|routing|speed/.test(text)) score += 14;
  if (/51-200|101-250|201-500|500|mid-market|midmarket/.test(text)) score += 10;
  if (stage === "activation_prospect") score += 18;
  if (stage === "beta_client") score -= 20;
  return Math.max(0, Math.min(100, score));
}

function firstFiveOutreachNextCheckAt(fromIso = now(), hours = 24) {
  const ms = new Date(fromIso || now()).getTime();
  return new Date((Number.isFinite(ms) ? ms : Date.now()) + hours * 60 * 60 * 1000).toISOString();
}

function firstFiveOutreachDeliveryAudit(record = {}) {
  const events = normalizeCompanyMemoryOutreachEvents(record.outreach_events || []);
  const latest = events[0] || null;
  const sentEvents = events.filter((event) => !["reply", "note"].includes(event.kind));
  const replyEvents = events.filter((event) => event.kind === "reply");
  const latestSent = sentEvents[0] || null;
  const latestReply = replyEvents[0] || null;
  const nextCheckAt = latestSent?.next_check_at || null;
  const nextCheckMs = nextCheckAt ? new Date(nextCheckAt).getTime() : null;
  const followUpDue = nextCheckMs !== null && Number.isFinite(nextCheckMs) && nextCheckMs <= Date.now();
  return {
    event_count: events.length,
    sent_count: sentEvents.length,
    reply_count: replyEvents.length,
    latest_event: latest,
    latest_sent_at: latestSent?.sent_at || null,
    latest_reply_at: latestReply?.sent_at || null,
    latest_channel: latestSent?.channel || latest?.channel || null,
    next_check_at: nextCheckAt,
    follow_up_due: Boolean(followUpDue),
    events: events.slice(0, 5)
  };
}

function firstFiveOutreachSendRoomStatus(stage, deliveryAudit) {
  if (stage === "beta_client") return "already_in_beta";
  if (stage === "activation_prospect") return "use_activation_outbox";
  if (deliveryAudit.follow_up_due) return "follow_up_due";
  if (deliveryAudit.sent_count > 0) return "manual_outreach_sent";
  return "manual_outreach_ready";
}

function firstFiveOutreachSendRoomStatusLabel(status) {
  return {
    already_in_beta: "Already in beta",
    use_activation_outbox: "Use activation outbox",
    follow_up_due: "Follow-up due",
    manual_outreach_sent: "Manual outreach sent",
    manual_outreach_ready: "Manual outreach ready"
  }[status] || humanizeEnum(status);
}

function markFirstFiveOutreachSent(domainValue, body = {}, actor = "operator", baseUrl = "") {
  const domain = normalizeDomain(domainValue);
  if (!domain) return { error: "domain_required", status: 400, message: "Target account domain is required." };
  const existing = state.companyMemory.get(domain);
  if (!existing) return { error: "company_memory_not_found", status: 404, message: "Target account memory was not found." };

  const record = normalizeCompanyMemoryRecord(existing);
  const sentAt = normalizeIsoDateTime(stringFromBody(body, "sentAt", "sent_at")) || now();
  const subject = stringFromBody(body, "subject") || `${record.company_name || record.domain}: replace the form with a rep-ready buyer profile?`;
  const recipients = uniqueStrings(parseFlexibleList(stringFromBody(body, "recipients", "recipient", "to")));
  const note = stringFromBody(body, "note", "notes") || "First-touch outreach sent manually from the first-five outreach room.";
  const channel = stringFromBody(body, "channel") || "email";
  const nextCheckAt = normalizeIsoDateTime(stringFromBody(body, "nextCheckAt", "next_check_at")) || firstFiveOutreachNextCheckAt(sentAt);
  const event = normalizeCompanyMemoryOutreachEvent({
    kind: stringFromBody(body, "kind", "type") || "first_touch",
    channel,
    recipients,
    subject,
    note,
    sent_by: actor,
    sends_from_server: false,
    sent_at: sentAt,
    created_at: now(),
    next_check_at: nextCheckAt
  });

  record.outreach_events = normalizeCompanyMemoryOutreachEvents([event, ...(record.outreach_events || [])]);
  record.updated_at = now();
  state.companyMemory.set(domain, normalizeCompanyMemoryRecord(record));
  track("first_five_outreach_marked_sent", {
    domain,
    recordId: record.id,
    eventId: event.id,
    channel: event.channel,
    recipients: event.recipients.length,
    actor
  });
  persistSoon();

  return {
    marked_sent: true,
    sends_from_server: false,
    mutates_state: true,
    event,
    memory: state.companyMemory.get(domain),
    outreach_account: firstFiveOutreachAccount(state.companyMemory.get(domain), { baseUrl })
  };
}

async function createFirstFiveOutreachActivationProspect(domainValue, body = {}, actor = "operator", baseUrl = "") {
  const domain = normalizeDomain(domainValue);
  if (!domain) return { error: "domain_required", status: 400, message: "Target account domain is required." };
  const existing = state.companyMemory.get(domain);
  if (!existing) return { error: "company_memory_not_found", status: 404, message: "Target account memory was not found." };

  const activation = realBetaActivationSummary(baseUrl);
  const existingProspect = (activation.prospects || []).find((prospect) => normalizeDomain(prospect.domain || prospect.recommended_website_url) === domain);
  if (existingProspect) {
    return {
      type: "deal_threads.target_account_activation_prospect.v1",
      created: false,
      already_activation_prospect: true,
      creates_activation_prospect: false,
      creates_beta_client: false,
      sends_from_server: false,
      transmits_external_crm: false,
      paid_provider_lookup: false,
      activation_prospect: existingProspect,
      outreach_account: firstFiveOutreachAccount(existing, {
        baseUrl,
        realClients: activation.real_beta_clients || [],
        prospects: activation.prospects || []
      })
    };
  }

  const realClient = (activation.real_beta_clients || []).find((client) => normalizeDomain(client.domain || client.website_url) === domain);
  if (realClient) {
    return { error: "already_beta_client", status: 409, message: "This target account is already a real beta client." };
  }

  const record = normalizeCompanyMemoryRecord(existing);
  const contactEmail = stringFromBody(body, "contactEmail", "contact_email", "email").toLowerCase();
  if (!contactEmail || !/^[^@\s]+@[^@\s]+\.[^@\s]+$/.test(contactEmail)) {
    return { error: "contact_email_required", status: 400, message: "Add the buyer work email from the interested reply." };
  }

  const companyName = record.company_name || record.domain || "Target account";
  const websiteUrl = record.website || normalizeWebsiteUrl("", record.domain);
  const replyNote =
    stringFromBody(body, "replyNote", "reply_note", "businessNeed", "message", "note", "notes") ||
    record.signals?.[0]?.value ||
    `Interested reply from ${companyName}; evaluate one high-intent page for the first-five Deal Threads beta.`;
  const buyerConfirmed = booleanFromAnyBody(body, "buyerConfirmed", "buyer_confirmed", "confirmationComplete", "confirmation_complete");
  const reportRecipients = buyerConfirmed
    ? normalizeOptionalList(firstDefined(body, "reportRecipients", "report_recipients")) || uniqueStrings([contactEmail])
    : [];
  const targetPageUrl =
    normalizeWebsiteUrl(stringFromBody(body, "targetPageUrl", "target_page_url") || (websiteUrl ? `${websiteUrl.replace(/\/$/, "")}/demo` : ""), domain) || websiteUrl;
  const intakeBody = {
    ...body,
    consentAccepted: true,
    contactName: stringFromBody(body, "contactName", "contact_name", "name"),
    contactEmail,
    role: stringFromBody(body, "role") || "Revenue or GTM owner",
    companyName,
    websiteUrl,
    companySize: record.company_size || stringFromBody(body, "companySize", "company_size"),
    crm: stringFromBody(body, "crm") || inferredCrmFromMemory(record),
    businessNeed: replyNote,
    targetPageUrl,
    timeline: stringFromBody(body, "timeline") || "this_month",
    budgetStatus: stringFromBody(body, "budgetStatus", "budget_status") || "building_case",
    budgetRange: stringFromBody(body, "budgetRange", "budget_range") || "30k_60k",
    authority: stringFromBody(body, "authority") || "influencer",
    implementationOwnerEmail: stringFromBody(body, "implementationOwnerEmail", "implementation_owner_email") || contactEmail,
    crmOwnerEmail: stringFromBody(body, "crmOwnerEmail", "crm_owner_email") || contactEmail,
    routingOwnerEmail: stringFromBody(body, "routingOwnerEmail", "routing_owner_email") || contactEmail,
    reportRecipients,
    pageUrl: "/outreach",
    notes: [
      `Protected operator captured an interested target-account reply for ${companyName}.`,
      stringFromBody(body, "notes", "note") || "",
      buyerConfirmed ? "Operator marked buyer details confirmed." : "Buyer confirmation still needs proof recipients and operator review before kickoff."
    ]
      .filter(Boolean)
      .join(" ")
  };
  const result = await createPublicPilotIntakeLead(intakeBody, null);
  if (result.error) return result;

  const capturedAt = now();
  const lead = result.lead;
  const closeWorkflow = normalizeProspectCloseWorkflow(
    {
      ...(lead.beta_client_conversion?.prospect_close || {}),
      status: buyerConfirmed && prospectCloseConfirmationComplete(lead.beta_client_conversion?.prospect_close || {}) ? "confirmed" : "collecting_details",
      buyer_confirmed_at: buyerConfirmed ? capturedAt : null,
      buyer_confirmed_by: buyerConfirmed ? actor : null,
      report_recipients: reportRecipients,
      confirmation_review: {
        source: "target_account_reply_capture",
        operator_review_complete: false,
        defaulted_required_fields_acknowledged: false,
        extracted_fields: 4,
        defaulted_required_fields: buyerConfirmed ? 0 : 1,
        missing_required_details: buyerConfirmed ? 0 : 1,
        checklist_status: buyerConfirmed ? "buyer_confirmed_by_operator" : "needs_buyer_confirmation",
        notes: replyNote,
        reviewed_by: actor,
        reviewed_at: capturedAt
      },
      notes: intakeBody.notes,
      updated_at: capturedAt
    },
    lead
  );
  lead.source = {
    ...(lead.source || {}),
    pilot_intake: false,
    target_account_outreach: true,
    target_account_reply: true,
    target_account_domain: domain,
    target_account_memory_id: record.id,
    page_url: "/outreach",
    captured_by: actor,
    captured_at: capturedAt
  };
  lead.beta_client_conversion = {
    ...(lead.beta_client_conversion || {}),
    prospect_close: closeWorkflow
  };
  lead.updated_at = capturedAt;
  state.leads.set(lead.id, lead);

  const replyEvent = normalizeCompanyMemoryOutreachEvent({
    kind: "reply",
    channel: stringFromBody(body, "channel") || "email",
    recipients: [contactEmail],
    subject: stringFromBody(body, "subject") || `${companyName} interested reply captured`,
    note: replyNote,
    sent_by: actor,
    sends_from_server: false,
    sent_at: capturedAt,
    created_at: capturedAt,
    next_check_at: activationFollowUpNextCheckAt(capturedAt)
  });
  const nextRecord = normalizeCompanyMemoryRecord({
    ...record,
    outreach_events: [replyEvent, ...(record.outreach_events || [])],
    latest_lead_id: lead.id,
    latest_lead_at: capturedAt,
    lead_count: Math.max(Number(record.lead_count || 0), 1),
    updated_at: capturedAt
  });
  state.companyMemory.set(domain, nextRecord);
  track("first_five_outreach_activation_prospect_created", {
    domain,
    leadProfileId: lead.id,
    contactEmail,
    buyerConfirmed,
    actor,
    sendsExternalEmail: false,
    transmitsExternalCrm: false,
    paidProviderLookup: false
  });
  persistSoon();

  const updatedActivation = realBetaActivationSummary(baseUrl);
  return {
    type: "deal_threads.target_account_activation_prospect.v1",
    created: true,
    creates_activation_prospect: true,
    creates_beta_client: false,
    sends_from_server: false,
    transmits_external_crm: false,
    paid_provider_lookup: false,
    buyer_confirmation_complete: prospectCloseConfirmationComplete(closeWorkflow),
    lead: leadListItem(lead),
    close_workflow: closeWorkflow,
    public_handoff: publicPilotIntakeHandoffPacket(closeWorkflow, baseUrl),
    activation_prospect: realBetaActivationProspectItem(lead),
    outreach_event: replyEvent,
    outreach_account: firstFiveOutreachAccount(nextRecord, {
      baseUrl,
      realClients: updatedActivation.real_beta_clients || [],
      prospects: updatedActivation.prospects || []
    })
  };
}

function firstFiveOutreachAccount(record, context = {}) {
  const baseUrl = context.baseUrl || "";
  const root = baseUrl.replace(/\/$/, "");
  const realClients = context.realClients || [];
  const prospects = context.prospects || [];
  const normalized = normalizeCompanyMemoryRecord(record);
  const stage = firstFiveOutreachStage(normalized, realClients, prospects);
  const score = firstFiveOutreachPriority(normalized, stage);
  const companyName = normalized.company_name || normalized.domain || "Target account";
  const website = normalized.website || normalizeWebsiteUrl("", normalized.domain);
  const signal = normalized.signals?.[0]?.value || normalized.notes || "Imported target account for the first-five beta cohort.";
  const crm = inferredCrmFromMemory(normalized);
  const pilotIntakeUrl = pilotIntakePrefillUrl(baseUrl, normalized);
  const publicLinks = {
    pilot_intake: pilotIntakeUrl,
    pilot_close_kit: `${root}/pilot-close-kit`,
    business_case: `${root}/business-case`,
    approval_room: `${root}/pilot-approval-room`,
    comparison: `${root}/compare`,
    proof_preview: `${root}/proof-preview`,
    security: `${root}/security`
  };
  const copy = {
    email_subject: `${companyName}: replace the form with a rep-ready buyer profile?`,
    email_body: [
      `Hi there - quick idea for ${companyName}.`,
      "",
      `Teams with ${displayCrm(crm)} and high-value inbound leads usually lose time between form submit and first rep touch because the profile still has to be researched manually.`,
      "",
      `Deal Threads replaces one demo/contact form with an AI chat that captures intent, timeline, budget, CRM context, and providerless company signals before the rep follows up. The first-five beta is intentionally narrow: one page, 14 days, dry-run/manual CRM by default, and no paid enrichment calls unless the proof says we need them.`,
      "",
      `Would it be worth testing this on one high-intent page and comparing the first profiles against your current form baseline?`,
      "",
      `Pilot intake: ${pilotIntakeUrl}`
    ].join("\n"),
    linkedin_opener: `Quick idea for ${companyName}: test replacing one high-intent form with an AI buyer-profile flow, then compare rep-ready context and first-touch speed against the old form over 14 days.`
  };
  const recipientCandidates = uniqueStrings([
    normalized.contact_email,
    normalized.owner_email,
    normalized.email,
    ...emailsFromText(
      [
        normalized.notes,
        ...(normalized.signals || []).map((item) => item.value),
        ...(normalized.tech_stack || []).map((item) => item.value)
      ].join(" ")
    )
  ]);
  const manualMailtoUrl = mailtoDraftUrl({ recipients: recipientCandidates, subject: copy.email_subject, body: copy.email_body });
  const deliveryAudit = firstFiveOutreachDeliveryAudit(normalized);
  const sendRoomStatus = firstFiveOutreachSendRoomStatus(stage, deliveryAudit);
  const sendRoomStatusLabel = firstFiveOutreachSendRoomStatusLabel(sendRoomStatus);
  const encodedDomain = encodeURIComponent(normalized.domain || "");
  const manualSentAction =
    normalized.domain && !["beta_client", "activation_prospect"].includes(stage)
      ? {
          method: "POST",
          api_url: `${root}/api/v1/outreach/target-accounts/${encodedDomain}/sent`,
          html_action: `/outreach/target-accounts/${encodedDomain}/mark-sent`,
          payload_preview: {
            recipients: recipientCandidates.join(", "),
            subject: copy.email_subject,
            channel: "email",
            note: "First-touch outreach sent manually from the first-five outreach room.",
            returnTo: "/outreach"
          },
          sends_from_server: false,
          mutates_state: true,
          preview_only_on_get: true
        }
      : null;
  const activationProspectAction =
    normalized.domain && !["beta_client", "activation_prospect"].includes(stage) ? firstFiveOutreachActivationProspectAction(baseUrl, normalized) : null;
  return {
    domain: normalized.domain,
    company_name: companyName,
    website,
    industry: normalized.industry,
    company_size: normalized.company_size,
    crm,
    stage,
    priority_score: score,
    fit_reasons: [
      normalized.company_size ? `Mid-market size signal: ${normalized.company_size}` : null,
      normalized.industry ? `Industry: ${normalized.industry}` : null,
      normalized.tech_stack?.length ? `Known stack: ${normalized.tech_stack.slice(0, 3).map((item) => item.value).join(", ")}` : null,
      normalized.signals?.length ? `Signal: ${normalized.signals.slice(0, 2).map((item) => item.value).join(", ")}` : null
    ].filter(Boolean),
    recommended_action:
      stage === "beta_client"
        ? "Work the beta launch wizard and proof loop."
        : stage === "activation_prospect"
          ? "Use /activation to send the close packet or buyer-confirmation nudge."
          : "Send the first-touch email and route the buyer to the prefilled pilot-intake link.",
    copy,
    manual_mailto_url: manualMailtoUrl,
    send_room: {
      status: sendRoomStatus,
      status_label: sendRoomStatusLabel,
      subject: copy.email_subject,
      body: copy.email_body,
      linkedin_opener: copy.linkedin_opener,
      recipients: recipientCandidates,
      recipient_hint: recipientCandidates.length
        ? "Review the detected recipient before sending."
        : "Add the RevOps, VP Sales, revenue leader, or GTM owner email before sending.",
      manual_mailto_url: manualMailtoUrl,
      has_manual_mailto_draft: manualMailtoUrl.startsWith("mailto:"),
      opens_local_email_draft: manualMailtoUrl.startsWith("mailto:"),
      send_action: null,
      manual_sent_action: manualSentAction,
      activation_prospect_action: activationProspectAction,
      delivery_audit: deliveryAudit,
      buyer_safe_links: publicLinks,
      operator_links: {
        outreach_room: `${root}/outreach`,
        activation: `${root}/activation`,
        target_import: `${root}/enrichment`,
        markdown: `${root}/api/v1/outreach/first-five?format=markdown`
      },
      post_send_plan: {
        status: "ready_after_manual_outreach",
        status_label: "Ready after manual outreach",
        next_check_at: deliveryAudit.next_check_at,
        watch_room: `${root}/outreach`,
        reply_parser: activationProspectAction?.api_url || `${root}/pilot-intake`,
        manual_sent_recorder: manualSentAction,
        reply_capture_action: activationProspectAction,
        after_send_actions: [
          manualSentAction
            ? "Record manual mailbox or LinkedIn delivery with the POST-only outreach recorder after the opener leaves the mailbox."
            : "Use the correct protected room for this account stage before recording outreach.",
          activationProspectAction
            ? "Capture an interested buyer reply with the POST-only activation prospect recorder so the account enters activation without retyping the public form."
            : "Use the current activation room for this account stage before creating another prospect.",
          "Use the prefilled pilot-intake link only when the buyer wants to submit the request themselves.",
          deliveryAudit.follow_up_due
            ? "Follow up now; the next-check time has passed without a recorded conversion."
            : "Check the outreach room at the next-check time before sending another touch.",
          "If the buyer reply lacks proof recipients or owner details, keep the prospect in buyer-confirmation follow-up before kickoff.",
          "Use /activation only after the buyer confirms target page, owner, CRM/routing context, report recipients, and baseline.",
          "Keep paid enrichment disabled until rep feedback proves a missing field changes first-touch quality."
        ],
        acceptance_criteria: [
          "Target buyer receives the first-touch email or LinkedIn opener.",
          "Manual outreach delivery is recorded if the message was sent outside Deal Threads.",
          "Interested buyer reply is captured through the protected POST-only activation prospect recorder or buyer-submitted pilot intake.",
          "Qualified intake creates an activation prospect instead of a beta client.",
          "No beta client is created until buyer confirmation is captured.",
          "No paid enrichment is run during first-touch outreach."
        ],
        next_gate: "qualified_activation_prospect",
        paid_enrichment_needed_now: 0
      },
      proof_effect: {
        current_market_blocker: "first_five_pipeline",
        next_gate_unlocked:
          deliveryAudit.sent_count > 0
            ? "audited target-account outreach can be followed up until the buyer enters pilot intake."
            : "qualified activation prospect ready for close packet or buyer-confirmation chase.",
        paid_enrichment_needed_now: 0
      },
      safety: {
        read_only_get: true,
        sends_external_email_on_get: false,
        mutates_buyer_state_on_get: false,
        creates_beta_client_on_get: false,
        transmits_external_crm_on_get: false,
        paid_provider_lookup_by_default: false,
        live_proof_claimed: false,
        send_requires_post: false,
        manual_record_requires_post: Boolean(manualSentAction),
        activation_prospect_requires_post: Boolean(activationProspectAction)
      }
    },
    links: publicLinks,
    source: {
      memory_id: normalized.id,
      imported_fields: normalized.imported_fields,
      confidence: normalized.confidence,
      outreach_events: normalized.outreach_events,
      updated_at: normalized.updated_at
    }
  };
}

function firstFiveOutreachSequence(baseUrl = "") {
  const root = baseUrl.replace(/\/$/, "");
  return [
    {
      day: "Day 0",
      step: "Target account opener",
      goal: "Start the one-page pilot conversation.",
      asset: `${root}/pilot-close-kit`,
      operator_note: "Send the account-specific email body and include the prefilled pilot-intake link."
    },
    {
      day: "Day 1",
      step: "Business case follow-up",
      goal: "Give RevOps or sales leadership a budget frame.",
      asset: `${root}/business-case`,
      operator_note: "Anchor on manual research time, first-touch speed, and the $2,500/month managed pilot."
    },
    {
      day: "Day 3",
      step: "Buying committee forward",
      goal: "Help the champion route the decision internally.",
      asset: `${root}/pilot-approval-room`,
      operator_note: "Send stakeholder-specific links for executive, RevOps, website, CRM, and security/procurement owners."
    },
    {
      day: "Day 5",
      step: "Proof preview",
      goal: "Show exactly what the 14-day report will prove without claiming live results yet.",
      asset: `${root}/proof-preview`,
      operator_note: "Move interested buyers into /activation only after target page, owners, recipients, and baseline are confirmed."
    }
  ];
}

function firstFiveOutreachSummary(baseUrl = "", searchParams = new URLSearchParams()) {
  const activation = realBetaActivationSummary(baseUrl, searchParams);
  const importedMemory = companyMemorySummary(allLeadsSorted(), { segment: "imported", q: searchParams.get("q") || "" }, { limit: 50 });
  const fallbackMemory = importedMemory.records.length
    ? importedMemory
    : companyMemorySummary(allLeadsSorted(), { q: searchParams.get("q") || "" }, { limit: 50 });
  const accounts = fallbackMemory.records
    .map((record) =>
      firstFiveOutreachAccount(record, {
        baseUrl,
        realClients: activation.real_beta_clients || [],
        prospects: activation.prospects || []
      })
    )
    .sort((a, b) => b.priority_score - a.priority_score)
    .slice(0, 25);
  const targetClientCount = PILOT_TARGET_CLIENTS;
  const realBetaClients = Number(activation.summary.real_beta_clients || 0);
  const qualifiedProspects = Number(activation.summary.qualified_prospects || 0);
  const remainingSlots = Math.max(0, targetClientCount - realBetaClients);
  const status = realBetaClients >= targetClientCount ? "cohort_full" : qualifiedProspects || accounts.length ? "pipeline_active" : "needs_targets";
  const recommendedActions = [];
  if (!accounts.length) recommendedActions.push("Import a target-account CSV in /enrichment so the first-five outreach room has named accounts.");
  const outreachFollowupsDue = accounts.filter((account) => account.send_room?.delivery_audit?.follow_up_due).length;
  const outreachSentRecords = accounts.reduce((total, account) => total + Number(account.send_room?.delivery_audit?.sent_count || 0), 0);
  const outreachReplyRecords = accounts.reduce((total, account) => total + Number(account.send_room?.delivery_audit?.reply_count || 0), 0);
  if (outreachFollowupsDue > 0) {
    recommendedActions.push(`Follow up on ${outreachFollowupsDue} target account${outreachFollowupsDue === 1 ? "" : "s"} with a recorded opener past its next-check time.`);
  }
  if (remainingSlots > 0 && qualifiedProspects < remainingSlots) {
    recommendedActions.push(`Create ${remainingSlots - qualifiedProspects} more qualified activation prospect${remainingSlots - qualifiedProspects === 1 ? "" : "s"} from pilot-intake or CRM conversion.`);
  }
  if (qualifiedProspects > 0) recommendedActions.push("Use /activation to send close packets, confirmation nudges, and kickoff confirmed buyers.");
  recommendedActions.push("Keep paid enrichment disabled until rep feedback identifies a missing field that changes conversion.");
  const featuredAccount = accounts.find((account) => account.send_room?.status === "manual_outreach_ready") || accounts[0] || null;

  return {
    type: "deal_threads.first_five_outreach.v1",
    generated_at: now(),
    status,
    status_label: humanizeEnum(status),
    target_client_count: targetClientCount,
    summary: {
      real_beta_clients: realBetaClients,
      remaining_beta_slots: remainingSlots,
      qualified_activation_prospects: qualifiedProspects,
      imported_target_accounts: importedMemory.records.length,
      visible_target_accounts: accounts.length,
      outreach_send_rooms_ready: accounts.filter((account) => account.send_room?.status === "manual_outreach_ready").length,
      manual_mailto_drafts: accounts.filter((account) => account.send_room?.has_manual_mailto_draft).length,
      manual_sent_recorders: accounts.filter((account) => account.send_room?.manual_sent_action).length,
      activation_reply_capture_actions: accounts.filter((account) => account.send_room?.activation_prospect_action).length,
      outreach_sent_records: outreachSentRecords,
      outreach_reply_records: outreachReplyRecords,
      outreach_followups_due: outreachFollowupsDue,
      paid_lookups_recommended_now: 0,
      live_proof_ready: activation.live_proof_gate?.live_ready || false
    },
    first_account: accounts[0]
      ? {
          domain: featuredAccount.domain,
          company_name: featuredAccount.company_name,
          manual_mailto_url: featuredAccount.manual_mailto_url,
          send_room: {
            status: featuredAccount.send_room.status,
            manual_mailto_url: featuredAccount.send_room.manual_mailto_url,
            manual_sent_action: featuredAccount.send_room.manual_sent_action,
            activation_prospect_action: featuredAccount.send_room.activation_prospect_action,
            delivery_audit: featuredAccount.send_room.delivery_audit,
            recipient_hint: featuredAccount.send_room.recipient_hint,
            post_send_plan: featuredAccount.send_room.post_send_plan,
            proof_effect: featuredAccount.send_room.proof_effect
          }
        }
      : null,
    target_accounts: accounts,
    outreach_sequence: firstFiveOutreachSequence(baseUrl),
    recommended_actions: recommendedActions,
    links: {
      operator_room: `${baseUrl.replace(/\/$/, "")}/outreach`,
      activation: `${baseUrl.replace(/\/$/, "")}/activation`,
      pilot_intake: `${baseUrl.replace(/\/$/, "")}/pilot-intake`,
      target_import: `${baseUrl.replace(/\/$/, "")}/enrichment`,
      sales_enablement: `${baseUrl.replace(/\/$/, "")}/sales-enablement`,
      markdown: `${baseUrl.replace(/\/$/, "")}/api/v1/outreach/first-five?format=markdown`
    },
    public_safety: {
      protected_operator_surface: true,
      mutates_buyer_state_on_get: false,
      sends_external_email_on_get: false,
      creates_beta_client_on_get: false,
      transmits_external_crm_on_get: false,
      paid_provider_lookup_by_default: false
    }
  };
}

