function minutesToFirstContact(lead) {
  const outcome = ensureLeadOutcome(lead);
  const outcomeMinutes = minutesBetween(lead.created_at, outcome.first_contacted_at);
  if (outcomeMinutes !== null) return outcomeMinutes;
  const workflow = ensureLeadWorkflow(lead);
  const contactStages = new Set(["contacted", "meeting_booked", "closed_won", "closed_lost"]);
  const activity = [...workflow.activity].reverse().find((item) => contactStages.has(item.stage));
  if (!activity) return null;
  return minutesBetween(lead.created_at, activity.created_at);
}

function minutesBetween(startIso, endIso) {
  if (!startIso || !endIso) return null;
  const start = new Date(startIso).getTime();
  const end = new Date(endIso).getTime();
  if (Number.isNaN(start) || Number.isNaN(end)) return null;
  return Math.max(0, Number(((end - start) / 60000).toFixed(1)));
}

function leadListItem(lead) {
  const workflow = ensureLeadWorkflow(lead);
  const outcome = ensureLeadOutcome(lead);
  const repAlert = repAlertForLead(lead.id);
  const crmDelivery = crmDeliveryForLead(lead.id);
  return {
    id: lead.id,
    created_at: lead.created_at,
    updated_at: lead.updated_at,
    status: lead.status,
    contact: lead.contact,
    company: lead.company,
    beta_client_id: lead.source?.beta_client_id || null,
    score: lead.score,
    routing: lead.routing,
    crm: lead.crm,
    workflow,
    outcome,
    rep_alert: repAlert ? repAlertListItem(repAlert) : null,
    crm_delivery: crmDelivery ? crmDeliveryListItem(crmDelivery) : null,
    crm_handoff: lead.crm_handoff || null,
    enrichment_review: ensureEnrichmentReview(lead),
    sla_status: workflowSlaStatus(lead),
    summary: lead.summary?.rep_summary || ""
  };
}

function hubSpotQueueItem(lead) {
  const preview = hubSpotSyncPreview(lead);
  return {
    id: lead.id,
    created_at: lead.created_at,
    updated_at: lead.updated_at,
    contact: {
      name: lead.contact?.name || "Unknown visitor",
      email: lead.contact?.email || null
    },
    company: {
      name: lead.company?.name || "Unknown company",
      domain: lead.company?.domain || null
    },
    priority: lead.score?.priority || "unknown",
    crm_status: lead.crm?.sync_status || "pending",
    crm_mode: lead.crm?.mode || hubSpotMode(),
    last_error: lead.crm?.last_error || null,
    eligible: preview.eligible,
    blockers: preview.blockers,
    operation_count: preview.operations.length,
    preview_url: `/api/v1/leads/${lead.id}/hubspot-preview`,
    sync_url: `/api/v1/leads/${lead.id}/sync`
  };
}

function hubSpotSyncQueue(leads = allLeadsSorted()) {
  const items = leads
    .filter((lead) => !["synced"].includes(lead.crm?.sync_status))
    .map(hubSpotQueueItem);
  const eligibleItems = items.filter((item) => item.eligible);
  const blockedItems = items.filter((item) => !item.eligible);
  return {
    generated_at: now(),
    mode: hubSpotMode(),
    token_configured: hubSpotMode() === "live",
    dry_run: hubSpotMode() !== "live",
    total_leads: leads.length,
    unsynced_count: items.length,
    eligible_count: eligibleItems.length,
    blocked_count: blockedItems.length,
    synced_count: leads.filter((lead) => lead.crm?.sync_status === "synced").length,
    failed_count: leads.filter((lead) => lead.crm?.sync_status === "failed").length,
    stubbed_count: leads.filter((lead) => lead.crm?.sync_status === "stubbed").length,
    pending_count: leads.filter((lead) => lead.crm?.sync_status === "pending").length,
    property_readiness: state.hubspotReadiness?.summary || null,
    items
  };
}

async function runHubSpotSyncQueue(body = {}, actor = "operator") {
  const limit = Math.max(1, Math.min(50, Math.round(Number(body.limit || body.max || 25) || 25)));
  const requestedDryRun = body.dryRun !== undefined || body.dry_run !== undefined ? booleanFromBody(body, body.dryRun !== undefined ? "dryRun" : "dry_run") : true;
  const dryRun = hubSpotMode() !== "live" || requestedDryRun;
  const queue = hubSpotSyncQueue();
  const candidates = queue.items.filter((item) => item.eligible).slice(0, limit);
  const result = {
    generated_at: now(),
    mode: hubSpotMode(),
    dry_run: dryRun,
    limit,
    eligible_count: queue.eligible_count,
    blocked_count: queue.blocked_count,
    considered: candidates.length,
    would_sync: dryRun ? candidates.length : 0,
    attempted: 0,
    synced: 0,
    failed: 0,
    results: []
  };

  for (const item of candidates) {
    const lead = state.leads.get(item.id);
    if (!lead) continue;

    if (dryRun) {
      result.results.push({
        leadProfileId: lead.id,
        status: "would_sync",
        crm_status: lead.crm?.sync_status || "pending",
        contact_email: lead.contact?.email || null,
        company_domain: lead.company?.domain || null,
        preview_url: item.preview_url
      });
      continue;
    }

    result.attempted += 1;
    track("crm_sync_started", { leadProfileId: lead.id, mode: hubSpotMode(), actor, queue: true });
    lead.crm = await syncLeadToHubSpot(lead);
    lead.updated_at = now();
    track(lead.crm.sync_status === "synced" ? "crm_sync_completed" : "crm_sync_failed", {
      leadProfileId: lead.id,
      status: lead.crm.sync_status,
      mode: lead.crm.mode,
      actor,
      queue: true,
      error: lead.crm.last_error
    });

    if (lead.crm.sync_status === "synced") result.synced += 1;
    if (lead.crm.sync_status === "failed") result.failed += 1;
    result.results.push({
      leadProfileId: lead.id,
      status: lead.crm.sync_status,
      crm: lead.crm
    });
  }

  if (!dryRun && result.attempted) persistSoon();
  return result;
}

function betaLaunchReadinessSummary(baseUrl = "") {
  const leads = allLeadsSorted();
  const beta = betaClientSummary(baseUrl);
  const pilot = pilotCommandSummary(baseUrl);
  const enrichment = enrichmentQualitySummary(leads);
  const hubSpotQueue = hubSpotSyncQueue(leads);
  const llm = llmReadinessSummary();
  const backupValidation = validateStateBackup(stateBackupExport());
  const reportSummary = reportDeliverySummary();
  const repAlerts = repAlertSummary();
  const crmDeliveries = crmDeliverySummary();
  const emailAdapter = reportEmailAdapterStatus();
  const crmAdapter = crmDeliveryAdapterStatus();
  const checks = [];

  addReadinessCheck(checks, {
    section: "runtime",
    key: "admin_auth",
    label: "Admin authentication",
    status: ADMIN_PASSWORD ? "pass" : "blocker",
    detail: ADMIN_PASSWORD ? "Protected operator endpoints require Basic Auth." : "ADMIN_PASSWORD is not configured.",
    action: ADMIN_PASSWORD ? null : "Set ADMIN_PASSWORD before exposing any beta environment."
  });
  addReadinessCheck(checks, {
    section: "runtime",
    key: "data_store",
    label: "Persistent data store",
    status: DATA_STORE_MODE === "sqlite" ? "pass" : "warning",
    detail:
      DATA_STORE_MODE === "sqlite"
        ? `SQLite persistence is active at ${DATA_STORE_LOCATION}.`
        : `JSON persistence is active at ${DATA_STORE_LOCATION}. This is fine locally; SQLite with a mounted volume is preferred for beta deployment.`,
    action: DATA_STORE_MODE === "sqlite" ? null : "Use DEAL_THREADS_DATA_STORE=sqlite with a persistent Railway volume before multi-client beta traffic."
  });
  addReadinessCheck(checks, {
    section: "runtime",
    key: "state_backup",
    label: "State backup restore readiness",
    status: backupValidation.restore_ready ? "pass" : "blocker",
    detail: backupValidation.restore_ready
      ? "The current state backup validates and can be restored with explicit confirmation."
      : backupValidation.errors.join("; ") || "Current state backup is not restore-ready.",
    action: backupValidation.restore_ready ? null : "Fix backup validation errors before deploy or migration."
  });

  addReadinessCheck(checks, {
    section: "pilot",
    key: "beta_clients",
    label: "Beta client records",
    status: beta.count > 0 ? (beta.count >= PILOT_TARGET_CLIENTS ? "pass" : "warning") : "blocker",
    detail: `${beta.count}/${PILOT_TARGET_CLIENTS} beta clients configured.`,
    action: beta.count ? "Keep adding beta clients until the five-client cohort is full." : "Create at least one beta client before launch."
  });
  addReadinessCheck(checks, {
    section: "pilot",
    key: "client_readiness",
    label: "Client readiness blockers",
    status: beta.summary.readiness_blocked ? "blocker" : beta.summary.ready_to_send_snippet ? "pass" : beta.count ? "warning" : "blocker",
    detail: `${beta.summary.ready_to_send_snippet} ready for snippet, ${beta.summary.ready_for_live_beta} ready for live beta, ${beta.summary.readiness_blocked} blocked.`,
    action: beta.summary.readiness_blocked
      ? "Open /beta-clients and clear the first client readiness blocker."
      : beta.summary.ready_to_send_snippet
        ? null
        : beta.count
          ? "Finish client profile, widget, routing, report, and CRM setup before sending snippets."
          : "Create at least one beta client before checking client readiness."
  });
  addReadinessCheck(checks, {
    section: "pilot",
    key: "test_leads",
    label: "Beta test lead",
    status: beta.summary.total_leads > 0 ? "pass" : "blocker",
    detail: `${beta.summary.total_leads} beta-attributed leads captured.`,
    action: beta.summary.total_leads ? null : "Create one test lead from a beta-client install snippet before launch."
  });
  addReadinessCheck(checks, {
    section: "pilot",
    key: "installed_clients",
    label: "Installed client snippets",
    status: pilot.installed_clients > 0 ? "pass" : "warning",
    detail: `${pilot.installed_clients} clients marked installed/live/complete.`,
    action: pilot.installed_clients ? null : "Mark install progress after the first beta script tag loads."
  });
  addReadinessCheck(checks, {
    section: "pilot",
    key: "overdue_followup",
    label: "Overdue beta follow-up",
    status: pilot.leads.overdue ? "warning" : "pass",
    detail: `${pilot.leads.overdue} beta leads are overdue.`,
    action: pilot.leads.overdue ? "Clear overdue beta follow-up before announcing pilot readiness." : null
  });

  addReadinessCheck(checks, {
    section: "crm",
    key: "hubspot_mode",
    label: "HubSpot handoff mode",
    status: hubSpotMode() === "live" ? "pass" : "warning",
    detail:
      hubSpotMode() === "live"
        ? "HubSpot token is configured for live sync."
        : "HubSpot is stubbed; preview and queue dry-runs are available.",
    action: hubSpotMode() === "live" ? null : "Connect a HubSpot sandbox token when ready to test real CRM sync."
  });
  addReadinessCheck(checks, {
    section: "crm",
    key: "hubspot_queue",
    label: "HubSpot queue eligibility",
    status: hubSpotQueue.blocked_count ? "blocker" : "pass",
    detail: `${hubSpotQueue.eligible_count} eligible unsynced leads, ${hubSpotQueue.blocked_count} blocked.`,
    action: hubSpotQueue.blocked_count ? "Fix blocked HubSpot previews before queue sync." : null
  });
  addReadinessCheck(checks, {
    section: "crm",
    key: "hubspot_properties",
    label: "HubSpot property readiness",
    status: state.hubspotReadiness ? (state.hubspotReadiness.summary?.failed ? "blocker" : "warning") : "warning",
    detail: state.hubspotReadiness
      ? `${state.hubspotReadiness.summary.missing} missing, ${state.hubspotReadiness.summary.inaccessible || 0} inaccessible, ${state.hubspotReadiness.summary.failed} failed in ${state.hubspotReadiness.mode} mode.`
      : "HubSpot property check has not run in this session.",
    action: state.hubspotReadiness?.summary?.inaccessible
      ? "Add the missing HubSpot object scopes, then rerun the property check."
      : state.hubspotReadiness
        ? "Run live property setup in a sandbox before production sync."
        : "Run the HubSpot property check from /admin."
  });
  addReadinessCheck(checks, {
    section: "crm",
    key: "rep_alerts",
    label: "Rep alert handoff",
    status: repAlerts.summary.failed ? "blocker" : repAlerts.summary.queued ? "warning" : repAlerts.summary.sent ? "pass" : beta.summary.total_leads ? "warning" : "pass",
    detail: `${repAlerts.summary.queued} queued, ${repAlerts.summary.sent} sent, ${repAlerts.summary.failed} failed rep alerts.`,
    action: repAlerts.summary.failed
      ? "Resolve failed rep alerts from /admin."
      : repAlerts.summary.queued
        ? "Send queued rep alerts before judging speed-to-lead readiness."
        : beta.summary.total_leads && !repAlerts.summary.sent
          ? "Create and send a rep alert for at least one test lead."
          : null
  });
  addReadinessCheck(checks, {
    section: "crm",
    key: "generic_crm_delivery",
    label: "Generic CRM delivery",
    status: crmDeliveries.summary.failed
      ? "blocker"
      : crmDeliveries.summary.queued
        ? "warning"
        : crmDeliveries.summary.sent
          ? "pass"
          : beta.summary.total_leads
            ? "warning"
            : "pass",
    detail: `${crmDeliveries.summary.queued} queued, ${crmDeliveries.summary.sent} sent, ${crmDeliveries.summary.failed} failed CRM deliveries.`,
    action: crmDeliveries.summary.failed
      ? "Resolve failed CRM deliveries from /admin."
      : crmDeliveries.summary.queued
        ? "Send queued CRM deliveries in dry-run mode before calling beta handoff ready."
        : beta.summary.total_leads && !crmDeliveries.summary.sent
          ? "Send one generic CRM delivery for a beta test lead."
          : null
  });

  addReadinessCheck(checks, {
    section: "intake",
    key: "llm_extraction",
    label: "OpenAI extraction",
    status: llm.api_key_configured ? "pass" : "warning",
    detail: llm.api_key_configured ? `Live extraction is configured with ${llm.model}.` : "Heuristic extraction is active and safe for demos.",
    action: llm.api_key_configured ? null : "Run the OpenAI extraction probe with a real key before high-volume beta traffic."
  });
  addReadinessCheck(checks, {
    section: "enrichment",
    key: "paid_provider_spend",
    label: "Paid enrichment spend",
    status: enrichment.cost.paid_provider_spend === 0 ? "pass" : "warning",
    detail: `$${enrichment.cost.paid_provider_spend.toFixed(2)} paid-provider spend recorded.`,
    action: enrichment.cost.paid_provider_spend === 0 ? null : "Review paid-provider calls and confirm they changed rep behavior."
  });
  addReadinessCheck(checks, {
    section: "enrichment",
    key: "review_queue",
    label: "High-priority enrichment review",
    status: enrichment.quality.high_priority_review_candidates ? "warning" : "pass",
    detail: `${enrichment.quality.high_priority_review_candidates} high-priority enrichment reviews open.`,
    action: enrichment.quality.high_priority_review_candidates ? "Close high-priority enrichment reviews before relying on profile quality." : null
  });
  addReadinessCheck(checks, {
    section: "reporting",
    key: "report_email",
    label: "Report delivery adapter",
    status: emailAdapter.transmits_external_email ? "pass" : "warning",
    detail: emailAdapter.transmits_external_email ? "Report email webhook is configured." : "Report delivery is dry-run/manual.",
    action: emailAdapter.transmits_external_email ? null : "Manual report delivery is fine for early beta; add webhook only after sending volume is known."
  });
  addReadinessCheck(checks, {
    section: "reporting",
    key: "failed_reports",
    label: "Failed report deliveries",
    status: reportSummary.summary.failed ? "blocker" : "pass",
    detail: `${reportSummary.summary.failed} failed report deliveries.`,
    action: reportSummary.summary.failed ? "Resolve failed report deliveries before launch." : null
  });

  const blockerCount = checks.filter((check) => check.status === "blocker").length;
  const warningCount = checks.filter((check) => check.status === "warning").length;
  const passCount = checks.filter((check) => check.status === "pass").length;

  return {
    generated_at: now(),
    status: blockerCount ? "blocked" : warningCount ? "needs_attention" : "ready",
    summary: {
      pass: passCount,
      warning: warningCount,
      blocker: blockerCount,
      total: checks.length
    },
    cohort: {
      target_clients: PILOT_TARGET_CLIENTS,
      beta_clients: beta.count,
      installed_clients: pilot.installed_clients,
      live_clients: pilot.live_clients,
      beta_leads: beta.summary.total_leads,
      rep_alerts_queued: repAlerts.summary.queued,
      rep_alerts_sent: repAlerts.summary.sent
    },
    runtime: {
      data_store: {
        mode: DATA_STORE_MODE,
        location: DATA_STORE_LOCATION
      },
      admin_auth: ADMIN_PASSWORD ? "enabled" : "missing",
      llm_mode: llm.mode,
      hubspot_mode: hubSpotMode(),
      enrichment_mode: internalEnrichmentMode(),
      report_email_mode: emailAdapter.mode,
      rep_alert_email_mode: emailAdapter.mode,
      crm_delivery_mode: crmAdapter.mode,
      crm_delivery_external: crmAdapter.transmits_external_crm
    },
    checks,
    next_actions: checks.filter((check) => check.status !== "pass" && check.action).map((check) => check.action)
  };
}

function midMarketReadinessSummary(baseUrl = "", searchParams = new URLSearchParams()) {
  const period = parseReportWindow(searchParams);
  const reportParams = new URLSearchParams({ days: String(period.days) });
  const launch = betaLaunchReadinessSummary(baseUrl);
  const proof = betaProofSummary(reportParams);
  const liveGate = liveProofGate(reportParams);
  const report = buildBetaReport(reportParams);
  const enrichment = enrichmentQualitySummary(allLeadsSorted());
  const buildPlan = providerlessEnrichmentBuildPlan(enrichment);
  const backupValidation = validateStateBackup(stateBackupExport());
  const scenario = demoScenarioStatus();
  const repAlerts = repAlertSummary();
  const crmDeliveries = crmDeliverySummary();
  const emailAdapter = reportEmailAdapterStatus();
  const crmAdapter = crmDeliveryAdapterStatus();
  const checks = [];

  addReadinessCheck(checks, {
    section: "proof",
    key: "beta_cohort",
    label: "Beta cohort configured",
    status: launch.cohort.beta_clients >= PILOT_TARGET_CLIENTS ? "pass" : launch.cohort.beta_clients ? "warning" : "blocker",
    detail: `${launch.cohort.beta_clients}/${PILOT_TARGET_CLIENTS} target beta clients configured.`,
    action: launch.cohort.beta_clients ? "Add remaining beta clients until the proof cohort is full." : "Create at least one beta client before a buyer demo."
  });
  addReadinessCheck(checks, {
    section: "proof",
    key: "proof_baselines",
    label: "Old-form baselines",
    status: proof.summary.client_count && proof.summary.clients_with_baseline === proof.summary.client_count ? "pass" : proof.summary.clients_with_baseline ? "warning" : "blocker",
    detail: `${proof.summary.clients_with_baseline}/${proof.summary.client_count} clients have old-form baseline metrics.`,
    action: proof.summary.clients_with_baseline === proof.summary.client_count && proof.summary.client_count ? null : "Add old-form first-touch and conversion baselines for every beta client."
  });
  addReadinessCheck(checks, {
    section: "proof",
    key: "rep_feedback",
    label: "Rep profile feedback",
    status: proof.summary.rep_feedback_reviewed ? (proof.summary.rep_feedback_missing_context || proof.summary.rep_feedback_needs_rework ? "warning" : "pass") : proof.summary.total_leads ? "warning" : "blocker",
    detail: `${proof.summary.rep_feedback_reviewed} profiles reviewed by reps; ${proof.summary.rep_feedback_helpful} helpful, ${proof.summary.rep_feedback_missing_context} missing context.`,
    action: proof.summary.rep_feedback_reviewed ? "Use missing-field trends to tune questions before adding paid data." : "Collect rep feedback on worked profiles so buyer proof includes profile quality."
  });
  addReadinessCheck(checks, {
    section: "proof",
    key: "pipeline_results",
    label: "Pipeline result evidence",
    status: report.summary.conversion.opportunities_created || report.summary.conversion.meeting_booked ? "pass" : report.summary.total ? "warning" : "blocker",
    detail: `${report.summary.conversion.meeting_booked} meetings, ${report.summary.conversion.opportunities_created} opportunities, $${report.summary.pipeline.opportunity_value.toFixed(2)} pipeline.`,
    action: report.summary.total ? "Log outcomes after first touch so the buyer sees conversion evidence." : "Capture leads before claiming result lift."
  });
  addReadinessCheck(checks, {
    section: "handoff",
    key: "rep_alerts",
    label: "Rep alert handoff",
    status: repAlerts.summary.failed ? "blocker" : repAlerts.summary.sent ? "pass" : repAlerts.summary.queued ? "warning" : launch.cohort.beta_leads ? "warning" : "pass",
    detail: `${repAlerts.summary.sent} sent, ${repAlerts.summary.queued} queued, ${repAlerts.summary.failed} failed.`,
    action: repAlerts.summary.sent || !launch.cohort.beta_leads ? null : "Send one rep alert from a beta test lead before a buyer demo."
  });
  addReadinessCheck(checks, {
    section: "handoff",
    key: "crm_delivery",
    label: "CRM delivery proof",
    status: crmDeliveries.summary.failed ? "blocker" : crmDeliveries.summary.sent ? "pass" : crmDeliveries.summary.queued ? "warning" : launch.cohort.beta_leads ? "warning" : "pass",
    detail: `${crmDeliveries.summary.sent} sent, ${crmDeliveries.summary.queued} queued, ${crmDeliveries.summary.failed} failed.`,
    action: crmDeliveries.summary.sent || !launch.cohort.beta_leads ? null : "Send one generic CRM delivery in dry-run or sandbox mode before demoing handoff readiness."
  });
  addReadinessCheck(checks, {
    section: "governance",
    key: "admin_auth",
    label: "Operator authentication",
    status: ADMIN_PASSWORD ? "pass" : "blocker",
    detail: ADMIN_PASSWORD ? "Protected operator routes and APIs require Basic Auth." : "ADMIN_PASSWORD is missing.",
    action: ADMIN_PASSWORD ? null : "Set a strong ADMIN_PASSWORD before exposing any buyer environment."
  });
  addReadinessCheck(checks, {
    section: "governance",
    key: "backup_restore",
    label: "Backup and restore",
    status: backupValidation.restore_ready ? "pass" : "blocker",
    detail: backupValidation.restore_ready ? "Current state export validates and can be restored with confirmation." : backupValidation.errors.join("; "),
    action: backupValidation.restore_ready ? null : "Fix backup validation before live buyer pilots."
  });
  addReadinessCheck(checks, {
    section: "governance",
    key: "provider_firewall",
    label: "Paid enrichment firewall",
    status: enrichment.cost.paid_provider_spend === 0 && buildPlan.paid_escalation_policy.manual_approval_required ? "pass" : "warning",
    detail: `$${enrichment.cost.paid_provider_spend.toFixed(2)} paid-provider spend; manual approval required: ${
      buildPlan.paid_escalation_policy.manual_approval_required ? "yes" : "no"
    }.`,
    action: enrichment.cost.paid_provider_spend === 0 ? null : "Review paid lookups and prove they changed rep behavior."
  });
  addReadinessCheck(checks, {
    section: "governance",
    key: "external_modes",
    label: "External send modes",
    status: emailAdapter.transmits_external_email || crmAdapter.transmits_external_crm ? "warning" : "pass",
    detail: `Report email: ${emailAdapter.mode}; CRM delivery: ${crmAdapter.mode}; HubSpot: ${hubSpotMode()}; LLM: ${llmExtractionMode()}.`,
    action: emailAdapter.transmits_external_email || crmAdapter.transmits_external_crm ? "Confirm webhook destinations and data-processing terms before live buyer traffic." : null
  });

  const blockerCount = checks.filter((check) => check.status === "blocker").length;
  const warningCount = checks.filter((check) => check.status === "warning").length;
  const passCount = checks.filter((check) => check.status === "pass").length;
  const score = Math.round((passCount / Math.max(1, checks.length)) * 100);
  const status = blockerCount ? "not_ready" : warningCount ? "demo_ready_with_gaps" : "buyer_ready";
  const openGaps = uniqueStrings([
	    ...checks.filter((check) => check.status !== "pass" && check.action).map((check) => check.action),
	    ...liveGate.actions,
    ...launch.next_actions,
    ...proof.recommended_actions,
    ...buildPlan.quality_gates.filter((gate) => !gate.passed).map((gate) => gate.action)
  ]).slice(0, 12);

  return {
    generated_at: now(),
    status,
    status_label: readinessRoomStatusLabel(status),
    score,
    period,
    summary: {
      pass: passCount,
      warning: warningCount,
      blocker: blockerCount,
      total: checks.length
    },
    proof: {
      status: proof.summary.proof_status,
      status_label: proof.summary.proof_status_label,
      clients: proof.summary.client_count,
      baselines: proof.summary.clients_with_baseline,
      total_leads: proof.summary.total_leads,
      meetings_booked: proof.summary.meetings_booked,
      opportunities_created: proof.summary.opportunities_created,
      pipeline_value: proof.summary.opportunity_value,
      expected_value: proof.summary.expected_value,
      first_touch_minutes_saved_per_lead: proof.summary.first_touch_minutes_saved_per_lead,
      research_hours_saved: proof.summary.estimated_manual_research_hours_saved,
      paid_provider_spend: proof.summary.paid_provider_spend,
      rep_feedback_reviewed: proof.summary.rep_feedback_reviewed,
      rep_feedback_helpful: proof.summary.rep_feedback_helpful,
      rep_feedback_missing_context: proof.summary.rep_feedback_missing_context,
      rep_feedback_average_usefulness_score: proof.summary.rep_feedback_average_usefulness_score,
      top_missing_fields: proof.summary.rep_feedback_top_missing_fields
	    },
	    live_proof_gate: {
	      status: liveGate.status,
	      status_label: liveGate.status_label,
	      live_ready: liveGate.live_ready,
	      summary: liveGate.summary,
	      blockers: liveGate.blockers,
	      warnings: liveGate.warnings,
	      actions: liveGate.actions
	    },
    operations: {
      beta_clients: launch.cohort.beta_clients,
      installed_clients: launch.cohort.installed_clients,
      live_clients: launch.cohort.live_clients,
      beta_leads: launch.cohort.beta_leads,
      rep_alerts: repAlerts.summary,
      crm_deliveries: crmDeliveries.summary,
      report_deliveries: reportDeliverySummary().summary
    },
    governance: {
      admin_auth: ADMIN_PASSWORD ? "enabled" : "missing",
      data_store_mode: DATA_STORE_MODE,
      data_store_location: DATA_STORE_LOCATION,
      backup_restore_ready: backupValidation.restore_ready,
      consent_policy_version: widgetConfig.consent.policyVersion,
      allowed_domains: widgetConfig.tenant.allowedDomains,
      llm_mode: llmExtractionMode(),
      hubspot_mode: hubSpotMode(),
      enrichment_mode: internalEnrichmentMode(),
      report_email_mode: emailAdapter.mode,
      crm_delivery_mode: crmAdapter.mode,
      paid_escalation_policy: buildPlan.paid_escalation_policy
    },
    providerless_plan: {
      recommendation: buildPlan.recommendation,
      cost_model: buildPlan.cost_model,
      quality_gates: buildPlan.quality_gates,
      stages: buildPlan.stages
    },
    demo_scenario: scenario,
    checks,
    open_gaps: openGaps,
    buyer_questions: midMarketBuyerQuestions(proof, report, enrichment, buildPlan),
    links: {
      proof: `/proof?days=${period.days}`,
      beta_report: `/reports/beta?days=${period.days}`,
      trust_packet: "/trust",
      beta_clients: "/beta-clients",
      enrichment: "/enrichment",
      admin: "/admin"
    }
  };
}

function readinessRoomStatusLabel(status) {
  const labels = {
    buyer_ready: "Buyer ready",
    demo_ready_with_gaps: "Demo ready with gaps",
    not_ready: "Not ready"
  };
  return labels[status] || humanizeEnum(status);
}

function midMarketBuyerQuestions(proof, report, enrichment, buildPlan) {
  return [
    {
      question: "What results can you prove?",
      answer: `${proof.summary.total_leads} leads, ${proof.summary.meetings_booked} meetings, ${proof.summary.opportunities_created} opportunities, and $${proof.summary.opportunity_value.toFixed(2)} pipeline in the selected window.`
    },
    {
      question: "Are reps actually using the profiles?",
      answer: `${proof.summary.rep_feedback_reviewed} profiles have rep feedback, with ${proof.summary.rep_feedback_helpful} marked helpful and average usefulness ${
        proof.summary.rep_feedback_average_usefulness_score ?? "not measured"
      }/5.`
    },
    {
      question: "How do you avoid expensive enrichment spend?",
      answer: `${buildPlan.recommendation} Current paid-provider spend is $${enrichment.cost.paid_provider_spend.toFixed(2)}. Paid lookup remains behind manual approval and rep-confirmed missing-field evidence.`
    },
    {
      question: "What happens when data is uncertain?",
      answer: `${enrichment.quality.high_priority_review_candidates} high-priority profiles are open for enrichment review; operators can add sourced evidence, save company memory, or mark profiles reviewed before handoff.`
    },
    {
      question: "How do you control handoff risk?",
      answer: `Rep alerts, generic CRM deliveries, HubSpot previews, report packets, backup validation, and dry-run modes are all visible from protected operator pages.`
    }
  ];
}

function productionHardeningSummary() {
  const allowedDomains = widgetConfig.tenant.allowedDomains || [];
  const headers = securityHeaders();
  const checks = [];
  const addCheck = (check) => checks.push(check);
  const hasExternalTransmission =
    hubSpotMode() === "live" || reportEmailAdapterStatus().transmits_external_email || crmDeliveryAdapterStatus().transmits_external_crm || Boolean(llmReadinessSummary().api_key_configured);

  addCheck({
    key: "security_headers",
    label: "Security headers",
    status: "pass",
    evidence: `Responses include ${Object.keys(headers).join(", ")}.`,
    action: null
  });
  addCheck({
    key: "request_body_limit",
    label: "Request body limit",
    status: "pass",
    evidence: `Requests are capped at ${MAX_REQUEST_BODY_BYTES} bytes before parsing.`,
    action: null
  });
  addCheck({
    key: "client_error_handling",
    label: "Client error handling",
    status: "pass",
    evidence: "Invalid JSON and oversized payloads return 400/413 instead of generic server errors.",
    action: null
  });
  addCheck({
    key: "widget_origin_enforcement",
    label: "Widget origin enforcement",
    status: allowedDomains.length && !allowedDomains.includes("*") ? "pass" : allowedDomains.length ? "warning" : "blocker",
    evidence: `${allowedDomains.length} explicit allowed domain${allowedDomains.length === 1 ? "" : "s"} configured: ${allowedDomains.join(", ") || "none"}.`,
    action: allowedDomains.length && !allowedDomains.includes("*") ? null : "Configure explicit widget allowed domains before live installs."
  });
  addCheck({
    key: "public_widget_scope",
    label: "Public widget API scope",
    status: "pass",
    evidence: "Config, session, message, completion, and fallback endpoints enforce widget source allowlists.",
    action: null
  });
  addCheck({
    key: "operator_authentication",
    label: "Operator authentication",
    status: ADMIN_PASSWORD ? "pass" : "blocker",
    evidence: ADMIN_PASSWORD ? "Protected operator pages and APIs require Basic Auth." : "ADMIN_PASSWORD is not configured.",
    action: ADMIN_PASSWORD ? null : "Set ADMIN_PASSWORD before exposing buyer or operator environments."
  });
  addCheck({
    key: "production_admin_secret",
    label: "Production admin secret",
    status: process.env.NODE_ENV === "production" && !process.env.ADMIN_PASSWORD ? "blocker" : "pass",
    evidence:
      process.env.NODE_ENV === "production"
        ? process.env.ADMIN_PASSWORD
          ? "Production admin password is supplied from the environment."
          : "Production mode is active without ADMIN_PASSWORD."
        : "Local/dev fallback auth is allowed outside production.",
    action: process.env.NODE_ENV === "production" && !process.env.ADMIN_PASSWORD ? "Set ADMIN_PASSWORD in the deployment environment." : null
  });
  addCheck({
    key: "data_store_persistence",
    label: "Data store persistence",
    status: process.env.NODE_ENV === "production" && DATA_STORE_MODE !== "sqlite" ? "warning" : "pass",
    evidence:
      DATA_STORE_MODE === "sqlite"
        ? `SQLite persistence is active at ${DATA_STORE_LOCATION}.`
        : `JSON persistence is active at ${DATA_STORE_LOCATION}${process.env.NODE_ENV === "production" ? "; use a mounted volume or SQLite for beta traffic." : " for local/dev use."}`,
    action: process.env.NODE_ENV === "production" && DATA_STORE_MODE !== "sqlite" ? "Use DEAL_THREADS_DATA_STORE=sqlite with a persistent deployment volume." : null
  });
  addCheck({
    key: "external_adapter_disclosure",
    label: "External adapter disclosure",
    status: hasExternalTransmission ? "warning" : "pass",
    evidence: hasExternalTransmission
      ? "At least one live external adapter or LLM path can transmit customer data."
      : "Default mode keeps CRM, email, HubSpot, OpenAI, and paid enrichment dry-run, stubbed, heuristic, or internal-first.",
    action: hasExternalTransmission ? "Confirm destination scopes, DPAs, and buyer disclosure before live traffic." : null
  });

  const blockerCount = checks.filter((check) => check.status === "blocker").length;
  const warningCount = checks.filter((check) => check.status === "warning").length;
  const passCount = checks.filter((check) => check.status === "pass").length;
  return {
    generated_at: now(),
    status: blockerCount ? "not_hardened" : warningCount ? "hardened_with_warnings" : "hardened",
    score: Math.round((passCount / Math.max(1, checks.length)) * 100),
    max_request_body_bytes: MAX_REQUEST_BODY_BYTES,
    security_headers: headers,
    summary: {
      pass: passCount,
      warning: warningCount,
      blocker: blockerCount,
      total: checks.length
    },
    checks,
    next_actions: checks.filter((check) => check.status !== "pass" && check.action).map((check) => check.action)
  };
}

function buyerTrustPacket(baseUrl = "", searchParams = new URLSearchParams()) {
  const readiness = midMarketReadinessSummary(baseUrl, searchParams);
  const backupValidation = validateStateBackup(stateBackupExport());
  const buildPlan = providerlessEnrichmentBuildPlan(enrichmentQualitySummary(allLeadsSorted()));
  const llm = llmReadinessSummary();
  const emailAdapter = reportEmailAdapterStatus();
  const crmAdapter = crmDeliveryAdapterStatus();
  const scenario = demoScenarioStatus();
  const counts = backupCounts(snapshotState());
  const allowedDomains = widgetConfig.tenant.allowedDomains || [];
  const hardening = productionHardeningSummary();
  const externalModes = [
    llm.api_key_configured ? "OpenAI extraction can transmit visitor conversation text when enabled." : null,
    hubSpotMode() === "live" ? "HubSpot sync can transmit contact, company, deal, and note fields." : null,
    emailAdapter.transmits_external_email ? "Report/rep alert webhook can transmit report packets and lead briefs." : null,
    crmAdapter.transmits_external_crm ? "CRM delivery webhook can transmit buyer-profile payloads." : null
  ].filter(Boolean);
  const controls = [];
  const addControl = (control) => controls.push(control);

  addControl({
    section: "access",
    key: "operator_authentication",
    label: "Operator authentication",
    status: ADMIN_PASSWORD ? "pass" : "blocker",
    evidence: ADMIN_PASSWORD ? "Protected operator pages and APIs require Basic Auth." : "ADMIN_PASSWORD is not configured.",
    action: ADMIN_PASSWORD ? null : "Set ADMIN_PASSWORD before any buyer-facing environment."
  });
  addControl({
    section: "access",
    key: "domain_allowlist",
    label: "Widget domain allowlist",
    status: allowedDomains.length && !allowedDomains.includes("*") ? "pass" : allowedDomains.length ? "warning" : "blocker",
    evidence: `${allowedDomains.length} allowed domain${allowedDomains.length === 1 ? "" : "s"} configured: ${allowedDomains.join(", ") || "none"}.`,
    action: allowedDomains.length && !allowedDomains.includes("*") ? null : "Configure explicit client domains before sending a live snippet."
  });
	  addControl({
	    section: "privacy",
	    key: "consent_capture",
	    label: "Consent capture",
	    status: widgetConfig.consent?.policyVersion && widgetConfig.consent?.disclosure ? "pass" : "blocker",
	    evidence: `Policy ${widgetConfig.consent?.policyVersion || "missing"} is shown before chat or fallback lead creation.`,
	    action: widgetConfig.consent?.policyVersion && widgetConfig.consent?.disclosure ? null : "Add consent copy and a policy version before live buyer traffic."
	  });
  addControl({
    section: "privacy",
    key: "retention_deletion",
    label: "Retention and deletion",
    status: "pass",
    evidence: `Tenant-scoped export, deletion preview, and guarded deletion are available. Beta retention policy is ${DATA_RETENTION_POLICY.default_beta_retention_days} days after pilot close unless deleted earlier.`,
    action: null
  });
  addControl({
    section: "data_control",
    key: "providerless_enrichment",
    label: "Providerless enrichment default",
    status: readiness.proof.paid_provider_spend === 0 && buildPlan.paid_escalation_policy.manual_approval_required ? "pass" : "warning",
    evidence: `$${readiness.proof.paid_provider_spend.toFixed(2)} paid-provider spend; manual approval required: ${
      buildPlan.paid_escalation_policy.manual_approval_required ? "yes" : "no"
    }.`,
    action: readiness.proof.paid_provider_spend === 0 ? null : "Review paid lookups and prove they changed rep behavior."
  });
  addControl({
    section: "data_control",
    key: "external_transmission",
    label: "External transmission modes",
    status: externalModes.length ? "warning" : "pass",
    evidence: externalModes.length ? externalModes.join(" ") : "Current local mode does not transmit email, CRM, HubSpot, OpenAI, or paid-enrichment data externally.",
    action: externalModes.length ? "Confirm destination contracts, scopes, and data-processing terms before live traffic." : null
  });
  addControl({
    section: "operations",
    key: "backup_restore",
    label: "Backup and restore",
    status: backupValidation.restore_ready ? "pass" : "blocker",
    evidence: backupValidation.restore_ready ? "Current state export validates and is restore-ready with confirmation." : backupValidation.errors.join("; "),
    action: backupValidation.restore_ready ? null : "Fix backup validation before live buyer pilots."
  });
  addControl({
    section: "operations",
    key: "audit_trail",
    label: "Operational audit trail",
    status: state.events.length ? "pass" : "warning",
    evidence: `${state.events.length} operational event${state.events.length === 1 ? "" : "s"} recorded.`,
    action: state.events.length ? null : "Generate and retain operational events for widget, lead, handoff, report, and admin activity."
  });
  addControl({
    section: "operations",
    key: "production_hardening",
    label: "Production hardening",
    status: hardening.summary.blocker ? "blocker" : hardening.summary.warning ? "warning" : "pass",
    evidence: `${hardening.summary.pass}/${hardening.summary.total} hardening checks pass; status is ${humanizeEnum(hardening.status)}.`,
    action: hardening.next_actions[0] || null
  });
  addControl({
    section: "demo",
    key: "synthetic_data_boundary",
    label: "Synthetic data boundary",
    status: scenario.active ? "warning" : "pass",
    evidence: scenario.active ? `${scenario.clients} synthetic clients and ${scenario.leads} synthetic leads are loaded.` : "No marked demo scenario data is active.",
    action: scenario.active ? "Clear the demo scenario before exporting live beta proof." : null
  });

  const blockerCount = controls.filter((control) => control.status === "blocker").length;
  const warningCount = controls.filter((control) => control.status === "warning").length;
  const passCount = controls.filter((control) => control.status === "pass").length;
  const status = blockerCount ? "not_procurement_ready" : warningCount ? "procurement_ready_with_disclosures" : "procurement_ready";

  return {
    generated_at: now(),
    status,
    status_label:
      status === "procurement_ready"
        ? "Procurement ready"
        : status === "procurement_ready_with_disclosures"
          ? "Ready with disclosures"
          : "Not procurement ready",
    score: Math.round((passCount / Math.max(1, controls.length)) * 100),
    summary: {
      pass: passCount,
      warning: warningCount,
      blocker: blockerCount,
      total: controls.length
    },
    runtime: {
      admin_auth: ADMIN_PASSWORD ? "enabled" : "missing",
      data_store_mode: DATA_STORE_MODE,
      data_store_location: DATA_STORE_LOCATION,
      llm_mode: llm.mode,
      openai_configured: llm.api_key_configured,
      hubspot_mode: hubSpotMode(),
      enrichment_mode: internalEnrichmentMode(),
      report_email_mode: emailAdapter.mode,
      crm_delivery_mode: crmAdapter.mode,
      external_email: emailAdapter.transmits_external_email,
      external_crm: crmAdapter.transmits_external_crm,
      hardening_status: hardening.status
    },
    hardening,
    data_inventory: {
      counts,
      consent_policy_version: widgetConfig.consent?.policyVersion || null,
      retention_policy: DATA_RETENTION_POLICY,
      allowed_domains: allowedDomains,
      demo_scenario: scenario
    },
    data_categories: [
      {
        name: "Visitor identity",
        fields: ["name", "email", "authority signal"],
        purpose: "Route qualified inquiries and prepare rep follow-up."
      },
      {
        name: "Conversation qualification",
        fields: ["business need", "timeline", "budget", "CRM", "company/domain", "consent metadata"],
        purpose: "Build the buyer profile before the first sales touch."
      },
      {
        name: "Company intelligence",
        fields: ["industry", "employee range", "tech stack", "buying committee", "buying triggers", "research evidence"],
        purpose: "Replace manual rep research with internal or operator-sourced context."
      },
      {
        name: "Sales operations",
        fields: ["owner", "workflow stage", "SLA", "rep feedback", "outcome", "CRM handoff", "report delivery"],
        purpose: "Measure whether profiles improve speed-to-lead, meetings, and pipeline."
      },
      {
        name: "Operational metadata",
        fields: ["page URL", "UTM fields", "timestamps", "config version", "audit events"],
        purpose: "Debug installs, prove handoffs, and support reporting."
      }
    ],
    data_flow: [
      "Website loads the script-tag widget from the Deal Threads app.",
      "Visitor accepts the consent disclosure and answers qualification questions.",
      "The server extracts a structured profile and enriches it using internal/company-memory signals by default.",
      "The rep opens a protected CRM profile with call plan, evidence, source gaps, and handoff controls.",
      "Dry-run rep alerts, CRM deliveries, HubSpot previews, and reports record proof without external transmission unless live adapters are configured.",
      "Tenant data can be exported, previewed for deletion, or deleted with a guarded confirmation phrase from the trust packet."
    ],
    processors: [
      {
        name: "Deal Threads app",
        mode: "required",
        sends_data: true,
        condition: "Stores widget configuration, conversations, leads, enrichment memory, reports, and audit events."
      },
      {
        name: "OpenAI",
        mode: llm.api_key_configured ? llm.mode : "not_configured",
        sends_data: Boolean(llm.api_key_configured),
        condition: llm.api_key_configured ? "Structured extraction may use OpenAI for conversation text." : "Heuristic extraction is active; no OpenAI request is made."
      },
      {
        name: "HubSpot",
        mode: hubSpotMode(),
        sends_data: hubSpotMode() === "live",
        condition: hubSpotMode() === "live" ? "Sync adapter can create/update CRM records." : "Stub/preview mode records intended operations only."
      },
      {
        name: "Report email webhook",
        mode: emailAdapter.mode,
        sends_data: emailAdapter.transmits_external_email,
        condition: emailAdapter.transmits_external_email ? "Webhook receives report packets and rep alerts." : "Dry-run mode stores send attempts locally."
      },
      {
        name: "CRM delivery webhook",
        mode: crmAdapter.mode,
        sends_data: crmAdapter.transmits_external_crm,
        condition: crmAdapter.transmits_external_crm ? "Webhook receives buyer-profile payloads." : "Dry-run mode stores CRM handoff payloads locally."
      }
    ],
    controls,
    open_gaps: controls.filter((control) => control.status !== "pass" && control.action).map((control) => control.action),
    buyer_answers: [
      {
        question: "What leaves the system by default?",
        answer: externalModes.length
          ? "At least one live adapter is configured; review the processors list before live traffic."
          : "In this local/default mode, CRM, email, HubSpot, OpenAI, and paid enrichment are dry-run, stubbed, heuristic, or internal-first."
      },
      {
        question: "How is demo data separated from real proof?",
        answer: "The mid-market scenario uses marked `.example` domains and a `mid_market_buyer_demo` tag, and it can be cleared without removing real beta clients or leads."
      },
      {
        question: "How do we avoid enrichment cost surprise?",
        answer: "Paid provider lookup is not default behavior; escalation requires manual approval and rep-confirmed missing-field evidence."
      },
      {
        question: "What is still needed before production procurement?",
        answer: "Live adapter DPAs/scopes and customer-specific security review should be completed before a production rollout. Tenant export/delete and beta retention rules are already represented in the trust packet."
      }
    ],
    links: {
      readiness: "/readiness",
      proof: "/proof",
      beta_report: "/reports/beta",
      admin_backup: "/api/v1/admin/state/export",
      tenant_data_export: "/api/v1/trust/tenant-data/export",
      enrichment: "/enrichment"
    }
  };
}

