function publicProcurementPacket(baseUrl = "") {
  const root = baseUrl.replace(/\/$/, "");
  const trust = buyerTrustPacket(baseUrl, new URLSearchParams([["days", "14"]]));
  const agreement = pilotAgreementPacket(baseUrl);
  const readiness = midMarketReadinessSummary(baseUrl, new URLSearchParams([["days", "14"]]));
  const hardening = productionHardeningSummary();
  const publicLinks = {
    buyer_demo: `${root}/`,
    pilot_intake: `${root}/pilot-intake`,
    pilot_close_kit: `${root}/pilot-close-kit`,
    pilot_approval_room: `${root}/pilot-approval-room`,
    pilot_agreement: `${root}/pilot-agreement`,
    business_case: `${root}/business-case`,
    implementation_guide: `${root}/implementation-guide`,
    crm_handoff_guide: `${root}/crm-handoff-guide`,
    security_center: `${root}/security`,
    sample_profile: `${root}/sample-profile`,
    markdown: `${root}/api/v1/procurement-packet?format=markdown`
  };
  const defaultPosture = [
    "Providerless enrichment by default; paid enrichment requires explicit approval.",
    "CRM delivery, report email, and HubSpot sync default to dry-run, manual, or preview mode unless live adapters are configured.",
    "Synthetic CRM webhook tests can validate Zapier/Make/n8n routing before real buyer profiles are transmitted.",
    "Visitor consent is required before chat or fallback lead creation.",
    "Operator CRM profiles, tenant data controls, activation actions, and beta reports stay behind admin authentication.",
    `Beta retention target is ${DATA_RETENTION_POLICY.default_beta_retention_days} days after pilot close unless the customer requests export or deletion earlier.`
  ];
  const approvalChecklist = [
    "Confirm the target page URL and approved client domain.",
    "Name implementation, CRM, routing, and proof-report owners.",
    "Approve the single-page, 14-day beta scope and success criteria.",
    "Confirm dry-run/manual CRM handoff until webhook or HubSpot sync is approved.",
    "Confirm no paid enrichment provider calls are enabled by default.",
    "Review processor modes and customer-specific security or DPA requirements before production expansion."
  ];
  const procurementDisclosures = [
    readiness.demo_scenario.active
      ? `Current demo proof uses marked synthetic data (${readiness.demo_scenario.clients} demo clients, ${readiness.demo_scenario.leads} demo leads); live customer proof begins after real beta traffic.`
      : "Current proof is based on live beta data in the selected window.",
    hardening.status === "hardened"
      ? "Production hardening is currently passing without blockers."
      : `Production hardening status is ${hardening.status}; review open actions before live traffic.`,
    trust.runtime.external_crm || trust.runtime.external_email || trust.runtime.openai_configured || trust.runtime.hubspot_mode === "live"
      ? "At least one live external data path is configured; buyer review should confirm scopes and processor terms."
      : "Default posture does not transmit CRM, email, HubSpot, OpenAI, or paid-enrichment data externally."
  ];
  const packet = {
    type: "deal_threads.public_procurement_packet",
    generated_at: now(),
    status: trust.status,
    status_label: trust.status_label,
    trust_score: trust.score,
    hardening_status: hardening.status,
    hardening_score: hardening.score,
    offer: agreement.offer,
    pilot_scope: agreement.scope,
    success_criteria: agreement.success_criteria,
    commercial_terms: agreement.commercial_terms,
    data_security_posture: agreement.data_security,
    default_posture: defaultPosture,
    approval_checklist: approvalChecklist,
    procurement_disclosures: procurementDisclosures,
    data_categories: trust.data_categories,
    processors: trust.processors.map((processor) => ({
      name: processor.name,
      mode: processor.mode,
      sends_data: processor.sends_data,
      condition: processor.condition
    })),
    controls: trust.controls.map((control) => ({
      section: control.section,
      key: control.key,
      label: control.label,
      status: control.status,
      evidence: control.evidence,
      action: control.action
    })),
    public_links: publicLinks,
    exclusions: agreement.exclusions,
    public_safety: {
      exposes_operator_forms: false,
      exposes_crm_profiles: false,
      exposes_tenant_exports: false,
      mutates_buyer_state: false
    }
  };
  packet.markdown = publicProcurementPacketMarkdown(packet);
  return packet;
}

