function isDemoScenarioClient(client, scenarioId = MID_MARKET_DEMO_SCENARIO_ID) {
  if (!client) return false;
  if (client.demo_scenario_id === scenarioId) return true;
  const markerText = [
    client.notes,
    client.measurement_settings?.proof_notes,
    client.domain,
    client.website_url
  ]
    .filter(Boolean)
    .join(" ");
  const hasDemoMarker =
    markerText.includes(scenarioId) || markerText.includes(MID_MARKET_DEMO_SCENARIO_NAME) || /\b[a-z0-9-]+\.example\b/i.test(markerText);
  if (!hasDemoMarker) return false;
  const clientLeads = allLeadsSorted().filter((lead) => lead.source?.beta_client_id === client.id);
  return clientLeads.length > 0 && clientLeads.every((lead) => isDemoScenarioLead(lead, scenarioId));
}

function isDemoScenarioLead(lead, scenarioId = MID_MARKET_DEMO_SCENARIO_ID) {
  return Boolean(lead?.demo_scenario_id === scenarioId || lead?.source?.demo_scenario_id === scenarioId);
}

function demoScenarioStatus(scenarioId = MID_MARKET_DEMO_SCENARIO_ID) {
  const clients = [...state.betaClients.values()].filter((client) => isDemoScenarioClient(client, scenarioId));
  const clientIds = new Set(clients.map((client) => client.id));
  const leads = allLeadsSorted().filter((lead) => lead.source?.demo_scenario_id === scenarioId || clientIds.has(lead.source?.beta_client_id));
  const leadIds = new Set(leads.map((lead) => lead.id));
  const reportDeliveries = [...state.reportDeliveries.values()].filter((delivery) => delivery.demo_scenario_id === scenarioId || clientIds.has(delivery.beta_client_id));
  const repAlerts = [...state.repAlerts.values()].filter((alert) => alert.demo_scenario_id === scenarioId || leadIds.has(alert.lead_id));
  const crmDeliveries = [...state.crmDeliveries.values()].filter((delivery) => delivery.demo_scenario_id === scenarioId || leadIds.has(delivery.lead_id));
  return {
    id: scenarioId,
    name: MID_MARKET_DEMO_SCENARIO_NAME,
    active: Boolean(clients.length || leads.length),
    clients: clients.length,
    leads: leads.length,
    report_deliveries: reportDeliveries.length,
    rep_alerts: repAlerts.length,
    crm_deliveries: crmDeliveries.length,
    latest_seeded_at: clients.map((client) => client.demo_seeded_at).filter(Boolean).sort().at(-1) || null
  };
}

async function seedMidMarketDemoScenario(baseUrl = "", actor = "operator", options = {}) {
  if (options.clearExisting !== false) clearMidMarketDemoScenario(actor);

  const scenarioId = MID_MARKET_DEMO_SCENARIO_ID;
  const seededAt = now();
  const createdClients = [];
  const createdLeads = [];
  const sentAlerts = [];
  const sentCrmDeliveries = [];
  const sentReports = [];

  for (const clientSpec of midMarketDemoClientSpecs()) {
    const result = createOrUpdateBetaClient(
      {
        name: clientSpec.name,
        websiteUrl: clientSpec.websiteUrl,
        ownerEmail: clientSpec.ownerEmail,
        crm: clientSpec.crm,
        status: "live",
        notes: `${MID_MARKET_DEMO_SCENARIO_NAME}: ${clientSpec.notes}`,
        launcherText: clientSpec.launcherText,
        welcomeMessage: clientSpec.welcomeMessage,
        quickReplies: "Fix demo routing, Improve lead quality, Shorten speed-to-lead",
        requiredFields: "email,business_need,timeline,company_name_or_domain,crm",
        primaryColor: clientSpec.primaryColor,
        highPriorityOwner: clientSpec.highPriorityOwner,
        mediumPriorityOwner: clientSpec.mediumPriorityOwner,
        highPriorityAction: clientSpec.highPriorityAction,
        mediumPriorityAction: clientSpec.mediumPriorityAction,
        crmDeliveryEnabled: "true",
        crmDeliveryProvider: clientSpec.crm,
        crmDestinationName: `${clientSpec.name} CRM handoff`,
        crmDeliveryWebhookUrl: `https://hooks.example.test/${clientSpec.domain.replaceAll(".", "-")}`,
        crmDeliveryOwner: clientSpec.crmOwner,
        reportRecipients: `${clientSpec.ownerEmail}, ${clientSpec.crmOwner}`,
        reportCadence: "weekly",
        reportPeriodDays: "14",
        nextReportDueAt: new Date(Date.now() - 24 * 60 * 60 * 1000).toISOString(),
        baselineFirstTouchMinutes: clientSpec.baseline.firstTouch,
        baselineMeetingRate: clientSpec.baseline.meetingRate,
        baselineOpportunityRate: clientSpec.baseline.opportunityRate,
        baselineWinRate: clientSpec.baseline.winRate,
        baselineCycleDays: clientSpec.baseline.cycleDays,
        minimumProofLeads: "2",
        proofNotes: `${MID_MARKET_DEMO_SCENARIO_NAME}: old-form baseline from pre-demo CRM export.`
      },
      actor
    );
    if (result.error) return result;
    const client = result.client;
    client.demo_scenario_id = scenarioId;
    client.demo_seeded_at = seededAt;
    client.status = "live";
    client.install_activity = normalizeInstallActivity({
      config_loads: 9,
      hosted_config_loads: 0,
      client_page_config_loads: 9,
      session_starts: 7,
      last_config_loaded_at: seededAt,
      last_client_page_config_loaded_at: seededAt,
      last_session_started_at: seededAt,
      last_load_scope: "client_site",
      last_origin: client.domain,
      last_page_url: client.website_url,
      last_client_origin: client.domain,
      last_client_page_url: client.website_url,
      last_referrer: "https://google.com/search?q=demo+routing"
    });
    state.betaClients.set(client.id, client);
    for (const key of ["install_snippet_sent", "widget_installed", "routing_confirmed"]) {
      markBetaChecklistSystem(client.id, key, `${MID_MARKET_DEMO_SCENARIO_NAME} seeded ${key.replaceAll("_", " ")} evidence.`);
    }
    createdClients.push(client);

    for (const leadSpec of clientSpec.leads) {
      const leadResult = await createFirstBetaLaunchTestLead(
        client,
        {
          contactName: leadSpec.contactName,
          email: leadSpec.email,
          companyName: clientSpec.companyName,
          crm: clientSpec.crm,
          pageUrl: `${client.website_url}/demo`,
          message: leadSpec.message
        },
        actor
      );
      if (leadResult.error) return leadResult;
      const lead = leadResult.lead;
      const createdAt = demoIsoDaysAgo(leadSpec.daysAgo);
      lead.created_at = createdAt;
      lead.source = {
        ...(lead.source || {}),
        demo_scenario_id: scenarioId,
        demo_scenario_name: MID_MARKET_DEMO_SCENARIO_NAME,
        page_url: `${client.website_url}/demo`
      };
      const conversation = state.conversations.get(lead.conversation_id);
      if (conversation) {
        conversation.source = { ...(conversation.source || {}), demo_scenario_id: scenarioId, demo_scenario_name: MID_MARKET_DEMO_SCENARIO_NAME };
        conversation.createdAt = createdAt;
        conversation.updatedAt = createdAt;
        state.conversations.set(conversation.id, conversation);
      }
      ensureLeadWorkflow(lead);
      lead.workflow.last_activity_at = createdAt;
      lead.workflow.due_at = new Date(new Date(createdAt).getTime() + 15 * 60 * 1000).toISOString();
      state.leads.set(lead.id, lead);

      updateLeadWorkflow(
        lead,
        {
          stage: leadSpec.stage,
          ownerEmail: clientSpec.highPriorityOwner,
          nextAction: leadSpec.nextAction,
          dueAt: new Date(Date.now() + leadSpec.followupDueHours * 60 * 60 * 1000).toISOString(),
          outcomeStatus: leadSpec.outcomeStatus,
          outcomeValue: leadSpec.value,
          outcomeProbability: leadSpec.probability,
          firstContactedAt: demoIsoAfter(createdAt, leadSpec.firstTouchMinutes),
          meetingBookedAt: leadSpec.meetingMinutes ? demoIsoAfter(createdAt, leadSpec.meetingMinutes) : "",
          opportunityCreatedAt: leadSpec.opportunityMinutes ? demoIsoAfter(createdAt, leadSpec.opportunityMinutes) : "",
          closedAt: leadSpec.closedMinutes ? demoIsoAfter(createdAt, leadSpec.closedMinutes) : "",
          note: leadSpec.workflowNote
        },
        actor
      );
      updateRepFeedback(
        lead,
        {
          status: leadSpec.feedbackStatus,
          usefulnessScore: leadSpec.feedbackScore,
          repConfidence: leadSpec.repConfidence,
          usedOnCall: true,
          missingFields: leadSpec.missingFields,
          missingContextNote: leadSpec.feedbackNote
        },
        actor
      );
      for (const evidence of leadSpec.evidence) {
        addLeadResearchEvidence(
          lead,
          {
            category: evidence.category,
            value: evidence.value,
            sourceUrl: evidence.sourceUrl,
            sourceLabel: evidence.sourceLabel,
            confidence: evidence.confidence,
            note: evidence.note,
            reusable: true,
            markReviewed: true
          },
          actor
        );
      }
      const memory = lead.company?.domain ? state.companyMemory.get(lead.company.domain) : null;
      if (memory) {
        memory.demo_scenario_id = scenarioId;
        memory.demo_seeded_at = seededAt;
        state.companyMemory.set(memory.domain, memory);
      }
      const alertResult = await sendLeadRepAlert(lead, baseUrl, { recipients: clientSpec.highPriorityOwner }, actor);
      if (!alertResult.error) {
        alertResult.alert.demo_scenario_id = scenarioId;
        state.repAlerts.set(alertResult.alert.id, alertResult.alert);
        sentAlerts.push(alertResult.alert);
      }
      const crmResult = await sendLeadCrmDelivery(
        lead,
        baseUrl,
        {
          destinationName: `${clientSpec.name} CRM handoff`,
          webhookUrl: `https://hooks.example.test/${clientSpec.domain.replaceAll(".", "-")}`,
          note: `${MID_MARKET_DEMO_SCENARIO_NAME} dry-run CRM delivery.`
        },
        actor
      );
      if (!crmResult.error) {
        crmResult.delivery.demo_scenario_id = scenarioId;
        state.crmDeliveries.set(crmResult.delivery.id, crmResult.delivery);
        sentCrmDeliveries.push(crmResult.delivery);
      }
      lead.demo_scenario_id = scenarioId;
      lead.demo_seeded_at = seededAt;
      state.leads.set(lead.id, lead);
      createdLeads.push(lead);
    }

    captureOutcomeSnapshot(client, { days: 14, decision: clientSpec.snapshotDecision, learnings: clientSpec.snapshotLearnings }, actor);
    const reportDelivery = createReportDeliveryForClient(client, { days: 14, recipients: `${clientSpec.ownerEmail}, ${clientSpec.crmOwner}` }, actor);
    if (!reportDelivery.error) {
      reportDelivery.delivery.demo_scenario_id = scenarioId;
      state.reportDeliveries.set(reportDelivery.delivery.id, reportDelivery.delivery);
      const sent = await sendReportDelivery(reportDelivery.delivery, { note: `${MID_MARKET_DEMO_SCENARIO_NAME} dry-run report delivery.` }, actor);
      if (!sent.error) {
        sent.demo_scenario_id = scenarioId;
        state.reportDeliveries.set(sent.id, sent);
        sentReports.push(sent);
      }
    }
    client.updated_at = seededAt;
    state.betaClients.set(client.id, client);
  }

  track("demo_scenario_seeded", {
    demoScenarioId: scenarioId,
    clients: createdClients.length,
    leads: createdLeads.length,
    actor
  });
  persistSoon();
  return {
    scenario: demoScenarioStatus(scenarioId),
    created: {
      clients: createdClients.map((client) => client.id),
      leads: createdLeads.map((lead) => lead.id),
      rep_alerts: sentAlerts.map((alert) => alert.id),
      crm_deliveries: sentCrmDeliveries.map((delivery) => delivery.id),
      report_deliveries: sentReports.map((delivery) => delivery.id)
    }
  };
}

function clearMidMarketDemoScenario(actor = "operator") {
  const scenarioId = MID_MARKET_DEMO_SCENARIO_ID;
  const clients = [...state.betaClients.values()].filter((client) => isDemoScenarioClient(client, scenarioId));
  const clientIds = new Set(clients.map((client) => client.id));
  const leads = [...state.leads.values()].filter((lead) => lead.demo_scenario_id === scenarioId || lead.source?.demo_scenario_id === scenarioId || clientIds.has(lead.source?.beta_client_id));
  const leadIds = new Set(leads.map((lead) => lead.id));
  const conversationIds = new Set(leads.map((lead) => lead.conversation_id).filter(Boolean));
  const domains = new Set(leads.map((lead) => lead.company?.domain).filter(Boolean));

  for (const lead of leads) state.leads.delete(lead.id);
  for (const client of clients) state.betaClients.delete(client.id);
  for (const conversation of [...state.conversations.values()]) {
    if (conversationIds.has(conversation.id) || conversation.source?.demo_scenario_id === scenarioId || clientIds.has(conversation.source?.beta_client_id)) {
      state.conversations.delete(conversation.id);
    }
  }
  for (const session of [...state.sessions.values()]) {
    if (session.source?.demo_scenario_id === scenarioId || clientIds.has(session.source?.beta_client_id)) state.sessions.delete(session.id);
  }
  for (const alert of [...state.repAlerts.values()]) {
    if (alert.demo_scenario_id === scenarioId || leadIds.has(alert.lead_id)) state.repAlerts.delete(alert.id);
  }
  for (const delivery of [...state.crmDeliveries.values()]) {
    if (delivery.demo_scenario_id === scenarioId || leadIds.has(delivery.lead_id)) state.crmDeliveries.delete(delivery.id);
  }
  for (const delivery of [...state.reportDeliveries.values()]) {
    if (delivery.demo_scenario_id === scenarioId || clientIds.has(delivery.beta_client_id)) state.reportDeliveries.delete(delivery.id);
  }
  for (const record of [...state.companyMemory.values()]) {
    if (record.demo_scenario_id === scenarioId || domains.has(record.domain)) state.companyMemory.delete(record.domain);
  }
  widgetConfig.tenant.allowedDomains = widgetConfig.tenant.allowedDomains.filter((domain) => !clients.some((client) => client.domain === domain));
  state.events = state.events.filter((event) => {
    const props = event.properties || {};
    return (
      props.demoScenarioId !== scenarioId &&
      props.demo_scenario_id !== scenarioId &&
      !clientIds.has(props.betaClientId || props.beta_client_id) &&
      !leadIds.has(props.leadProfileId || props.lead_id)
    );
  });
  track("demo_scenario_cleared", { demoScenarioId: scenarioId, clients: clients.length, leads: leads.length, actor });
  persistSoon();
  return {
    scenario: demoScenarioStatus(scenarioId),
    removed: {
      clients: clients.length,
      leads: leads.length,
      conversations: conversationIds.size,
      company_memory: domains.size
    }
  };
}

function demoIsoDaysAgo(daysAgo) {
  return new Date(Date.now() - Number(daysAgo || 0) * 24 * 60 * 60 * 1000).toISOString();
}

function demoIsoAfter(fromIso, minutes) {
  return new Date(new Date(fromIso).getTime() + Number(minutes || 0) * 60 * 1000).toISOString();
}

