function launchProfileHandoffBridge(baseUrl = "", searchParams = new URLSearchParams()) {
  const root = baseUrl.replace(/\/$/, "");
  const requestedClientId = searchParams.get("client") || searchParams.get("betaClientId") || searchParams.get("beta_client_id") || "";
  const requestedLeadId = searchParams.get("lead") || searchParams.get("leadId") || searchParams.get("lead_id") || "";
  const installQueue = launchInstallQueue(baseUrl, searchParams);
  const market = marketLaunchReadinessPacket(baseUrl, searchParams);
  const queue = installQueue.queue || [];
  let selectedLead = requestedLeadId ? state.leads.get(requestedLeadId) || null : null;
  const leadClientId = selectedLead?.source?.beta_client_id || "";
  let selectedItem =
    (requestedClientId ? queue.find((item) => item.beta_client_id === requestedClientId) : null) ||
    (leadClientId ? queue.find((item) => item.beta_client_id === leadClientId) : null) ||
    queue.find((item) => item.lead_count && (!item.crm_delivery_count || !item.rep_feedback?.reviewed_profiles)) ||
    queue.find((item) => item.status === "create_first_profile") ||
    queue[0] ||
    null;
  const client =
    (selectedItem?.beta_client_id ? state.betaClients.get(selectedItem.beta_client_id) : null) ||
    (leadClientId ? state.betaClients.get(leadClientId) : null) ||
    null;
  const clientLeads = client ? allLeadsSorted().filter((lead) => lead.source?.beta_client_id === client.id) : [];
  if (!selectedLead && selectedItem?.latest_lead?.id) selectedLead = state.leads.get(selectedItem.latest_lead.id) || null;
  if (!selectedLead && clientLeads.length) selectedLead = clientLeads[0];
  if (!selectedItem && client) selectedItem = queue.find((item) => item.beta_client_id === client.id) || null;

  const detail = client ? betaClientDetail(client, root) : null;
  const feedback = selectedLead ? ensureRepFeedback(selectedLead) : null;
  const repBrief = selectedLead ? buildRepReadyBrief(selectedLead, root) : null;
  const crmDeliveries = selectedLead ? crmDeliveriesForLead(selectedLead.id) : [];
  const latestCrmDelivery = crmDeliveries[0] || null;
  const crmSent = crmDeliveries.some((delivery) => delivery.status === "sent");
  const repAlert = selectedLead ? repAlertForLead(selectedLead.id) : null;
  const repAlertRecipients = selectedLead ? repAlertRecipientsForLead(selectedLead) : [];
  const feedbackReviewed = feedback ? feedback.status !== "not_reviewed" : false;
  const clientProfileCount = clientLeads.length || Number(selectedItem?.lead_count || 0);
  const crmAdapter = selectedLead ? crmDeliveryAdapterStatus({ crm_delivery: crmDeliverySettingsForLead(selectedLead) }) : crmDeliveryAdapterStatus();
  const emailAdapter = reportEmailAdapterStatus();
  const status = !client
    ? "needs_real_beta_client"
    : !clientProfileCount || !selectedLead
      ? "first_profile_needed"
      : !crmSent
        ? "crm_handoff_needed"
        : !feedbackReviewed
          ? "rep_feedback_needed"
          : market.market_ready
            ? "market_ready_review"
            : "proof_packet_ready";
  const currentAction = !client
    ? {
        key: "create_real_beta_client",
        label: "Create real beta client",
        method: "GET",
        instruction: "Convert a buyer-confirmed prospect into a real beta client before handoff.",
        surface: `${root}/activation`
      }
    : !selectedLead
      ? {
          key: "capture_first_profile",
          label: "Capture first beta profile",
          method: "POST",
          instruction: "Use the first-profile capture room to create or capture one beta-attributed buyer profile.",
          surface: `${root}/launch/first-profile?client=${encodeURIComponent(client.id)}`
        }
      : !crmSent
        ? {
            key: "send_crm_handoff",
            label: "Send CRM handoff proof",
            method: "POST",
            instruction: "Review the profile, then use the explicit CRM delivery POST to record dry-run or webhook handoff proof.",
            surface: `${root}/crm/${encodeURIComponent(selectedLead.id)}`
          }
        : !feedbackReviewed
          ? {
              key: "collect_rep_feedback",
              label: "Collect rep feedback",
              method: "POST",
              instruction: "Send the public rep handoff and feedback room, then collect one rep review after the profile is worked.",
              surface: detail?.public_feedback_url || ""
            }
          : {
              key: "assemble_proof_packet",
              label: "Assemble proof packet",
              method: "GET",
              instruction: "CRM handoff and rep feedback exist. Review the first proof packet gate before any live-proof claim.",
              surface: `${root}/launch/proof-packet${client ? `?client=${encodeURIComponent(client.id)}` : ""}`
            };
  const profileStatus = selectedLead ? "pass" : "blocker";
  const crmStatus = selectedLead ? (crmSent ? "pass" : crmDeliveries.length ? "warning" : "blocker") : "blocker";
  const feedbackStatus = selectedLead ? (feedbackReviewed ? "pass" : "blocker") : "blocker";
  const proofStatus = crmSent && feedbackReviewed ? (market.market_ready ? "pass" : "warning") : "blocker";
  const handoffChecklist = [
    {
      key: "first_beta_profile",
      label: "First beta profile",
      status: profileStatus,
      status_label: humanizeEnum(profileStatus),
      evidence: selectedLead
        ? `${selectedLead.id} captured for ${selectedLead.company?.name || selectedLead.company?.domain || client?.name || "selected beta client"}.`
        : `${clientProfileCount} beta-attributed profile${clientProfileCount === 1 ? "" : "s"} captured.`,
      action: selectedLead ? "Review the profile and move it into CRM/rep handoff." : "Capture the first beta profile from the client-specific widget."
    },
    {
      key: "rep_ready_brief",
      label: "Rep-ready brief",
      status: selectedLead ? "pass" : "blocker",
      status_label: selectedLead ? "Pass" : "Blocker",
      evidence: selectedLead ? `${repBrief?.call_plan?.length || 0} call-plan steps and ${repBrief?.discovery_questions?.length || 0} discovery questions generated.` : "No profile is available for brief generation.",
      action: selectedLead ? "Use the brief before the first touch." : "Capture a beta profile first."
    },
    {
      key: "crm_handoff_proof",
      label: "CRM handoff proof",
      status: crmStatus,
      status_label: humanizeEnum(crmStatus),
      evidence: crmSent
        ? `${crmDeliveries.filter((delivery) => delivery.status === "sent").length} sent CRM handoff proof record${crmDeliveries.filter((delivery) => delivery.status === "sent").length === 1 ? "" : "s"} captured.`
        : crmDeliveries.length
          ? `${crmDeliveries.length} CRM delivery record${crmDeliveries.length === 1 ? "" : "s"} queued or pending.`
          : "No CRM handoff proof record has been sent yet.",
      action: crmSent ? "CRM handoff proof exists." : selectedLead ? "Use the explicit CRM delivery POST after operator review." : "Capture a beta profile before CRM handoff."
    },
    {
      key: "rep_alert_or_handoff",
      label: "Rep alert or handoff",
      status: selectedLead ? (repAlert?.status === "sent" ? "pass" : repAlert ? "warning" : "warning") : "blocker",
      status_label: selectedLead ? (repAlert?.status === "sent" ? "Pass" : "Warning") : "Blocker",
      evidence: repAlert ? `${humanizeEnum(repAlert.status)} rep alert for ${repAlert.recipients.join(", ") || "rep owner"}.` : selectedLead ? "Public rep handoff packet is available; no protected rep alert has been sent yet." : "No profile is available for rep handoff.",
      action: selectedLead ? "Send the public handoff or explicit rep alert, then request feedback after first touch." : "Capture a beta profile before rep handoff."
    },
    {
      key: "rep_feedback",
      label: "Rep feedback",
      status: feedbackStatus,
      status_label: humanizeEnum(feedbackStatus),
      evidence: feedbackReviewed ? `${feedback.status_label}${feedback.usefulness_score !== null ? `, ${feedback.usefulness_score}/5` : ""}.` : "No rep review has been captured for the selected profile.",
      action: feedbackReviewed ? "Rep feedback proof exists." : selectedLead ? "Use the feedback room or protected rep feedback POST after the rep works the profile." : "Capture a beta profile before requesting feedback."
    },
    {
      key: "proof_packet_gate",
      label: "Proof packet gate",
      status: proofStatus,
      status_label: humanizeEnum(proofStatus),
      evidence: market.market_ready ? "Market gate is clear." : `${market.summary?.blocker ?? 0} market blocker${market.summary?.blocker === 1 ? "" : "s"} remain.`,
      action: crmSent && feedbackReviewed ? "Review the proof packet before buyer-facing proof claims." : "Keep proof packet and live-proof claims blocked until CRM handoff and rep feedback exist."
    }
  ];
  const safety = {
    protected_operator_only: true,
    read_only_get: true,
    creates_profile_on_get: false,
    sends_external_email_on_get: false,
    sends_rep_alert_on_get: false,
    queues_crm_delivery_on_get: false,
    transmits_external_crm_on_get: false,
    updates_rep_feedback_on_get: false,
    mutates_buyer_state_on_get: false,
    creates_beta_client_on_get: false,
    paid_provider_lookup_by_default: false,
    live_proof_claimed: false,
    crm_delivery_requires_post: true,
    rep_alert_requires_post: true,
    rep_feedback_requires_post: true
  };
  const actions = selectedLead
    ? {
        crm_delivery: {
          key: "send_crm_handoff",
          label: latestCrmDelivery?.status === "sent" ? "Send another CRM delivery" : "Send CRM delivery",
          method: "POST",
          html_action: `/crm/${encodeURIComponent(selectedLead.id)}/crm-delivery/send`,
          api_url: `${root}/api/v1/leads/${encodeURIComponent(selectedLead.id)}/crm-delivery/send`,
          mutates_state: true,
          transmits_external_crm_on_post: crmAdapter.transmits_external_crm,
          preview_only_on_get: true,
          payload_preview: {
            destinationName: latestCrmDelivery?.destination_name || crmDeliverySettingsForLead(selectedLead).destination_name,
            note: "First beta profile handoff proof."
          }
        },
        rep_alert: {
          key: "send_rep_alert",
          label: repAlert?.status === "sent" ? "Send another rep alert" : "Send rep alert",
          method: "POST",
          html_action: `/crm/${encodeURIComponent(selectedLead.id)}/rep-alert/send`,
          api_url: `${root}/api/v1/leads/${encodeURIComponent(selectedLead.id)}/rep-alert/send`,
          mutates_state: true,
          sends_external_email_on_post: emailAdapter.transmits_external_email,
          preview_only_on_get: true,
          payload_preview: {
            recipients: repAlertRecipients.join(", "),
            subject: repAlertSubject(selectedLead)
          }
        },
        protected_rep_feedback: {
          key: "save_rep_feedback",
          label: "Save protected rep feedback",
          method: "POST",
          html_action: `/crm/${encodeURIComponent(selectedLead.id)}/rep-feedback`,
          api_url: `${root}/api/v1/leads/${encodeURIComponent(selectedLead.id)}/rep-feedback`,
          mutates_state: true,
          preview_only_on_get: true
        }
      }
    : {
        crm_delivery: null,
        rep_alert: null,
        protected_rep_feedback: null
      };
  const links = {
    operator_room: `${root}/launch/profile-handoff${client ? `?client=${encodeURIComponent(client.id)}` : ""}${selectedLead ? `${client ? "&" : "?"}lead=${encodeURIComponent(selectedLead.id)}` : ""}`,
    markdown: `${root}/api/v1/launch/profile-handoff?format=markdown${client ? `&client=${encodeURIComponent(client.id)}` : ""}${selectedLead ? `&lead=${encodeURIComponent(selectedLead.id)}` : ""}`,
    first_profile: `${root}/launch/first-profile${client ? `?client=${encodeURIComponent(client.id)}` : ""}`,
    proof_capture: `${root}/launch/proof-capture${client ? `?client=${encodeURIComponent(client.id)}` : ""}`,
    proof_packet: `${root}/launch/proof-packet${client ? `?client=${encodeURIComponent(client.id)}` : ""}`,
    market_gate: `${root}/launch/market-ready`,
    install_queue: `${root}/launch/install-queue`,
    crm_profile: selectedLead ? `${root}/crm/${encodeURIComponent(selectedLead.id)}` : "",
    providerless_evidence: selectedLead ? `${root}/crm/${encodeURIComponent(selectedLead.id)}/providerless-evidence` : "",
    rep_brief: selectedLead ? `${root}/api/v1/leads/${encodeURIComponent(selectedLead.id)}/rep-brief` : "",
    rep_brief_markdown: selectedLead ? `${root}/api/v1/leads/${encodeURIComponent(selectedLead.id)}/rep-brief?format=markdown` : "",
    public_rep_handoff: client && selectedLead ? publicBetaLeadHandoffUrl(client, selectedLead, root) : "",
    public_feedback_room: detail?.public_feedback_url || "",
    public_feedback_profile: detail?.public_feedback_url && selectedLead ? `${detail.public_feedback_url}#${encodeURIComponent(selectedLead.id)}` : "",
    manual_crm_export: detail?.public_crm_export_url || "",
    manual_crm_export_markdown: detail?.public_crm_export_markdown_url || "",
    buyer_safe_proof: detail?.public_beta_proof_url || ""
  };
  const packet = {
    type: "deal_threads.launch_profile_handoff_bridge.v1",
    generated_at: now(),
    status,
    status_label: humanizeEnum(status),
    market_ready: market.market_ready,
    decision: selectedLead
      ? crmSent && feedbackReviewed
        ? "The first profile has CRM handoff proof and rep feedback. Move to proof packet review before any live-proof claim."
        : "The first profile exists. Use this bridge to record CRM handoff proof and collect rep feedback without adding paid enrichment."
      : client
        ? "Install proof exists, but no beta-attributed profile is ready for handoff yet. Capture the first profile first."
        : "No real beta client is available for profile handoff. Convert a buyer-confirmed prospect first.",
    summary: {
      selected_beta_client_id: client?.id || null,
      selected_beta_client_name: client?.name || null,
      selected_domain: client?.domain || null,
      selected_lead_id: selectedLead?.id || null,
      selected_company: selectedLead?.company?.name || selectedLead?.company?.domain || null,
      selected_contact: selectedLead?.contact?.name || selectedLead?.contact?.email || null,
      beta_profiles: clientProfileCount,
      crm_delivery_records: crmDeliveries.length,
      crm_handoff_sent: crmSent,
      rep_alert_status: repAlert?.status || "not_queued",
      rep_feedback_status: feedback?.status || "not_reviewed",
      rep_feedback_score: feedback?.usefulness_score ?? null,
      rep_feedback_reviewed: feedbackReviewed,
      proof_preflight_blockers: selectedItem?.proof_preflight?.summary?.blocker ?? null,
      proof_preflight_warnings: selectedItem?.proof_preflight?.summary?.warning ?? null,
      required_code_builds_before_first_beta: market.readiness_estimate?.counts?.required_code_builds_before_first_beta ?? 0,
      required_real_world_steps: market.readiness_estimate?.counts?.required_real_world_steps ?? market.summary?.blocker ?? 0,
      paid_lookups_recommended_now: 0
    },
    current_action: currentAction,
    selected_client: client
      ? {
          id: client.id,
          name: client.name,
          domain: client.domain,
          owner_email: client.owner_email,
          crm: client.crm,
          status: client.status
        }
      : null,
    selected_profile: selectedLead
      ? {
          id: selectedLead.id,
          created_at: selectedLead.created_at,
          company: selectedLead.company?.name || selectedLead.company?.domain || "Unknown company",
          contact: selectedLead.contact?.name || selectedLead.contact?.email || "Unknown contact",
          email: selectedLead.contact?.email || null,
          priority: selectedLead.score?.priority || "unknown",
          icp_fit: selectedLead.score?.icp_fit || 0,
          business_need: selectedLead.qualification?.business_need || null,
          timeline: selectedLead.qualification?.timeline || "unknown",
          budget: selectedLead.qualification?.budget_range || selectedLead.qualification?.budget_status || "unknown",
          crm: selectedLead.qualification?.crm || selectedLead.crm?.provider || client?.crm || "unknown"
        }
      : null,
    rep_ready_brief: repBrief
      ? {
          version: repBrief.version,
          headline: repBrief.headline,
          owner: repBrief.owner,
          call_plan: repBrief.call_plan,
          discovery_questions: repBrief.discovery_questions,
          quality_flags: repBrief.quality_flags,
          copy_blocks: repBrief.copy_blocks,
          paid_provider_used: repBrief.evidence.paid_provider_used
        }
      : null,
    crm_handoff: {
      adapter: crmAdapter,
      latest_delivery: latestCrmDelivery ? crmDeliveryListItem(latestCrmDelivery) : null,
      sent_count: crmDeliveries.filter((delivery) => delivery.status === "sent").length,
      queued_count: crmDeliveries.filter((delivery) => delivery.status === "queued").length
    },
    rep_handoff: {
      alert: repAlert ? repAlertListItem(repAlert) : null,
      recipients: repAlertRecipients,
      email_adapter: emailAdapter,
      feedback,
      public_feedback_room: links.public_feedback_room,
      public_rep_handoff: links.public_rep_handoff
    },
    handoff_checklist: handoffChecklist,
    actions,
    links,
    safety,
    public_safety: safety
  };
  packet.markdown = launchProfileHandoffMarkdown(packet);
  return packet;
}

function launchProfileHandoffMarkdown(packet) {
  const checklistLines = packet.handoff_checklist.flatMap((item) => [
    `### ${item.label}`,
    "",
    `- Key: ${item.key}`,
    `- Status: ${item.status_label}`,
    `- Evidence: ${item.evidence}`,
    `- Action: ${item.action}`,
    ""
  ]);
  return `${[
    "# Deal Threads Profile Handoff Bridge",
    "",
    `Generated: ${formatDateTime(packet.generated_at)}`,
    `Status: ${packet.status_label}`,
    `Market ready: ${packet.market_ready ? "yes" : "no"}`,
    "",
    "## Decision",
    "",
    packet.decision,
    "",
    "## Summary",
    "",
    `- Selected beta client: ${packet.summary.selected_beta_client_name || "none"}`,
    `- Selected beta client ID: ${packet.summary.selected_beta_client_id || "none"}`,
    `- Selected profile: ${packet.summary.selected_lead_id || "none"}`,
    `- Beta profiles: ${packet.summary.beta_profiles}`,
    `- CRM delivery records: ${packet.summary.crm_delivery_records}`,
    `- CRM handoff sent: ${packet.summary.crm_handoff_sent ? "yes" : "no"}`,
    `- Rep alert status: ${humanizeEnum(packet.summary.rep_alert_status)}`,
    `- Rep feedback status: ${humanizeEnum(packet.summary.rep_feedback_status)}`,
    `- Required code builds before first beta: ${packet.summary.required_code_builds_before_first_beta}`,
    `- Required real-world steps: ${packet.summary.required_real_world_steps}`,
    `- Paid lookups recommended now: ${packet.summary.paid_lookups_recommended_now}`,
    "",
    "## Current Action",
    "",
    `- Key: ${packet.current_action.key}`,
    `- Label: ${packet.current_action.label}`,
    `- Method: ${packet.current_action.method}`,
    `- Instruction: ${packet.current_action.instruction}`,
    `- Surface: ${packet.current_action.surface || "not available"}`,
    "",
    "## Handoff Checklist",
    "",
    ...checklistLines,
    "## Handoff Links",
    "",
    `- CRM profile: ${packet.links.crm_profile || "not available"}`,
    `- Rep brief: ${packet.links.rep_brief || "not available"}`,
    `- Public rep handoff: ${packet.links.public_rep_handoff || "not available"}`,
    `- Public feedback room: ${packet.links.public_feedback_room || "not available"}`,
    `- Manual CRM export: ${packet.links.manual_crm_export || "not available"}`,
    `- Buyer-safe proof: ${packet.links.buyer_safe_proof || "not available"}`,
    `- Proof packet: ${packet.links.proof_packet}`,
    "",
    "## Operator POST Previews",
    "",
    packet.actions.crm_delivery
      ? `- CRM delivery POST: ${packet.actions.crm_delivery.html_action}\n- External CRM on POST: ${packet.actions.crm_delivery.transmits_external_crm_on_post ? "yes" : "no"}`
      : "- CRM delivery POST: not available until a profile exists",
    packet.actions.rep_alert
      ? `- Rep alert POST: ${packet.actions.rep_alert.html_action}\n- External email on POST: ${packet.actions.rep_alert.sends_external_email_on_post ? "yes" : "no"}`
      : "- Rep alert POST: not available until a profile exists",
    packet.actions.protected_rep_feedback ? `- Protected rep feedback POST: ${packet.actions.protected_rep_feedback.html_action}` : "- Protected rep feedback POST: not available until a profile exists",
    "",
    "## Safety",
    "",
    `- Protected operator only: ${packet.safety.protected_operator_only ? "yes" : "no"}`,
    `- Read-only GET: ${packet.safety.read_only_get ? "yes" : "no"}`,
    `- GET creates profile: ${packet.safety.creates_profile_on_get ? "yes" : "no"}`,
    `- GET sends external email: ${packet.safety.sends_external_email_on_get ? "yes" : "no"}`,
    `- GET sends rep alert: ${packet.safety.sends_rep_alert_on_get ? "yes" : "no"}`,
    `- GET queues CRM delivery: ${packet.safety.queues_crm_delivery_on_get ? "yes" : "no"}`,
    `- GET transmits CRM data: ${packet.safety.transmits_external_crm_on_get ? "yes" : "no"}`,
    `- GET updates rep feedback: ${packet.safety.updates_rep_feedback_on_get ? "yes" : "no"}`,
    `- Paid lookup by default: ${packet.safety.paid_provider_lookup_by_default ? "yes" : "no"}`,
    `- Live proof claimed: ${packet.safety.live_proof_claimed ? "yes" : "no"}`,
    `- CRM delivery requires POST: ${packet.safety.crm_delivery_requires_post ? "yes" : "no"}`,
    `- Rep alert requires POST: ${packet.safety.rep_alert_requires_post ? "yes" : "no"}`,
    `- Rep feedback requires POST: ${packet.safety.rep_feedback_requires_post ? "yes" : "no"}`
  ].join("\n")}\n`;
}

function launchRepFeedbackProfileItem(client, lead, root = "") {
  const feedback = ensureRepFeedback(lead);
  const reviewed =
    feedback.status !== "not_reviewed" ||
    feedback.usefulness_score !== null ||
    feedback.rep_confidence !== "unknown" ||
    feedback.used_on_call ||
    feedback.missing_fields.length ||
    feedback.last_note;
  const company = lead.company?.name || lead.company?.domain || "Unknown company";
  const contact = lead.contact?.name || lead.contact?.email || "Unknown contact";
  const publicFeedbackRoom = betaClientPublicFeedbackUrl(client, root);
  return {
    lead_id: lead.id,
    created_at: lead.created_at,
    company,
    contact,
    email: lead.contact?.email || "",
    priority: lead.score?.priority || "unknown",
    score: Number(lead.score?.total || lead.score?.icp_fit || 0),
    business_need: lead.qualification?.business_need || "",
    timeline: lead.qualification?.timeline || "unknown",
    budget: lead.qualification?.budget_range || lead.qualification?.budget_status || "unknown",
    crm: lead.qualification?.crm || lead.crm?.provider || client.crm || "unknown",
    reviewed,
    needs_feedback: !reviewed,
    feedback: {
      status: feedback.status,
      status_label: feedback.status_label,
      usefulness_score: feedback.usefulness_score,
      rep_confidence: feedback.rep_confidence,
      rep_confidence_label: feedback.rep_confidence_label,
      used_on_call: feedback.used_on_call,
      missing_fields: feedback.missing_fields,
      missing_field_labels: feedback.missing_field_labels,
      last_note: feedback.last_note,
      reviewed_by: feedback.reviewed_by,
      reviewed_at: feedback.reviewed_at
    },
    public_links: {
      rep_handoff: publicBetaLeadHandoffUrl(client, lead, root),
      feedback_room: publicFeedbackRoom,
      feedback_profile_anchor: `${publicFeedbackRoom}#${encodeURIComponent(lead.id)}`
    },
    protected_links: {
      crm_profile: `${root}/crm/${encodeURIComponent(lead.id)}`,
      rep_brief_markdown: `${root}/api/v1/leads/${encodeURIComponent(lead.id)}/rep-brief?format=markdown`,
      protected_feedback_post: `${root}/api/v1/leads/${encodeURIComponent(lead.id)}/rep-feedback`,
      profile_handoff: `${root}/launch/profile-handoff?client=${encodeURIComponent(client.id)}&lead=${encodeURIComponent(lead.id)}`
    }
  };
}

function launchRepFeedbackCopyBlock(client, item, profileItems, root = "") {
  const selectedProfile = profileItems.find((profile) => profile.needs_feedback) || profileItems[0] || null;
  const detail = betaClientDetail(client, root);
  const recipients = uniqueStrings([
    ...(normalizeOptionalList(detail.report_settings?.recipients) || []),
    detail.high_priority_owner,
    detail.medium_priority_owner,
    detail.owner_email,
    item.owner_email
  ]);
  const subject = selectedProfile
    ? `Quick score request: Deal Threads profile for ${selectedProfile.company}`
    : `Rep feedback needed after the first Deal Threads profile for ${detail.name}`;
  const body = selectedProfile
    ? [
        `Can you score the Deal Threads buyer profile for ${selectedProfile.company} after the rep works it?`,
        "",
        `Public rep handoff: ${selectedProfile.public_links.rep_handoff}`,
        `Feedback room: ${selectedProfile.public_links.feedback_profile_anchor}`,
        "",
        "Please answer three things:",
        "1. Did the profile make first touch faster or more useful?",
        "2. What context was missing?",
        "3. Did it change the opening call, routing decision, or next step?",
        "",
        "No login is required. The score only updates pilot proof and conversation-flow decisions; it does not trigger paid enrichment or CRM writes."
      ].join("\n")
    : [
        `Once ${detail.name} has its first beta buyer profile, send the tokenized feedback room to the rep who works it.`,
        "",
        `Feedback room: ${detail.public_feedback_url}`,
        `Public install status: ${detail.public_install_status_url}`,
        "",
        "The goal is to learn whether the profile changed first-touch quality before buying any enrichment data."
      ].join("\n");
  return {
    key: "rep_feedback_ask",
    label: "Copy-ready rep ask",
    subject,
    body,
    recipients,
    mailto_url: mailtoDraftUrl({ recipients, subject, body }),
    primary_link: selectedProfile?.public_links.feedback_profile_anchor || detail.public_feedback_url,
    selected_lead_id: selectedProfile?.lead_id || null,
    sends_from_server: false,
    mutates_state_on_get: false
  };
}

function launchRepFeedbackClientItem(item, baseUrl = "") {
  const root = baseUrl.replace(/\/$/, "");
  const client = state.betaClients.get(item.beta_client_id);
  if (!client) return null;
  const detail = betaClientDetail(client, root);
  const leads = allLeadsSorted().filter((lead) => lead.source?.beta_client_id === client.id);
  const profileItems = leads.map((lead) => launchRepFeedbackProfileItem(client, lead, root));
  const pendingProfiles = profileItems.filter((profile) => profile.needs_feedback);
  const gapProfiles = profileItems.filter((profile) => ["missing_context", "not_helpful", "needs_rework"].includes(profile.feedback.status) || profile.feedback.missing_fields.length);
  const copyBlock = launchRepFeedbackCopyBlock(client, item, profileItems, root);
  const status = !profileItems.length
    ? "waiting_for_profiles"
    : pendingProfiles.length
      ? "feedback_needed"
      : gapProfiles.length
        ? "feedback_captured_with_gaps"
        : "feedback_clear";
  const nextAction =
    status === "waiting_for_profiles"
      ? "Capture the first beta-attributed buyer profile before asking a rep for feedback."
      : status === "feedback_needed"
        ? "Send the copy-ready rep ask and public feedback room after the profile is worked."
        : status === "feedback_captured_with_gaps"
          ? "Use missing-context feedback to tune widget questions or providerless evidence before buying data."
          : "Rep feedback is captured. Move this client into proof-packet and market-gate review.";
  return {
    beta_client_id: client.id,
    beta_client_name: detail.name,
    domain: detail.domain,
    owner_email: detail.owner_email,
    crm: detail.crm,
    status,
    status_label: humanizeEnum(status),
    next_action: nextAction,
    summary: {
      beta_profiles: profileItems.length,
      pending_profiles: pendingProfiles.length,
      reviewed_profiles: item.rep_feedback?.reviewed_profiles || 0,
      helpful_profiles: item.rep_feedback?.helpful_profiles || 0,
      missing_context_profiles: item.rep_feedback?.missing_context_profiles || 0,
      not_helpful_profiles: item.rep_feedback?.not_helpful_profiles || 0,
      needs_rework_profiles: item.rep_feedback?.needs_rework_profiles || 0,
      average_usefulness_score: item.rep_feedback?.average_usefulness_score ?? null,
      used_on_call_profiles: item.rep_feedback?.used_on_call_profiles || 0,
      crm_handoffs: item.crm_delivery_count || 0,
      proof_preflight_status: item.proof_preflight?.status || "unknown"
    },
    profiles: profileItems,
    pending_profiles: pendingProfiles,
    gap_profiles: gapProfiles,
    copy_block: copyBlock,
    public_links: {
      feedback_room: detail.public_feedback_url,
      install_status: detail.public_install_status_url,
      manual_crm_export: detail.public_crm_export_url,
      beta_proof_report: detail.public_beta_proof_url
    },
    protected_links: {
      install_workbench: `${root}/launch/install-queue/${encodeURIComponent(client.id)}/workbench`,
      profile_handoff: `${root}/launch/profile-handoff?client=${encodeURIComponent(client.id)}`,
      proof_packet: `${root}/launch/proof-packet?client=${encodeURIComponent(client.id)}`,
      market_gate: `${root}/launch/market-ready`
    }
  };
}

function launchRepFeedbackCommand(baseUrl = "", searchParams = new URLSearchParams()) {
  const root = baseUrl.replace(/\/$/, "");
  const installQueue = launchInstallQueue(baseUrl, searchParams);
  const market = marketLaunchReadinessPacket(baseUrl, searchParams);
  const clients = (installQueue.queue || []).map((item) => launchRepFeedbackClientItem(item, baseUrl)).filter(Boolean);
  const allProfiles = clients.flatMap((client) => client.profiles);
  const pendingProfiles = allProfiles.filter((profile) => profile.needs_feedback);
  const gapProfiles = allProfiles.filter((profile) => ["missing_context", "not_helpful", "needs_rework"].includes(profile.feedback.status) || profile.feedback.missing_fields.length);
  const aggregateFeedback = leadAnalytics(
    allLeadsSorted().filter((lead) => clients.some((client) => client.beta_client_id === lead.source?.beta_client_id))
  ).rep_feedback;
  const firstPendingClient = clients.find((client) => client.pending_profiles.length) || null;
  const firstWaitingClient = clients.find((client) => client.status === "waiting_for_profiles") || null;
  const status = !clients.length
    ? "needs_real_beta_client"
    : !allProfiles.length
      ? "waiting_for_profiles"
      : pendingProfiles.length
        ? "feedback_needed"
        : gapProfiles.length
          ? "feedback_captured_with_gaps"
          : "feedback_clear";
  const currentAction = !clients.length
    ? {
        key: "create_real_beta_client",
        label: "Create real beta client",
        method: "GET",
        instruction: "Convert a buyer-confirmed activation prospect before collecting rep feedback.",
        surface: `${root}/activation`
      }
    : !allProfiles.length
      ? {
          key: "capture_first_profile",
          label: "Capture first beta profile",
          method: "GET",
          instruction: "Open first-profile capture for the next installed beta client, then return here.",
          surface: firstWaitingClient?.protected_links.profile_handoff || `${root}/launch/first-profile`
        }
      : pendingProfiles.length
        ? {
            key: "send_rep_feedback_ask",
            label: "Send rep feedback ask",
            method: "manual",
            instruction: "Use the copy-ready rep ask below after the profile has been worked.",
            surface: firstPendingClient?.copy_block.primary_link || `${root}/launch/install-queue`
          }
        : gapProfiles.length
          ? {
              key: "review_missing_context",
              label: "Review missing context",
              method: "GET",
              instruction: "Tune the conversation flow or providerless evidence based on the feedback gaps before buying data.",
              surface: `${root}/enrichment/review-queue`
            }
          : {
              key: "review_proof_packet",
              label: "Review proof packet",
              method: "GET",
              instruction: "Rep feedback is captured. Assemble proof packet evidence before external live-proof claims.",
              surface: `${root}/launch/proof-packet`
            };
  const recommendedActions = uniqueStrings([
    !clients.length ? "Convert a buyer-confirmed activation prospect into a real beta client." : null,
    clients.length && !allProfiles.length ? "Capture one beta-attributed profile before asking for rep usefulness feedback." : null,
    pendingProfiles.length ? `Send rep feedback asks for ${pendingProfiles.length} pending profile${pendingProfiles.length === 1 ? "" : "s"}.` : null,
    gapProfiles.length ? "Review missing-context feedback before changing the enrichment stack or buying data." : null,
    !pendingProfiles.length && allProfiles.length ? "Move feedback-reviewed clients into proof-packet and market-gate review." : null,
    "Keep paid enrichment disabled until repeated rep feedback proves a missing field changes first-touch quality."
  ]);
  const safety = {
    protected_operator_only: true,
    read_only_get: true,
    sends_external_email_on_get: false,
    creates_profile_on_get: false,
    mutates_buyer_state_on_get: false,
    creates_beta_client_on_get: false,
    queues_crm_delivery_on_get: false,
    transmits_external_crm_on_get: false,
    updates_rep_feedback_on_get: false,
    paid_provider_lookup_by_default: false,
    live_proof_claimed: false,
    feedback_submission_requires_external_rep_or_post: true
  };
  const packet = {
    type: "deal_threads.launch_rep_feedback_command.v1",
    generated_at: now(),
    status,
    status_label: humanizeEnum(status),
    market_ready: market.market_ready,
    decision:
      status === "feedback_clear"
        ? "Rep feedback is captured for the current beta proof scope. Review the proof packet before external claims."
        : status === "feedback_captured_with_gaps"
          ? "Rep feedback is captured, but missing-context trends should shape the conversation flow or providerless evidence before buying data."
          : "Rep feedback is still an evidence gap. Keep market-ready and live-proof claims blocked until reps score worked profiles.",
    summary: {
      real_beta_clients: clients.length,
      beta_profiles: allProfiles.length,
      pending_profiles: pendingProfiles.length,
      reviewed_profiles: aggregateFeedback.reviewed_profiles,
      helpful_profiles: aggregateFeedback.helpful_profiles,
      missing_context_profiles: aggregateFeedback.missing_context_profiles,
      not_helpful_profiles: aggregateFeedback.not_helpful_profiles,
      needs_rework_profiles: aggregateFeedback.needs_rework_profiles,
      used_on_call_profiles: aggregateFeedback.used_on_call_profiles,
      scored_profiles: aggregateFeedback.scored_profiles,
      average_usefulness_score: aggregateFeedback.average_usefulness_score,
      feedback_needed_clients: clients.filter((client) => client.status === "feedback_needed").length,
      waiting_for_profile_clients: clients.filter((client) => client.status === "waiting_for_profiles").length,
      market_blockers: market.summary?.blocker || 0,
      market_warnings: market.summary?.warning || 0,
      required_code_builds_before_first_beta: market.readiness_estimate?.counts?.required_code_builds_before_first_beta ?? 0,
      required_real_world_steps: market.readiness_estimate?.counts?.required_real_world_steps ?? market.summary?.blocker ?? 0,
      paid_lookups_recommended_now: 0
    },
    current_action: currentAction,
    clients,
    copy_blocks: {
      primary_rep_ask: firstPendingClient?.copy_block || clients[0]?.copy_block || null
    },
    recommended_actions: recommendedActions,
    links: {
      operator_room: `${root}/launch/rep-feedback`,
      markdown: `${root}/api/v1/launch/rep-feedback?format=markdown`,
      install_queue: `${root}/launch/install-queue`,
      profile_handoff: `${root}/launch/profile-handoff`,
      proof_capture: `${root}/launch/proof-capture`,
      proof_packet: `${root}/launch/proof-packet`,
      market_gate: `${root}/launch/market-ready`,
      proof_ledger: `${root}/launch/proof-ledger`,
      enrichment_review_queue: `${root}/enrichment/review-queue`
    },
    source_packets: {
      install_queue: `${root}/api/v1/launch/install-queue?format=markdown`,
      profile_handoff: `${root}/api/v1/launch/profile-handoff?format=markdown`,
      proof_packet: `${root}/api/v1/launch/proof-packet?format=markdown`,
      market_gate: `${root}/api/v1/launch/market-ready?format=markdown`,
      proof_ledger: `${root}/api/v1/launch/proof-ledger?format=markdown`
    },
    safety,
    public_safety: safety
  };
  packet.markdown = launchRepFeedbackCommandMarkdown(packet);
  return packet;
}

function launchRepFeedbackCommandMarkdown(packet) {
  const clientLines = packet.clients.length
    ? packet.clients.flatMap((client) => [
        `### ${client.beta_client_name}`,
        "",
        `- Status: ${client.status_label}`,
        `- Domain: ${client.domain || "unknown"}`,
        `- Beta profiles: ${client.summary.beta_profiles}`,
        `- Pending profiles: ${client.summary.pending_profiles}`,
        `- Reviewed profiles: ${client.summary.reviewed_profiles}`,
        `- Average usefulness: ${client.summary.average_usefulness_score ?? "not measured"}/5`,
        `- Feedback room: ${client.public_links.feedback_room}`,
        `- Profile handoff: ${client.protected_links.profile_handoff}`,
        `- Next action: ${client.next_action}`,
        ""
      ])
    : ["No real beta clients are available for rep feedback yet."];
  const pendingLines = packet.clients.flatMap((client) =>
    client.pending_profiles.map((profile) => `- ${client.beta_client_name}: ${profile.company} (${profile.lead_id}) - ${profile.public_links.feedback_profile_anchor}`)
  );
  const copyBlock = packet.copy_blocks.primary_rep_ask;
  return `${[
    "# Deal Threads Rep Feedback Command",
    "",
    `Generated: ${formatDateTime(packet.generated_at)}`,
    `Status: ${packet.status_label}`,
    `Market ready: ${packet.market_ready ? "yes" : "no"}`,
    "",
    "## Decision",
    "",
    packet.decision,
    "",
    "## Summary",
    "",
    `- Real beta clients: ${packet.summary.real_beta_clients}`,
    `- Beta profiles: ${packet.summary.beta_profiles}`,
    `- Pending profiles: ${packet.summary.pending_profiles}`,
    `- Reviewed profiles: ${packet.summary.reviewed_profiles}`,
    `- Helpful profiles: ${packet.summary.helpful_profiles}`,
    `- Missing-context profiles: ${packet.summary.missing_context_profiles}`,
    `- Average usefulness: ${packet.summary.average_usefulness_score ?? "not measured"}/5`,
    `- Feedback-needed clients: ${packet.summary.feedback_needed_clients}`,
    `- Waiting-for-profile clients: ${packet.summary.waiting_for_profile_clients}`,
    `- Market blockers: ${packet.summary.market_blockers}`,
    `- Required code builds before first beta: ${packet.summary.required_code_builds_before_first_beta}`,
    `- Required real-world steps: ${packet.summary.required_real_world_steps}`,
    `- Paid lookups recommended now: ${packet.summary.paid_lookups_recommended_now}`,
    "",
    "## Current Action",
    "",
    `- Key: ${packet.current_action.key}`,
    `- Label: ${packet.current_action.label}`,
    `- Method: ${packet.current_action.method}`,
    `- Instruction: ${packet.current_action.instruction}`,
    `- Surface: ${packet.current_action.surface || "not available"}`,
    "",
    "## Copy-Ready Rep Ask",
    "",
    copyBlock
      ? `- Subject: ${copyBlock.subject}\n- Recipients: ${copyBlock.recipients.join(", ") || "review manually"}\n- Mailto draft: ${copyBlock.mailto_url}\n- Primary link: ${copyBlock.primary_link}\n\n\`\`\`text\n${copyBlock.body}\n\`\`\``
      : "No rep feedback copy is available until a real beta client exists.",
    "",
    "## Pending Profiles",
    "",
    ...(pendingLines.length ? pendingLines : ["No pending rep feedback profiles."]),
    "",
    "## Client Queue",
    "",
    ...clientLines,
    "## Recommended Actions",
    "",
    ...packet.recommended_actions.map((action) => `- ${action}`),
    "",
    "## Links",
    "",
    `- Operator room: ${packet.links.operator_room}`,
    `- Install queue: ${packet.links.install_queue}`,
    `- Profile handoff: ${packet.links.profile_handoff}`,
    `- Proof packet: ${packet.links.proof_packet}`,
    `- Market gate: ${packet.links.market_gate}`,
    `- Enrichment review queue: ${packet.links.enrichment_review_queue}`,
    "",
    "## Safety",
    "",
    `- Protected operator only: ${packet.safety.protected_operator_only ? "yes" : "no"}`,
    `- Read-only GET: ${packet.safety.read_only_get ? "yes" : "no"}`,
    `- GET sends external email: ${packet.safety.sends_external_email_on_get ? "yes" : "no"}`,
    `- GET creates profile: ${packet.safety.creates_profile_on_get ? "yes" : "no"}`,
    `- GET creates beta client: ${packet.safety.creates_beta_client_on_get ? "yes" : "no"}`,
    `- GET queues CRM delivery: ${packet.safety.queues_crm_delivery_on_get ? "yes" : "no"}`,
    `- GET transmits CRM data: ${packet.safety.transmits_external_crm_on_get ? "yes" : "no"}`,
    `- GET updates rep feedback: ${packet.safety.updates_rep_feedback_on_get ? "yes" : "no"}`,
    `- Paid lookup by default: ${packet.safety.paid_provider_lookup_by_default ? "yes" : "no"}`,
    `- Live proof claimed: ${packet.safety.live_proof_claimed ? "yes" : "no"}`,
    `- Feedback requires external rep or POST: ${packet.safety.feedback_submission_requires_external_rep_or_post ? "yes" : "no"}`
  ].join("\n")}\n`;
}

function launchProofCaptureRunbookPhase({ key, label, status, owner, evidence, action, surface, clears_gate: clearsGate, proof_condition: proofCondition }) {
  return {
    key,
    label,
    status,
    status_label: humanizeEnum(status),
    owner,
    evidence,
    action,
    surface,
    clears_gate: clearsGate,
    proof_condition: proofCondition
  };
}

function launchProofCaptureRunbook(baseUrl = "", searchParams = new URLSearchParams()) {
  const root = baseUrl.replace(/\/$/, "");
  const requestedClientId = searchParams.get("client") || searchParams.get("betaClientId") || searchParams.get("beta_client_id") || "";
  const installQueue = launchInstallQueue(baseUrl, searchParams);
  const market = marketLaunchReadinessPacket(baseUrl, searchParams);
  const liveGate = liveProofGate(searchParams);
  const nextAction = firstBetaNextActionPacket(baseUrl, searchParams);
  const selectedItem = requestedClientId
    ? installQueue.queue.find((item) => item.beta_client_id === requestedClientId) || null
    : installQueue.queue[0] || null;
  const proof = selectedItem?.proof_preflight || null;
  const proofSummary = proof?.summary || {};
  const clientDomainLoads = Number(proofSummary.client_domain_config_loads || selectedItem?.install_activity?.client_page_config_loads || 0);
  const betaProfiles = Number(proofSummary.beta_profiles || selectedItem?.lead_count || 0);
  const crmHandoffs = Number(proofSummary.crm_handoffs || selectedItem?.crm_delivery_count || 0);
  const repFeedback = Number(proofSummary.rep_feedback_reviews || selectedItem?.rep_feedback?.reviewed_profiles || 0);
  const proofPackets = Number(proofSummary.proof_packets_sent || 0);
  const phases = selectedItem
    ? [
        launchProofCaptureRunbookPhase({
          key: "client_domain_install",
          label: "Client-domain install proof",
          status: clientDomainLoads ? "pass" : "blocker",
          owner: "Implementation owner",
          evidence: clientDomainLoads
            ? `${clientDomainLoads} client-domain widget config load${clientDomainLoads === 1 ? "" : "s"} captured.`
            : "No buyer-domain widget config load has been captured yet.",
          action: clientDomainLoads ? "Install proof exists; move to first beta profile capture." : "Have the implementation owner load the buyer target page after installing the script.",
          surface: selectedItem.public_links.install_status || selectedItem.public_links.hosted_widget_load_test || "",
          clears_gate: "client_domain_install",
          proof_condition: "The buyer target page loads the client-specific widget config."
        }),
        launchProofCaptureRunbookPhase({
          key: "first_real_profile",
          label: "First real beta profile",
          status: betaProfiles ? "pass" : "blocker",
          owner: "Buyer website visitor and sales rep",
          evidence: betaProfiles
            ? `${betaProfiles} beta-attributed buyer profile${betaProfiles === 1 ? "" : "s"} captured.`
            : "No beta-attributed buyer profile has been captured.",
          action: betaProfiles ? "Open the latest beta profile and prove CRM handoff." : "Complete one buyer-like conversation through the client-specific widget.",
          surface: betaProfiles ? selectedItem.protected_links.latest_lead || selectedItem.protected_links.launch || "" : selectedItem.protected_links.launch || selectedItem.public_links.hosted_widget_load_test || "",
          clears_gate: "first_real_profile",
          proof_condition: "At least one consented buyer profile is created by the real beta client's widget and attributed to that beta client."
        }),
        launchProofCaptureRunbookPhase({
          key: "crm_handoff",
          label: "CRM handoff proof",
          status: crmHandoffs ? "pass" : betaProfiles ? "warning" : "blocker",
          owner: "RevOps or CRM owner",
          evidence: crmHandoffs
            ? `${crmHandoffs} CRM handoff${crmHandoffs === 1 ? "" : "s"} recorded.`
            : betaProfiles
              ? "A beta profile exists, but no CRM handoff proof has been recorded."
              : "No beta profile exists to hand off yet.",
          action: crmHandoffs
            ? "CRM proof exists; collect rep feedback on the worked profile."
            : betaProfiles
              ? "Send manual, dry-run, sandbox, or approved CRM delivery proof from the latest lead profile."
              : "Capture the first beta profile before CRM handoff proof.",
          surface: selectedItem.protected_links.latest_lead || selectedItem.public_links.manual_crm_export || "",
          clears_gate: "crm_handoff",
          proof_condition: "A buyer profile is copied, exported, dry-run delivered, sandbox delivered, or approved-live delivered to the CRM workflow."
        }),
        launchProofCaptureRunbookPhase({
          key: "rep_feedback",
          label: "Rep feedback",
          status: repFeedback ? "pass" : betaProfiles ? "warning" : "blocker",
          owner: "Sales rep",
          evidence: repFeedback
            ? `${repFeedback} rep feedback review${repFeedback === 1 ? "" : "s"} recorded.`
            : betaProfiles
              ? "A beta profile exists, but no rep usefulness feedback has been submitted."
              : "No beta profile exists for rep feedback yet.",
          action: repFeedback
            ? "Rep feedback exists; queue the first proof packet."
            : betaProfiles
              ? "Send the tokenized feedback room after the rep works the first profile."
              : "Capture a beta profile before requesting rep feedback.",
          surface: selectedItem.public_links.feedback_room || "",
          clears_gate: "rep_feedback",
          proof_condition: "A sales rep scores whether the profile helped first touch and names missing context."
        }),
        launchProofCaptureRunbookPhase({
          key: "first_proof_packet",
          label: "First proof packet",
          status: proofPackets ? "pass" : betaProfiles && repFeedback ? "warning" : "blocker",
          owner: "Deal Threads operator",
          evidence: proofPackets
            ? `${proofPackets} proof packet${proofPackets === 1 ? "" : "s"} sent or marked sent.`
            : betaProfiles && repFeedback
              ? "Profile and rep feedback proof exist, but the first proof packet has not been sent."
              : "Profile and rep feedback proof are required before the proof packet.",
          action: proofPackets
            ? "Proof packet exists; re-check the live proof gate."
            : betaProfiles && repFeedback
              ? "Queue or send the first buyer-safe proof packet."
              : "Wait for profile and rep feedback proof before sending the proof packet.",
          surface: selectedItem.public_links.beta_proof_report || selectedItem.protected_links.report || "",
          clears_gate: "live_proof_gate",
          proof_condition: "A buyer-safe proof packet summarizes install, profile, CRM handoff, rep usefulness, and paid-provider posture."
        }),
        launchProofCaptureRunbookPhase({
          key: "live_proof_gate",
          label: "Live proof gate",
          status: liveGate.live_ready ? "pass" : "blocker",
          owner: "Deal Threads operator",
          evidence: liveGate.live_ready ? "Live proof gate is clear." : liveGate.blockers[0] || "Live proof gate is blocked.",
          action: liveGate.live_ready ? "Prepare buyer-facing live proof." : liveGate.actions[0] || "Clear all proof blockers before using live proof claims.",
          surface: `${root}/api/v1/proof/live-gate${selectedItem ? `?betaClientId=${encodeURIComponent(selectedItem.beta_client_id)}` : ""}`,
          clears_gate: "live_proof_gate",
          proof_condition: "The live-proof export has zero blockers and no undisclosed synthetic/demo proof."
        })
      ]
    : [
        launchProofCaptureRunbookPhase({
          key: "buyer_confirmation",
          label: "Buyer confirmation",
          status: nextAction.status === "kickoff_ready" ? "pass" : "blocker",
          owner: "Buyer champion",
          evidence: nextAction.status === "kickoff_ready" ? "A buyer-confirmed prospect is ready for kickoff." : `Current next action is ${humanizeEnum(nextAction.status)} for ${nextAction.summary?.active_company || "the active buyer"}.`,
          action: nextAction.decision || "Work the active buyer follow-up until confirmation is captured.",
          surface: `${root}/launch/next-action`,
          clears_gate: "buyer_confirmation",
          proof_condition: "Buyer confirms target page, implementation owner, proof recipients, routing owner, and CRM posture."
        }),
        launchProofCaptureRunbookPhase({
          key: "real_beta_client",
          label: "Real beta-client kickoff",
          status: "blocker",
          owner: "Deal Threads operator",
          evidence: `${installQueue.summary.real_beta_clients} real beta client${installQueue.summary.real_beta_clients === 1 ? "" : "s"} in the install queue.`,
          action: "Run the explicit kickoff POST only after buyer confirmation is complete.",
          surface: `${root}/launch/first-beta-execution`,
          clears_gate: "real_beta_client",
          proof_condition: "A non-demo beta client is created or reused from the confirmed buyer and receives the install handoff."
        })
      ];
  const currentPhase = phases.find((phase) => phase.status !== "pass") || phases[phases.length - 1] || null;
  const openBlockers = phases.filter((phase) => phase.status === "blocker");
  const openWarnings = phases.filter((phase) => phase.status === "warning");
  const safety = {
    protected_operator_only: true,
    read_only_get: true,
    mutates_buyer_state_on_get: false,
    sends_external_email_on_get: false,
    creates_beta_client_on_get: false,
    transmits_external_crm_on_get: false,
    paid_provider_lookup_by_default: false,
    live_proof_claimed: false,
    operator_posts_are_previews_only: true
  };
  return {
    type: "deal_threads.launch_proof_capture_runbook.v1",
    generated_at: now(),
    status: selectedItem ? (liveGate.live_ready ? "live_proof_ready" : "proof_capture_in_progress") : "needs_real_beta_client",
    status_label: selectedItem ? (liveGate.live_ready ? "Live proof ready" : "Proof capture in progress") : "Needs real beta client",
    market_ready: market.market_ready,
    selected_beta_client: selectedItem
      ? {
          id: selectedItem.beta_client_id,
          name: selectedItem.beta_client_name,
          domain: selectedItem.domain,
          owner_email: selectedItem.owner_email,
          status: selectedItem.status,
          status_label: selectedItem.status_label,
          current_phase: selectedItem.current_phase,
          latest_lead: selectedItem.latest_lead
        }
      : null,
    summary: {
      real_beta_clients: installQueue.summary.real_beta_clients,
      real_beta_leads: installQueue.summary.real_beta_leads,
      market_status: market.status,
      market_blockers: market.summary?.blocker || 0,
      market_warnings: market.summary?.warning || 0,
      install_queue_status: installQueue.status,
      current_phase: currentPhase?.key || null,
      current_action: currentPhase?.action || null,
      blockers: openBlockers.length,
      warnings: openWarnings.length,
      client_domain_config_loads: clientDomainLoads,
      beta_profiles: betaProfiles,
      crm_handoffs: crmHandoffs,
      rep_feedback_reviews: repFeedback,
      proof_packets_sent: proofPackets,
      paid_lookups_recommended_now: 0
    },
    current_phase: currentPhase,
    phases,
    install_queue: {
      status: installQueue.status,
      summary: installQueue.summary,
      top_item: installQueue.queue[0] || null
    },
    live_proof_gate: {
      status: liveGate.status,
      status_label: liveGate.status_label,
      live_ready: liveGate.live_ready,
      summary: liveGate.summary,
      blockers: liveGate.blockers,
      warnings: liveGate.warnings,
      actions: liveGate.actions
    },
    links: {
      operator_room: `${root}/launch/proof-capture`,
      markdown: `${root}/api/v1/launch/proof-capture?format=markdown`,
      next_action: `${root}/launch/next-action`,
      first_beta_execution: `${root}/launch/first-beta-execution`,
      install_queue: `${root}/launch/install-queue`,
      launch_wizard: selectedItem?.protected_links.launch_wizard || `${root}/launch`,
      install_workbench: selectedItem?.protected_links.install_workbench || "",
      market_gate: `${root}/launch/market-ready`,
      live_proof_gate: `${root}/api/v1/proof/live-gate`
    },
    safety,
    public_safety: safety
  };
}

function launchProofCaptureRunbookMarkdown(packet) {
  const phaseLines = packet.phases.flatMap((phase) => [
    `### ${phase.label}`,
    "",
    `- Key: ${phase.key}`,
    `- Status: ${phase.status_label}`,
    `- Owner: ${phase.owner}`,
    `- Evidence: ${phase.evidence}`,
    `- Proof condition: ${phase.proof_condition}`,
    `- Action: ${phase.action}`,
    `- Surface: ${phase.surface || "not available"}`,
    `- Clears gate: ${phase.clears_gate}`,
    ""
  ]);
  return `${[
    "# Deal Threads Proof Capture Runbook",
    "",
    `Generated: ${formatDateTime(packet.generated_at)}`,
    `Status: ${packet.status_label}`,
    `Market ready: ${packet.market_ready ? "yes" : "no"}`,
    "",
    "## Current Focus",
    "",
    `- Phase: ${packet.current_phase?.label || "No active phase"}`,
    `- Status: ${packet.current_phase?.status_label || "unknown"}`,
    `- Action: ${packet.current_phase?.action || "No action available"}`,
    `- Surface: ${packet.current_phase?.surface || "not available"}`,
    "",
    "## Summary",
    "",
    `- Real beta clients: ${packet.summary.real_beta_clients}`,
    `- Real beta leads: ${packet.summary.real_beta_leads}`,
    `- Market status: ${humanizeEnum(packet.summary.market_status)}`,
    `- Market blockers: ${packet.summary.market_blockers}`,
    `- Install queue status: ${humanizeEnum(packet.summary.install_queue_status)}`,
    `- Client-domain config loads: ${packet.summary.client_domain_config_loads}`,
    `- Beta profiles: ${packet.summary.beta_profiles}`,
    `- CRM handoffs: ${packet.summary.crm_handoffs}`,
    `- Rep feedback reviews: ${packet.summary.rep_feedback_reviews}`,
    `- Proof packets sent: ${packet.summary.proof_packets_sent}`,
    `- Paid lookups recommended now: ${packet.summary.paid_lookups_recommended_now}`,
    "",
    "## Phases",
    "",
    ...phaseLines,
    "## Links",
    "",
    `- Operator room: ${packet.links.operator_room}`,
    `- Next action: ${packet.links.next_action}`,
    `- First beta execution: ${packet.links.first_beta_execution}`,
    `- Install queue: ${packet.links.install_queue}`,
    `- Install workbench: ${packet.links.install_workbench || "not available"}`,
    `- Launch wizard: ${packet.links.launch_wizard}`,
    `- Market gate: ${packet.links.market_gate}`,
    `- Live proof gate: ${packet.links.live_proof_gate}`,
    "",
    "## Safety",
    "",
    `- Protected operator only: ${packet.safety.protected_operator_only ? "yes" : "no"}`,
    `- Read-only GET: ${packet.safety.read_only_get ? "yes" : "no"}`,
    `- GET mutates buyer state: ${packet.safety.mutates_buyer_state_on_get ? "yes" : "no"}`,
    `- GET sends external email: ${packet.safety.sends_external_email_on_get ? "yes" : "no"}`,
    `- GET creates beta client: ${packet.safety.creates_beta_client_on_get ? "yes" : "no"}`,
    `- GET transmits CRM data: ${packet.safety.transmits_external_crm_on_get ? "yes" : "no"}`,
    `- Paid lookup by default: ${packet.safety.paid_provider_lookup_by_default ? "yes" : "no"}`,
    `- Live proof claimed: ${packet.safety.live_proof_claimed ? "yes" : "no"}`
  ].join("\n")}\n`;
}

function launchProofPacketStatusLabel(status = "") {
  return {
    needs_real_beta_client: "Needs Real Beta Client",
    proof_evidence_blocked: "Proof Evidence Blocked",
    ready_to_queue_first_proof_packet: "Ready To Queue First Proof Packet",
    proof_packet_queued: "Proof Packet Queued",
    first_proof_packet_sent: "First Proof Packet Sent",
    proof_packet_failed: "Proof Packet Failed"
  }[status] || humanizeEnum(status);
}

function launchProofPacketEvidenceFromPreflight(proof = {}) {
  const checks = proof?.checks || [];
  const byKey = Object.fromEntries(checks.map((check) => [check.key, check]));
  const evidence = [
    byKey.client_domain_config_load || {
      key: "client_domain_config_load",
      label: "Client-domain config load",
      status: "blocker",
      detail: "No client-domain install proof is available.",
      action: "Have the implementation owner load the installed buyer target page once."
    },
    byKey.first_beta_profile || {
      key: "first_beta_profile",
      label: "First beta profile",
      status: "blocker",
      detail: "No beta-attributed profile is available.",
      action: "Capture one buyer-like profile from the client-specific widget."
    },
    byKey.crm_handoff_proof || {
      key: "crm_handoff_proof",
      label: "CRM handoff proof",
      status: "blocker",
      detail: "No CRM handoff proof is available.",
      action: "Send, dry-run, sandbox, or manually record CRM handoff proof."
    },
    byKey.rep_feedback || {
      key: "rep_feedback",
      label: "Rep feedback",
      status: "blocker",
      detail: "No rep feedback is available.",
      action: "Send the tokenized feedback room after a rep works the first profile."
    }
  ].map((check) => ({
    key: check.key,
    label: check.label,
    status: check.status,
    status_label: humanizeEnum(check.status),
    detail: check.detail,
    action: check.action || "No action needed.",
    ready: check.status === "pass"
  }));
  return {
    items: evidence,
    ready: evidence.every((item) => item.ready),
    blockers: evidence.filter((item) => item.status === "blocker").length,
    warnings: evidence.filter((item) => item.status === "warning").length,
    missing: evidence.filter((item) => item.status !== "pass").map((item) => item.label)
  };
}

function launchProofPacketWorkbench(baseUrl = "", searchParams = new URLSearchParams()) {
  const root = baseUrl.replace(/\/$/, "");
  const requestedClientId = searchParams.get("client") || searchParams.get("betaClientId") || searchParams.get("beta_client_id") || "";
  const days = parseReportDays(searchParams.get("days") || 14);
  const installQueue = launchInstallQueue(baseUrl, searchParams);
  const market = marketLaunchReadinessPacket(baseUrl, searchParams);
  const liveGate = liveProofGate(new URLSearchParams({ days: String(days), ...(requestedClientId ? { betaClientId: requestedClientId } : {}) }));
  const selectedItem = requestedClientId
    ? installQueue.queue.find((item) => item.beta_client_id === requestedClientId) || null
    : installQueue.queue.find((item) => item.status === "proof_packet_due" || item.proof_preflight?.ready_for_first_proof_packet) || installQueue.queue[0] || null;
  const client = selectedItem ? state.betaClients.get(selectedItem.beta_client_id) || null : null;
  const detail = client ? betaClientDetail(client, baseUrl) : null;
  const proofPreflight = selectedItem?.proof_preflight || null;
  const evidence = launchProofPacketEvidenceFromPreflight(proofPreflight || {});
  const deliveries = client ? reportDeliveriesForClient(client.id) : [];
  const latestDelivery = deliveries[0] || null;
  const queuedDelivery = deliveries.find((delivery) => delivery.status === "queued") || null;
  const failedDelivery = deliveries.find((delivery) => delivery.status === "failed") || null;
  const sentDelivery = deliveries.find((delivery) => delivery.status === "sent") || null;
  const proofPacketSent = Boolean(sentDelivery || proofPreflight?.summary?.proof_packets_sent);
  const proofPacketQueued = Boolean(queuedDelivery);
  const reportRecipients = detail?.report_settings?.recipients || [];
  const publicProofPacket = client ? publicBetaProofReportPacket(client, new URLSearchParams({ days: String(days) }), baseUrl) : null;
  const status = !selectedItem
    ? "needs_real_beta_client"
    : proofPacketSent
      ? "first_proof_packet_sent"
      : proofPacketQueued
        ? "proof_packet_queued"
        : failedDelivery
          ? "proof_packet_failed"
          : evidence.ready
            ? "ready_to_queue_first_proof_packet"
            : "proof_evidence_blocked";
  const queueReady = Boolean(client && evidence.ready && !proofPacketQueued && !proofPacketSent);
  const deliveryForAction = queuedDelivery || latestDelivery || null;
  const proofSubject = client ? `Deal Threads first beta proof packet - ${detail.name}` : "Deal Threads first beta proof packet";
  const proofBody = client
    ? [
        `Hi ${detail.name} team,`,
        "",
        "Here is the first Deal Threads beta proof packet for review.",
        "",
        `Buyer-safe proof report: ${detail.public_beta_proof_url}`,
        `Public install status: ${detail.public_install_status_url}`,
        `Manual CRM export: ${detail.public_crm_export_url}`,
        `Feedback room: ${detail.public_feedback_url}`,
        "",
        `Profiles captured: ${publicProofPacket.summary.buyer_profiles}`,
        `Rep reviews: ${publicProofPacket.rep_feedback.reviewed_profiles}`,
        `Average usefulness: ${publicProofPacket.rep_feedback.average_usefulness_score ?? "-"} / 5`,
        `Paid provider spend: $${Number(publicProofPacket.summary.paid_provider_spend || 0).toFixed(2)}`,
        "",
        "Please review whether this proof is strong enough to continue the pilot, tune the question flow, or expand to the next page."
      ].join("\n")
    : "";
  const safety = {
    protected_operator_only: true,
    read_only_get: true,
    mutates_buyer_state_on_get: false,
    sends_external_email_on_get: false,
    creates_beta_client_on_get: false,
    queues_report_delivery_on_get: false,
    marks_report_sent_on_get: false,
    transmits_external_crm_on_get: false,
    paid_provider_lookup_by_default: false,
    live_proof_claimed: false,
    queue_requires_post: true,
    manual_sent_record_requires_post: true
  };
  const queueAction = client
    ? {
        ready: queueReady,
        method: "POST",
        html_action: `${root}/launch/proof-packet/${encodeURIComponent(client.id)}/queue`,
        api_url: `${root}/api/v1/launch/proof-packet/${encodeURIComponent(client.id)}/queue`,
        blocked_reason: queueReady ? null : proofPacketQueued ? "A proof packet delivery is already queued." : proofPacketSent ? "The first proof packet has already been marked sent." : `Missing proof evidence: ${evidence.missing.join(", ") || "none"}.`,
        payload_preview: {
          recipients: reportRecipients.join(", "),
          days,
          returnTo: `/launch/proof-packet?client=${client.id}`
        },
        mutates_state: true,
        sends_from_server: false,
        preview_only_on_get: true
      }
    : null;
  const manualSentAction = deliveryForAction
    ? {
        ready: deliveryForAction.status !== "sent",
        delivery_id: deliveryForAction.id,
        method: "POST",
        html_action: `${root}/launch/proof-packet/deliveries/${encodeURIComponent(deliveryForAction.id)}/sent`,
        api_url: `${root}/api/v1/launch/proof-packet/deliveries/${encodeURIComponent(deliveryForAction.id)}/sent`,
        payload_preview: {
          note: "Proof packet sent manually from the launch proof packet workbench.",
          returnTo: client ? `/launch/proof-packet?client=${client.id}` : "/launch/proof-packet"
        },
        mutates_state: true,
        sends_from_server: false,
        preview_only_on_get: true
      }
    : null;
  const manualEmail = client
    ? {
        recipients: reportRecipients,
        subject: deliveryForAction?.subject || proofSubject,
        body: proofBody,
        mailto_url: mailtoDraftUrl({ recipients: reportRecipients, subject: deliveryForAction?.subject || proofSubject, body: proofBody }),
        sends_from_server: false
      }
    : null;
  const packet = {
    type: "deal_threads.launch_first_proof_packet_workbench.v1",
    generated_at: now(),
    status,
    status_label: launchProofPacketStatusLabel(status),
    market_ready: market.market_ready,
    selected_beta_client: selectedItem
      ? {
          id: selectedItem.beta_client_id,
          name: selectedItem.beta_client_name,
          domain: selectedItem.domain,
          owner_email: selectedItem.owner_email,
          status: selectedItem.status,
          status_label: selectedItem.status_label,
          current_phase: selectedItem.current_phase,
          latest_lead: selectedItem.latest_lead
        }
      : null,
    summary: {
      real_beta_clients: installQueue.summary.real_beta_clients,
      beta_profiles: proofPreflight?.summary?.beta_profiles || selectedItem?.lead_count || 0,
      client_domain_config_loads: proofPreflight?.summary?.client_domain_config_loads || selectedItem?.install_activity?.client_page_config_loads || 0,
      crm_handoffs: proofPreflight?.summary?.crm_handoffs || selectedItem?.crm_delivery_count || 0,
      rep_feedback_reviews: proofPreflight?.summary?.rep_feedback_reviews || selectedItem?.rep_feedback?.reviewed_profiles || 0,
      proof_deliveries: deliveries.length,
      proof_packets_queued: proofPacketQueued ? 1 : 0,
      proof_packets_sent: proofPacketSent ? 1 : 0,
      strict_evidence_ready: evidence.ready,
      evidence_blockers: evidence.blockers,
      evidence_warnings: evidence.warnings,
      market_blockers: market.summary?.blocker || 0,
      market_warnings: market.summary?.warning || 0,
      live_proof_ready: liveGate.live_ready,
      paid_lookups_recommended_now: 0
    },
    evidence,
    proof_preflight: proofPreflight,
    buyer_safe_packet: publicProofPacket,
    delivery: {
      latest: latestDelivery ? reportDeliveryListItem(latestDelivery) : null,
      queued: queuedDelivery ? reportDeliveryListItem(queuedDelivery) : null,
      failed: failedDelivery ? reportDeliveryListItem(failedDelivery) : null,
      sent: sentDelivery ? reportDeliveryListItem(sentDelivery) : null,
      all: deliveries.map(reportDeliveryListItem)
    },
    actions: {
      queue: queueAction,
      manual_email: manualEmail,
      mark_manual_sent: manualSentAction
    },
    live_proof_gate: {
      status: liveGate.status,
      status_label: liveGate.status_label,
      live_ready: liveGate.live_ready,
      blockers: liveGate.blockers,
      warnings: liveGate.warnings,
      actions: liveGate.actions
    },
    links: {
      operator_room: `${root}/launch/proof-packet${client ? `?client=${encodeURIComponent(client.id)}` : ""}`,
      markdown: `${root}/api/v1/launch/proof-packet${client ? `?client=${encodeURIComponent(client.id)}&` : "?"}format=markdown`,
      proof_capture: `${root}/launch/proof-capture`,
      install_queue: `${root}/launch/install-queue`,
      install_workbench: selectedItem?.protected_links.install_workbench || "",
      beta_client: client ? `${root}/beta-clients#client-${encodeURIComponent(client.id)}` : "",
      buyer_safe_proof_report: detail?.public_beta_proof_url || "",
      protected_beta_report: client ? `${root}/beta-clients/${encodeURIComponent(client.id)}/report?days=${days}` : "",
      report_deliveries: `${root}/reports/deliveries`,
      market_gate: `${root}/launch/market-ready`,
      live_proof_gate: `${root}/api/v1/proof/live-gate`
    },
    safety,
    public_safety: safety
  };
  packet.markdown = launchProofPacketWorkbenchMarkdown(packet);
  return packet;
}

function launchProofPacketWorkbenchMarkdown(packet) {
  const evidenceLines = packet.evidence.items.flatMap((item) => [
    `### ${item.label}`,
    "",
    `- Key: ${item.key}`,
    `- Status: ${item.status_label}`,
    `- Detail: ${item.detail}`,
    `- Action: ${item.action}`,
    ""
  ]);
  return `${[
    "# Deal Threads First Proof Packet Workbench",
    "",
    `Generated: ${formatDateTime(packet.generated_at)}`,
    `Status: ${packet.status_label}`,
    `Market ready: ${packet.market_ready ? "yes" : "no"}`,
    "",
    "## Selected Client",
    "",
    packet.selected_beta_client
      ? `- Client: ${packet.selected_beta_client.name}\n- Beta client ID: ${packet.selected_beta_client.id}\n- Domain: ${packet.selected_beta_client.domain || "unknown"}\n- Owner: ${packet.selected_beta_client.owner_email || "unknown"}`
      : "- No real beta client selected.",
    "",
    "## Summary",
    "",
    `- Strict evidence ready: ${packet.summary.strict_evidence_ready ? "yes" : "no"}`,
    `- Client-domain config loads: ${packet.summary.client_domain_config_loads}`,
    `- Beta profiles: ${packet.summary.beta_profiles}`,
    `- CRM handoffs: ${packet.summary.crm_handoffs}`,
    `- Rep feedback reviews: ${packet.summary.rep_feedback_reviews}`,
    `- Proof deliveries: ${packet.summary.proof_deliveries}`,
    `- Proof packets queued: ${packet.summary.proof_packets_queued}`,
    `- Proof packets sent: ${packet.summary.proof_packets_sent}`,
    `- Live proof ready: ${packet.summary.live_proof_ready ? "yes" : "no"}`,
    `- Paid lookups recommended now: ${packet.summary.paid_lookups_recommended_now}`,
    "",
    "## Evidence Gate",
    "",
    ...evidenceLines,
    "## Buyer-Safe Packet",
    "",
    packet.buyer_safe_packet
      ? `- Proof status: ${packet.buyer_safe_packet.proof_status_label}\n- Share status: ${packet.buyer_safe_packet.share_status_label}\n- Buyer profiles: ${packet.buyer_safe_packet.summary.buyer_profiles}\n- Rep reviews: ${packet.buyer_safe_packet.rep_feedback.reviewed_profiles}\n- Average usefulness: ${packet.buyer_safe_packet.rep_feedback.average_usefulness_score ?? "-"}/5\n- Paid provider spend: $${Number(packet.buyer_safe_packet.summary.paid_provider_spend || 0).toFixed(2)}`
      : "- No buyer-safe packet is available yet.",
    "",
    "## Delivery Actions",
    "",
    packet.actions.queue
      ? `- Queue ready: ${packet.actions.queue.ready ? "yes" : "no"}\n- Queue POST: ${packet.actions.queue.api_url}\n- Queue blocked reason: ${packet.actions.queue.blocked_reason || "not blocked"}`
      : "- Queue action unavailable.",
    packet.delivery.queued
      ? `- Queued delivery: ${packet.delivery.queued.id}\n- Manual sent POST: ${packet.actions.mark_manual_sent?.api_url || "not available"}`
      : "- No queued proof delivery.",
    packet.actions.manual_email
      ? `- Manual email draft: ${packet.actions.manual_email.mailto_url || "not available"}`
      : "- Manual email draft unavailable.",
    "",
    "## Links",
    "",
    `- Operator room: ${packet.links.operator_room}`,
    `- Proof capture: ${packet.links.proof_capture}`,
    `- Install queue: ${packet.links.install_queue}`,
    `- Install workbench: ${packet.links.install_workbench || "not available"}`,
    `- Buyer-safe proof report: ${packet.links.buyer_safe_proof_report || "not available"}`,
    `- Protected beta report: ${packet.links.protected_beta_report || "not available"}`,
    `- Report deliveries: ${packet.links.report_deliveries}`,
    `- Market gate: ${packet.links.market_gate}`,
    "",
    "## Safety",
    "",
    `- Protected operator only: ${packet.safety.protected_operator_only ? "yes" : "no"}`,
    `- Read-only GET: ${packet.safety.read_only_get ? "yes" : "no"}`,
    `- GET sends external email: ${packet.safety.sends_external_email_on_get ? "yes" : "no"}`,
    `- GET queues report delivery: ${packet.safety.queues_report_delivery_on_get ? "yes" : "no"}`,
    `- GET marks report sent: ${packet.safety.marks_report_sent_on_get ? "yes" : "no"}`,
    `- GET creates beta client: ${packet.safety.creates_beta_client_on_get ? "yes" : "no"}`,
    `- GET transmits CRM data: ${packet.safety.transmits_external_crm_on_get ? "yes" : "no"}`,
    `- Paid lookup by default: ${packet.safety.paid_provider_lookup_by_default ? "yes" : "no"}`,
    `- Live proof claimed: ${packet.safety.live_proof_claimed ? "yes" : "no"}`,
    `- Queue requires POST: ${packet.safety.queue_requires_post ? "yes" : "no"}`,
    `- Manual sent record requires POST: ${packet.safety.manual_sent_record_requires_post ? "yes" : "no"}`
  ].join("\n")}\n`;
}

function queueLaunchProofPacketForClient(client, body = {}, actor = "operator", baseUrl = "") {
  if (!client) return { error: "beta_client_not_found", status: 404, message: "Beta client not found." };
  const packet = launchProofPacketWorkbench(baseUrl, new URLSearchParams({ client: client.id, days: String(parseReportDays(body.days || body.reportPeriodDays || body.report_period_days || client.report_settings?.period_days || 14)) }));
  if (!packet.actions.queue?.ready) {
    return {
      error: "proof_packet_not_ready",
      status: 409,
      message: packet.actions.queue?.blocked_reason || "The first proof packet is not ready to queue.",
      packet
    };
  }
  const result = createReportDeliveryForClient(client, body, actor);
  if (result.error) return result;
  return {
    type: "deal_threads.launch_first_proof_packet_queued.v1",
    queued: true,
    delivery: reportDeliveryListItem(result.delivery),
    markdown: result.delivery.markdown,
    csv: result.delivery.csv,
    packet: launchProofPacketWorkbench(baseUrl, new URLSearchParams({ client: client.id, days: String(result.delivery.period?.days || 14) }))
  };
}

function markLaunchProofPacketDeliverySent(delivery, body = {}, actor = "operator", baseUrl = "") {
  if (!delivery) return { error: "report_delivery_not_found", status: 404, message: "Report delivery not found." };
  const sent = markReportDeliverySent(delivery, body, actor);
  return {
    type: "deal_threads.launch_first_proof_packet_sent.v1",
    marked_sent: true,
    delivery: reportDeliveryListItem(sent),
    manual_handoff: {
      method: "manual",
      sends_from_server: false,
      note: stringFromBody(body, "notes", "note") || ""
    },
    packet: launchProofPacketWorkbench(baseUrl, new URLSearchParams({ client: sent.beta_client_id, days: String(sent.period?.days || 14) }))
  };
}
	
function realBetaActivationSummary(baseUrl = "", searchParams = new URLSearchParams()) {
  const allClients = betaClientList(baseUrl);
  const demoClients = allClients.filter((client) => isDemoScenarioClient(client));
  const realClients = allClients.filter((client) => !isDemoScenarioClient(client));
  const prospects = realBetaActivationProspects(10);
  const requestedClientId = searchParams.get("client") || searchParams.get("betaClientId") || searchParams.get("beta_client_id");
  const selectedClient = requestedClientId
    ? realClients.find((client) => client.id === requestedClientId) || null
    : realClients.find((client) => client.readiness?.ready_to_send_snippet) || realClients[0] || null;
  const liveGate = liveProofGate(searchParams);
  const demoScenario = demoScenarioStatus();
  const steps = [];
  const checklist = selectedClient ? Object.fromEntries((selectedClient.checklist || []).map((item) => [item.key, item.checked])) : {};
  const handoff = normalizeInstallHandoff(selectedClient?.install_handoff);
  const sourceVerification = normalizeInstallSnippetVerification(handoff.verification);
  const install = normalizeInstallActivity(selectedClient?.install_activity);
  const launchPacketDelivery = normalizeLaunchPacketDelivery(selectedClient?.launch_packet_delivery);
  const clientDomainConfigLoads = Number(install.client_page_config_loads || 0);

  addReadinessCheck(steps, {
    section: "activation",
    key: "real_launch_target",
    label: "Real launch target",
    status: selectedClient ? "pass" : prospects.length ? "warning" : "blocker",
    detail: selectedClient
      ? `${selectedClient.name} is selected; demo clients are excluded from this cockpit.`
      : prospects.length
        ? `${prospects.length} qualified prospect${prospects.length === 1 ? "" : "s"} can be converted into a beta client.`
        : "No real beta client or convertible qualified prospect is available.",
    action: selectedClient ? null : prospects.length ? "Convert the top qualified prospect into a beta client." : "Capture or import a qualified prospect with a company domain."
  });
  addReadinessCheck(steps, {
    section: "activation",
    key: "snippet_handoff",
    label: "Install packet handoff",
    status: selectedClient ? (checklist.install_snippet_sent || launchPacketDelivery.status === "sent" ? "pass" : "warning") : "blocker",
    detail: selectedClient
      ? checklist.install_snippet_sent || launchPacketDelivery.status === "sent"
        ? `Install packet handoff recorded for ${selectedClient.name}.`
        : `${selectedClient.name} has not received the launch packet yet.`
      : "Create or convert a real beta client before sending an install packet.",
    action: selectedClient && !checklist.install_snippet_sent && launchPacketDelivery.status !== "sent" ? "Send the launch packet to the implementation owner." : null
  });
  addReadinessCheck(steps, {
    section: "activation",
    key: "tested_url",
    label: "Tested URL submitted",
    status: selectedClient ? (handoff.status === "submitted" ? "pass" : checklist.install_snippet_sent || launchPacketDelivery.status === "sent" ? "warning" : "warning") : "blocker",
    detail: selectedClient
      ? handoff.status === "submitted"
        ? `Implementation owner submitted ${handoff.tested_page_url}.`
        : "No tested client page URL has been submitted."
      : "Create or convert a real beta client first.",
    action: selectedClient && handoff.status !== "submitted" ? "Ask the implementation owner to submit the tested URL from the public install handoff page." : null
  });
  addReadinessCheck(steps, {
    section: "activation",
    key: "source_check",
    label: "Install source check",
    status: selectedClient
      ? clientDomainConfigLoads > 0 || sourceVerification.status === "passed"
        ? "pass"
        : sourceVerification.status === "failed" || sourceVerification.status === "blocked"
          ? "blocker"
          : handoff.status === "submitted"
            ? "warning"
            : "warning"
      : "blocker",
    detail: selectedClient
      ? clientDomainConfigLoads > 0
        ? "A client-domain widget config load has been captured."
        : installVerificationSummary(sourceVerification)
      : "Create or convert a real beta client first.",
    action:
      selectedClient && !clientDomainConfigLoads && sourceVerification.status !== "passed"
        ? handoff.status === "submitted"
          ? "Run the install source check against the submitted URL."
          : "Collect a tested URL before running the source check."
        : null
  });
  addReadinessCheck(steps, {
    section: "activation",
    key: "real_config_load",
    label: "Client-domain widget config load",
    status: selectedClient ? (clientDomainConfigLoads > 0 ? "pass" : "blocker") : "blocker",
    detail: selectedClient
      ? `${clientDomainConfigLoads} client-domain config load${clientDomainConfigLoads === 1 ? "" : "s"} captured; ${install.hosted_config_loads} hosted/test load${
          install.hosted_config_loads === 1 ? "" : "s"
        } captured.`
      : "Create or convert a real beta client first.",
    action: selectedClient && !clientDomainConfigLoads ? "Have the client load the installed page once so Deal Threads records real client-site install proof." : null
  });
  addReadinessCheck(steps, {
    section: "activation",
    key: "real_beta_lead",
    label: "Real beta lead captured",
    status: selectedClient ? (selectedClient.lead_count > 0 ? "pass" : "blocker") : "blocker",
    detail: selectedClient ? `${selectedClient.lead_count} real beta-attributed lead${selectedClient.lead_count === 1 ? "" : "s"} captured.` : "Create or convert a real beta client first.",
    action: selectedClient && !selectedClient.lead_count ? "Create one lead from the client-specific widget to prove attribution and CRM handoff." : null
  });
  addReadinessCheck(steps, {
    section: "activation",
    key: "live_proof_gate",
    label: "Live proof export gate",
    status: liveGate.live_ready ? "pass" : "blocker",
    detail: liveGate.live_ready ? "Live proof export is clear." : liveGate.blockers[0] || "Live proof export is blocked.",
    action: liveGate.live_ready ? null : liveGate.actions[0] || "Clear the live proof gate before exporting buyer-facing proof."
  });

  const blockerCount = steps.filter((step) => step.status === "blocker").length;
  const warningCount = steps.filter((step) => step.status === "warning").length;
  const status = selectedClient
    ? selectedClient.readiness?.ready_for_live_beta && liveGate.live_ready
      ? "ready_for_real_traffic"
      : "activation_in_progress"
    : prospects.length
      ? "prospect_ready"
      : "blocked";
  const nextActions = uniqueStrings([
    ...steps.filter((step) => step.status !== "pass" && step.action).map((step) => step.action),
    ...prospects.slice(0, 1).map((prospect) => `Convert ${prospect.company || prospect.domain} from CRM lead ${prospect.lead_id} into a beta client.`),
    ...liveGate.actions
  ]).slice(0, 8);

  return {
    generated_at: now(),
    status,
    status_label: realBetaActivationStatusLabel(status),
    summary: {
      real_beta_clients: realClients.length,
      demo_clients_excluded: demoClients.length,
      qualified_prospects: prospects.length,
      ready_to_send_snippet: realClients.filter((client) => client.readiness?.ready_to_send_snippet).length,
      ready_for_live_beta: realClients.filter((client) => client.readiness?.ready_for_live_beta).length,
      real_beta_leads: realClients.reduce((total, client) => total + Number(client.lead_count || 0), 0),
      blocker: blockerCount,
      warning: warningCount,
      pass: steps.filter((step) => step.status === "pass").length,
      total: steps.length
    },
    selected_client: selectedClient,
    real_beta_clients: realClients,
    prospects,
    demo_scenario: demoScenario,
    live_proof_gate: {
      status: liveGate.status,
      status_label: liveGate.status_label,
      live_ready: liveGate.live_ready,
      summary: liveGate.summary,
      blockers: liveGate.blockers,
      warnings: liveGate.warnings,
      actions: liveGate.actions
    },
    steps,
    next_actions: nextActions,
    links: {
      activation: "/activation",
      crm: "/crm",
      launch: selectedClient ? `/launch?client=${encodeURIComponent(selectedClient.id)}` : "/launch",
      beta_clients: "/beta-clients",
      live_proof_gate: "/api/v1/proof/live-gate"
    }
  };
}

function realBetaActivationStatusLabel(status) {
  const labels = {
    blocked: "Blocked",
    prospect_ready: "Prospect ready",
    activation_in_progress: "Activation in progress",
    ready_for_real_traffic: "Ready for real traffic"
  };
  return labels[status] || humanizeEnum(status);
}

function realBetaActivationProspects(limit = 10) {
  return allLeadsSorted()
    .filter(isRealBetaActivationProspect)
    .sort((a, b) => leadActivationPriorityRank(a) - leadActivationPriorityRank(b) || new Date(b.created_at).getTime() - new Date(a.created_at).getTime())
    .slice(0, limit)
    .map(realBetaActivationProspectItem);
}

function isRealBetaActivationProspect(lead) {
  if (!lead || isDemoScenarioLead(lead)) return false;
  if (lead.source?.beta_client_id) return false;
  if (lead.beta_client_conversion?.beta_client_id) return false;
  if (!betaClientConversionDomain(lead)) return false;
  const workflow = ensureLeadWorkflow(lead);
  if (isTerminalWorkflowStage(workflow.stage) || ["disqualified", "closed_lost"].includes(ensureLeadOutcome(lead).status)) return false;
  return ["high", "medium"].includes(lead.score?.priority) || lead.status === "qualified" || workflow.stage === "meeting_booked";
}

function leadActivationPriorityRank(lead) {
  const priority = lead.score?.priority;
  if (priority === "high") return 0;
  if (priority === "medium") return 1;
  return 2;
}

function normalizeProspectConfirmationReview(value = {}) {
  const raw = value && typeof value === "object" ? value : {};
  return {
    source: optionalString(firstDefined(raw, "source", "confirmation_source", "confirmationSource")),
    operator_review_complete: booleanFromAnyBody(raw, "operator_review_complete", "operatorReviewComplete", "review_complete", "reviewComplete"),
    defaulted_required_fields_acknowledged: booleanFromAnyBody(
      raw,
      "defaulted_required_fields_acknowledged",
      "defaultedRequiredFieldsAcknowledged"
    ),
    extracted_fields: optionalNonNegativeNumber(firstDefined(raw, "extracted_fields", "extractedFields", "review_extracted_fields", "reviewExtractedFields")) || 0,
    defaulted_required_fields:
      optionalNonNegativeNumber(
        firstDefined(raw, "defaulted_required_fields", "defaultedRequiredFields", "review_defaulted_required_fields", "reviewDefaultedRequiredFields")
      ) || 0,
    missing_required_details:
      optionalNonNegativeNumber(
        firstDefined(raw, "missing_required_details", "missingRequiredDetails", "review_missing_required_details", "reviewMissingRequiredDetails")
      ) || 0,
    checklist_status: optionalString(firstDefined(raw, "checklist_status", "checklistStatus", "review_checklist_status", "reviewChecklistStatus")),
    notes: optionalString(firstDefined(raw, "notes", "note", "operator_review_notes", "operatorReviewNotes")),
    reviewed_by: optionalString(firstDefined(raw, "reviewed_by", "reviewedBy")),
    reviewed_at: optionalString(firstDefined(raw, "reviewed_at", "reviewedAt")),
    reply_evidence_receipt: normalizeConfirmationReplyEvidenceReceipt(
      firstDefined(raw, "reply_evidence_receipt", "replyEvidenceReceipt", "replyEvidenceReceiptJson", "reply_evidence_receipt_json")
    )
  };
}

function normalizeConfirmationReplyEvidenceField(value = {}) {
  const raw = objectFromJsonLike(value) || { value };
  const values = normalizeOptionalList(firstDefined(raw, "values", "recipients", "emails"));
  return {
    value: optionalString(firstDefined(raw, "value")) || "",
    values: values || [],
    source: optionalString(firstDefined(raw, "source")) || "not_found",
    confidence: optionalNonNegativeNumber(firstDefined(raw, "confidence")) ?? 0,
    evidence: optionalString(firstDefined(raw, "evidence", "detail", "line")) || ""
  };
}

function normalizeConfirmationAppliedPayloadSnapshot(value = {}) {
  const raw = objectFromJsonLike(value) || {};
  const allowedFields = [
    "action",
    "targetPageUrl",
    "implementationOwnerName",
    "implementationOwnerEmail",
    "crmOwnerEmail",
    "routingOwnerEmail",
    "reportRecipients",
    "baselineFirstTouchMinutes",
    "baselineMeetingRate",
    "baselineOpportunityRate",
    "baselineWinRate",
    "baselineSalesCycleDays",
    "baselineNotes"
  ];
  return Object.fromEntries(
    allowedFields
      .map((field) => [field, firstDefined(raw, field)])
      .filter(([, fieldValue]) => fieldValue !== undefined && fieldValue !== null && String(fieldValue).trim() !== "")
      .map(([field, fieldValue]) => [field, String(fieldValue).trim()])
  );
}

function normalizeConfirmationReplyEvidenceReceipt(value = {}) {
  const raw = objectFromJsonLike(value);
  if (!raw) return null;
  const reply = objectFromJsonLike(raw.reply || raw.reply_summary || raw.replySummary) || raw;
  const fieldEvidenceRaw = objectFromJsonLike(firstDefined(raw, "field_evidence", "fieldEvidence")) || {};
  const fieldEvidence = Object.fromEntries(
    Object.entries(fieldEvidenceRaw)
      .filter(([field]) => field)
      .map(([field, evidence]) => [field, normalizeConfirmationReplyEvidenceField(evidence)])
  );
  const appliedPayload = normalizeConfirmationAppliedPayloadSnapshot(firstDefined(raw, "applied_payload", "appliedPayload", "suggested_payload", "suggestedPayload"));
  const generatedAt = normalizeIsoDateTime(firstDefined(raw, "generated_at", "generatedAt", "supplied_at", "suppliedAt")) || optionalString(firstDefined(raw, "generated_at", "generatedAt", "supplied_at", "suppliedAt"));
  const reviewedAt = normalizeIsoDateTime(firstDefined(raw, "reviewed_at", "reviewedAt")) || optionalString(firstDefined(raw, "reviewed_at", "reviewedAt"));
  const replyExcerpt = optionalString(firstDefined(raw, "reply_excerpt", "replyExcerpt") || firstDefined(reply, "excerpt", "reply_excerpt", "replyExcerpt")) || "";
  const receipt = {
    type:
      optionalString(firstDefined(raw, "type")) ||
      "deal_threads.confirmation_reply_evidence_receipt.v1",
    source: optionalString(firstDefined(raw, "source")) || "confirmation_reply_preview",
    generated_at: generatedAt || null,
    reviewed_at: reviewedAt || null,
    reply: {
      supplied: Boolean(firstDefined(reply, "supplied", "reply_supplied", "replySupplied")),
      character_count: optionalNonNegativeNumber(firstDefined(reply, "character_count", "characterCount", "reply_character_count", "replyCharacterCount")) ?? 0,
      email_count: optionalNonNegativeNumber(firstDefined(reply, "email_count", "emailCount", "reply_email_count", "replyEmailCount")) ?? 0,
      url_count: optionalNonNegativeNumber(firstDefined(reply, "url_count", "urlCount", "reply_url_count", "replyUrlCount")) ?? 0,
      excerpt: replyExcerpt.slice(0, 700)
    },
    review_summary: {
      checklist_status:
        optionalString(firstDefined(raw.review_summary || raw.reviewSummary || {}, "checklist_status", "checklistStatus")) ||
        optionalString(firstDefined(raw, "checklist_status", "checklistStatus")) ||
        "",
      extracted_fields:
        optionalNonNegativeNumber(firstDefined(raw.review_summary || raw.reviewSummary || {}, "extracted_fields", "extractedFields")) ??
        optionalNonNegativeNumber(firstDefined(raw, "extracted_fields", "extractedFields")) ??
        0,
      defaulted_required_fields:
        optionalNonNegativeNumber(firstDefined(raw.review_summary || raw.reviewSummary || {}, "defaulted_required_fields", "defaultedRequiredFields")) ??
        optionalNonNegativeNumber(firstDefined(raw, "defaulted_required_fields", "defaultedRequiredFields")) ??
        0,
      missing_required_details:
        optionalNonNegativeNumber(firstDefined(raw.review_summary || raw.reviewSummary || {}, "missing_required_details", "missingRequiredDetails")) ??
        optionalNonNegativeNumber(firstDefined(raw, "missing_required_details", "missingRequiredDetails")) ??
        0
    },
    field_evidence: fieldEvidence,
    field_evidence_keys: Object.keys(fieldEvidence),
    applied_payload: appliedPayload,
    applied_payload_keys: Object.keys(appliedPayload),
    safety: {
      preview_mutates_state: false,
      apply_requires_post: true,
      sends_external_email: false,
      creates_beta_client: false,
      transmits_external_crm: false,
      paid_provider_lookup: false,
      claims_live_proof: false
    }
  };
  const hasUsefulEvidence =
    receipt.reply.supplied ||
    receipt.reply.character_count ||
    receipt.field_evidence_keys.length ||
    receipt.applied_payload_keys.length ||
    receipt.review_summary.checklist_status;
  return hasUsefulEvidence ? receipt : null;
}

function confirmationReplyEvidenceReceiptFromBody(body = {}, fallback = null) {
  const direct = firstDefined(body, "replyEvidenceReceipt", "replyEvidenceReceiptJson", "reply_evidence_receipt", "reply_evidence_receipt_json");
  if (direct !== undefined) return normalizeConfirmationReplyEvidenceReceipt(direct);
  const replyExcerpt = stringFromBody(body, "replyExcerpt", "reply_excerpt");
  const fieldEvidence = objectFromJsonLike(stringFromBody(body, "fieldEvidenceJson", "field_evidence_json"));
  const appliedPayload = objectFromJsonLike(stringFromBody(body, "appliedPayloadJson", "applied_payload_json"));
  if (replyExcerpt || fieldEvidence || appliedPayload) {
    return normalizeConfirmationReplyEvidenceReceipt({
      source: stringFromBody(body, "confirmationSource", "confirmation_source") || "confirmation_reply_preview",
      generated_at: stringFromBody(body, "replyPreviewGeneratedAt", "reply_preview_generated_at"),
      reviewed_at: now(),
      reply: {
        supplied: true,
        character_count: stringFromBody(body, "replyCharacterCount", "reply_character_count"),
        email_count: stringFromBody(body, "replyEmailCount", "reply_email_count"),
        url_count: stringFromBody(body, "replyUrlCount", "reply_url_count"),
        excerpt: replyExcerpt
      },
      review_summary: {
        checklist_status: stringFromBody(body, "reviewChecklistStatus", "review_checklist_status"),
        extracted_fields: stringFromBody(body, "reviewExtractedFields", "review_extracted_fields"),
        defaulted_required_fields: stringFromBody(body, "reviewDefaultedRequiredFields", "review_defaulted_required_fields"),
        missing_required_details: stringFromBody(body, "reviewMissingRequiredDetails", "review_missing_required_details")
      },
      field_evidence: fieldEvidence || {},
      applied_payload: appliedPayload || {}
    });
  }
  return fallback || null;
}

const PILOT_ACCEPTANCE_TERMS_VERSION = "pilot_agreement_private_beta_v1";

function normalizePilotAcceptance(value = {}) {
  const raw = value && typeof value === "object" ? value : {};
  const acceptedAt = optionalString(firstDefined(raw, "accepted_at", "acceptedAt"));
  const statusCandidate = optionalString(firstDefined(raw, "status", "acceptance_status", "acceptanceStatus"));
  const status = ["accepted", "declined", "superseded"].includes(statusCandidate) ? statusCandidate : acceptedAt ? "accepted" : "not_started";
  const billingMethodCandidate = optionalString(firstDefined(raw, "billing_method", "billingMethod", "payment_method", "paymentMethod"));
  const setupFeeStatusCandidate = optionalString(firstDefined(raw, "setup_fee_status", "setupFeeStatus"));
  const billingMethod = ["manual_invoice", "purchase_order", "card_later", "waived", "other"].includes(billingMethodCandidate)
    ? billingMethodCandidate
    : "manual_invoice";
  const setupFeeStatus = ["pending", "paid", "waived"].includes(setupFeeStatusCandidate) ? setupFeeStatusCandidate : "pending";
  const signerEmail = optionalString(firstDefined(raw, "signer_email", "signerEmail", "accepted_by_email", "acceptedByEmail"));
  const billingEmail = optionalString(firstDefined(raw, "billing_contact_email", "billingContactEmail", "billing_email", "billingEmail")) || signerEmail;
  const termsVersion = optionalString(firstDefined(raw, "terms_version", "termsVersion")) || PILOT_ACCEPTANCE_TERMS_VERSION;

  return {
    status,
    accepted_at: acceptedAt,
    accepted_by: optionalString(firstDefined(raw, "accepted_by", "acceptedBy")),
    terms_version: termsVersion,
    signer_name: optionalString(firstDefined(raw, "signer_name", "signerName", "accepted_by_name", "acceptedByName")),
    signer_email: signerEmail,
    signer_title: optionalString(firstDefined(raw, "signer_title", "signerTitle", "title")),
    billing_contact_name: optionalString(firstDefined(raw, "billing_contact_name", "billingContactName", "billing_name", "billingName")),
    billing_contact_email: billingEmail,
    billing_method: billingMethod,
    setup_fee_status: setupFeeStatus,
    setup_fee_usd: optionalNonNegativeNumber(firstDefined(raw, "setup_fee_usd", "setupFeeUsd")) ?? 500,
    managed_pilot_monthly_usd: optionalNonNegativeNumber(firstDefined(raw, "managed_pilot_monthly_usd", "managedPilotMonthlyUsd")) ?? 2500,
    payment_collection_method:
      optionalString(firstDefined(raw, "payment_collection_method", "paymentCollectionMethod")) ||
      (billingMethod === "purchase_order" ? "purchase_order" : billingMethod === "waived" ? "waived" : "manual_invoice"),
    purchase_order_number: optionalString(firstDefined(raw, "purchase_order_number", "purchaseOrderNumber", "po_number", "poNumber")),
    invoice_notes: optionalString(firstDefined(raw, "invoice_notes", "invoiceNotes")),
    accepted_scope: booleanFromAnyBody(raw, "accepted_scope", "acceptedScope", "scopeAccepted"),
    accepted_buyer_responsibilities: booleanFromAnyBody(raw, "accepted_buyer_responsibilities", "acceptedBuyerResponsibilities", "buyerResponsibilitiesAccepted"),
    accepted_providerless_default: booleanFromAnyBody(raw, "accepted_providerless_default", "acceptedProviderlessDefault", "providerlessAccepted"),
    accepted_no_guarantee: booleanFromAnyBody(raw, "accepted_no_guarantee", "acceptedNoGuarantee", "noGuaranteeAccepted"),
    notes: optionalString(firstDefined(raw, "notes", "note")),
    updated_at: optionalString(firstDefined(raw, "updated_at", "updatedAt"))
  };
}

function normalizeProspectCloseWorkflow(value = {}, lead = {}) {
  const raw = value && typeof value === "object" ? value : {};
  const confirmationToken =
    optionalString(firstDefined(raw, "confirmation_token", "confirmationToken", "public_confirmation_token", "publicConfirmationToken")) ||
    `pcf_${randomUUID().replaceAll("-", "")}`;
  const sentAt = optionalString(firstDefined(raw, "close_packet_sent_at", "closePacketSentAt", "sent_at", "sentAt"));
  const confirmedAt = optionalString(firstDefined(raw, "buyer_confirmed_at", "buyerConfirmedAt", "confirmed_at", "confirmedAt"));
  const targetPageUrlRaw = optionalString(firstDefined(raw, "target_page_url", "targetPageUrl", "tested_page_url", "testedPageUrl"));
  const reportRecipients = normalizeOptionalList(firstDefined(raw, "report_recipients", "reportRecipients")) || [];
  const sentTo = normalizeOptionalList(firstDefined(raw, "sent_to", "sentTo")) || [];
  const closePacketDelivery = normalizeLaunchPacketDelivery({
    channel: "prospect_close_packet_email",
    ...(raw.close_packet_delivery || raw.closePacketDelivery || {}),
    recipients: firstDefined(raw.close_packet_delivery || raw.closePacketDelivery || {}, "recipients") || sentTo,
    subject: firstDefined(raw.close_packet_delivery || raw.closePacketDelivery || {}, "subject") || raw.close_packet_subject || raw.closePacketSubject,
    sent_at: firstDefined(raw.close_packet_delivery || raw.closePacketDelivery || {}, "sent_at", "sentAt") || sentAt,
    sent_by: firstDefined(raw.close_packet_delivery || raw.closePacketDelivery || {}, "sent_by", "sentBy") || raw.close_packet_sent_by || raw.closePacketSentBy
  });
  const buyerConfirmationDelivery = normalizeLaunchPacketDelivery({
    channel: "buyer_confirmation_receipt_email",
    ...(raw.buyer_confirmation_delivery || raw.buyerConfirmationDelivery || {})
  });
  const confirmationNudgeDelivery = normalizeLaunchPacketDelivery({
    channel: "buyer_confirmation_nudge_email",
    ...(raw.confirmation_nudge_delivery || raw.confirmationNudgeDelivery || {})
  });
  const statusCandidate = optionalString(raw.status);
  const status = ["not_sent", "sent", "collecting_details", "confirmed"].includes(statusCandidate)
    ? statusCandidate
    : confirmedAt
      ? "confirmed"
      : sentAt
        ? "sent"
        : "not_sent";
  const baseline = raw.baseline || {};

  return {
    confirmation_token: confirmationToken,
    status,
    close_packet_sent_at: sentAt,
    close_packet_sent_by: optionalString(firstDefined(raw, "close_packet_sent_by", "closePacketSentBy", "sent_by", "sentBy")),
    sent_to: sentTo,
    close_packet_delivery: closePacketDelivery,
    buyer_confirmation_delivery: buyerConfirmationDelivery,
    confirmation_nudge_delivery: confirmationNudgeDelivery,
    target_page_url: targetPageUrlRaw ? normalizeWebsiteUrl(targetPageUrlRaw) : "",
    implementation_owner_name: optionalString(firstDefined(raw, "implementation_owner_name", "implementationOwnerName")),
    implementation_owner_email: optionalString(firstDefined(raw, "implementation_owner_email", "implementationOwnerEmail")),
    crm_owner_email: optionalString(firstDefined(raw, "crm_owner_email", "crmOwnerEmail")) || betaClientConversionOwner(lead),
    routing_owner_email: optionalString(firstDefined(raw, "routing_owner_email", "routingOwnerEmail")) || ensureLeadWorkflow(lead).owner_email || lead.routing?.assigned_owner_email || null,
    report_recipients: reportRecipients,
    baseline: {
      first_touch_minutes: optionalNonNegativeNumber(firstDefined(baseline, "first_touch_minutes", "firstTouchMinutes") ?? firstDefined(raw, "baseline_first_touch_minutes", "baselineFirstTouchMinutes")),
      meeting_rate: optionalRate(firstDefined(baseline, "meeting_rate", "meetingRate") ?? firstDefined(raw, "baseline_meeting_rate", "baselineMeetingRate")),
      opportunity_rate: optionalRate(firstDefined(baseline, "opportunity_rate", "opportunityRate") ?? firstDefined(raw, "baseline_opportunity_rate", "baselineOpportunityRate")),
      win_rate: optionalRate(firstDefined(baseline, "win_rate", "winRate") ?? firstDefined(raw, "baseline_win_rate", "baselineWinRate")),
      sales_cycle_days: optionalNonNegativeNumber(firstDefined(baseline, "sales_cycle_days", "salesCycleDays") ?? firstDefined(raw, "baseline_sales_cycle_days", "baselineSalesCycleDays")),
      notes: optionalString(firstDefined(baseline, "notes") ?? firstDefined(raw, "baseline_notes", "baselineNotes"))
    },
    buyer_confirmed_at: confirmedAt,
    buyer_confirmed_by: optionalString(firstDefined(raw, "buyer_confirmed_by", "buyerConfirmedBy", "confirmed_by", "confirmedBy")),
    confirmation_review: normalizeProspectConfirmationReview(raw.confirmation_review || raw.confirmationReview || {}),
    pilot_acceptance: normalizePilotAcceptance(raw.pilot_acceptance || raw.pilotAcceptance || {}),
    notes: optionalString(raw.notes || raw.note),
    updated_at: optionalString(firstDefined(raw, "updated_at", "updatedAt"))
  };
}

function prospectCloseConfirmationComplete(close = {}) {
  return Boolean(
    close.target_page_url &&
      close.implementation_owner_email &&
      close.crm_owner_email &&
      close.routing_owner_email &&
      close.report_recipients?.length
  );
}

function ensureProspectCloseWorkflow(lead) {
  if (!lead) return normalizeProspectCloseWorkflow({}, {});
  if (!lead.beta_client_conversion?.prospect_close && !isRealBetaActivationProspect(lead)) return normalizeProspectCloseWorkflow({}, lead);
  const existingRaw = lead.beta_client_conversion?.prospect_close || {};
  const closeWorkflow = normalizeProspectCloseWorkflow(existingRaw, lead);
  if (!existingRaw.confirmation_token && !existingRaw.confirmationToken && !existingRaw.public_confirmation_token && !existingRaw.publicConfirmationToken) {
    lead.beta_client_conversion = {
      ...(lead.beta_client_conversion || {}),
      prospect_close: closeWorkflow
    };
    state.leads.set(lead.id, lead);
    persistSoon();
  }
  return closeWorkflow;
}

function prospectCloseConfirmationUrl(closeWorkflow, baseUrl = "") {
  const path = `/confirm/${encodeURIComponent(closeWorkflow.confirmation_token || "")}`;
  return baseUrl ? `${baseUrl.replace(/\/$/, "")}${path}` : path;
}

function prospectCloseConfirmationStatusUrl(closeWorkflow, baseUrl = "") {
  const path = `/confirm/${encodeURIComponent(closeWorkflow.confirmation_token || "")}/status`;
  return baseUrl ? `${baseUrl.replace(/\/$/, "")}${path}` : path;
}

function prospectCloseConfirmationApprovalBriefUrl(closeWorkflow, baseUrl = "") {
  const path = `/confirm/${encodeURIComponent(closeWorkflow.confirmation_token || "")}/brief`;
  return baseUrl ? `${baseUrl.replace(/\/$/, "")}${path}` : path;
}

function prospectCloseConfirmationRequestKitUrl(closeWorkflow, baseUrl = "") {
  const path = `/confirm/${encodeURIComponent(closeWorkflow.confirmation_token || "")}/request-kit`;
  return baseUrl ? `${baseUrl.replace(/\/$/, "")}${path}` : path;
}

function prospectPilotAcceptanceUrl(closeWorkflow, baseUrl = "") {
  const path = `/confirm/${encodeURIComponent(closeWorkflow.confirmation_token || "")}/acceptance`;
  return baseUrl ? `${baseUrl.replace(/\/$/, "")}${path}` : path;
}

function publicPilotIntakeHandoffPacket(closeWorkflow = {}, baseUrl = "") {
  const token = optionalString(closeWorkflow.confirmation_token);
  const root = baseUrl.replace(/\/$/, "");
  const confirmationComplete = prospectCloseConfirmationComplete(closeWorkflow);
  const confirmationForm = token ? prospectCloseConfirmationUrl(closeWorkflow, root) : null;
  const confirmationStatus = token ? prospectCloseConfirmationStatusUrl(closeWorkflow, root) : null;
  const approvalBrief = token ? prospectCloseConfirmationApprovalBriefUrl(closeWorkflow, root) : null;
  const requestKit = token ? prospectCloseConfirmationRequestKitUrl(closeWorkflow, root) : null;
  const acceptanceRoom = token ? prospectPilotAcceptanceUrl(closeWorkflow, root) : null;
  return {
    status: token ? (confirmationComplete ? "confirmation_status_ready" : "confirmation_details_needed") : "operator_review_pending",
    next_action: token
      ? confirmationComplete
        ? "Review the confirmation status room and wait for Deal Threads to issue the client-specific install handoff."
        : "Open the confirmation status room, then submit the missing target page, owner, routing, proof, and baseline details."
      : "Deal Threads created the protected activation prospect. Watch for the operator follow-up with the confirmation room.",
    links: {
      confirmation_form: confirmationForm,
      confirmation_status: confirmationStatus,
      confirmation_status_receipt: confirmationStatus ? `${confirmationStatus}?intake=1` : null,
      approval_brief: approvalBrief,
      request_kit: requestKit,
      pilot_acceptance: acceptanceRoom,
      buyer_confirmation_guide: `${root}/buyer-confirmation-guide`,
      stakeholder_forwarding_kit: `${root}/stakeholder-forwarding-kit`,
      mutual_action_plan: `${root}/mutual-action-plan`,
      pilot_approval_room: `${root}/pilot-approval-room`,
      pilot_agreement: `${root}/pilot-agreement`,
      implementation_guide: `${root}/implementation-guide`,
      crm_handoff_guide: `${root}/crm-handoff-guide`,
      procurement_packet: `${root}/procurement-packet`,
      security_center: `${root}/security`,
      sample_profile: `${root}/sample-profile`
    },
    safety: {
      buyer_safe_public_links_only: true,
      exposes_crm_profiles: false,
      exposes_operator_actions: false,
      exposes_tenant_exports: false,
      sends_external_email_on_get: false,
      mutates_buyer_state_on_get: false,
      creates_beta_client_on_get: false,
      runs_paid_enrichment_on_get: false,
      claims_live_proof: false
    }
  };
}

function validatePilotAcceptanceBody(body = {}) {
  const accepted = booleanFromAnyBody(body, "acceptTerms", "accept_terms", "pilotAccepted", "pilot_accepted", "accepted");
  if (!accepted) return "Accept the pilot terms before submitting.";
  if (!stringFromBody(body, "signerName", "signer_name", "acceptedByName", "accepted_by_name")) return "Signer name is required.";
  if (!stringFromBody(body, "signerEmail", "signer_email", "acceptedByEmail", "accepted_by_email")) return "Signer email is required.";
  return "";
}

function pilotAcceptanceStatusLabel(acceptance = {}) {
  if (acceptance.status === "accepted") return "Accepted";
  if (acceptance.status === "declined") return "Declined";
  if (acceptance.status === "superseded") return "Superseded";
  return "Needs acceptance";
}

function recordProspectPilotAcceptance(lead, body = {}, actor = "buyer", baseUrl = "") {
  if (!lead) return { error: "lead_not_found", status: 404, message: "Lead not found." };
  const closeWorkflow = ensureProspectCloseWorkflow(lead);
  if (!closeWorkflow.confirmation_token) {
    return { error: "acceptance_token_missing", status: 409, message: "This prospect does not have a buyer acceptance token." };
  }
  const validationError = validatePilotAcceptanceBody(body);
  if (validationError) return { error: "pilot_acceptance_invalid", status: 400, message: validationError };

  const acceptedAt = now();
  const signerEmail = stringFromBody(body, "signerEmail", "signer_email", "acceptedByEmail", "accepted_by_email");
  const signerName = stringFromBody(body, "signerName", "signer_name", "acceptedByName", "accepted_by_name");
  const nextAcceptance = normalizePilotAcceptance({
    ...closeWorkflow.pilot_acceptance,
    status: "accepted",
    accepted_at: acceptedAt,
    accepted_by: actor,
    terms_version: PILOT_ACCEPTANCE_TERMS_VERSION,
    signer_name: signerName,
    signer_email: signerEmail,
    signer_title: stringFromBody(body, "signerTitle", "signer_title", "title"),
    billing_contact_name: stringFromBody(body, "billingContactName", "billing_contact_name", "billingName", "billing_name") || signerName,
    billing_contact_email: stringFromBody(body, "billingContactEmail", "billing_contact_email", "billingEmail", "billing_email") || signerEmail,
    billing_method: stringFromBody(body, "billingMethod", "billing_method", "paymentMethod", "payment_method") || "manual_invoice",
    setup_fee_status: stringFromBody(body, "setupFeeStatus", "setup_fee_status") || "pending",
    setup_fee_usd: stringFromBody(body, "setupFeeUsd", "setup_fee_usd") || 500,
    managed_pilot_monthly_usd: stringFromBody(body, "managedPilotMonthlyUsd", "managed_pilot_monthly_usd") || 2500,
    payment_collection_method: stringFromBody(body, "paymentCollectionMethod", "payment_collection_method") || "manual_invoice",
    purchase_order_number: stringFromBody(body, "purchaseOrderNumber", "purchase_order_number", "poNumber", "po_number"),
    invoice_notes: stringFromBody(body, "invoiceNotes", "invoice_notes"),
    accepted_scope: true,
    accepted_buyer_responsibilities: true,
    accepted_providerless_default: true,
    accepted_no_guarantee: true,
    notes: stringFromBody(body, "notes", "note"),
    updated_at: acceptedAt
  });

  const nextCloseWorkflow = normalizeProspectCloseWorkflow(
    {
      ...closeWorkflow,
      pilot_acceptance: nextAcceptance,
      updated_at: acceptedAt
    },
    lead
  );
  lead.beta_client_conversion = {
    ...(lead.beta_client_conversion || {}),
    prospect_close: nextCloseWorkflow
  };
  lead.updated_at = acceptedAt;
  state.leads.set(lead.id, lead);
  track("pilot_acceptance_recorded", {
    leadProfileId: lead.id,
    company: lead.company?.name || lead.company?.domain || "",
    signerEmail,
    billingMethod: nextAcceptance.billing_method,
    setupFeeStatus: nextAcceptance.setup_fee_status,
    sends_external_email: false,
    transmits_payment: false,
    actor
  });
  persistSoon();

  return {
    status: "pilot_acceptance_recorded",
    leadProfileId: lead.id,
    close_workflow: nextCloseWorkflow,
    pilot_acceptance: nextAcceptance,
    packet: publicPilotAcceptancePacket(lead, baseUrl)
  };
}

function publicPilotAcceptancePacket(lead, baseUrl = "") {
  const prospect = realBetaActivationProspectItem(lead);
  const closeWorkflow = normalizeProspectCloseWorkflow(lead.beta_client_conversion?.prospect_close || {}, lead);
  const acceptance = normalizePilotAcceptance(closeWorkflow.pilot_acceptance || {});
  const agreement = pilotAgreementPacket(baseUrl);
  const root = baseUrl.replace(/\/$/, "");
  const accepted = acceptance.status === "accepted";
  const status = accepted ? "accepted" : "needs_acceptance";
  const publicLinks = {
    acceptance_room: prospectPilotAcceptanceUrl(closeWorkflow, root),
    acceptance_markdown: `${prospectPilotAcceptanceUrl(closeWorkflow, root)}?format=markdown`,
    confirmation_form: prospectCloseConfirmationUrl(closeWorkflow, root),
    confirmation_status: prospectCloseConfirmationStatusUrl(closeWorkflow, root),
    request_kit: prospectCloseConfirmationRequestKitUrl(closeWorkflow, root),
    pilot_agreement: `${root}/pilot-agreement`,
    pilot_close_kit: `${root}/pilot-close-kit`,
    procurement_packet: `${root}/procurement-packet`,
    security_center: `${root}/security`,
    business_case: `${root}/business-case`,
    implementation_guide: `${root}/implementation-guide`,
    crm_handoff_guide: `${root}/crm-handoff-guide`,
    sample_profile: `${root}/sample-profile`
  };
  const acceptanceChecklist = [
    {
      key: "scope",
      label: "14-day private beta scope",
      status: accepted ? "accepted" : "needs_acceptance",
      detail: "One high-intent page, one script tag, one CRM handoff path, and one proof motion."
    },
    {
      key: "commercial_terms",
      label: "Commercial terms",
      status: accepted ? "accepted" : "needs_acceptance",
      detail: `$${agreement.offer.setup_fee_usd} setup, $${agreement.offer.managed_pilot_monthly_usd}/month managed pilot, month-to-month after review unless cancelled or expanded.`
    },
    {
      key: "providerless_default",
      label: "Providerless cost posture",
      status: accepted ? "accepted" : "needs_acceptance",
      detail: "Paid enrichment remains off by default; missing fields escalate only after buyer/operator approval."
    },
    {
      key: "no_revenue_guarantee",
      label: "No guaranteed conversion lift",
      status: accepted ? "accepted" : "needs_acceptance",
      detail: "The pilot measures profile quality and workflow speed; it does not guarantee pipeline or revenue."
    },
    {
      key: "manual_payment",
      label: "Manual billing collection",
      status: accepted ? "accepted" : "needs_acceptance",
      detail: "This receipt records acceptance and billing intent only; it does not charge a card or transmit payment data."
    }
  ];
  const safety = {
    tokenized_public_room: true,
    mutates_buyer_state_on_get: false,
    mutates_buyer_state_on_post: true,
    sends_external_email_on_get: false,
    sends_external_email_on_post: false,
    creates_beta_client_on_get: false,
    creates_beta_client_on_post: false,
    exposes_crm_profiles: false,
    exposes_operator_actions: false,
    exposes_tenant_exports: false,
    transmits_external_data_on_get: false,
    transmits_payment_data: false,
    transmits_external_crm: false,
    paid_provider_lookup_by_default: false,
    live_proof_claimed: false
  };
  const packet = {
    type: "deal_threads.public_pilot_acceptance.v1",
    generated_at: now(),
    status,
    status_label: pilotAcceptanceStatusLabel(acceptance),
    prospect: {
      company: prospect.company,
      domain: prospect.domain,
      contact_name: prospect.contact_name,
      contact_email: prospect.contact_email,
      business_need: prospect.business_need,
      crm: prospect.crm
    },
    offer: agreement.offer,
    summary: {
      accepted,
      accepted_at: acceptance.accepted_at,
      signer_email: acceptance.signer_email,
      billing_contact_email: acceptance.billing_contact_email,
      billing_method: acceptance.billing_method,
      setup_fee_status: acceptance.setup_fee_status,
      setup_fee_usd: acceptance.setup_fee_usd,
      managed_pilot_monthly_usd: acceptance.managed_pilot_monthly_usd,
      transmits_payment_data: false,
      paid_lookups_recommended_now: 0
    },
    pilot_acceptance: acceptance,
    acceptance_checklist: acceptanceChecklist,
    next_action: accepted
      ? "Deal Threads can pair this acceptance receipt with buyer confirmation before sending the client-specific install handoff."
      : "Accept the pilot terms and confirm the billing contact so Deal Threads has a clean manual receipt before paid beta kickoff.",
    public_links: publicLinks,
    safety,
    public_safety: safety
  };
  packet.markdown = publicPilotAcceptanceMarkdown(packet);
  return packet;
}

