function prospectConfirmationQuickReplyTemplate(prospect, closeWorkflow, missingDetails = [], root = "") {
  const missing = new Set(missingDetails);
  const replyFields = [
    missing.has("Target page") ? "Target page: https://..." : null,
    missing.has("Implementation owner") ? "Implementation owner: name, email" : null,
    missing.has("CRM owner") ? "CRM owner: email" : null,
    missing.has("Routing owner") ? "Routing owner: email" : null,
    missing.has("Proof recipients") ? "Proof recipients: email, email" : null
  ].filter(Boolean);
  const requiredFields = replyFields.length
    ? replyFields
    : [
        `Target page: ${closeWorkflow.target_page_url || prospect.recommended_website_url || "already captured"}`,
        `Implementation owner: ${[closeWorkflow.implementation_owner_name, closeWorkflow.implementation_owner_email].filter(Boolean).join(", ") || "already captured"}`,
        `CRM owner: ${closeWorkflow.crm_owner_email || "already captured"}`,
        `Routing owner: ${closeWorkflow.routing_owner_email || "already captured"}`,
        `Proof recipients: ${closeWorkflow.report_recipients?.join(", ") || "already captured"}`
      ];
  const body = [
    "Quick reply fallback:",
    ...requiredFields,
    "Old-form baseline (optional): first-touch minutes, meeting rate, opportunity rate, win rate, sales-cycle days",
    "Approval: these details are approved for the 14-day pilot kickoff."
  ].join("\n");
  return {
    enabled: true,
    intro: "If the form is slower than replying, the buyer can reply with this block and the operator can parse it in the protected reply preview.",
    body,
    missing_details: missingDetails,
    protected_reply_preview_url: `${root}/activation/prospects/${encodeURIComponent(prospect.lead_id)}/confirmation-reply`,
    apply_requires_operator_post: true,
    sends_email_from_server: false,
    creates_beta_client: false,
    runs_paid_enrichment: false
  };
}

function prospectConfirmationNudgePacket(lead, baseUrl = "") {
  if (!isRealBetaActivationProspect(lead)) {
    return {
      error: "prospect_not_convertible",
      status: 409,
      message: "Lead is not currently eligible for real beta activation."
    };
  }

  const prospect = realBetaActivationProspectItem(lead);
  const closeWorkflow = ensureProspectCloseWorkflow(lead);
  const root = baseUrl.replace(/\/$/, "");
  const publicLinks = {
    buyer_confirmation: `${root}${prospect.confirmation_url}`,
    buyer_confirmation_status: prospectCloseConfirmationStatusUrl(closeWorkflow, root),
    buyer_confirmation_approval_brief: prospectCloseConfirmationApprovalBriefUrl(closeWorkflow, root),
    buyer_confirmation_request_kit: prospectCloseConfirmationRequestKitUrl(closeWorkflow, root),
    buyer_confirmation_guide: `${root}/buyer-confirmation-guide`,
    stakeholder_forwarding_kit: `${root}/stakeholder-forwarding-kit`,
    mutual_action_plan: `${root}/mutual-action-plan`,
    pilot_approval_room: `${root}/pilot-approval-room`,
    implementation_guide: `${root}/implementation-guide`,
    crm_handoff_guide: `${root}/crm-handoff-guide`,
    pilot_acceptance: prospectPilotAcceptanceUrl(closeWorkflow, root),
    security_center: `${root}/security`,
    sample_profile: `${root}/sample-profile`
  };
  const firstName = prospect.contact_name ? prospect.contact_name.split(/\s+/)[0] : "there";
  const missingDetails = [
    ["Target page", closeWorkflow.target_page_url],
    ["Implementation owner", closeWorkflow.implementation_owner_email],
    ["CRM owner", closeWorkflow.crm_owner_email],
    ["Routing owner", closeWorkflow.routing_owner_email],
    ["Proof recipients", closeWorkflow.report_recipients?.length ? closeWorkflow.report_recipients.join(", ") : ""]
  ]
    .filter(([, value]) => !value)
    .map(([label]) => label);
  const subject = `Confirm ${prospect.company} Deal Threads pilot details`;
  const status = closeWorkflow.status === "confirmed" ? "confirmation_already_received" : "buyer_confirmation_nudge_ready";
  const nextStep = closeWorkflow.status === "confirmed"
    ? "Buyer confirmation is already complete. Convert the prospect from /activation and send the install handoff when ready."
    : "Open the buyer confirmation form and confirm the page, owners, recipients, and old-form baseline so Deal Threads can issue the client-specific install handoff.";
  const quickReplyTemplate = prospectConfirmationQuickReplyTemplate(prospect, closeWorkflow, missingDetails, root);
  const emailBody = [
    `Hi ${firstName},`,
    "",
    `Quick follow-up on the Deal Threads 14-day pilot for ${prospect.company}.`,
    "",
    "The only thing needed before we send the client-specific install handoff is the buyer confirmation form:",
    publicLinks.buyer_confirmation,
    `Approval brief: ${publicLinks.buyer_confirmation_approval_brief}`,
    `Status room: ${publicLinks.buyer_confirmation_status}`,
    `Request kit: ${publicLinks.buyer_confirmation_request_kit}`,
    `Pilot acceptance: ${publicLinks.pilot_acceptance}`,
    "",
    "It confirms:",
    "- The target page for the current contact/demo form",
    "- The implementation owner for the one script-tag install",
    "- The CRM/routing owners and proof recipients",
    "- The old-form baseline we should beat during the pilot",
    "",
    "The default pilot posture is still providerless enrichment, explicit visitor consent, and dry-run/manual CRM handoff until your team approves live transmission.",
    "",
    `14-day mutual action plan: ${publicLinks.mutual_action_plan}`,
    `Buyer confirmation guide: ${publicLinks.buyer_confirmation_guide}`,
    `Stakeholder forwarding kit: ${publicLinks.stakeholder_forwarding_kit}`,
    `Implementation guide: ${publicLinks.implementation_guide}`,
    `CRM handoff guide: ${publicLinks.crm_handoff_guide}`,
    `Security center: ${publicLinks.security_center}`,
    "",
    missingDetails.length ? `Open items we still need: ${missingDetails.join(", ")}.` : "The form should only take a few minutes.",
    "",
    "If it is faster, you can also reply to this email with:",
    "",
    quickReplyTemplate.body,
    "",
    "Thanks,"
  ].join("\n");

  const packet = {
    generated_at: now(),
    lead_id: lead.id,
    status,
    prospect,
    public_links: publicLinks,
    subject,
    email_body: emailBody,
    missing_confirmation_details: missingDetails,
    quick_reply_template: quickReplyTemplate,
    close_workflow: closeWorkflow,
    operator_next_steps: [
      "Send this nudge only when the close packet is sent but the buyer confirmation form is still incomplete.",
      "If the buyer replies instead of using the form, paste the reply into the protected confirmation reply preview before applying it.",
      "After the buyer confirms, convert the prospect from /activation or use the activation kickoff endpoint.",
      "Do not claim live beta proof until a client-specific widget captures real buyer traffic."
    ],
    next_step: nextStep
  };
  packet.markdown = prospectConfirmationNudgeMarkdown(packet);
  return packet;
}

