  const closeDelivery = normalizeLaunchPacketDelivery(closeWorkflow.close_packet_delivery);
  const nudgeDelivery = normalizeLaunchPacketDelivery(closeWorkflow.confirmation_nudge_delivery);
  const receiptDelivery = normalizeLaunchPacketDelivery(closeWorkflow.buyer_confirmation_delivery);
  const pilotAcceptance = normalizePilotAcceptance(closeWorkflow.pilot_acceptance || {});
  const pilotAccepted = pilotAcceptance.status === "accepted";
  const status = convertedClient
