function launchProofOwnerSuggestedRecipients(owner = "", market = {}) {
  const activationItem = market.activation_follow_ups?.top_item || null;
  const installItem = market.install_queue?.top_item || null;
  const ownerText = owner.toLowerCase();
  if (ownerText.includes("buyer champion") || ownerText.includes("revops")) {
    return uniqueStrings([activationItem?.contact_email, activationItem?.suggested_recipients || []].flat());
  }
  if (ownerText.includes("implementation")) {
    return uniqueStrings([
      activationItem?.close_workflow?.implementation_owner_email,
      installItem?.beta_client?.owner_email,
      activationItem?.contact_email
    ]);
  }
  if (ownerText.includes("crm")) {
    return uniqueStrings([
      activationItem?.close_workflow?.crm_owner_email,
      activationItem?.recommended_beta_client?.owner_email,
      installItem?.beta_client?.owner_email
    ]);
  }
  if (ownerText.includes("sales rep")) {
    return uniqueStrings([installItem?.rep_feedback?.owner_email, activationItem?.high_priority_owner, activationItem?.recommended_beta_client?.high_priority_owner]);
  }
  return [];
}

function launchProofOwnerKey(owner = "") {
  return stableSlug(owner, "proof_owner");
}

function launchProofHandoffSentEvents(ownerKey = "") {
  const key = optionalString(ownerKey);
  return state.events
    .filter((event) => event.eventType === "launch_proof_owner_handoff_marked_sent")
    .map((event) => ({
      id: event.id,
      sent_at: event.createdAt,
      owner_key: optionalString(event.properties?.owner_key),
      owner: optionalString(event.properties?.owner),
      recipients: normalizeOptionalList(event.properties?.recipients) || [],
      subject: optionalString(event.properties?.subject),
      note: optionalString(event.properties?.note),
      sent_via: optionalString(event.properties?.sent_via) || "manual",
      sends_from_server: Boolean(event.properties?.sends_from_server),
      proof_item_keys: normalizeOptionalList(event.properties?.proof_item_keys) || [],
      actor: optionalString(event.properties?.actor)
    }))
    .filter((event) => !key || event.owner_key === key)
    .sort((a, b) => String(b.sent_at || "").localeCompare(String(a.sent_at || "")));
}

function launchProofOwnerHandoffBody(group, root = "") {
  const lines = group.items.flatMap((item) => [
    `- ${item.label}: ${item.proof_condition}`,
    `  Current evidence: ${item.current_evidence}`,
    `  Next action: ${item.next_action}`,
    `  Capture: ${item.capture_surface}`,
    `  Verify: ${item.verification_surface}`
  ]);
  return [
    `Hi ${group.owner_greeting},`,
    "",
    "To move Deal Threads from private beta setup toward market-ready proof, we need the evidence items below cleared.",
    "",
    ...lines,
    "",
    `Proof ledger: ${root}/launch/proof-ledger`,
    `Market gate: ${root}/launch/market-ready`,
    "",
    "Default posture stays providerless, consent-gated, and no live-proof claim until the ledger has zero blockers.",
    "",
    "Thanks,"
  ].join("\n");
}

function launchProofOwnerHandoffPacket(baseUrl = "", searchParams = new URLSearchParams()) {
  const root = baseUrl.replace(/\/$/, "");
  const market = marketLaunchReadinessPacket(baseUrl, searchParams);
  const ledger = launchProofLedgerPacket(baseUrl, searchParams);
  const openEntries = ledger.entries.filter((entry) => entry.status !== "pass");
  const deliveryEvents = launchProofHandoffSentEvents();
  const grouped = new Map();
  for (const entry of openEntries) {
    if (!grouped.has(entry.owner)) grouped.set(entry.owner, []);
    grouped.get(entry.owner).push(entry);
  }
  const groups = [...grouped.entries()].map(([owner, items]) => {
    const firstName = owner.includes("Deal Threads") ? "team" : "there";
    const key = launchProofOwnerKey(owner);
    const deliveries = deliveryEvents.filter((event) => event.owner_key === key);
    const lastDelivery = deliveries[0] || null;
    const group = {
      key,
      owner,
      owner_greeting: firstName,
      suggested_recipients: launchProofOwnerSuggestedRecipients(owner, market),
      subject: `Deal Threads proof items for ${owner}`,
      items,
      blocker_items: items.filter((item) => item.status === "blocker").length,
      warning_items: items.filter((item) => item.status === "warning").length,
      primary_capture_surface: items[0]?.capture_surface || ledger.links.operator_room,
      verification_surface: items[0]?.verification_surface || ledger.links.markdown,
      delivery_audit: {
        manual_sent_records: deliveries.length,
        last_sent_at: lastDelivery?.sent_at || null,
        last_sent_by: lastDelivery?.actor || null,
        last_recipients: lastDelivery?.recipients || []
      },
      manual_sent_action: {
        method: "POST",
        html_action: `${root}/launch/proof-handoff/${encodeURIComponent(key)}/mark-sent`,
        api_url: `${root}/api/v1/launch/proof-handoff/${encodeURIComponent(key)}/sent`,
        mutates_state: true,
        sends_from_server: false,
        preview_only_on_get: true
      }
    };
    group.body = launchProofOwnerHandoffBody(group, root);
    group.mailto_url = mailtoDraftUrl({ recipients: group.suggested_recipients, subject: group.subject, body: group.body });
    return group;
  });
  const safety = {
    protected_operator_only: true,
    sends_external_email_on_get: false,
    marks_buyer_confirmation_complete_on_get: false,
    creates_beta_client_on_get: false,
    transmits_external_crm_on_get: false,
    paid_provider_lookup_by_default: false,
    live_proof_claimed: false
  };
  const recommendedActions = uniqueStrings([
    "Send or paste the first owner handoff only after reviewing the recipient list.",
    groups[0] ? `Start with ${groups[0].owner}: ${groups[0].items[0]?.next_action}` : null,
    "Keep the proof ledger open while owners submit confirmation, install, CRM, and rep-feedback evidence."
  ].filter(Boolean));
  return {
    type: "deal_threads.launch_proof_owner_handoff.v1",
    generated_at: now(),
    status: ledger.status,
    status_label: ledger.status_label,
    market_ready: ledger.market_ready,
    summary: {
      owner_groups: groups.length,
      open_items: openEntries.length,
      blocker_items: openEntries.filter((entry) => entry.status === "blocker").length,
      warning_items: openEntries.filter((entry) => entry.status === "warning").length,
      suggested_recipient_count: uniqueStrings(groups.flatMap((group) => group.suggested_recipients)).length,
      mailto_drafts: groups.length,
      manual_sent_records: groups.reduce((total, group) => total + group.delivery_audit.manual_sent_records, 0),
      paid_lookups_recommended_now: 0
    },
    groups,
    recommended_actions: recommendedActions,
    source_ledger: {
      operator_room: ledger.links.operator_room,
      markdown: ledger.links.markdown,
      market_gate: ledger.links.market_gate
    },
    links: {
      operator_room: `${root}/launch/proof-handoff`,
      proof_ledger: `${root}/launch/proof-ledger`,
      market_gate: `${root}/launch/market-ready`,
      activation_close_desk: `${root}/activation/close-desk`,
      install_queue: `${root}/launch/install-queue`,
      markdown: `${root}/api/v1/launch/proof-handoff?format=markdown`
    },
    safety,
    public_safety: safety
	  };
	}

function markLaunchProofOwnerHandoffSent(ownerKey, body = {}, actor = "operator", baseUrl = "") {
  const key = optionalString(ownerKey);
  const packet = launchProofOwnerHandoffPacket(baseUrl);
  const group = packet.groups.find((item) => item.key === key);
  if (!group) {
    return {
      error: "proof_owner_group_not_found",
      status: 404,
      message: "Proof owner handoff group is not currently open."
    };
  }
  const recipients = normalizeOptionalList(firstDefined(body, "recipients", "sentTo", "sent_to")) || group.suggested_recipients;
  const note = stringFromBody(body, "note", "notes") || "Proof owner handoff was sent manually from the mailto draft.";
  const event = track("launch_proof_owner_handoff_marked_sent", {
    owner_key: group.key,
    owner: group.owner,
    recipients,
    subject: group.subject,
    note,
    sent_via: "manual",
    sends_from_server: false,
    proof_item_keys: group.items.map((item) => item.key),
    blocker_items: group.blocker_items,
    warning_items: group.warning_items,
    market_status: packet.status,
    market_ready: packet.market_ready,
    actor
  });
  const delivery = launchProofHandoffSentEvents(group.key).find((item) => item.id === event.id) || {
    id: event.id,
    sent_at: event.createdAt,
    owner_key: group.key,
    owner: group.owner,
    recipients,
    subject: group.subject,
    note,
    sent_via: "manual",
    sends_from_server: false,
    proof_item_keys: group.items.map((item) => item.key),
    actor
  };
  return {
    type: "deal_threads.launch_proof_owner_handoff_sent.v1",
    marked_sent: true,
    delivery,
    group: {
      key: group.key,
      owner: group.owner,
      items: group.items.map((item) => ({ key: item.key, label: item.label, status: item.status })),
      blocker_items: group.blocker_items,
      warning_items: group.warning_items
    },
    manual_handoff: {
      method: "manual",
      sends_from_server: false,
      marked_sent: true,
      note
    },
    market_gate: {
      status: packet.status,
      market_ready: packet.market_ready
    }
  };
}

