function realBetaProspectClosePacket(lead, baseUrl = "") {
  if (!isRealBetaActivationProspect(lead)) {
    return {
      error: "prospect_not_convertible",
      status: 409,
      message: "Lead is not currently eligible for real beta activation."
    };
  }

  const prospect = realBetaActivationProspectItem(lead);
  const root = baseUrl.replace(/\/$/, "");
  const publicLinks = {
    pilot_close_kit: `${root}/pilot-close-kit`,
    pilot_approval_room: `${root}/pilot-approval-room`,
    mutual_action_plan: `${root}/mutual-action-plan`,
    buyer_confirmation_guide: `${root}/buyer-confirmation-guide`,
    stakeholder_forwarding_kit: `${root}/stakeholder-forwarding-kit`,
    pilot_agreement: `${root}/pilot-agreement`,
    buyer_confirmation: `${root}${prospect.confirmation_url}`,
    buyer_confirmation_status: prospectCloseConfirmationStatusUrl(prospect.close_workflow, root),
    buyer_confirmation_approval_brief: prospectCloseConfirmationApprovalBriefUrl(prospect.close_workflow, root),
    buyer_confirmation_request_kit: prospectCloseConfirmationRequestKitUrl(prospect.close_workflow, root),
    pilot_acceptance: prospectPilotAcceptanceUrl(prospect.close_workflow, root),
    security_center: `${root}/security`,
    sample_profile: `${root}/sample-profile`
  };
  const firstName = prospect.contact_name ? prospect.contact_name.split(/\s+/)[0] : "there";
  const subject = `14-day Deal Threads beta pilot for ${prospect.company}`;
  const confirmationChecklist = [
    "Target page where the current contact or demo form lives.",
    "Implementation owner name and email for the single script-tag install.",
    "CRM owner and preferred handoff path for the first beta leads.",
    "Routing owner for high-priority buyer profiles.",
    "Old-form baseline: average first-touch time, meeting rate, opportunity rate, win rate, and sales-cycle length if available.",
    "Report recipients for the weekly proof packet."
  ];
  const operatorNextSteps = [
    `Convert ${prospect.company} into a beta client from /activation after the buyer confirms the pilot.`,
    "Send the beta launch packet with the client-specific install handoff page.",
    "Have the implementation owner submit the tested page URL from the tokenized install page.",
    "Run the protected install source check, then capture one real beta-attributed lead before claiming live proof."
  ];
  const emailBody = [
    `Hi ${firstName},`,
    "",
    `Based on the ${prospect.company} conversation, Deal Threads looks like a good 14-day beta fit:`,
    "",
    `- Need: ${prospect.business_need || "improve inbound qualification and sales follow-up context"}`,
    `- Timeline: ${prospect.timeline || "not captured yet"}`,
    `- Budget signal: ${prospect.budget || "not captured yet"}`,
    `- CRM: ${prospect.crm || "not captured yet"}`,
    `- ICP fit: ${prospect.icp_fit}/100`,
    "",
    "The beta is intentionally low-friction: one script tag on one high-intent page, explicit visitor consent, providerless enrichment by default, dry-run/manual CRM handoff until you approve a live path, and a weekly proof packet showing whether better buyer profiles improve response speed and pipeline movement.",
    "",
    `Pilot close kit: ${publicLinks.pilot_close_kit}`,
    `Approval room: ${publicLinks.pilot_approval_room}`,
    `Mutual action plan: ${publicLinks.mutual_action_plan}`,
    `Buyer confirmation guide: ${publicLinks.buyer_confirmation_guide}`,
    `Stakeholder forwarding kit: ${publicLinks.stakeholder_forwarding_kit}`,
    `Pilot agreement: ${publicLinks.pilot_agreement}`,
    `Buyer confirmation form: ${publicLinks.buyer_confirmation}`,
    `Approval brief: ${publicLinks.buyer_confirmation_approval_brief}`,
    `Buyer confirmation status: ${publicLinks.buyer_confirmation_status}`,
    `Buyer confirmation request kit: ${publicLinks.buyer_confirmation_request_kit}`,
    `Pilot acceptance receipt: ${publicLinks.pilot_acceptance}`,
    `Security center: ${publicLinks.security_center}`,
    `Sample profile: ${publicLinks.sample_profile}`,
    "",
    "To start, please confirm the pilot details in the buyer confirmation form. It asks for:",
    ...confirmationChecklist.map((item) => `- ${item}`),
    "",
    "Once we have that, we can send the client-specific install handoff and create the first attributed test lead.",
    "",
    "Thanks,"
  ].join("\n");

  const packet = {
    generated_at: now(),
    lead_id: lead.id,
    status: "prospect_close_ready",
    prospect,
    recommended_beta_client: {
      name: prospect.recommended_client_name,
      website_url: prospect.recommended_website_url,
      owner_email: prospect.owner_email,
      crm: prospect.crm,
      high_priority_owner: prospect.high_priority_owner,
      report_recipients: prospect.report_recipients
    },
    public_links: publicLinks,
    subject,
    email_body: emailBody,
    confirmation_checklist: confirmationChecklist,
    operator_next_steps: operatorNextSteps,
    operator_conversion_url: `${root}${prospect.conversion_url}`,
    protected_close_packet_url: `${root}${prospect.close_packet_markdown_url}`
  };
  packet.markdown = realBetaProspectClosePacketMarkdown(packet);
  return packet;
}

