async function readBody(req) {
  const chunks = [];
  let size = 0;
  for await (const chunk of req) {
    size += chunk.length;
    if (size > MAX_REQUEST_BODY_BYTES) {
      const error = new Error(`Request body exceeds ${MAX_REQUEST_BODY_BYTES} bytes.`);
      error.status = 413;
      error.code = "payload_too_large";
      throw error;
    }
    chunks.push(chunk);
  }
  const raw = Buffer.concat(chunks).toString("utf8");
  if (!raw) return {};
  const contentType = req.headers["content-type"] || "";

  if (contentType.includes("application/json")) {
    try {
      return JSON.parse(raw);
    } catch {
      const error = new Error("Request JSON could not be parsed.");
      error.status = 400;
      error.code = "invalid_json";
      throw error;
    }
  }

  if (contentType.includes("application/x-www-form-urlencoded")) {
    return Object.fromEntries(new URLSearchParams(raw));
  }

  return { raw };
}

async function readWebhookBody(req) {
  const chunks = [];
  let size = 0;
  for await (const chunk of req) {
    size += chunk.length;
    if (size > MAX_REQUEST_BODY_BYTES) {
      const error = new Error(`Request body exceeds ${MAX_REQUEST_BODY_BYTES} bytes.`);
      error.status = 413;
      error.code = "payload_too_large";
      throw error;
    }
    chunks.push(chunk);
  }
  const raw = Buffer.concat(chunks).toString("utf8");
  if (!raw) return { raw, body: {} };
  try {
    return { raw, body: JSON.parse(raw) };
  } catch {
    const error = new Error("Webhook JSON could not be parsed.");
    error.status = 400;
    error.code = "invalid_json";
    throw error;
  }
}

function track(eventType, properties = {}) {
  const event = {
    id: id("evt"),
    tenantId: widgetConfig.tenantId,
    widgetId: widgetConfig.widgetId,
    eventType,
    properties,
    createdAt: now()
  };
  state.events.push(event);
  persistSoon();
  return event;
}

function emptyProfile() {
  return {
    visitor: {
      name: null,
      email: null,
      phone: null,
      role: null,
      seniority: "unknown",
      authority_signal: "unknown"
    },
    company: {
      name: null,
      domain: null,
      website: null,
      industry_hint: null,
      size_hint: null
    },
    qualification: {
      business_need: null,
      pain_point: null,
      product_interest: null,
      timeline: "unknown",
      budget_status: "unknown",
      budget_range: "unknown",
      buying_stage: "unknown",
      crm: "unknown",
      sales_stack: [],
      integration_need: null
    },
    routing: {
      priority_hint: "manual_review",
      route_type: "manual_review",
      recommended_next_action: "Review the lead profile before follow-up."
    },
    meta: {
      confidence: 0.5,
      missing_required_fields: [],
      needs_human_review: true,
      reasoning_summary: null
    }
  };
}

function normalizeDomain(input) {
  if (!input) return null;
  let value = String(input).trim().toLowerCase();
  try {
    const parsed = new URL(/^https?:\/\//i.test(value) ? value : `https://${value}`);
    value = parsed.hostname.toLowerCase();
  } catch {
    value = value.replace(/^https?:\/\//, "").split("/")[0].split(":")[0];
  }
  value = value.replace(/^www\./, "");
  if (!value.includes(".")) return null;
  return value.replace(/[^a-z0-9.-]/g, "");
}

const MONTH_INDEX = new Map(
  ["january", "february", "march", "april", "may", "june", "july", "august", "september", "october", "november", "december"].map((month, index) => [
    month,
    index
  ])
);

function markHumanReview(profile, reason) {
  profile.meta.needs_human_review = true;
  if (reason) {
    const existing = profile.meta.reasoning_summary || "";
    if (!existing.includes(reason)) profile.meta.reasoning_summary = existing ? `${existing} ${reason}` : reason;
  }
  profile.meta.confidence = Math.min(Number(profile.meta.confidence || 0.5), 0.45);
}

function hasStickyHumanReviewReason(profile) {
  return /instruction injection|negated timeline|conflicting/i.test(profile.meta.reasoning_summary || "");
}

function hasMeaningfulLeadEvidence(profile) {
  return Boolean(
    profile.visitor.email ||
      profile.visitor.phone ||
      profile.visitor.name ||
      profile.company.name ||
      profile.company.domain ||
      profile.company.size_hint ||
      profile.qualification.business_need ||
      profile.qualification.product_interest ||
      profile.qualification.pain_point ||
      profile.qualification.timeline !== "unknown" ||
      profile.qualification.budget_status !== "unknown" ||
      profile.qualification.budget_range !== "unknown" ||
      profile.qualification.crm !== "unknown" ||
      profile.qualification.buying_stage !== "unknown" ||
      profile.visitor.authority_signal !== "unknown"
  );
}

function heuristicConfidence(profile) {
  const captured = [
    Boolean(profile.visitor.email || profile.visitor.phone),
    Boolean(profile.company.name || profile.company.domain || profile.company.size_hint),
    Boolean(profile.qualification.business_need || profile.qualification.product_interest || profile.qualification.pain_point),
    profile.qualification.timeline !== "unknown",
    profile.qualification.budget_status !== "unknown" || profile.qualification.budget_range !== "unknown",
    profile.qualification.crm !== "unknown",
    profile.visitor.authority_signal !== "unknown"
  ].filter(Boolean).length;
  return Math.min(0.82, 0.25 + captured * 0.08);
}

function refreshHumanReviewFromEvidence(profile) {
  if (hasStickyHumanReviewReason(profile)) return;
  const hasEvidence = hasMeaningfulLeadEvidence(profile);
  profile.meta.needs_human_review = !hasEvidence;
  profile.meta.confidence = hasEvidence ? Math.max(Number(profile.meta.confidence || 0), heuristicConfidence(profile)) : 0.2;
}

function hasInstructionInjection(text) {
  return /\b(ignore (?:all )?(?:previous|prior|your)|set (?:my |our |the )?(?:priority|budget|budget_range|authority|crm|schema)|output that|regardless of what i say|your (?:budget|crm|authority|priority) is|developer message|system prompt|schema)\b/i.test(
    text
  );
}

function sanitizedExtractionText(text) {
  const parts = String(text || "")
    .split(/(?<=[.!?])\s+|[\r\n]+/)
    .map((part) => part.trim())
    .filter(Boolean);
  const kept = parts.filter((part) => !hasInstructionInjection(part));
  return kept.length ? kept.join(" ") : "";
}

function crmFromGroundedText(lower) {
  const crms = ["hubspot", "salesforce", "pipedrive", "zoho"];
  for (const crm of crms) {
    if (lower.includes(crm)) return crm === "zoho" ? "other" : crm;
  }
  return "unknown";
}

function applyInstructionInjectionGuards(profile, originalText) {
  const text = String(originalText || "");
  if (!hasInstructionInjection(text)) return false;

  const factText = sanitizedExtractionText(text);
  const factLower = factText.toLowerCase();
  markHumanReview(profile, "Potential instruction injection detected; extracted only grounded visitor facts.");

  if (/\b(?:crm|salesforce|hubspot|pipedrive|zoho|output that we use)\b/i.test(text)) {
    const groundedCrm = crmFromGroundedText(factLower);
    profile.qualification.crm = groundedCrm;
    profile.qualification.sales_stack = groundedCrm === "unknown" ? [] : [displayCrm(groundedCrm)];
    if (groundedCrm === "unknown") profile.qualification.integration_need = null;
  }

  if (/\b(?:budget|budget_range)\b/i.test(text)) {
    profile.qualification.budget_range = "unknown";
    if (hasNoBudgetSignal(factLower)) profile.qualification.budget_status = "none";
    else if (hasBudgetUnknownSignal(factLower)) profile.qualification.budget_status = "unknown";
  }

  if (/\b(?:authority|decision_owner)\b/i.test(text)) {
    if (/\bintern\b/.test(factLower) || /\bjust (?:looking|exploring)\b|\bearly research\b|\bresearching\b/.test(factLower)) {
      profile.visitor.authority_signal = "researcher";
    } else if (!/\b(?:i own|own the decision|decision maker|founder|ceo|vp|i influence|influence the decision|consultant)\b/.test(factLower)) {
      profile.visitor.authority_signal = "unknown";
    }
  }

  if (/\bintern\b/.test(factLower)) {
    profile.visitor.role ||= "intern";
    profile.visitor.seniority = "individual_contributor";
    profile.visitor.authority_signal = "researcher";
  }

  if (profile.company.name && /\b(?:ignore|schema|output|priority|budget_range|decision_owner|salesforce|hubspot|pipedrive)\b/i.test(profile.company.name)) {
    profile.company.name = null;
  }

  return true;
}

function parseTimeline(lower) {
  if (/\b(?:do not|don't|dont|we do not|we don't|haven't|have not)\s+.{0,24}\btimeline\b|\bno timeline\b/.test(lower)) return "unknown";
  if (/\b(?:later this year|end of (?:the )?year|toward the end of (?:the )?year|by year end)\b/.test(lower)) return "later_this_year";

  const quarter = lower.match(/\b(?:in\s+)?q([1-4])\b/);
  if (quarter) {
    const requestedQuarter = Number(quarter[1]);
    const currentQuarter = Math.floor(new Date().getMonth() / 3) + 1;
    return /\bthis\s+(?:q|quarter|qtr)\b/.test(lower) || requestedQuarter === currentQuarter ? "this_quarter" : "later_this_year";
  }

  if (/\bthis\s*(?:q|quarter|qtr)\b|\bcurrent quarter\b/.test(lower)) return "this_quarter";
  if (/\bthis week\b|\bby\s+(?:monday|tuesday|wednesday|thursday|friday|saturday|sunday)\b|\basap\b|\bimmediately\b|\bright away\b|\bmove fast\b|\burgent\b|\blive by\b|\bsince this morning\b/.test(lower)) {
    return "this_week";
  }
  if (/\bthis month\b|\bsoon\b/.test(lower)) return "this_month";

  for (const [month, index] of MONTH_INDEX) {
    if (new RegExp(`\\b${month}\\b`).test(lower)) {
      const now = new Date();
      const currentMonth = now.getMonth();
      if (index === currentMonth) return "this_month";
      if (Math.floor(index / 3) === Math.floor(currentMonth / 3) && index > currentMonth) return "this_quarter";
      return "later_this_year";
    }
  }

  if (/\b(?:researching|just looking|just exploring|early research|looking into options)\b/.test(lower)) return "researching";
  return null;
}

function budgetAmountRange(lower) {
  const range = lower.match(/\$?\s*(\d{1,3})\s*(?:k)?\s*(?:-|to)\s*\$?\s*(\d{1,3})\s*k\b/);
  const single = range ? null : lower.match(/\$?\s*(\d{1,3})\s*k\b/);
  const amount = Number(range?.[2] || single?.[1] || 0);
  if (!amount) return null;
  if (amount <= 10) return "under_10k";
  if (amount < 30) return "10k_30k";
  if (amount <= 60) return "30k_60k";
  return "60k_plus";
}

function hasBudgetUnknownSignal(lower) {
  return /\b(?:haven't|have not|not)\s+.{0,32}\bbudget\b|\bbudget\s+(?:is\s+)?(?:unknown|unclear|not sure|tbd)\b|\bnot sure\b.{0,24}\bbudget\b/.test(lower);
}

function hasNoBudgetSignal(lower) {
  return /\bno budget\b|\bwithout budget\b|\bzero budget\b|\bspend (?:basically )?nothing\b|\bno budget allocated\b/.test(lower);
}

function hasMeaningfulNeedText(lower) {
  if (/^(?:hey|hi|hello)\b/.test(lower)) return false;
  if (/^we get a lot of leads\.?$/.test(lower)) return false;
  return /\b(?:lead|leads|demo|routing|follow[- ]?up|inbound|forms?|widget|crm|pipedrive|hubspot|salesforce|resell|embed|partnership|pricing|support|sync|custom fields|tooling|contact forms?)\b/.test(
    lower
  );
}

function extractFromMessage(profile, message) {
  const text = String(message || "").trim();
  const injectionDetected = hasInstructionInjection(text);
  const factText = injectionDetected ? sanitizedExtractionText(text) : text;
  const lower = factText.toLowerCase();

  if (injectionDetected) applyInstructionInjectionGuards(profile, text);

  const emails = [...factText.matchAll(/[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,}/gi)].map((match) => match[0]);
  const email = emails.at(-1);
  if (email) {
    profile.visitor.email = email.toLowerCase();
    const domain = normalizeDomain(email.split("@")[1]);
    if (domain && !["gmail.com", "yahoo.com", "outlook.com", "hotmail.com", "icloud.com"].includes(domain)) {
      profile.company.domain ||= domain;
      profile.company.website ||= `https://${domain}`;
    }
  }

  const url = factText.match(/(?:https?:\/\/)?(?:www\.)?[a-z0-9-]+\.[a-z]{2,}(?:\/[^\s]*)?/i)?.[0];
  const domain = normalizeDomain(url);
  if (domain && !domain.includes("@")) {
    profile.company.domain ||= domain;
    profile.company.website ||= `https://${domain}`;
  }

  const employeeMatch = lower.match(/(?:about|around|roughly|maybe|abt)?\s*(\d{1,5})[\s-]*(?:person|people|ppl|employee|employees|seat|seats)/);
  if (employeeMatch) profile.company.size_hint = `${employeeMatch[1]} employees`;
  else if (/\bsmall (?:marketing )?shop\b/.test(lower)) profile.company.size_hint ||= "small";

  if (/\bb2b saas\b/.test(lower)) profile.company.industry_hint ||= "B2B SaaS";
  else if (/\bsaas\b/.test(lower)) profile.company.industry_hint ||= "SaaS";
  else if (/\bmarketing shop\b|\bmarketing agency\b/.test(lower)) profile.company.industry_hint ||= "marketing agency";
  else if (/\bb2b services\b/.test(lower)) profile.company.industry_hint ||= "B2B services";
  else if (/\bconsulting firm\b|\bconsultant\b/.test(lower)) profile.company.industry_hint ||= "consulting";
  else if (/\blogistics\b/.test(lower)) profile.company.industry_hint ||= "logistics";
  else if (/\bfintech\b/.test(lower)) profile.company.industry_hint ||= "fintech";
  else if (/\bcandle\b|\bshopify\b/.test(lower)) profile.company.industry_hint ||= "handmade candles / ecommerce retail";

  const budgetUnknown = hasBudgetUnknownSignal(lower);
  const noBudget = hasNoBudgetSignal(lower);
  const budgetRange = budgetUnknown || noBudget ? null : budgetAmountRange(lower);
  if (budgetUnknown) {
    profile.qualification.budget_status = "unknown";
    profile.qualification.budget_range = "unknown";
  } else if (noBudget) {
    profile.qualification.budget_status = "none";
    profile.qualification.budget_range = /\bspend (?:basically )?nothing\b|\bzero budget\b/.test(lower) ? "under_10k" : "unknown";
  } else if (budgetRange) {
    profile.qualification.budget_range = budgetRange;
    profile.qualification.budget_status = "likely";
  }

  if (/\bbudget(?:'s| is| has been)? approved\b|\bapproved budget\b|\bbudget.+approved\b|\bset aside\b/.test(lower)) profile.qualification.budget_status = "approved";
  if (/\blikely (?:have |got |has )?budget\b|\bbudget (?:is )?likely\b|\bprob(?:ably)? got\b/.test(lower)) profile.qualification.budget_status = "likely";
  if (lower.includes("build the case") || lower.includes("business case")) profile.qualification.budget_status = "building_case";

  if (/\b(?:do not|don't|dont|we do not|we don't|haven't|have not)\s+.{0,24}\btimeline\b|\bno timeline\b/.test(lower)) {
    profile.qualification.timeline = "unknown";
    markHumanReview(profile, "Visitor negated timeline availability; timeline requires review.");
  } else {
    const timeline = parseTimeline(lower);
    if (timeline) profile.qualification.timeline = timeline;
  }

  const crms = ["hubspot", "salesforce", "pipedrive", "zoho"];
  for (const crm of crms) {
    if (lower.includes(crm)) {
      profile.qualification.crm = crm === "zoho" ? "other" : crm;
      if (!profile.qualification.sales_stack.includes(displayCrm(crm))) {
        profile.qualification.sales_stack.push(displayCrm(crm));
      }
    }
  }

  if (/\bcustom fields?\b|\bsync\b|\bhard requirement\b/.test(lower) && profile.qualification.crm !== "unknown") {
    profile.qualification.integration_need ||= `${displayCrm(profile.qualification.crm)} sync${lower.includes("custom field") ? " with custom fields" : ""}`;
  }

  if (lower.includes("demo routing") || lower.includes("routing")) {
    profile.qualification.product_interest = "AI lead routing and enrichment";
    profile.qualification.business_need ||= "Improve demo routing and lead handoff";
    profile.qualification.pain_point ||= "High-intent leads are not reaching reps with enough context";
  }

  if (lower.includes("lead enrichment") || lower.includes("lead quality") || lower.includes("buyer profile")) {
    profile.qualification.product_interest = "AI lead enrichment";
    profile.qualification.business_need ||= "Improve lead quality with enriched buyer profiles";
    profile.qualification.pain_point ||= "Sales reps need more context before first touch";
  }

  if (/\binbound\b.*\b(?:mess|nowhere|pile up)\b|\bforms?\b.*\b(?:nowhere|miss|broken)\b|\bfollow[- ]?up\b/.test(lower)) {
    profile.qualification.business_need ||= "Improve inbound lead follow-up and routing";
    if (/\bslow lead follow[- ]?up\b/.test(lower)) profile.qualification.pain_point ||= "Slow lead follow-up";
    else if (/\bpile up\b/.test(lower)) profile.qualification.pain_point ||= "Inbound leads pile up and nobody follows up fast";
    else if (/\bgo(?:es)? nowhere\b/.test(lower)) profile.qualification.pain_point ||= "Inbound forms go nowhere";
    else if (/\bmanual chaos\b/.test(lower)) profile.qualification.pain_point ||= "Manual lead routing chaos";
  }

  if (lower.includes("pricing")) profile.qualification.buying_stage = "vendor_evaluation";
  if (lower.includes("book a demo") || lower.includes("demo")) profile.qualification.buying_stage = "vendor_evaluation";
  if (/\bevaluating\b|\bcan't sign off\b|\bcannot sign off\b|\bneed to run it by\b|\bprobably finance\b/.test(lower)) profile.qualification.buying_stage = "vendor_evaluation";
  if (/\bjust (?:looking|exploring)\b|\bearly research\b|\bresearching\b|\bstudent\b|\bpaper\b/.test(lower)) profile.qualification.buying_stage = "education";
  if (/\bcontact forms?\b|\bno crm really\b/.test(lower) && profile.qualification.buying_stage === "unknown") profile.qualification.buying_stage = "education";
  if (lower.includes("support") || lower.includes("already use") || lower.includes("customer")) profile.qualification.buying_stage = "support";
  if (/\bpartnerships?\b|\bpartner program\b|\bresell(?:ing|er)?\b|\bembedding?\b/.test(lower)) profile.qualification.buying_stage = "partner";
  if (profile.qualification.buying_stage === "partner" && profile.qualification.timeline === "unknown") profile.qualification.timeline = "researching";
  if (/\bactive project\b|\bhard requirement\b|\bhave to have\b|\bwant to fix\b|\bwanna sort\b|\bneed this fixed\b|\bmanual chaos\b/.test(lower)) {
    profile.qualification.buying_stage = profile.qualification.buying_stage === "education" ? profile.qualification.buying_stage : "active_project";
  }
  if (profile.qualification.buying_stage === "unknown" && /\binbound\b.*\bmess\b|\bforms?\b.*\bnowhere\b/.test(lower)) profile.qualification.buying_stage = "active_project";

  if (/\b(?:i am|i'm|im)\s+(?:the\s+)?vp\b/.test(lower)) {
    profile.visitor.seniority = "vp";
    profile.visitor.authority_signal = "decision_owner";
  }
  if (/\bmarketing manager\b|\bops lead\b|\boperations lead\b|\bsales ops\b/.test(lower)) {
    profile.visitor.seniority = /\bmanager\b|\blead\b/.test(lower) ? "manager" : profile.visitor.seniority;
    if (profile.visitor.authority_signal === "unknown") profile.visitor.authority_signal = "influencer";
  }
  if (/\brevops\b/.test(lower)) {
    profile.visitor.role ||= "RevOps";
    if (/\bi run revops\b|\brevops lead\b/.test(lower)) {
      profile.visitor.seniority = "director";
      profile.visitor.authority_signal = "influencer";
    }
  }
  if (/\bi run\b.*\bshop\b|\bmy partner\b/.test(lower)) {
    profile.visitor.seniority = profile.visitor.seniority === "unknown" ? "founder" : profile.visitor.seniority;
    profile.visitor.authority_signal = profile.visitor.authority_signal === "unknown" ? "decision_owner" : profile.visitor.authority_signal;
    if (profile.qualification.timeline === "unknown") profile.qualification.timeline = "researching";
  }
  if (/\bintern\b/.test(lower)) {
    profile.visitor.role ||= "intern";
    profile.visitor.seniority = "individual_contributor";
    profile.visitor.authority_signal = "researcher";
  }
  if (/\bi'?m a partner here\b|\bi am a partner here\b/.test(lower)) {
    profile.visitor.role ||= "partner";
    profile.visitor.seniority = "executive";
    profile.visitor.authority_signal = "decision_owner";
  }
  if (/\bconsultant\b|\bfractional revops\b/.test(lower)) {
    profile.visitor.seniority = "consultant";
    profile.visitor.authority_signal = "consultant";
  }
  if (lower.includes("founder") || lower.includes("ceo")) {
    profile.visitor.seniority = "founder";
    profile.visitor.authority_signal = "decision_owner";
  }
  if (lower.includes("i own") || lower.includes("decision maker") || lower.includes("own the decision")) {
    profile.visitor.authority_signal = "decision_owner";
  }
  if (lower.includes("i influence") || lower.includes("influence the decision")) {
    profile.visitor.authority_signal = "influencer";
  }
  if (lower.includes("researching for") || /\bjust (?:looking|exploring)\b|\bearly research\b/.test(lower)) profile.visitor.authority_signal = "researcher";

  const nameMatch =
    factText.match(/my name is\s+([A-Z][a-z]+(?:\s+[A-Z][a-z]+)?)/i) ||
    factText.match(/(?:I am|I'm|Im)\s+([A-Z][a-z]+(?:\s+[A-Z][a-z]+)?)(?:,|$)/) ||
    factText.match(/,\s*([A-Z][a-z]+(?:\s+[A-Z][a-z]+)?)\s*$/);
  if (nameMatch && isLikelyName(nameMatch[1]) && !isLikelyName(profile.visitor.name)) {
    profile.visitor.name = nameMatch[1];
  }

  const companyAtMatch = factText.match(/(?:at|from|for)\s+([A-Z][A-Za-z0-9&.\- ]{2,40})(?:\.|,|\s|$)/);
  if (companyAtMatch) {
    const possible = companyAtMatch[1].trim().replace(/\s+(and|with|using)$/i, "");
    if (!["HubSpot", "Salesforce", "Pipedrive"].includes(possible)) profile.company.name ||= possible;
  }

  const companyWeAreMatch = factText.match(/\bwe(?:'re| are)\s+([A-Z][A-Za-z0-9&.\- ]{2,40})(?:\.|,|\s|$)/i);
  if (companyWeAreMatch) {
    const possible = companyWeAreMatch[1].trim().replace(/\s+(and|with|using)$/i, "");
    if (!/^(?:a|an|about|around|roughly|maybe|on|using)\b/i.test(possible) && !["HubSpot", "Salesforce", "Pipedrive"].includes(possible)) {
      profile.company.name ||= possible;
    }
  }

  const accountMatch = factText.match(/\baccount is\s+([A-Z][A-Za-z0-9&.\- ]{2,40})(?:\.|,|\s|$)/i);
  if (accountMatch) profile.company.name ||= capitalize(accountMatch[1].trim());

  if (!profile.qualification.business_need && factText.length > 12 && hasMeaningfulNeedText(lower)) {
    profile.qualification.business_need = factText.length > 260 ? `${factText.slice(0, 257)}...` : factText;
  }

  if (injectionDetected) applyInstructionInjectionGuards(profile, text);
  refreshHumanReviewFromEvidence(profile);
}

async function extractIntoProfile(conversation, message) {
  extractFromMessage(conversation.profile, message);

  if (llmExtractionMode() !== "openai") return;

  try {
    const extracted = await extractLeadFieldsWithLlm({
      currentProfile: conversation.profile,
      messages: conversation.messages,
      latestMessage: message
    });
    mergeExtractedProfile(conversation.profile, extracted);
    applyInstructionInjectionGuards(conversation.profile, message);
    track("llm_extraction_completed", { conversationId: conversation.id, mode: llmExtractionMode() });
  } catch (error) {
    const safeError = safeExtractorErrorMessage(error);
    const shouldReviewFallback = conversation.profile.meta.needs_human_review || !hasMeaningfulLeadEvidence(conversation.profile);
    conversation.profile.meta.needs_human_review = shouldReviewFallback;
    conversation.profile.meta.reasoning_summary = shouldReviewFallback
      ? `LLM extraction failed; heuristic extraction used. ${safeError}`
      : `LLM extraction failed; heuristic extraction used.`;
    track("llm_extraction_failed", { conversationId: conversation.id, error: safeError });
  }
}

function safeExtractorErrorMessage(error) {
  return String(error?.message || "Unknown extraction error.")
    .replace(/sk-(?:proj|svcacct)?-[A-Za-z0-9_-]+/g, "[redacted-api-key]")
    .replace(/Incorrect API key provided:[^.]+/i, "OpenAI API key was rejected");
}

function llmReadinessSummary() {
  const settings = llmExtractionSettings();
  const recommendations = settings.api_key_configured
    ? ["Run the extraction probe before beta traffic, then compare captured fields against the heuristic fallback."]
    : ["Set OPENAI_API_KEY to enable live structured extraction. The heuristic extractor remains active and free for demos."];
  return {
    checked_at: now(),
    status: settings.api_key_configured ? "live_ready" : "heuristic_only",
    mode: settings.mode,
    api_key_configured: settings.api_key_configured,
    live_request_available: settings.live_request_available,
    base_url: settings.base_url,
    model: settings.model,
    fallback_mode: settings.fallback_mode,
    stores_test_leads: false,
    mutates_state: false,
    recommendations
  };
}

async function runLlmExtractionProbe(body = {}) {
  const sampleMessage =
    stringFromBody(body, "message", "sampleMessage", "sample_message") ||
    "My name is Lina Vale. I am evaluating this for ReadyCo, a 160-person SaaS company using HubSpot. Demo requests are going cold because reps research manually. We want to fix demo routing this quarter and likely have $30K-$50K annually. I own the decision. lina@readyco.test";
  const startedAt = Date.now();
  const profile = emptyProfile();
  const messages = [{ sender: "visitor", body: sampleMessage, createdAt: now() }];
  extractFromMessage(profile, sampleMessage);

  const result = {
    ...llmReadinessSummary(),
    tested_at: now(),
    sample_message: sampleMessage,
    live_request_attempted: false,
    test_status: "heuristic_only",
    duration_ms: 0,
    heuristic_profile: structuredClone(profile),
    llm_profile: null,
    extracted_profile: structuredClone(profile),
    error: null
  };

  if (llmExtractionMode() !== "openai") {
    result.duration_ms = Date.now() - startedAt;
    return result;
  }

  result.live_request_attempted = true;
  try {
    const extracted = await extractLeadFieldsWithLlm({
      currentProfile: structuredClone(profile),
      messages,
      latestMessage: sampleMessage
    });
    result.llm_profile = extracted;
    result.extracted_profile = mergeExtractedProfile(profile, extracted);
    result.test_status = "passed";
  } catch (error) {
    result.test_status = "failed";
    result.error = error.message;
    result.recommendations = [
      "OpenAI live extraction failed. Keep heuristic fallback enabled and verify OPENAI_API_KEY, OPENAI_MODEL, and OPENAI_BASE_URL before beta traffic.",
      ...result.recommendations
    ];
  }
  result.duration_ms = Date.now() - startedAt;
  return result;
}

function capitalize(value) {
  return value.charAt(0).toUpperCase() + value.slice(1);
}

function displayCrm(value) {
  const key = String(value || "").toLowerCase();
  if (key === "hubspot") return "HubSpot";
  if (key === "salesforce") return "Salesforce";
  if (key === "pipedrive") return "Pipedrive";
  if (key === "zoho") return "Zoho";
  return capitalize(key);
}

function normalizeCrmValue(value) {
  const key = String(value || "").trim().toLowerCase();
  if (!key || key === "unknown" || key === "not sure") return "unknown";
  if (/hubspot/.test(key)) return "hubspot";
  if (/salesforce|force\.com/.test(key)) return "salesforce";
  if (/pipedrive/.test(key)) return "pipedrive";
  if (/zoho/.test(key)) return "other";
  return key.length <= 32 ? key.replace(/[^a-z0-9_-]/g, "_") : "other";
}

function humanizeEnum(value) {
  return String(value || "unknown").replaceAll("_", " ");
}

function isLikelyName(value) {
  if (!value) return false;
  const normalized = String(value).trim().toLowerCase();
  const blocked = new Set([
    "evaluating this",
    "looking for",
    "researching options",
    "vp sales",
    "sales",
    "the decision",
    "a consultant"
  ]);
  if (blocked.has(normalized)) return false;
  return /^[A-Z][a-z]+(?:\s+[A-Z][a-z]+)?$/.test(String(value).trim());
}

function fieldCaptured(profile, key) {
  const normalized = normalizeQuestionKey(key);
  if (normalized === "email") return Boolean(profile.visitor.email || profile.visitor.phone);
  if (normalized === "name") return Boolean(profile.visitor.name);
  if (normalized === "business_need") return Boolean(profile.qualification.business_need);
  if (normalized === "company_name_or_domain") return Boolean(profile.company.name || profile.company.domain);
  if (normalized === "authority") return profile.visitor.authority_signal !== "unknown";
  if (normalized === "timeline") return profile.qualification.timeline !== "unknown";
  if (normalized === "budget") return profile.qualification.budget_status !== "unknown" || profile.qualification.budget_range !== "unknown";
  if (normalized === "crm") return profile.qualification.crm !== "unknown";
  return true;
}

function conversationQuestionsForContext(context = {}) {
  if (context.question_flow?.length) return normalizeConversationQuestions(context.question_flow);
  if (context.conversation?.questions?.length) return normalizeConversationQuestions(context.conversation.questions);
  if (context.questions?.length) return normalizeConversationQuestions(context.questions);
  return normalizeConversationQuestions(widgetConfig.conversation.questions);
}

function requiredFieldsForContext(context = {}) {
  const explicit =
    normalizeOptionalList(context.required_fields || context.requiredFields || context.conversation?.requiredFields || context.conversation?.required_fields) ||
    normalizeOptionalList(widgetConfig.conversation.requiredFields);
  return explicit?.length ? explicit.map(normalizeQuestionKey) : requiredFieldsFromQuestions(conversationQuestionsForContext(context));
}

function requiredMissing(profile, context = {}) {
  const missing = [];
  for (const key of requiredFieldsForContext(context)) {
    if (!fieldCaptured(profile, key)) missing.push(key);
  }
  profile.meta.missing_required_fields = missing;
  if (missing.length && !hasMeaningfulLeadEvidence(profile)) {
    profile.meta.needs_human_review = true;
    profile.meta.confidence = Math.min(Number(profile.meta.confidence || 0.5), 0.2);
    profile.routing.priority_hint = "manual_review";
    profile.routing.route_type = "manual_review";
    profile.routing.recommended_next_action = "Insufficient data - hold for human review or re-engage.";
  }
  return missing;
}

function nextAssistantMessage(input) {
  const conversation = input?.profile ? input : { profile: input };
  const profile = conversation.profile;
  const missing = requiredMissing(profile, conversation);
  const questions = conversationQuestionsForContext(conversation);

  for (const question of questions) {
    if (!fieldCaptured(profile, question.key)) {
      return {
        message: question.prompt,
        quickReplies: question.quickReplies || [],
        completionStatus: question.completionStatus || "in_progress",
        questionKey: question.key
      };
    }
  }

  const configuredKeys = new Set(questions.map((question) => question.key));
  for (const key of missing.filter((item) => !configuredKeys.has(item))) {
    const fallback = normalizeConversationQuestion({ key });
    if (fallback && !fieldCaptured(profile, fallback.key)) {
      return {
        message: fallback.prompt,
        quickReplies: fallback.quickReplies || [],
        completionStatus: fallback.completionStatus || "in_progress",
        questionKey: fallback.key
      };
    }
  }

  return {
    message: `Here is what I will send over: ${summarySentence(profile)} Is that right?`,
    quickReplies: ["Yes, send it", "Edit something"],
    completionStatus: missing.length ? "in_progress" : "ready_to_complete"
  };
}

function summarySentence(profile) {
  const need = profile.qualification.business_need || "your request";
  const timeline = humanizeEnum(profile.qualification.timeline);
  const budget = humanizeEnum(profile.qualification.budget_status);
  const crm = profile.qualification.crm === "unknown" ? "CRM unknown" : `${displayCrm(profile.qualification.crm)} in the stack`;
  return `you are looking to ${need.toLowerCase()}, timeline is ${timeline}, budget status is ${budget}, and ${crm}.`;
}

function mockEnrich(profile) {
  const domain = profile.company.domain || "";
  const sizeHint = profile.company.size_hint;
  const crm = profile.qualification.crm;
  const isPlaceholder = domain === "example.com";
  const isSaas =
    /saas|software|platform|tech/i.test(
      `${profile.company.name || ""} ${profile.qualification.business_need || ""} ${profile.qualification.product_interest || ""}`
    );

  return {
    status: isPlaceholder ? "manual_review" : "completed",
    completed_at: now(),
    provider: "mock_enrichment",
    confidence: isPlaceholder ? 0.42 : 0.78,
    company_size: {
      value: sizeHint || (isSaas ? "51-250" : "unknown"),
      source: sizeHint ? "visitor" : "mock_enrichment",
      confidence: sizeHint ? 0.9 : isSaas ? 0.68 : 0.4
    },
    industry: {
      value: isSaas ? "B2B SaaS" : "unknown",
      source: "mock_enrichment",
      confidence: isSaas ? 0.72 : 0.35
    },
    tech_stack:
      crm === "unknown"
        ? []
        : [
            {
              value: displayCrm(crm),
              category: "CRM",
              source: "visitor",
              confidence: 0.95
          }
        ],
    funding_events: [],
    decision_makers: [
      {
        value: "RevOps leader",
        role: "RevOps leader",
        title: "VP Revenue Operations / Director RevOps",
        category: "buying_committee",
        source: "mock_enrichment",
        confidence: 0.45,
        reason: "Likely owner for lead routing and sales handoff quality."
      }
    ],
    buyer_profile: {
      icp_fit: {
        score: isSaas ? 72 : 42,
        segment: isSaas ? "potential_b2b_fit" : "needs_more_research",
        reasons: isSaas ? ["Conversation suggests a B2B software or sales technology context."] : []
      },
      buying_committee: [
        {
          value: "RevOps leader",
          role: "RevOps leader",
          title: "VP Revenue Operations / Director RevOps",
          category: "buying_committee",
          source: "mock_enrichment",
          confidence: 0.45,
          reason: "Likely owner for lead routing and sales handoff quality."
        }
      ],
      buying_triggers: isSaas
        ? [
            {
              value: "SaaS or sales technology context inferred from conversation",
              category: "company_context",
              source: "mock_enrichment",
              confidence: 0.55
            }
          ]
        : [],
      opening_angle: `Open by confirming who owns inbound lead routing at ${profile.company.name || profile.company.domain || "the account"} and tie the next step to the captured sales handoff pain.`
    },
    signals: isSaas
      ? [
          {
            value: "SaaS or sales technology context inferred from conversation",
            category: "company_context",
            source: "mock_enrichment",
            confidence: 0.55
          }
        ]
      : [],
    website: {
      final_url: profile.company.website || null,
      title: null,
      description: null,
      canonical: null,
      social_links: [],
      signal_links: [],
      inspected_pages: []
    },
    cost: {
      paid_provider_used: false,
      estimated_usd: 0,
      billable_requests: 0,
      internal_requests: 0,
      note: "Mock enrichment does not call a paid provider."
    }
  };
}

async function enrichProfile(profile) {
  if (internalEnrichmentMode() === "mock") return mockEnrich(profile);

  const memory = companyMemoryForProfile(profile);
  if (companyMemoryUsable(memory)) {
    return enrichmentFromCompanyMemory(profile, memory);
  }

  try {
    const enrichment = await enrichCompanyInternally(profile);
    return mergeCompanyMemoryIntoEnrichment(enrichment, profile, memory);
  } catch (error) {
    const fallback = mockEnrich(profile);
    fallback.status = "fallback";
    fallback.provider = "mock_enrichment_after_internal_error";
    fallback.notes = [`Internal enrichment failed: ${error.message}`];
    return mergeCompanyMemoryIntoEnrichment(fallback, profile, memory);
  }
}

function scoreProfile(profile, enrichment) {
  let score = 0;
  const rationale = [];
  const disqualifiers = [];

  if (profile.qualification.buying_stage === "support") {
    return {
      icp_fit: 80,
      priority: "high",
      segment: "existing_customer_or_support",
      rationale: ["Existing customer or support issue requires urgent non-sales routing"],
      disqualifiers: ["support_request"]
    };
  }

  if (profile.qualification.buying_stage === "partner") {
    return {
      icp_fit: scoringWeights.mediumThreshold,
      priority: "medium",
      segment: "partnership",
      rationale: ["Partner or reseller inquiry should route to partnerships, not direct sales"],
      disqualifiers
    };
  }

  if (profile.qualification.buying_stage === "education") {
    return {
      icp_fit: 12,
      priority: "low",
      segment: "education_or_research",
      rationale: ["Visitor appears to be researching rather than buying"],
      disqualifiers: ["student_or_research"]
    };
  }

  if (profile.company.size_hint || enrichment.company_size.confidence >= 0.65) {
    score += scoringWeights.companyFit;
    rationale.push("Company size or fit signal is available");
  }

  if (/lead|demo|routing|sales|crm|enrichment|buyer/i.test(profile.qualification.business_need || "")) {
    score += scoringWeights.painFit;
    rationale.push("Pain matches lead enrichment or sales handoff use case");
  }

  if (["this_week", "this_month", "this_quarter"].includes(profile.qualification.timeline)) {
    score += scoringWeights.urgency;
    rationale.push(`Timeline is ${humanizeEnum(profile.qualification.timeline)}`);
  } else if (profile.qualification.timeline === "later_this_year") {
    score += 8;
    rationale.push("Timeline is later this year");
  }

  if (["approved", "likely"].includes(profile.qualification.budget_status)) {
    score += scoringWeights.budget;
    rationale.push(`Budget is ${profile.qualification.budget_status}`);
  } else if (profile.qualification.budget_status === "building_case") {
    score += 7;
    rationale.push("Visitor is building the business case");
  }

  if (["decision_owner", "influencer"].includes(profile.visitor.authority_signal) && profile.qualification.budget_status !== "unknown") {
    score += scoringWeights.authority;
    rationale.push(`Authority signal is ${humanizeEnum(profile.visitor.authority_signal)}`);
  }

  if (["hubspot", "salesforce"].includes(profile.qualification.crm)) {
    score += scoringWeights.integration;
    rationale.push(`${displayCrm(profile.qualification.crm)} integration need is clear`);
  }

  if (profile.company.domain === "example.com") {
    score = Math.min(score, 35);
    disqualifiers.push("placeholder_domain");
  }

  if (
    score < scoringWeights.mediumThreshold &&
    profile.qualification.timeline === "unknown" &&
    Boolean(profile.company.name || profile.company.domain) &&
    profile.qualification.crm !== "unknown" &&
    Boolean(profile.qualification.business_need || profile.qualification.pain_point)
  ) {
    score = scoringWeights.mediumThreshold;
    rationale.push("Named account with CRM context and clear inbound pain needs sales follow-up to qualify timing");
  }

  const priority = score >= scoringWeights.highThreshold ? "high" : score >= scoringWeights.mediumThreshold ? "medium" : "low";
  return {
    icp_fit: score,
    priority,
    segment: priority === "high" ? "mid_market_b2b" : priority === "medium" ? "needs_nurture" : "low_fit",
    rationale,
    disqualifiers
  };
}

function routeLead(profile, score, betaClientId = null) {
  const routing = routingForBetaClient(betaClientId);

  if (profile.qualification.buying_stage === "support") {
    return {
      route_type: "customer_success",
      assigned_owner_email: routing.customerSuccessOwner,
      queue: routing.customerSuccessQueue,
      recommended_next_action: routing.customerSuccessAction
    };
  }

  if (profile.qualification.buying_stage === "partner") {
    return {
      route_type: "partnerships",
      assigned_owner_email: routing.mediumPriorityOwner,
      queue: "partnerships",
      recommended_next_action: "Route to partnerships for a reseller or embed conversation."
    };
  }

  if (score.priority === "high") {
    return {
      route_type: "sales",
      assigned_owner_email: routing.highPriorityOwner,
      queue: routing.highPriorityQueue,
      recommended_next_action: routing.highPriorityAction
    };
  }

  if (score.priority === "medium") {
    return {
      route_type: "sales",
      assigned_owner_email: routing.mediumPriorityOwner,
      queue: routing.mediumPriorityQueue,
      recommended_next_action: routing.mediumPriorityAction
    };
  }

  return {
    route_type: "nurture",
    assigned_owner_email: null,
    queue: routing.lowPriorityQueue,
    recommended_next_action: routing.lowPriorityAction
  };
}

function applyManualReviewLeadDisposition(lead, missing = []) {
  const missingText = missing.length ? ` Missing required fields: ${missing.join(", ")}.` : "";
  lead.status = "manual_review";
  lead.score = {
    ...(lead.score || {}),
    icp_fit: Math.min(Number(lead.score?.icp_fit || 0), 10),
    priority: "manual_review",
    segment: "manual_review",
    rationale: ["Insufficient evidence to qualify automatically.", ...(lead.score?.rationale || [])],
    disqualifiers: Array.from(new Set([...(lead.score?.disqualifiers || []), "missing_required_fields"]))
  };
  lead.routing = {
    ...(lead.routing || {}),
    route_type: "manual_review",
    assigned_owner_email: null,
    queue: "manual_review",
    recommended_next_action: `Insufficient data - hold for human review or re-engage.${missingText}`
  };
  lead.updated_at = now();
  persistSoon();
  return lead;
}

async function buildLead(conversation) {
  const profile = conversation.profile;
  track("enrichment_started", { conversationId: conversation.id, mode: internalEnrichmentMode() });
  const enrichment = await enrichProfile(profile);
  track(enrichment.status === "completed" ? "enrichment_completed" : "enrichment_failed", {
    conversationId: conversation.id,
    mode: internalEnrichmentMode(),
    provider: enrichment.provider,
    status: enrichment.status
  });
  const score = scoreProfile(profile, enrichment);
  const routing = routeLead(profile, score, conversation.source?.beta_client_id);
  const companyName = profile.company.name || profile.company.domain || "Unknown company";
  const lead = {
    id: id("lead"),
    tenant_id: widgetConfig.tenantId,
    widget_id: widgetConfig.widgetId,
    conversation_id: conversation.id,
    status: score.priority === "low" ? "low_priority" : "qualified",
    created_at: now(),
    updated_at: now(),
    source: conversation.source,
    consent: conversation.consent,
    contact: profile.visitor,
    company: {
      name: profile.company.name || companyName,
      domain: profile.company.domain,
      website: profile.company.website,
      industry: enrichment.industry.value,
      employee_range: enrichment.company_size.value,
      source: "mixed"
    },
    qualification: profile.qualification,
    enrichment,
    score,
    routing,
    crm: {
      provider: "hubspot",
      sync_status: "pending",
      contact_id: null,
      company_id: null,
      deal_id: null,
      last_error: null,
      mode: hubSpotMode()
    },
    summary: buildRepSummary(profile, enrichment, score, routing)
  };
  lead.workflow = defaultLeadWorkflow(lead);
  lead.outcome = defaultLeadOutcome(lead);
  lead.enrichment_review = ensureEnrichmentReview(lead);
  state.leads.set(lead.id, lead);
  conversation.leadId = lead.id;
  rememberCompanyFromLead(lead);
  markBetaChecklistSystem(conversation.source?.beta_client_id, "test_lead_created", `Lead profile ${lead.id} was created.`);
  track("lead_profile_created", { leadProfileId: lead.id, priority: score.priority });
  sdrDesk.ingestSignal({
    event_id: `lead-profile:${lead.id}`,
    source: "deal_threads_widget",
    signal_type: "inbound",
    summary: lead.qualification?.business_need || "Buyer completed the Deal Threads intake",
    source_lead_id: lead.id,
    account_name: lead.company?.name,
    account_domain: lead.company?.domain,
    employee_count: Number.parseInt(String(lead.company?.employee_range || "").replace(/\D/g, ""), 10) || null,
    industry: lead.company?.industry,
    contact_name: lead.contact?.name,
    contact_email: lead.contact?.email,
    contact_role: lead.contact?.role,
    icp_match: Number(lead.score?.icp_fit || 0) >= 60,
    authority: ["decision_owner", "influencer"].includes(lead.contact?.authority_signal),
    active_need: Boolean(lead.qualification?.business_need),
    timeline: lead.qualification?.timeline,
    facts: lead.score?.rationale || []
  });
  if (shouldQueueRepAlert(lead)) queueRepAlertForLead(lead, "system");
  track("crm_sync_started", { leadProfileId: lead.id, mode: hubSpotMode() });
  lead.crm = await syncLeadToHubSpot(lead);
  lead.updated_at = now();
  track(lead.crm.sync_status === "synced" ? "crm_sync_completed" : "crm_sync_failed", {
    leadProfileId: lead.id,
    status: lead.crm.sync_status,
    mode: lead.crm.mode,
    error: lead.crm.last_error
  });
  if (shouldQueueCrmDelivery(lead)) queueCrmDeliveryForLead(lead, "system");
  persistSoon();
  return lead;
}

async function createFirstBetaLaunchTestLead(client, body = {}, actor = "operator") {
  if (!client) {
    return { error: "beta_client_not_found", status: 404, message: "Beta client not found." };
  }

  const contactName = stringFromBody(body, "contactName", "name") || "Launch Test Buyer";
  const contactEmail =
    stringFromBody(body, "email", "contactEmail") ||
    `launch-test@${client.domain || normalizeDomain(client.website_url) || "example.test"}`;
  const companyName = stringFromBody(body, "companyName", "company") || client.name;
  const crm = stringFromBody(body, "crm") || client.crm || "hubspot";
  const message =
    stringFromBody(body, "message") ||
    `My name is ${contactName}. I am evaluating this for ${companyName}, a 160-person B2B SaaS company using ${displayCrm(
      crm
    )}. Demo requests are going cold because reps research manually. We want to fix this this quarter and likely have $30K-$50K annually. I own the decision. ${contactEmail}`;
  const config = betaClientEffectiveWidgetConfig(client);
  const profile = emptyProfile();
  extractFromMessage(profile, message);
  profile.visitor.name ||= contactName;
  profile.visitor.email ||= contactEmail.toLowerCase();
  profile.visitor.authority_signal = profile.visitor.authority_signal === "unknown" ? "decision_owner" : profile.visitor.authority_signal;
  profile.company.name ||= companyName;
  profile.company.domain ||= client.domain || normalizeDomain(contactEmail.split("@")[1]);
  profile.company.website ||= client.website_url || (profile.company.domain ? `https://${profile.company.domain}` : null);
  profile.company.size_hint ||= "160 employees";
  profile.qualification.crm = profile.qualification.crm === "unknown" ? crm : profile.qualification.crm;
  profile.qualification.business_need ||= "Improve demo routing and lead handoff";
  profile.qualification.timeline = profile.qualification.timeline === "unknown" ? "this_quarter" : profile.qualification.timeline;
  profile.qualification.budget_status = profile.qualification.budget_status === "unknown" ? "likely" : profile.qualification.budget_status;
  profile.qualification.budget_range = profile.qualification.budget_range === "unknown" ? "30k_60k" : profile.qualification.budget_range;

  const conversation = {
    id: id("con"),
    sessionId: null,
    source: {
      page_url: stringFromBody(body, "pageUrl", "page_url") || client.website_url || `/launch/test-install?client=${client.id}`,
      referrer: null,
      beta_client_id: client.id,
      widget_config_version: config.version,
      launch_test: true
    },
    consent: {
      accepted: true,
      accepted_at: now(),
      policy_version: config.consent.policyVersion,
      source_url: client.website_url || `/launch/test-install?client=${client.id}`,
      region: "local"
    },
    profile,
    messages: [{ sender: "visitor", body: message, createdAt: now() }],
    status: "launch_test",
    leadId: null,
    createdAt: now(),
    updatedAt: now()
  };
  state.conversations.set(conversation.id, conversation);
  const lead = await buildLead(conversation);
  track("first_beta_launch_test_lead_created", { betaClientId: client.id, leadProfileId: lead.id, actor });
  return { lead, client: betaClientDetail(state.betaClients.get(client.id), ""), status: 201 };
}

function normalizePilotTimeline(value) {
  const key = String(value || "").trim().toLowerCase();
  if (["this_week", "this_month", "this_quarter", "later_this_year", "researching", "unknown"].includes(key)) return key;
  if (/week|asap|urgent/.test(key)) return "this_week";
  if (/month/.test(key)) return "this_month";
  if (/quarter|q[1-4]/.test(key)) return "this_quarter";
  if (/year|later/.test(key)) return "later_this_year";
  if (/research|explor/.test(key)) return "researching";
  return "unknown";
}

function normalizePilotBudgetStatus(value) {
  const key = String(value || "").trim().toLowerCase();
  if (["approved", "likely", "building_case", "none", "unknown"].includes(key)) return key;
  if (/approved|allocated|set aside/.test(key)) return "approved";
  if (/likely|probably/.test(key)) return "likely";
  if (/case/.test(key)) return "building_case";
  if (/none|no budget|zero/.test(key)) return "none";
  return "unknown";
}

function normalizePilotBudgetRange(value) {
  const key = String(value || "").trim().toLowerCase();
  if (["under_10k", "10k_30k", "30k_60k", "60k_plus", "unknown"].includes(key)) return key;
  const parsed = budgetAmountRange(key);
  return parsed || "unknown";
}

function normalizePilotAuthority(value) {
  const key = String(value || "").trim().toLowerCase();
  if (["decision_owner", "influencer", "researcher", "consultant", "unknown"].includes(key)) return key;
  if (/own|decision|founder|ceo|vp/.test(key)) return "decision_owner";
  if (/influence|revops|ops|manager|leader/.test(key)) return "influencer";
  if (/consult/.test(key)) return "consultant";
  if (/research/.test(key)) return "researcher";
  return "unknown";
}

function publicPilotIntakeRequiredMissing(body = {}) {
  const required = [
    ["contactEmail", "Work email"],
    ["companyName", "Company name"],
    ["websiteUrl", "Company website"],
    ["businessNeed", "Inbound sales problem"]
  ];
  return required.filter(([key]) => !stringFromBody(body, key)).map(([, label]) => label);
}

function publicPilotIntakeSummary(body = {}) {
  const parts = [
    `My name is ${stringFromBody(body, "contactName", "name") || "the buyer"}.`,
    `I am ${stringFromBody(body, "role") || "evaluating this"} at ${stringFromBody(body, "companyName", "company") || "our company"}.`,
    `Company website: ${stringFromBody(body, "websiteUrl", "website", "domain")}.`,
    stringFromBody(body, "companySize") ? `Company size: ${stringFromBody(body, "companySize")}.` : "",
    stringFromBody(body, "crm") ? `CRM: ${stringFromBody(body, "crm")}.` : "",
    `Need: ${stringFromBody(body, "businessNeed", "message") || "improve inbound lead qualification and handoff"}.`,
    stringFromBody(body, "targetPageUrl", "target_page_url") ? `Target page: ${stringFromBody(body, "targetPageUrl", "target_page_url")}.` : "",
    `Timeline: ${humanizeEnum(normalizePilotTimeline(stringFromBody(body, "timeline")))}.`,
    `Budget: ${humanizeEnum(normalizePilotBudgetStatus(stringFromBody(body, "budgetStatus", "budget_status")))} ${humanizeEnum(
      normalizePilotBudgetRange(stringFromBody(body, "budgetRange", "budget_range"))
    )}.`,
    `Authority: ${humanizeEnum(normalizePilotAuthority(stringFromBody(body, "authority")))}.`,
    stringFromBody(body, "contactEmail", "email")
  ].filter(Boolean);
  return parts.join(" ");
}

async function createPublicPilotIntakeLead(body = {}, req = null) {
  if (!booleanFromBody(body, "consentAccepted") && !booleanFromBody(body, "consent_accepted")) {
    return {
      error: "consent_required",
      status: 400,
      message: "Accept the consent disclosure before requesting a beta pilot."
    };
  }

  const missing = publicPilotIntakeRequiredMissing(body);
  if (missing.length) {
    return {
      error: "missing_required_fields",
      status: 400,
      message: `Missing required fields: ${missing.join(", ")}.`,
      missing
    };
  }

  const contactEmail = stringFromBody(body, "contactEmail", "email").toLowerCase();
  const contactName = stringFromBody(body, "contactName", "name");
  const companyName = stringFromBody(body, "companyName", "company");
  const websiteUrl = normalizeWebsiteUrl(stringFromBody(body, "websiteUrl", "website", "domain"));
  const companyDomain = normalizeDomain(websiteUrl || contactEmail.split("@")[1]);
  const targetPageUrl = normalizeWebsiteUrl(stringFromBody(body, "targetPageUrl", "target_page_url") || websiteUrl, companyDomain);
  const crm = String(stringFromBody(body, "crm") || "hubspot").trim().toLowerCase();
  const role = stringFromBody(body, "role");
  const timeline = normalizePilotTimeline(stringFromBody(body, "timeline"));
  const budgetStatus = normalizePilotBudgetStatus(stringFromBody(body, "budgetStatus", "budget_status"));
  const budgetRange = normalizePilotBudgetRange(stringFromBody(body, "budgetRange", "budget_range"));
  const authority = normalizePilotAuthority(stringFromBody(body, "authority"));
  const businessNeed = stringFromBody(body, "businessNeed", "message");
  const reportRecipients =
    normalizeOptionalList(firstDefined(body, "reportRecipients", "report_recipients")) ||
    uniqueStrings([
      contactEmail,
      stringFromBody(body, "crmOwnerEmail", "crm_owner_email"),
      stringFromBody(body, "routingOwnerEmail", "routing_owner_email")
    ]);
  const implementationOwnerEmail = stringFromBody(body, "implementationOwnerEmail", "implementation_owner_email") || contactEmail;
  const crmOwnerEmail = stringFromBody(body, "crmOwnerEmail", "crm_owner_email") || contactEmail;
  const routingOwnerEmail = stringFromBody(body, "routingOwnerEmail", "routing_owner_email") || crmOwnerEmail;
  const nowIso = now();
  const profile = emptyProfile();
  extractFromMessage(profile, publicPilotIntakeSummary(body));
  profile.visitor.name = contactName || profile.visitor.name;
  profile.visitor.email = contactEmail;
  profile.visitor.role = role || profile.visitor.role;
  profile.visitor.authority_signal = authority === "unknown" ? profile.visitor.authority_signal : authority;
  profile.company.name = companyName || profile.company.name;
  profile.company.domain = companyDomain || profile.company.domain;
  profile.company.website = websiteUrl || profile.company.website;
  profile.company.size_hint = stringFromBody(body, "companySize", "company_size") || profile.company.size_hint;
  profile.qualification.business_need = businessNeed;
  profile.qualification.pain_point = businessNeed;
  profile.qualification.product_interest = "14-day Deal Threads beta pilot";
  profile.qualification.timeline = timeline;
  profile.qualification.budget_status = budgetStatus;
  profile.qualification.budget_range = budgetRange;
  profile.qualification.buying_stage = timeline === "researching" ? "vendor_evaluation" : "active_project";
  profile.qualification.crm = ["hubspot", "salesforce", "pipedrive", "other"].includes(crm) ? crm : "other";
  profile.qualification.integration_need = `${displayCrm(profile.qualification.crm)} handoff for beta pilot`;
  profile.qualification.pilot_target_page_url = targetPageUrl;
  profile.qualification.deal_size = stringFromBody(body, "dealSize", "deal_size");
  profile.meta.needs_human_review = false;
  profile.meta.reasoning_summary = "Created from public pilot intake with explicit consent.";

  const conversation = {
    id: id("con"),
    sessionId: null,
    source: {
      page_url: stringFromBody(body, "pageUrl", "page_url") || "/pilot-intake",
      referrer: req?.headers?.referer || req?.headers?.referrer || null,
      beta_client_id: null,
      widget_config_version: widgetConfig.version,
      pilot_intake: true
    },
    consent: {
      accepted: true,
      accepted_at: nowIso,
      policy_version: widgetConfig.consent.policyVersion,
      source_url: stringFromBody(body, "pageUrl", "page_url") || "/pilot-intake",
      region: "local"
    },
    profile,
    messages: [{ sender: "visitor", body: publicPilotIntakeSummary(body), createdAt: nowIso }],
    status: "public_pilot_intake",
    leadId: null,
    createdAt: nowIso,
    updatedAt: nowIso
  };
  state.conversations.set(conversation.id, conversation);
  const lead = await buildLead(conversation);
  const closeWorkflow = normalizeProspectCloseWorkflow(
    {
      status: "confirmed",
      target_page_url: targetPageUrl,
      implementation_owner_name: stringFromBody(body, "implementationOwnerName", "implementation_owner_name") || contactName,
      implementation_owner_email: implementationOwnerEmail,
      crm_owner_email: crmOwnerEmail,
      routing_owner_email: routingOwnerEmail,
      report_recipients: reportRecipients,
      baseline: {
        first_touch_minutes: stringFromBody(body, "baselineFirstTouchMinutes", "baseline_first_touch_minutes"),
        meeting_rate: stringFromBody(body, "baselineMeetingRate", "baseline_meeting_rate"),
        opportunity_rate: stringFromBody(body, "baselineOpportunityRate", "baseline_opportunity_rate"),
        win_rate: stringFromBody(body, "baselineWinRate", "baseline_win_rate"),
        sales_cycle_days: stringFromBody(body, "baselineSalesCycleDays", "baseline_sales_cycle_days"),
        notes: stringFromBody(body, "baselineNotes", "baseline_notes")
      },
      buyer_confirmed_at: nowIso,
      buyer_confirmed_by: "public_pilot_intake",
      notes: stringFromBody(body, "notes", "note") || `Public pilot intake submitted from ${companyName}.`,
      updated_at: nowIso
    },
    lead
  );
  if (!prospectCloseConfirmationComplete(closeWorkflow)) {
    closeWorkflow.status = "collecting_details";
    closeWorkflow.buyer_confirmed_at = null;
    closeWorkflow.buyer_confirmed_by = null;
  }
  lead.beta_client_conversion = {
    ...(lead.beta_client_conversion || {}),
    prospect_close: closeWorkflow
  };
  lead.updated_at = now();
  state.leads.set(lead.id, lead);
  track("public_pilot_intake_created", { leadProfileId: lead.id, company: companyName, domain: companyDomain, priority: lead.score?.priority });
  persistSoon();

  return {
    status: 201,
    lead,
    close_workflow: closeWorkflow,
    activation_prospect: isRealBetaActivationProspect(lead) ? realBetaActivationProspectItem(lead) : null
  };
}

function buildRepSummary(profile, enrichment, score, routing) {
  const contactName = profile.visitor.name || "Unknown visitor";
  const companyName = profile.company.name || profile.company.domain || "unknown company";
  const buyerProfile = normalizeBuyerProfile(enrichment.buyer_profile, enrichment);
  const repSummary = `${contactName} from ${companyName} shared this need: "${
    profile.qualification.business_need || "Sales follow-up requested"
  }" Timeline is ${humanizeEnum(profile.qualification.timeline)}, budget is ${humanizeEnum(
    profile.qualification.budget_status
  )}, and priority is ${score.priority} (${score.icp_fit}/100). ${routing.recommended_next_action}`;

  return {
    rep_summary: repSummary,
    visitor_facts: [
      profile.qualification.business_need,
      profile.qualification.timeline !== "unknown" ? `Timeline: ${profile.qualification.timeline}` : null,
      profile.qualification.crm !== "unknown" ? `CRM: ${displayCrm(profile.qualification.crm)}` : null,
      profile.visitor.authority_signal !== "unknown" ? `Authority: ${profile.visitor.authority_signal}` : null
    ].filter(Boolean),
    enriched_facts: [
      enrichment.company_size.value !== "unknown" ? `Company size: ${enrichment.company_size.value}` : null,
      enrichment.industry.value !== "unknown" ? `Industry: ${enrichment.industry.value}` : null,
      buyerProfile.icp_fit.score ? `ICP fit: ${buyerProfile.icp_fit.score}/100 (${humanizeEnum(buyerProfile.icp_fit.segment)})` : null,
      buyerProfile.buying_committee.length
        ? `Likely buying committee: ${buyerProfile.buying_committee.map((item) => item.title || item.role || item.value).join(", ")}`
        : null,
      buyerProfile.buying_triggers.length
        ? `Buying triggers: ${buyerProfile.buying_triggers.map((item) => item.value).join(", ")}`
        : null,
      enrichment.funding_events?.length
        ? `Funding/growth signals: ${enrichment.funding_events.map((item) => item.round || item.value).join(", ")}`
        : null,
      enrichment.tech_stack.length ? `Tech stack: ${enrichment.tech_stack.map((item) => item.value).join(", ")}` : null,
      enrichment.signals?.length ? `Self-built signals: ${enrichment.signals.map((item) => item.value).join(", ")}` : null,
      enrichment.website?.title ? `Website title: ${enrichment.website.title}` : null,
      enrichment.website?.description ? `Website description: ${enrichment.website.description}` : null
    ].filter(Boolean),
    watchouts: [
      enrichment.confidence < 0.7 ? "Enrichment confidence is low or requires review" : null,
      score.disqualifiers.length ? `Disqualifiers: ${score.disqualifiers.join(", ")}` : null,
      ...(enrichment.notes || [])
    ].filter(Boolean)
  };
}

function buildRepReadyBrief(lead, baseUrl = "") {
  const workflow = ensureLeadWorkflow(lead);
  const outcome = ensureLeadOutcome(lead);
  const buyerProfile = normalizeBuyerProfile(lead.enrichment?.buyer_profile, lead.enrichment || {});
  const betaClient = lead.source?.beta_client_id ? state.betaClients.get(lead.source.beta_client_id) : null;
  const profileUrl = baseUrl ? `${baseUrl.replace(/\/$/, "")}/crm/${lead.id}` : `/crm/${lead.id}`;
  const reportUrl = betaClient ? `${baseUrl.replace(/\/$/, "") || ""}/beta-clients/${betaClient.id}/report?days=14` : null;
  const evidence = normalizeResearchEvidenceList(lead.enrichment?.research_evidence).slice(0, 6);
  const triggers = (buyerProfile.buying_triggers || []).slice(0, 6);
  const committee = (buyerProfile.buying_committee || []).slice(0, 6);
  const techStack = (lead.enrichment?.tech_stack || []).map((item) => item.value).filter(Boolean).slice(0, 8);
  const selfBuiltSignals = (lead.enrichment?.signals || []).map((item) => item.value).filter(Boolean).slice(0, 8);
  const need = lead.qualification?.business_need || "Sales follow-up requested";
  const timeline = humanizeEnum(lead.qualification?.timeline || "unknown");
  const budget = humanizeEnum(lead.qualification?.budget_status || "unknown");
  const crm = displayCrm(lead.qualification?.crm || lead.crm?.provider || "unknown");
  const companyName = lead.company?.name || lead.company?.domain || "Unknown company";
  const contactName = lead.contact?.name || "Unknown visitor";
  // Send-ready copy must never contain a placeholder name/company — use neutral fallbacks for outbound.
  const hasContactName = Boolean(lead.contact?.name);
  const greetingName = lead.contact?.name || "there";
  const companyLabel = (lead.company?.name && lead.company.name !== "Unknown company" ? lead.company.name : lead.company?.domain) || "your team";
  const firstQuestion = `Confirm ${hasContactName ? `${contactName}'s` : "the visitor's"} top priority: ${need}`;
  const qualityFlags = [
    lead.enrichment?.confidence < 0.7 ? "Enrichment confidence is below 70%; verify firmographic details before quoting them." : null,
    isPersonalEmail(lead.contact?.email) ? "Visitor used a personal email; confirm work email and company domain." : null,
    !lead.company?.domain ? "Company domain is missing; ask for website or work email on the first touch." : null,
    !hasContactName ? "No contact name captured; personalize the opener before sending outbound copy." : null,
    lead.score?.disqualifiers?.length ? `Disqualifiers: ${lead.score.disqualifiers.join(", ")}` : null,
    workflowSlaStatus(lead) === "overdue" ? "SLA is overdue; prioritize this before more beta traffic." : null
  ].filter(Boolean);
  const callPlan = [
    firstQuestion,
    buyerProfile.opening_angle || `Open by tying ${companyName}'s stated need to ${timeline} timing and confirm who owns the decision.`,
    `Validate urgency: timeline is ${timeline}, budget is ${budget}, CRM is ${crm}.`,
    workflow.next_action || lead.routing?.recommended_next_action || "Agree on the next step and log the outcome."
  ];
  const routeType = lead.routing?.route_type || "sales";
  const discoveryByRoute = {
    support: [
      "When did this start, and is it blocking lead delivery right now?",
      "Which leads or pages are affected, and is there a workaround in place?",
      "Who on your side owns the widget install and CRM connection?"
    ],
    customer_success: [
      "What outcome were you expecting that you're not seeing yet?",
      "Which part of the workflow is causing the most friction today?",
      "Who should be in the loop to get this resolved and adopted?"
    ],
    partnerships: [
      "Which of your clients would this serve, and roughly how many?",
      "Do you resell, refer, or embed today — and through what commercials?",
      "Who owns partnership decisions and technical integration on your side?"
    ],
    nurture: [
      "What would need to be true for this to become a priority?",
      "What are you using today, and where's the gap?",
      "When might you revisit this, and what should we send in the meantime?"
    ],
    sales: [
      "What happens if this isn't fixed this quarter?",
      "Who owns the inbound routing, CRM fields, and SLA acceptance criteria?",
      "Which fields must be in the CRM before a rep accepts the lead?",
      "What would make this pilot worth expanding after the first report?"
    ]
  };
  const discoveryQuestions = [
    `What's driving "${need}" right now, and what have you tried?`,
    ...(discoveryByRoute[routeType] || discoveryByRoute.sales)
  ];
  const copyBlocks = {
    email_opener: `Hi ${greetingName}, saw your note about ${need}. I pulled together the context upfront so we can skip the blank intake call and focus on whether ${companyLabel} can improve ${timeline} lead follow-up.`,
    voicemail_opener: `Hi ${greetingName}, this is the team following up on your ${companyLabel} request about ${need}. I have the budget, timing, and CRM context in front of me and wanted to confirm the right next step.`,
    internal_note: `${lead.score?.priority || "unknown"} priority lead. ${lead.summary?.rep_summary || ""} Next action: ${workflow.next_action || lead.routing?.recommended_next_action || "Review profile."}`
  };

  return {
    version: "deal_threads.rep_ready_brief.v1",
    generated_at: now(),
    lead_id: lead.id,
    profile_url: profileUrl,
    beta_client: betaClient
      ? {
          id: betaClient.id,
          name: betaClient.name,
          domain: betaClient.domain,
          report_url: reportUrl
        }
      : null,
    headline: `${humanizeEnum(lead.score?.priority || "lead")} priority: ${companyName} - ${need}`,
    executive_summary: lead.summary?.rep_summary || `${contactName} from ${companyName} requested follow-up.`,
    priority: {
      score: lead.score?.icp_fit || 0,
      level: lead.score?.priority || "unknown",
      queue: lead.routing?.queue || "unassigned",
      rationale: lead.score?.rationale || []
    },
    owner: {
      email: workflow.owner_email || lead.routing?.assigned_owner_email || null,
      sla_due_at: workflow.due_at,
      sla_status: workflowSlaStatus(lead),
      next_action: workflow.next_action || lead.routing?.recommended_next_action || ""
    },
    contact: lead.contact,
    company: lead.company,
    qualification: {
      business_need: need,
      timeline: lead.qualification?.timeline || "unknown",
      timeline_label: timeline,
      budget_status: lead.qualification?.budget_status || "unknown",
      budget_label: budget,
      budget_range: lead.qualification?.budget_range || "unknown",
      crm: lead.qualification?.crm || "unknown",
      crm_label: crm,
      authority_signal: lead.contact?.authority_signal || lead.qualification?.authority || "unknown"
    },
    buyer_profile: {
      icp_fit: buyerProfile.icp_fit,
      opening_angle: buyerProfile.opening_angle,
      buying_committee: committee,
      buying_triggers: triggers
    },
    evidence: {
      enrichment_status: lead.enrichment?.status || "unknown",
      provider: lead.enrichment?.provider || "unknown",
      confidence: Number(lead.enrichment?.confidence || 0),
      paid_provider_used: Boolean(lead.enrichment?.cost?.paid_provider_used),
      company_size: lead.enrichment?.company_size || null,
      industry: lead.enrichment?.industry || null,
      tech_stack: techStack,
      self_built_signals: selfBuiltSignals,
      research_evidence: evidence
    },
    outcome: {
      status: outcome.status,
      value: Number(outcome.value || 0),
      probability: Number(outcome.probability || 0),
      expected_value: Number((Number(outcome.value || 0) * Number(outcome.probability || 0)).toFixed(2)),
      first_contacted_at: outcome.first_contacted_at,
      meeting_booked_at: outcome.meeting_booked_at,
      opportunity_created_at: outcome.opportunity_created_at,
      closed_at: outcome.closed_at
    },
    call_plan: callPlan,
    discovery_questions: discoveryQuestions,
    quality_flags: qualityFlags,
    copy_blocks: copyBlocks,
    links: {
      profile: profileUrl,
      hubspot_preview: `${baseUrl.replace(/\/$/, "") || ""}/api/v1/leads/${lead.id}/hubspot-preview`,
      rep_alert: `${baseUrl.replace(/\/$/, "") || ""}/api/v1/leads/${lead.id}/rep-alert/send`,
      crm_delivery: `${baseUrl.replace(/\/$/, "") || ""}/api/v1/leads/${lead.id}/crm-delivery/send`,
      client_report: reportUrl
    }
  };
}

function repReadyBriefMarkdown(brief) {
  const committee = brief.buyer_profile.buying_committee.length
    ? brief.buyer_profile.buying_committee.map((item) => `- ${item.title || item.role || item.value}: ${item.reason || item.source || "Likely stakeholder"}`)
    : ["- No likely buying committee captured yet."];
  const triggers = brief.buyer_profile.buying_triggers.length
    ? brief.buyer_profile.buying_triggers.map((item) => `- ${item.value}`)
    : ["- No buying triggers captured yet."];
  const evidence = brief.evidence.research_evidence.length
    ? brief.evidence.research_evidence.map((item) => `- ${item.label}: ${item.value}${item.source_url ? ` (${item.source_url})` : ""}`)
    : ["- No sourced research evidence saved yet."];
  const flags = brief.quality_flags.length ? brief.quality_flags.map((item) => `- ${item}`) : ["- No quality flags open."];

  const lines = [
    `# Rep-Ready Lead Brief - ${brief.company.name || brief.company.domain || brief.lead_id}`,
    "",
    `Generated: ${formatDateTime(brief.generated_at)}`,
    `Profile: ${brief.profile_url}`,
    "",
    "## Executive Summary",
    "",
    brief.executive_summary,
    "",
    "## Priority And Owner",
    "",
    `- Priority: ${brief.priority.level} (${brief.priority.score}/100)`,
    `- Queue: ${brief.priority.queue}`,
    `- Owner: ${brief.owner.email || "Unassigned"}`,
    `- SLA: ${humanizeEnum(brief.owner.sla_status)} due ${formatDateTime(brief.owner.sla_due_at)}`,
    `- Next action: ${brief.owner.next_action || "Review profile"}`,
    "",
    "## Contact And Company",
    "",
    `- Contact: ${brief.contact.name || "Unknown"} <${brief.contact.email || "no email"}>`,
    `- Role: ${brief.contact.role || "unknown"}`,
    `- Company: ${brief.company.name || "Unknown"}${brief.company.domain ? ` (${brief.company.domain})` : ""}`,
    `- Company size: ${brief.evidence.company_size?.value || brief.company.employee_range || "unknown"}`,
    `- Industry: ${brief.evidence.industry?.value || brief.company.industry || "unknown"}`,
    `- CRM: ${brief.qualification.crm_label}`,
    "",
    "## Why They Came In",
    "",
    `- Need: ${brief.qualification.business_need}`,
    `- Timeline: ${brief.qualification.timeline_label}`,
    `- Budget: ${brief.qualification.budget_label} (${humanizeEnum(brief.qualification.budget_range)})`,
    `- Authority: ${humanizeEnum(brief.qualification.authority_signal)}`,
    "",
    "## Opening Angle",
    "",
    brief.buyer_profile.opening_angle || brief.call_plan[1],
    "",
    "## Call Plan",
    "",
    ...brief.call_plan.map((item, index) => `${index + 1}. ${item}`),
    "",
    "## Discovery Questions",
    "",
    ...brief.discovery_questions.map((item) => `- ${item}`),
    "",
    "## Buying Committee",
    "",
    ...committee,
    "",
    "## Buying Triggers",
    "",
    ...triggers,
    "",
    "## Evidence",
    "",
    `- Enrichment: ${brief.evidence.provider}, ${Math.round(brief.evidence.confidence * 100)}% confidence`,
    `- Paid provider used: ${brief.evidence.paid_provider_used ? "yes" : "no"}`,
    ...(brief.evidence.tech_stack.length ? [`- Tech stack: ${brief.evidence.tech_stack.join(", ")}`] : []),
    ...(brief.evidence.self_built_signals.length ? [`- Self-built signals: ${brief.evidence.self_built_signals.join(", ")}`] : []),
    ...evidence,
    "",
    "## Quality Flags",
    "",
    ...flags,
    "",
    "## Copy Blocks",
    "",
    `Email opener: ${brief.copy_blocks.email_opener}`,
    "",
    `Voicemail opener: ${brief.copy_blocks.voicemail_opener}`,
    "",
    `Internal note: ${brief.copy_blocks.internal_note}`
  ];

  return `${lines.join("\n")}\n`;
}

function publicSafeText(value = "") {
  return String(value || "")
    .replace(/https?:\/\/[^\s)]+\/crm\/[^\s)]*/gi, "[protected CRM profile]")
    .replace(/\/crm\/[^\s)]*/gi, "[protected CRM profile]")
    .replace(/https?:\/\/[^\s)]+\/api\/v1\/[^\s)]*/gi, "[protected operator endpoint]")
    .replace(/\/api\/v1\/[^\s)]*/gi, "[protected operator endpoint]")
    .replace(/https?:\/\/[^\s)]+\/admin[^\s)]*/gi, "[protected operator page]")
    .replace(/\/admin[^\s)]*/gi, "[protected operator page]")
    .replace(/https?:\/\/[^\s)]+\/reports[^\s)]*/gi, "[protected report]")
    .replace(/\/reports[^\s)]*/gi, "[protected report]");
}

function publicSafeList(items = []) {
  return items.map((item) => publicSafeText(item)).filter(Boolean);
}

function publicSafeEvidenceItem(item = {}) {
  const sourceUrl = optionalString(item.source_url || item.url);
  let safeSourceUrl = null;
  if (sourceUrl) {
    try {
      const parsed = new URL(sourceUrl);
      const pathname = parsed.pathname || "";
      if (!/\/(crm|api\/v1|admin|reports|beta-clients|launch)(\/|$)/i.test(pathname)) {
        safeSourceUrl = parsed.toString();
      }
    } catch {
      safeSourceUrl = null;
    }
  }
  return {
    label: publicSafeText(item.label || item.source_label || item.type || "Evidence"),
    value: publicSafeText(item.value || item.summary || item.note || ""),
    confidence: item.confidence ?? null,
    source_url: safeSourceUrl
  };
}

function publicBetaLeadHandoffPacket(client, lead, baseUrl = "") {
  const brief = buildRepReadyBrief(lead, "");
  const feedbackUrl = `${betaClientPublicFeedbackUrl(client, baseUrl)}#${encodeURIComponent(lead.id)}`;
  const handoffUrl = publicBetaLeadHandoffUrl(client, lead, baseUrl);
  const statusUrl = betaClientPublicInstallStatusUrl(client, baseUrl);
  const qualityFlags = publicSafeList(brief.quality_flags);
  const evidenceItems = brief.evidence.research_evidence.map(publicSafeEvidenceItem).filter((item) => item.value || item.source_url);
  const nextActions = [
    brief.owner.next_action || "Review the buyer context and confirm the first-touch plan.",
    "Use the email or voicemail opener before asking the prospect to repeat details they already gave.",
    "After the first touch, score this packet in the feedback room so the beta can improve without paid enrichment."
  ];

  return {
    version: "deal_threads.public_rep_handoff.v1",
    generated_at: now(),
    public_reference: lead.id.replace(/^lead_/, "profile_"),
    client: {
      name: client.name,
      domain: client.domain,
      crm: displayCrm(client.crm || "unknown")
    },
    contact: {
      name: publicSafeText(brief.contact.name || "Unknown"),
      email: publicSafeText(brief.contact.email || "No email captured"),
      role: publicSafeText(brief.contact.role || "Unknown"),
      authority_signal: publicSafeText(humanizeEnum(brief.qualification.authority_signal))
    },
    company: {
      name: publicSafeText(brief.company.name || "Unknown"),
      domain: publicSafeText(brief.company.domain || normalizeDomain(brief.company.website || brief.contact.email || "") || "Unknown"),
      size: publicSafeText(brief.evidence.company_size?.value || brief.company.employee_range || "Unknown"),
      industry: publicSafeText(brief.evidence.industry?.value || brief.company.industry || "Unknown")
    },
    summary: {
      headline: publicSafeText(brief.headline),
      executive_summary: publicSafeText(brief.executive_summary),
      opening_angle: publicSafeText(brief.buyer_profile.opening_angle || brief.call_plan[1] || "")
    },
    priority: {
      level: brief.priority.level,
      score: brief.priority.score,
      queue: publicSafeText(brief.priority.queue),
      owner_email: publicSafeText(brief.owner.email || "Unassigned"),
      sla_status: brief.owner.sla_status,
      sla_due_at: brief.owner.sla_due_at
    },
    qualification: {
      business_need: publicSafeText(brief.qualification.business_need),
      timeline: publicSafeText(brief.qualification.timeline_label),
      budget: publicSafeText(`${brief.qualification.budget_label} / ${humanizeEnum(brief.qualification.budget_range)}`),
      crm: publicSafeText(brief.qualification.crm_label)
    },
    call_plan: publicSafeList(brief.call_plan),
    discovery_questions: publicSafeList(brief.discovery_questions),
    quality_flags: qualityFlags,
    copy_blocks: {
      email_opener: publicSafeText(brief.copy_blocks.email_opener),
      voicemail_opener: publicSafeText(brief.copy_blocks.voicemail_opener),
      internal_note: publicSafeText(brief.copy_blocks.internal_note)
    },
    evidence: {
      enrichment_status: publicSafeText(brief.evidence.enrichment_status),
      provider: publicSafeText(brief.evidence.provider),
      confidence: brief.evidence.confidence,
      paid_provider_used: brief.evidence.paid_provider_used,
      tech_stack: publicSafeList(brief.evidence.tech_stack),
      self_built_signals: publicSafeList(brief.evidence.self_built_signals),
      research_evidence: evidenceItems
    },
    next_actions: publicSafeList(nextActions),
    links: {
      handoff_page: handoffUrl,
      markdown: `${handoffUrl}?format=markdown`,
      feedback_room: feedbackUrl,
      public_install_status: statusUrl
    },
    public_safety: {
      exposes_protected_crm_profiles: false,
      exposes_operator_actions: false,
      exposes_reports_or_exports: false,
      triggers_live_crm_sync: false,
      paid_provider_used: brief.evidence.paid_provider_used
    }
  };
}

