function publicBetaCrmExportPacket(client, baseUrl = "") {
  const rows = publicBetaCrmExportRows(client, baseUrl);
  const highPriority = rows.filter((row) => row.priority === "high").length;
  const reviewed = rows.filter((row) => row.rep_feedback_status && row.rep_feedback_status !== "not_reviewed").length;
  return {
    type: "deal_threads.manual_crm_export",
    version: "deal_threads.public_crm_export.v1",
    generated_at: now(),
    client: {
      name: client.name,
      domain: client.domain,
      crm: displayCrm(client.crm || "unknown")
    },
    summary: {
      buyer_profiles: rows.length,
      high_priority: highPriority,
      reviewed_profiles: reviewed,
      paid_provider_used: rows.some((row) => row.paid_provider_used),
      recommended_use: "Import this CSV into the beta client's CRM or copy individual public handoff packets into CRM notes before native sync is connected."
    },
    links: {
      csv: betaClientPublicCrmExportUrl(client, baseUrl, "csv"),
      markdown: betaClientPublicCrmExportUrl(client, baseUrl, "markdown"),
      json: betaClientPublicCrmExportUrl(client, baseUrl, "json"),
      feedback_room: betaClientPublicFeedbackUrl(client, baseUrl),
      public_install_status: betaClientPublicInstallStatusUrl(client, baseUrl)
    },
    rows,
    public_safety: {
      exposes_protected_crm_profiles: false,
      exposes_operator_actions: false,
      exposes_reports_or_exports: false,
      triggers_live_crm_sync: false,
      paid_provider_used: rows.some((row) => row.paid_provider_used)
    }
  };
}

function publicBetaCrmExportMarkdown(packet) {
  const profileRows = packet.rows.length
    ? packet.rows.flatMap((row) => [
        `### ${row.company_name || row.company_domain || row.public_reference}`,
        "",
        `- Contact: ${row.contact_name || "Unknown"}${row.contact_email ? ` <${row.contact_email}>` : ""}`,
        `- Priority: ${row.priority} (${row.icp_score}/100)`,
        `- Need: ${row.business_need}`,
        `- Timeline: ${row.timeline}`,
        `- Budget: ${row.budget}`,
        `- Owner: ${row.owner_email || "Unassigned"}`,
        `- Public handoff: ${row.handoff_url}`,
        `- Markdown handoff: ${row.handoff_markdown_url}`,
        "",
        row.summary,
        ""
      ])
    : ["No beta-attributed buyer profiles have been captured yet."];
  const lines = [
    `# Manual CRM Export - ${packet.client.name}`,
    "",
    `Generated: ${formatDateTime(packet.generated_at)}`,
    "",
    "## Import Notes",
    "",
    "- Use the CSV export for HubSpot, Salesforce, Pipedrive, or a Zapier/Make table import.",
    "- Map `public_handoff_url` into a CRM note or custom URL field so reps can open the buyer-safe packet.",
    "- This packet does not trigger live CRM sync and does not include protected Deal Threads CRM pages.",
    "- Keep paid enrichment disabled unless rep feedback proves a missing field changes first-touch quality.",
    "",
    "## Summary",
    "",
    `- Buyer profiles: ${packet.summary.buyer_profiles}`,
    `- High priority: ${packet.summary.high_priority}`,
    `- Reviewed profiles: ${packet.summary.reviewed_profiles}`,
    `- Paid provider used: ${packet.summary.paid_provider_used ? "yes" : "no"}`,
    `- CSV export: ${packet.links.csv}`,
    `- JSON export: ${packet.links.json}`,
    `- Feedback room: ${packet.links.feedback_room}`,
    "",
    "## Profiles",
    "",
    ...profileRows,
    "This tokenized export does not expose protected CRM pages, operator APIs, reports, tenant exports, or live CRM controls."
  ];
  return `${lines.join("\n")}\n`;
}

function publicProofComparison(comparison = {}) {
  return {
    label: comparison.label || "",
    status: comparison.status || "unavailable",
    current: comparison.current ?? null,
    baseline: comparison.baseline ?? null,
    delta: comparison.delta ?? null,
    delta_points: comparison.delta_points ?? null,
    delta_percent: comparison.delta_percent ?? null,
    display: formatProofComparison(comparison)
  };
}

function publicBetaProofReportPacket(client, searchParams = new URLSearchParams(), baseUrl = "") {
  const period = parseReportWindow(searchParams);
  const detail = betaClientDetail(client, baseUrl);
  const scorecard = betaClientProofScorecard(detail, period);
  const installStatus = betaClientPublicInstallStatus(client, baseUrl);
  const report = buildBetaReport(new URLSearchParams({ days: String(period.days) }), { betaClientId: client.id });
  const proofUrl = betaClientPublicProofUrl(client, baseUrl, period.days);
  const reviewed = Number(scorecard.current.rep_feedback?.reviewed_profiles || 0);
  const enoughLeads = scorecard.current.total_leads >= scorecard.settings.minimum_proof_leads;
  const shareStatus =
    scorecard.proof_status === "winning" && enoughLeads && reviewed
      ? "ready_for_case_study"
      : scorecard.current.total_leads
        ? "collecting_buyer_proof"
        : "waiting_for_profile";

  return {
    type: "deal_threads.public_beta_proof_report",
    version: "deal_threads.public_beta_proof.v1",
    generated_at: now(),
    client: {
      name: detail.name,
      domain: detail.domain,
      status: detail.status,
      status_label: detail.status_label,
      crm: displayCrm(detail.crm || "unknown")
    },
    period,
    share_status: shareStatus,
    share_status_label: humanizeEnum(shareStatus),
    proof_status: scorecard.proof_status,
    proof_status_label: scorecard.proof_status_label,
    confidence: scorecard.confidence,
    decision: publicSafeText(scorecard.decision),
    summary: {
      buyer_profiles: scorecard.current.total_leads,
      high_priority: scorecard.current.high_priority,
      contacted: scorecard.current.contacted,
      meetings_booked: scorecard.current.meetings_booked,
      opportunities_created: scorecard.current.opportunities_created,
      opportunity_value: scorecard.current.opportunity_value,
      expected_value: scorecard.current.expected_value,
      average_minutes_to_first_contact: scorecard.current.average_minutes_to_first_contact,
      baseline_minutes_to_first_contact: scorecard.baseline.minutes_to_first_contact,
      first_touch_minutes_saved_per_lead: scorecard.comparisons.first_touch_speed.delta === null ? null : roundNumber(-1 * Number(scorecard.comparisons.first_touch_speed.delta), 1),
      meeting_rate: scorecard.current.meeting_rate,
      baseline_meeting_rate: scorecard.baseline.meeting_rate,
      opportunity_rate: scorecard.current.opportunity_rate,
      baseline_opportunity_rate: scorecard.baseline.opportunity_rate,
      manual_research_hours_saved: scorecard.current.estimated_manual_research_hours_saved,
      paid_provider_spend: scorecard.current.paid_provider_spend,
      paid_provider_used: Boolean(report.enrichment.paid_provider_used)
    },
    install: {
      status: installStatus.status,
      status_label: installStatus.status_label,
      config_loads: installStatus.install_activity.config_loads,
      hosted_config_loads: installStatus.install_activity.hosted_config_loads,
      client_page_config_loads: installStatus.install_activity.client_page_config_loads,
      session_starts: installStatus.install_activity.session_starts,
      source_check_status: installStatus.source_check.status,
      source_check_message: installStatus.source_check.message
    },
    rep_feedback: {
      reviewed_profiles: scorecard.current.rep_feedback.reviewed_profiles,
      helpful_profiles: scorecard.current.rep_feedback.helpful_profiles,
      missing_context_profiles: scorecard.current.rep_feedback.missing_context_profiles,
      needs_rework_profiles: scorecard.current.rep_feedback.needs_rework_profiles,
      used_on_call_profiles: scorecard.current.rep_feedback.used_on_call_profiles,
      average_usefulness_score: scorecard.current.rep_feedback.average_usefulness_score ?? null,
      top_missing_fields: scorecard.current.rep_feedback.top_missing_fields || []
    },
    enrichment: {
      mode: report.enrichment.mode,
      self_built_profiles: report.enrichment.self_built_profiles,
      buyer_profiles: report.enrichment.buyer_profiles,
      buying_committee_profiles: report.enrichment.buying_committee_profiles,
      buying_trigger_profiles: report.enrichment.buying_trigger_profiles,
      research_evidence_profiles: report.enrichment.research_evidence_profiles,
      research_evidence_count: report.enrichment.research_evidence_count,
      paid_provider_calls: report.enrichment.paid_provider_calls,
      estimated_paid_provider_spend: report.enrichment.estimated_paid_provider_spend,
      paid_provider_used: report.enrichment.paid_provider_used
    },
    comparisons: {
      first_touch_speed: publicProofComparison(scorecard.comparisons.first_touch_speed),
      meeting_rate: publicProofComparison(scorecard.comparisons.meeting_rate),
      opportunity_rate: publicProofComparison(scorecard.comparisons.opportunity_rate),
      win_rate: publicProofComparison(scorecard.comparisons.win_rate)
    },
    next_actions: publicSafeList(scorecard.next_actions),
    disclosures: [
      `This is a ${period.days}-day beta proof view for ${detail.name}.`,
      "This page is tokenized for the beta client and does not expose protected Deal Threads CRM profiles.",
      "Use this as pilot-operating proof; wait for enough real traffic and rep feedback before turning it into a public case study.",
      report.enrichment.paid_provider_used
        ? `This period includes $${report.enrichment.estimated_paid_provider_spend.toFixed(2)} in paid-provider enrichment spend.`
        : "No paid enrichment provider spend is included in this period."
    ],
    links: {
      proof_report: proofUrl,
      markdown: `${proofUrl}&format=markdown`,
      json: `${proofUrl}&format=json`,
      install_status: betaClientPublicInstallStatusUrl(client, baseUrl),
      feedback_room: betaClientPublicFeedbackUrl(client, baseUrl),
      manual_crm_export: betaClientPublicCrmExportUrl(client, baseUrl, "csv"),
      manual_crm_export_notes: betaClientPublicCrmExportUrl(client, baseUrl, "markdown")
    },
    public_safety: {
      exposes_protected_crm_profiles: false,
      exposes_operator_actions: false,
      exposes_reports_or_exports: false,
      triggers_live_crm_sync: false,
      includes_lead_ids: false,
      paid_provider_used: Boolean(report.enrichment.paid_provider_used)
    }
  };
}

function publicBetaProofReportMarkdown(packet) {
  const missingRows = packet.rep_feedback.top_missing_fields.length
    ? packet.rep_feedback.top_missing_fields.map((item) => `- ${item.value}: ${item.count}`)
    : ["- No missing fields reported yet."];
  const actions = packet.next_actions.length ? packet.next_actions.map((action) => `- ${action}`) : ["- No public beta proof actions are open."];
  const disclosures = packet.disclosures.map((item) => `- ${item}`);
  const lines = [
    `# Beta Proof Report - ${packet.client.name}`,
    "",
    `Generated: ${formatDateTime(packet.generated_at)}`,
    `Window: ${packet.period.days} days`,
    `Status: ${packet.proof_status_label} (${packet.confidence} confidence)`,
    "",
    "## Executive Decision",
    "",
    packet.decision,
    "",
    "## Core Metrics",
    "",
    `- Buyer profiles: ${packet.summary.buyer_profiles}`,
    `- High priority: ${packet.summary.high_priority}`,
    `- Average first touch: ${formatMinutes(packet.summary.average_minutes_to_first_contact)}`,
    `- Old form first touch: ${formatMinutes(packet.summary.baseline_minutes_to_first_contact)}`,
    `- First-touch minutes saved per lead: ${packet.summary.first_touch_minutes_saved_per_lead ?? "not measured"}`,
    `- Meetings booked: ${packet.summary.meetings_booked}`,
    `- Opportunities created: ${packet.summary.opportunities_created}`,
    `- Pipeline value: $${Number(packet.summary.opportunity_value || 0).toFixed(2)}`,
    `- Manual research saved: ${packet.summary.manual_research_hours_saved}h`,
    `- Paid provider spend: $${Number(packet.summary.paid_provider_spend || 0).toFixed(2)}`,
    `- Client-domain config loads: ${packet.install.client_page_config_loads}`,
    `- Hosted/test config loads: ${packet.install.hosted_config_loads}`,
    "",
    "## Rep Feedback",
    "",
    `- Reviewed profiles: ${packet.rep_feedback.reviewed_profiles}`,
    `- Helpful profiles: ${packet.rep_feedback.helpful_profiles}`,
    `- Used on call: ${packet.rep_feedback.used_on_call_profiles}`,
    `- Average usefulness: ${packet.rep_feedback.average_usefulness_score ?? "-"}/5`,
    "",
    "## Missing Context",
    "",
    ...missingRows,
    "",
    "## Comparisons",
    "",
    `- First-touch speed: ${packet.comparisons.first_touch_speed.display}`,
    `- Meeting rate: ${packet.comparisons.meeting_rate.display}`,
    `- Opportunity rate: ${packet.comparisons.opportunity_rate.display}`,
    "",
    "## Next Actions",
    "",
    ...actions,
    "",
    "## Public Links",
    "",
    `- Install status: ${packet.links.install_status}`,
    `- Feedback room: ${packet.links.feedback_room}`,
    `- Manual CRM export: ${packet.links.manual_crm_export}`,
    "",
    "## Disclosures",
    "",
    ...disclosures,
    "",
    "This tokenized report does not expose protected CRM pages, operator APIs, tenant exports, or live CRM controls."
  ];
  return `${lines.join("\n")}\n`;
}

