function renderPilotAgreementPage(baseUrl = "") {
  const packet = pilotAgreementPacket(baseUrl);
  const readiness = midMarketReadinessSummary(baseUrl, new URLSearchParams([["days", "14"]]));
  const trust = buyerTrustPacket(baseUrl, new URLSearchParams([["days", "14"]]));
  const hardening = productionHardeningSummary();
  const offer = packet.offer;
  const termsRows = [
    ["Setup", `$${offer.setup_fee_usd}`, "Implementation, domain allowlist, widget configuration, launch packet, test lead, and proof setup."],
    ["Managed pilot", `$${offer.managed_pilot_monthly_usd}/month`, "Widget, providerless enrichment workflow, routing, weekly proof packet, and conversation tuning."],
    ["Premium expansion", `$${offer.premium_expansion_monthly_usd}/month`, "ICP campaigns and monthly intelligence reports after the first proof packet validates the motion."],
    ["Pilot window", `${offer.pilot_window_days} days`, "A narrow evaluation window before continuation or expansion."]
  ]
    .map(
      ([label, value, detail]) =>
        `<div class="term"><span>${escapeHtml(label)}</span><b>${escapeHtml(value)}</b><small>${escapeHtml(detail)}</small></div>`
    )
    .join("");
  const list = (items) => items.map((item) => `<li>${escapeHtml(item)}</li>`).join("");
  const commercialReview = packet.commercial_review_checklist;
  const commercialReviewRows = [
    `Status: ${commercialReview.status_label}`,
    `Captures signature on public page: ${commercialReview.captures_signature_on_public_page ? "yes" : "no"}`,
    `Collects payment on public page: ${commercialReview.collects_payment_on_public_page ? "yes" : "no"}`,
    `Public links only: ${commercialReview.public_links_only ? "yes" : "no"}`,
    `Requires buyer owner confirmation: ${commercialReview.requires_buyer_owner_confirmation ? "yes" : "no"}`,
    `Requires tokenized acceptance or order: ${commercialReview.requires_tokenized_acceptance_or_order ? "yes" : "no"}`,
    `Requires market gate before live claims: ${commercialReview.requires_market_gate_before_live_claims ? "yes" : "no"}`,
    `Required public links: ${commercialReview.required_public_links.join(", ")}`,
    ...commercialReview.required_steps
  ];
  const agreementAudit = packet.agreement_claim_audit;
  const agreementAuditRows = [
    `Claim scope: ${agreementAudit.status_label}`,
    `Binding acceptance surface: ${agreementAudit.safety.binding_acceptance_surface ? "yes" : "no"}`,
    `Captures signature: ${agreementAudit.safety.captures_signature ? "yes" : "no"}`,
    `Collects payment: ${agreementAudit.safety.collects_payment ? "yes" : "no"}`,
    `Charges buyer: ${agreementAudit.safety.charges_buyer ? "yes" : "no"}`,
    `Creates beta client: ${agreementAudit.safety.creates_beta_client ? "yes" : "no"}`,
    `Mutates buyer state: ${agreementAudit.safety.mutates_buyer_state ? "yes" : "no"}`,
    `Transmits external data: ${agreementAudit.safety.transmits_external_data ? "yes" : "no"}`,
    `Sends email: ${agreementAudit.safety.sends_email ? "yes" : "no"}`,
    `Runs paid lookup: ${agreementAudit.safety.runs_paid_lookup ? "yes" : "no"}`,
    `Claims live results: ${agreementAudit.safety.claims_live_results ? "yes" : "no"}`,
    `Claims market ready: ${agreementAudit.safety.claims_market_ready ? "yes" : "no"}`,
    `Claims customer ROI: ${agreementAudit.safety.claims_customer_roi ? "yes" : "no"}`,
    `Claims guaranteed lift: ${agreementAudit.safety.claims_guaranteed_lift ? "yes" : "no"}`,
    `Requires tokenized acceptance or order: ${agreementAudit.safety.requires_tokenized_acceptance_or_order ? "yes" : "no"}`,
    `Requires market gate before live claims: ${agreementAudit.safety.requires_market_gate_before_live_claims ? "yes" : "no"}`,
    ...agreementAudit.evidence_required.map((item) => `Evidence ${item.key}: ${item.required ? "required" : "recommended"} - ${item.proof}`),
    ...agreementAudit.blocked_claims.map((item) => `Blocked claim: ${item}`)
  ];

  return `<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width, initial-scale=1">
  <title>Deal Threads pilot agreement</title>
  <style>
    * { box-sizing: border-box; }
    body { margin: 0; font-family: Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif; color: #122033; background: #f4f7f8; }
    a { color: inherit; }
    .topbar { display: flex; justify-content: space-between; align-items: center; gap: 18px; padding: 18px 28px; border-bottom: 1px solid #d9e4e9; background: rgba(244, 247, 248, .94); position: sticky; top: 0; z-index: 4; }
    .brand { display: flex; align-items: center; gap: 10px; font-weight: 800; color: #102033; text-decoration: none; }
    .mark { width: 28px; height: 28px; border-radius: 6px; background: #0f766e; color: #ffffff; display: grid; place-items: center; font-size: 13px; font-weight: 900; }
    .nav { display: flex; gap: 18px; font-size: 14px; color: #526476; }
    .nav a { text-decoration: none; }
    main { max-width: 1180px; margin: 0 auto; padding: 38px 28px 56px; }
    .hero { display: grid; grid-template-columns: minmax(0, 1fr) 360px; gap: 18px; align-items: stretch; }
    .hero-copy, .side-panel, .panel, .term { background: #ffffff; border: 1px solid #d8e3e8; border-radius: 8px; }
    .hero-copy { padding: 26px; box-shadow: 0 16px 42px rgba(16, 32, 51, .1); }
    .side-panel { padding: 20px; background: #102033; color: #ffffff; }
    .eyebrow { display: inline-flex; align-items: center; min-height: 28px; border: 1px solid #b7d8d4; border-radius: 6px; padding: 4px 10px; font-size: 12px; font-weight: 800; color: #0f766e; background: #e7f6f3; margin-bottom: 16px; }
    h1 { max-width: 760px; margin: 0; font-size: 48px; line-height: 1.03; letter-spacing: 0; color: #102033; }
    h2 { margin: 0 0 10px; font-size: 20px; letter-spacing: 0; }
    h3 { margin: 0 0 8px; font-size: 16px; letter-spacing: 0; }
    p { color: #526476; line-height: 1.6; margin: 12px 0 0; }
    .lede { max-width: 760px; font-size: 18px; }
    .actions { display: flex; flex-wrap: wrap; gap: 10px; margin-top: 22px; }
    .button { display: inline-flex; align-items: center; justify-content: center; min-height: 42px; padding: 0 16px; border-radius: 6px; background: #0f766e; color: #ffffff; text-decoration: none; font-size: 14px; font-weight: 800; border: 0; }
    .button.secondary { background: #ffffff; color: #102033; border: 1px solid #cbd8df; }
    .side-panel span { color: #a9bbc5; display: block; font-size: 12px; font-weight: 800; margin-top: 14px; }
    .side-panel span:first-child { margin-top: 0; }
    .side-panel b { display: block; font-size: 24px; margin-top: 4px; }
    .terms-grid { display: grid; grid-template-columns: repeat(4, minmax(0, 1fr)); gap: 12px; margin-top: 16px; }
    .term { padding: 16px; }
    .term span { display: block; color: #657684; font-size: 12px; font-weight: 800; margin-bottom: 7px; }
    .term b { display: block; font-size: 24px; }
    .term small { display: block; color: #657684; margin-top: 7px; line-height: 1.4; }
    .detail-grid { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 14px; margin-top: 16px; }
    .panel { padding: 18px; }
    .wide { grid-column: 1 / -1; }
    ul { margin: 0; padding-left: 20px; color: #3c4d5b; line-height: 1.55; }
    li { margin: 8px 0; }
    .disclosure { margin-top: 16px; border-left: 4px solid #d69e2e; background: #fffaf0; color: #70480b; padding: 14px 16px; border-radius: 6px; font-size: 13px; line-height: 1.5; }
    .footer { margin-top: 22px; color: #64748b; font-size: 13px; display: flex; flex-wrap: wrap; gap: 14px; }
    @media (max-width: 860px) {
      .topbar { align-items: flex-start; flex-direction: column; padding: 16px 18px; }
      .nav { flex-wrap: wrap; gap: 12px; }
      main { padding: 24px 18px 42px; }
      .hero, .terms-grid, .detail-grid { grid-template-columns: 1fr; }
      .wide { grid-column: auto; }
      h1 { font-size: 36px; }
    }
  </style>
</head>
<body>
  <header class="topbar">
    <a class="brand" href="/"><span class="mark">DT</span><span>Deal Threads</span></a>
    <nav class="nav" aria-label="Primary">
      <a href="/">Buyer demo</a>
      <a href="/pilot-intake">Request pilot</a>
      <a href="/pilot-close-kit">Pilot kit</a>
      <a href="/business-case">Business case</a>
      <a href="/implementation-guide">Implementation</a>
      <a href="/security">Security</a>
      <a href="/sample-profile">Sample profile</a>
    </nav>
  </header>
  <main>
    <section class="hero">
      <div class="hero-copy">
        <div class="eyebrow">14-day private beta order packet</div>
        <h1>Deal Threads pilot agreement.</h1>
        <p class="lede">A buyer-safe scope, responsibility, commercial, and success-criteria packet for mid-market B2B teams evaluating the widget before wider rollout.</p>
        <div class="actions">
          <a class="button" href="/pilot-intake">Request beta pilot</a>
          <a class="button secondary" href="/pilot-close-kit">Review close kit</a>
          <a class="button secondary" href="/business-case">Business case</a>
          <a class="button secondary" href="/implementation-guide">Implementation guide</a>
          <a class="button secondary" href="/security">Security center</a>
          <a class="button secondary" href="/sample-profile">View sample profile</a>
          <a class="button secondary" href="/api/v1/pilot-agreement?format=markdown">Markdown packet</a>
        </div>
      </div>
      <aside class="side-panel">
        <span>Status</span><b>${escapeHtml(humanizeEnum(packet.status))}</b>
        <span>Setup</span><b>$${offer.setup_fee_usd}</b>
        <span>Managed pilot</span><b>$${offer.managed_pilot_monthly_usd}/month</b>
        <span>Premium expansion</span><b>$${offer.premium_expansion_monthly_usd}/month</b>
        <span>Proof window</span><b>${offer.pilot_window_days} days</b>
      </aside>
    </section>
    <section class="terms-grid">${termsRows}</section>
    <div class="disclosure">No paid enrichment provider calls by default. CRM mutation, external email transmission, OpenAI extraction, and paid data-provider usage require explicit buyer approval before live configuration.</div>
    <section class="detail-grid">
      <article class="panel wide">
        <h2>Scope</h2>
        <ul>${list(packet.scope)}</ul>
      </article>
      <article class="panel">
        <h2>Buyer responsibilities</h2>
        <ul>${list(packet.buyer_responsibilities)}</ul>
      </article>
      <article class="panel">
        <h2>Deal Threads responsibilities</h2>
        <ul>${list(packet.deal_threads_responsibilities)}</ul>
      </article>
      <article class="panel">
        <h2>Success criteria</h2>
        <ul>${list(packet.success_criteria)}</ul>
      </article>
      <article class="panel">
        <h2>Data and security posture</h2>
        <ul>${list(packet.data_security)}</ul>
      </article>
      <article class="panel">
        <h2>Commercial terms</h2>
        <ul>${list(packet.commercial_terms)}</ul>
      </article>
      <article class="panel">
        <h2>Not included</h2>
        <ul>${list(packet.exclusions)}</ul>
      </article>
      <article class="panel">
        <h2>Commercial review checklist</h2>
        <ul>${list(commercialReviewRows)}</ul>
      </article>
      <article class="panel">
        <h2>Agreement claim audit</h2>
        <ul>${list(agreementAuditRows)}</ul>
      </article>
    </section>
    <div class="footer">
      <span>Public pilot agreement: no operator forms, no real beta profiles, no protected exports, no signature capture, and no payment collection.</span>
      <span>Hardening: ${escapeHtml(humanizeEnum(hardening.status))} · Trust: ${escapeHtml(trust.status_label)} · Readiness: ${escapeHtml(humanizeEnum(readiness.status))}</span>
    </div>
  </main>
</body>
</html>`;
}

function pilotIntakePrefillFromSearchParams(searchParams = new URLSearchParams()) {
  const pick = (...keys) => {
    for (const key of keys) {
      const value = optionalString(searchParams.get(key));
      if (value) return value;
    }
    return "";
  };
  return {
    contactName: pick("contactName", "contact", "name"),
    contactEmail: pick("contactEmail", "email", "workEmail"),
    role: pick("role", "title"),
    companyName: pick("companyName", "company", "account", "accountName"),
    websiteUrl: normalizeWebsiteUrl(pick("websiteUrl", "website", "domain", "companyDomain"), normalizeDomain(pick("domain", "companyDomain", "websiteUrl", "website"))),
    companySize: pick("companySize", "size", "employees"),
    crm: pick("crm") || "hubspot",
    targetPageUrl: pick("targetPageUrl", "targetPage", "pageUrl"),
    businessNeed: pick("businessNeed", "need", "message"),
    timeline: pick("timeline") || "this_month",
    budgetStatus: pick("budgetStatus") || "likely",
    budgetRange: pick("budgetRange") || "30k_60k",
    authority: pick("authority") || "decision_owner",
    implementationOwnerEmail: pick("implementationOwnerEmail", "implementationOwner", "webOwnerEmail"),
    routingOwnerEmail: pick("routingOwnerEmail", "crmOwnerEmail", "routingOwner", "crmOwner"),
    reportRecipients: pick("reportRecipients", "proofRecipients"),
    baselineFirstTouchMinutes: pick("baselineFirstTouchMinutes"),
    baselineMeetingRate: pick("baselineMeetingRate"),
    baselineOpportunityRate: pick("baselineOpportunityRate"),
    baselineWinRate: pick("baselineWinRate"),
    baselineSalesCycleDays: pick("baselineSalesCycleDays"),
    notes: pick("notes", "note")
  };
}

function normalizePilotIntakePrefill(prefill = {}) {
  const params = prefill instanceof URLSearchParams ? pilotIntakePrefillFromSearchParams(prefill) : prefill || {};
  return {
    contactName: optionalString(params.contactName),
    contactEmail: optionalString(params.contactEmail),
    role: optionalString(params.role),
    companyName: optionalString(params.companyName),
    websiteUrl: optionalString(params.websiteUrl),
    companySize: optionalString(params.companySize),
    crm: optionalString(params.crm) || "hubspot",
    targetPageUrl: optionalString(params.targetPageUrl),
    businessNeed: optionalString(params.businessNeed),
    timeline: optionalString(params.timeline) || "this_month",
    budgetStatus: optionalString(params.budgetStatus) || "likely",
    budgetRange: optionalString(params.budgetRange) || "30k_60k",
    authority: optionalString(params.authority) || "decision_owner",
    implementationOwnerEmail: optionalString(params.implementationOwnerEmail),
    routingOwnerEmail: optionalString(params.routingOwnerEmail || params.crmOwnerEmail),
    reportRecipients: optionalString(params.reportRecipients),
    baselineFirstTouchMinutes: optionalString(params.baselineFirstTouchMinutes),
    baselineMeetingRate: optionalString(params.baselineMeetingRate),
    baselineOpportunityRate: optionalString(params.baselineOpportunityRate),
    baselineWinRate: optionalString(params.baselineWinRate),
    baselineSalesCycleDays: optionalString(params.baselineSalesCycleDays),
    notes: optionalString(params.notes)
  };
}

function renderPublicPilotIntakePage(options = {}) {
  const submitted = Boolean(options.submitted);
  const error = optionalString(options.error);
  const prefill = normalizePilotIntakePrefill(options.prefill);
  const readiness = midMarketReadinessSummary("", new URLSearchParams([["days", "14"]]));
  const trust = buyerTrustPacket("", new URLSearchParams([["days", "14"]]));
  const statusBanner = submitted
    ? `<div class="notice success"><b>Request received.</b><span>We created a protected activation prospect for operator review. The next step is confirming the target page and sending the install handoff.</span></div>`
    : error
      ? `<div class="notice error"><b>Check the request.</b><span>${escapeHtml(error)}</span></div>`
      : "";
  return `<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width, initial-scale=1">
  <title>Request a Deal Threads beta pilot</title>
  <style>
    * { box-sizing: border-box; }
    body { margin: 0; font-family: Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif; color: #122033; background: #f4f7f8; }
    a { color: inherit; }
    .topbar { display: flex; justify-content: space-between; align-items: center; gap: 18px; padding: 18px 28px; border-bottom: 1px solid #d9e4e9; background: rgba(244, 247, 248, .94); position: sticky; top: 0; z-index: 4; }
    .brand { display: flex; align-items: center; gap: 10px; font-weight: 800; color: #102033; text-decoration: none; }
    .mark { width: 28px; height: 28px; border-radius: 6px; background: #0f766e; color: #ffffff; display: grid; place-items: center; font-size: 13px; font-weight: 900; }
    .nav { display: flex; gap: 18px; font-size: 14px; color: #526476; }
    .nav a { text-decoration: none; }
    main { max-width: 1180px; margin: 0 auto; padding: 38px 28px 56px; }
    .hero { display: grid; grid-template-columns: minmax(0, 1fr) 360px; gap: 18px; align-items: start; }
    .copy, .panel, form { background: #ffffff; border: 1px solid #d8e3e8; border-radius: 8px; }
    .copy { padding: 26px; box-shadow: 0 16px 42px rgba(16, 32, 51, .1); }
    .panel { padding: 20px; }
    .eyebrow { display: inline-flex; align-items: center; min-height: 28px; border: 1px solid #b7d8d4; border-radius: 6px; padding: 4px 10px; font-size: 12px; font-weight: 800; color: #0f766e; background: #e7f6f3; margin-bottom: 16px; }
    h1 { max-width: 720px; margin: 0; font-size: 46px; line-height: 1.04; letter-spacing: 0; color: #102033; }
    h2 { margin: 0 0 10px; font-size: 20px; letter-spacing: 0; }
    h3 { margin: 0 0 8px; font-size: 16px; letter-spacing: 0; }
    p { color: #526476; line-height: 1.6; margin: 12px 0 0; }
    .lede { font-size: 18px; }
    .actions { display: flex; flex-wrap: wrap; gap: 10px; margin-top: 22px; }
    .button, button { display: inline-flex; align-items: center; justify-content: center; min-height: 42px; padding: 0 16px; border-radius: 6px; background: #0f766e; color: #ffffff; text-decoration: none; font-size: 14px; font-weight: 800; border: 0; cursor: pointer; }
    .button.secondary { background: #ffffff; color: #102033; border: 1px solid #cbd8df; }
    .facts { display: grid; gap: 10px; margin-top: 16px; }
    .fact { display: flex; justify-content: space-between; gap: 12px; border-top: 1px solid #edf2f5; padding-top: 10px; color: #526476; }
    .fact:first-child { border-top: 0; padding-top: 0; }
    .fact b { color: #102033; }
    form { margin-top: 18px; padding: 20px; }
    .form-grid { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 14px; }
    label { display: grid; gap: 7px; color: #394b5c; font-size: 13px; font-weight: 800; }
    input, select, textarea { width: 100%; border: 1px solid #cbd8df; border-radius: 6px; padding: 10px 11px; font: inherit; color: #102033; background: #ffffff; }
    textarea { min-height: 112px; resize: vertical; }
    .wide { grid-column: 1 / -1; }
    .check { display: flex; align-items: flex-start; gap: 10px; margin-top: 14px; color: #526476; line-height: 1.5; }
    .check input { width: auto; margin-top: 4px; }
    .notice { display: grid; gap: 4px; margin-top: 18px; border-radius: 8px; padding: 14px 16px; line-height: 1.5; }
    .notice.success { background: #e7f6f3; border: 1px solid #b7d8d4; color: #0f766e; }
    .notice.error { background: #fff1f2; border: 1px solid #fecdd3; color: #9f1239; }
    .small { color: #657684; font-size: 13px; line-height: 1.5; }
    @media (max-width: 860px) {
      .topbar { align-items: flex-start; flex-direction: column; padding: 16px 18px; }
      .nav { flex-wrap: wrap; gap: 12px; }
      main { padding: 24px 18px 42px; }
      .hero, .form-grid { grid-template-columns: 1fr; }
      .wide { grid-column: auto; }
      h1 { font-size: 36px; }
    }
  </style>
</head>
<body>
  <header class="topbar">
    <a class="brand" href="/"><span class="mark">DT</span><span>Deal Threads</span></a>
    <nav class="nav" aria-label="Primary">
      <a href="/">Buyer demo</a>
      <a href="/pilot-close-kit">Pilot kit</a>
      <a href="/pilot-agreement">Pilot agreement</a>
      <a href="/business-case">Business case</a>
      <a href="/implementation-guide">Implementation</a>
      <a href="/crm-handoff-guide">CRM handoff</a>
      <a href="/procurement-packet">Procurement</a>
      <a href="/sample-profile">Sample profile</a>
      <a href="/security">Security</a>
    </nav>
  </header>
  <main>
    <section class="hero">
      <div class="copy">
        <div class="eyebrow">Private beta request</div>
        <h1>Run Deal Threads on one high-intent page.</h1>
        <p class="lede">Tell us where the old form lives, who owns the handoff, and what baseline you want to beat. The request becomes a protected activation prospect, not a public profile.</p>
        <div class="actions">
          <a class="button secondary" href="/pilot-close-kit">Review pilot offer</a>
          <a class="button secondary" href="/pilot-agreement">Pilot agreement</a>
          <a class="button secondary" href="/business-case">Business case</a>
          <a class="button secondary" href="/implementation-guide">Implementation guide</a>
          <a class="button secondary" href="/crm-handoff-guide">CRM handoff guide</a>
          <a class="button secondary" href="/procurement-packet">Procurement packet</a>
          <a class="button secondary" href="/security">Security center</a>
          <a class="button secondary" href="/sample-profile">View sample profile</a>
        </div>
        ${statusBanner}
      </div>
      <aside class="panel">
        <h2>What this starts</h2>
        <div class="facts">
          <div class="fact"><span>Setup</span><b>$500</b></div>
          <div class="fact"><span>Managed pilot</span><b>$2,500/mo</b></div>
          <div class="fact"><span>Install</span><b>1 script tag</b></div>
          <div class="fact"><span>Proof window</span><b>14 days</b></div>
          <div class="fact"><span>Paid enrichment</span><b>$0 default</b></div>
          <div class="fact"><span>Trust score</span><b>${trust.score}/100</b></div>
          <div class="fact"><span>Readiness</span><b>${readiness.score}/100</b></div>
        </div>
        <p class="small">CRM sync can stay dry-run/manual until your team approves a live handoff.</p>
      </aside>
    </section>
    <form method="POST" action="/pilot-intake">
      <h2>Pilot intake</h2>
      <div class="form-grid">
        <label>Name<input name="contactName" autocomplete="name" value="${escapeHtml(prefill.contactName)}" placeholder="Dana Vale"></label>
        <label>Work email<input name="contactEmail" type="email" autocomplete="email" required value="${escapeHtml(prefill.contactEmail)}" placeholder="dana@company.com"></label>
        <label>Role<input name="role" value="${escapeHtml(prefill.role)}" placeholder="VP Sales, RevOps, Growth"></label>
        <label>Company name<input name="companyName" required value="${escapeHtml(prefill.companyName)}" placeholder="Acme Revenue"></label>
        <label>Company website<input name="websiteUrl" required value="${escapeHtml(prefill.websiteUrl)}" placeholder="https://acme.com"></label>
        <label>Company size<input name="companySize" value="${escapeHtml(prefill.companySize)}" placeholder="180 employees"></label>
        <label>CRM<select name="crm">
          ${filterOption("hubspot", "HubSpot", prefill.crm)}
          ${filterOption("salesforce", "Salesforce", prefill.crm)}
          ${filterOption("pipedrive", "Pipedrive", prefill.crm)}
          ${filterOption("other", "Other / manual handoff", prefill.crm)}
        </select></label>
        <label>Target form/demo page<input name="targetPageUrl" value="${escapeHtml(prefill.targetPageUrl)}" placeholder="https://acme.com/demo"></label>
        <label class="wide">What is broken about the current form or handoff?<textarea name="businessNeed" required placeholder="Demo requests are getting stale while reps research company size, CRM fit, budget, and the buying committee.">${escapeHtml(prefill.businessNeed)}</textarea></label>
        <label>Timeline<select name="timeline">
          ${filterOption("this_month", "This month", prefill.timeline)}
          ${filterOption("this_week", "This week", prefill.timeline)}
          ${filterOption("this_quarter", "This quarter", prefill.timeline)}
          ${filterOption("later_this_year", "Later this year", prefill.timeline)}
          ${filterOption("researching", "Researching", prefill.timeline)}
        </select></label>
        <label>Budget status<select name="budgetStatus">
          ${filterOption("likely", "Budget likely", prefill.budgetStatus)}
          ${filterOption("approved", "Budget approved", prefill.budgetStatus)}
          ${filterOption("building_case", "Building the case", prefill.budgetStatus)}
          ${filterOption("unknown", "Not sure yet", prefill.budgetStatus)}
        </select></label>
        <label>Budget range<select name="budgetRange">
          ${filterOption("30k_60k", "$30K-$60K annually", prefill.budgetRange)}
          ${filterOption("10k_30k", "$10K-$30K annually", prefill.budgetRange)}
          ${filterOption("60k_plus", "$60K+ annually", prefill.budgetRange)}
          ${filterOption("unknown", "Not sure yet", prefill.budgetRange)}
        </select></label>
        <label>Buying role<select name="authority">
          ${filterOption("decision_owner", "I own the decision", prefill.authority)}
          ${filterOption("influencer", "I influence the decision", prefill.authority)}
          ${filterOption("consultant", "I am advising the team", prefill.authority)}
          ${filterOption("researcher", "Researching for the team", prefill.authority)}
        </select></label>
        <label>Implementation owner email<input name="implementationOwnerEmail" type="email" value="${escapeHtml(prefill.implementationOwnerEmail)}" placeholder="web@company.com"></label>
        <label>CRM/routing owner email<input name="routingOwnerEmail" type="email" value="${escapeHtml(prefill.routingOwnerEmail)}" placeholder="ae@company.com"></label>
        <label>Report recipients<input name="reportRecipients" value="${escapeHtml(prefill.reportRecipients)}" placeholder="revops@company.com, sales@company.com"></label>
        <label>Baseline first-touch minutes<input name="baselineFirstTouchMinutes" type="number" min="0" value="${escapeHtml(prefill.baselineFirstTouchMinutes)}" placeholder="45"></label>
        <label>Baseline meeting rate<input name="baselineMeetingRate" type="number" min="0" max="100" step="0.01" value="${escapeHtml(prefill.baselineMeetingRate)}" placeholder="18"></label>
        <label>Baseline opportunity rate<input name="baselineOpportunityRate" type="number" min="0" max="100" step="0.01" value="${escapeHtml(prefill.baselineOpportunityRate)}" placeholder="7"></label>
        <label>Baseline win rate<input name="baselineWinRate" type="number" min="0" max="100" step="0.01" value="${escapeHtml(prefill.baselineWinRate)}" placeholder="21"></label>
        <label>Baseline sales cycle days<input name="baselineSalesCycleDays" type="number" min="0" value="${escapeHtml(prefill.baselineSalesCycleDays)}" placeholder="47"></label>
        <label class="wide">Notes<textarea name="notes" placeholder="Anything your implementation or sales team needs us to know before the pilot.">${escapeHtml(prefill.notes)}</textarea></label>
      </div>
      <label class="check"><input name="consentAccepted" type="checkbox" required><span>I consent to Deal Threads using this information to create a protected pilot activation prospect and follow up about the beta.</span></label>
      <div class="actions"><button type="submit">Request beta pilot</button></div>
      <p class="small">Protected operator pages, CRM profiles, exports, and install actions stay behind admin authentication.</p>
    </form>
  </main>
</body>
</html>`;
}

function renderPublicSecurityPage(baseUrl = "") {
  const trust = buyerTrustPacket(baseUrl, new URLSearchParams([["days", "14"]]));
  const readiness = midMarketReadinessSummary(baseUrl, new URLSearchParams([["days", "14"]]));
  const hardening = productionHardeningSummary();
  const buildPlan = providerlessEnrichmentBuildPlan(enrichmentQualitySummary(allLeadsSorted()));
  const externalProcessors = trust.processors.filter((processor) => processor.sends_data);
  const processorRows = trust.processors
    .map(
      (processor) => `<tr>
        <td>${escapeHtml(processor.name)}</td>
        <td>${escapeHtml(humanizeEnum(processor.mode))}</td>
        <td><span class="pill ${processor.sends_data ? "warn" : "pass"}">${processor.sends_data ? "Can transmit" : "No external send"}</span></td>
        <td>${escapeHtml(processor.condition)}</td>
      </tr>`
    )
    .join("");
  const dataCategoryRows = trust.data_categories
    .map(
      (category) => `<article class="panel">
        <h3>${escapeHtml(category.name)}</h3>
        <p>${escapeHtml(category.purpose)}</p>
        <small>${escapeHtml(category.fields.join(", "))}</small>
      </article>`
    )
    .join("");
  const controlRows = trust.controls
    .filter((control) => ["access", "privacy", "data_control", "operations"].includes(control.section))
    .map(
      (control) => `<div class="status-row">
        <span><b>${escapeHtml(control.label)}</b><small>${escapeHtml(control.evidence)}</small></span>
        <span class="pill ${control.status === "pass" ? "pass" : control.status === "warning" ? "warn" : "block"}">${escapeHtml(
          humanizeEnum(control.status)
        )}</span>
      </div>`
    )
    .join("");
  const hardeningRows = hardening.checks
    .slice(0, 6)
    .map(
      (check) => `<div class="status-row">
        <span><b>${escapeHtml(check.label)}</b><small>${escapeHtml(check.evidence)}</small></span>
        <span class="pill ${check.status === "pass" ? "pass" : check.status === "warning" ? "warn" : "block"}">${escapeHtml(
          humanizeEnum(check.status)
        )}</span>
      </div>`
    )
    .join("");
  const fieldRows = (buildPlan.field_level_strategy || [])
    .slice(0, 6)
    .map(
      (field) => `<tr>
        <td>${escapeHtml(field.label)}</td>
        <td>${field.rep_missing_count}</td>
        <td>${field.coverage_percent === null ? "N/A" : `${field.coverage_percent}%`}</td>
        <td>${escapeHtml(field.decision_label)}</td>
        <td>${escapeHtml(field.paid_provider_trigger)}</td>
      </tr>`
    )
    .join("");
  const disclosureRows = [
    readiness.demo_scenario.active
      ? "Current public proof uses marked synthetic demo data until real beta traffic is captured."
      : "Current proof window is using live beta data.",
    externalProcessors.length
      ? "One or more live external processors can transmit data; buyer review should confirm scopes and contracts before production rollout."
      : "Default mode does not transmit CRM, email, HubSpot, OpenAI, or paid-enrichment data externally.",
    "Protected exports, tenant deletion, CRM profiles, beta reports, readiness dashboards, and operator controls require admin authentication."
  ]
    .map((item) => `<li>${escapeHtml(item)}</li>`)
    .join("");

  return `<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width, initial-scale=1">
  <title>Deal Threads security center</title>
  <style>
    * { box-sizing: border-box; }
    body { margin: 0; font-family: Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif; color: #102033; background: #f5f7f8; }
    a { color: inherit; }
    .topbar { display: flex; justify-content: space-between; align-items: center; gap: 18px; padding: 18px 28px; border-bottom: 1px solid #d9e4e9; background: rgba(245, 247, 248, .94); position: sticky; top: 0; z-index: 4; }
    .brand { display: flex; align-items: center; gap: 10px; font-weight: 800; color: #102033; text-decoration: none; }
    .mark { width: 28px; height: 28px; border-radius: 6px; background: #0f766e; color: #ffffff; display: grid; place-items: center; font-size: 13px; font-weight: 900; }
    .nav { display: flex; gap: 18px; font-size: 14px; color: #526476; }
    .nav a { text-decoration: none; }
    main { max-width: 1180px; margin: 0 auto; padding: 38px 28px 58px; }
    .hero { background: #ffffff; border: 1px solid #d8e3e8; border-radius: 8px; padding: 28px; box-shadow: 0 16px 42px rgba(16, 32, 51, .08); }
    .eyebrow { display: inline-flex; align-items: center; min-height: 28px; border: 1px solid #b7d8d4; border-radius: 6px; padding: 4px 10px; font-size: 12px; font-weight: 800; color: #0f766e; background: #e7f6f3; margin-bottom: 16px; }
    h1 { max-width: 780px; margin: 0; font-size: 48px; line-height: 1.04; letter-spacing: 0; }
    h2 { margin: 0 0 10px; font-size: 20px; letter-spacing: 0; }
    h3 { margin: 0 0 8px; font-size: 16px; letter-spacing: 0; }
    p { color: #526476; line-height: 1.6; margin: 12px 0 0; }
    small { display: block; color: #64748b; line-height: 1.45; }
    .lede { max-width: 780px; font-size: 18px; }
    .actions { display: flex; flex-wrap: wrap; gap: 10px; margin-top: 22px; }
    .button { display: inline-flex; align-items: center; justify-content: center; min-height: 42px; padding: 0 16px; border-radius: 6px; background: #0f766e; color: #ffffff; text-decoration: none; font-size: 14px; font-weight: 800; }
    .button.secondary { background: #ffffff; color: #102033; border: 1px solid #cbd8df; }
    .metrics-grid { display: grid; grid-template-columns: repeat(4, minmax(0, 1fr)); gap: 12px; margin-top: 16px; }
    .metric, .panel { background: #ffffff; border: 1px solid #d8e3e8; border-radius: 8px; padding: 16px; }
    .metric span { display: block; color: #657684; font-size: 12px; font-weight: 800; margin-bottom: 7px; }
    .metric b { display: block; font-size: 24px; }
    .detail-grid { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 14px; margin-top: 16px; }
    .wide { grid-column: 1 / -1; }
    .data-grid { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 12px; margin-top: 14px; }
    .status-list { display: grid; gap: 10px; }
    .status-row { display: flex; justify-content: space-between; gap: 14px; border: 1px solid #d8e3e8; border-radius: 8px; background: #ffffff; padding: 14px 16px; }
    .status-row b { display: block; }
    .status-row small { margin-top: 4px; }
    .pill { display: inline-flex; align-items: center; align-self: flex-start; min-height: 24px; border-radius: 6px; padding: 2px 8px; font-size: 12px; font-weight: 800; white-space: nowrap; }
    .pill.pass { background: #e7f6f3; color: #0f766e; }
    .pill.warn { background: #fff7dd; color: #925f09; }
    .pill.block { background: #fee2e2; color: #991b1b; }
    table { width: 100%; border-collapse: collapse; font-size: 14px; }
    th, td { border-top: 1px solid #edf2f5; padding: 10px 8px; text-align: left; vertical-align: top; }
    th { color: #64748b; font-size: 12px; text-transform: uppercase; letter-spacing: .03em; }
    ul { color: #3c4d5b; line-height: 1.55; margin: 8px 0 0; padding-left: 20px; }
    li { margin: 8px 0; }
    .disclosure { margin-top: 16px; border-left: 4px solid #d69e2e; background: #fffaf0; color: #70480b; padding: 14px 16px; border-radius: 6px; font-size: 13px; line-height: 1.5; }
    .footer { margin-top: 22px; color: #64748b; font-size: 13px; display: flex; flex-wrap: wrap; gap: 14px; }
    @media (max-width: 860px) {
      .topbar { align-items: flex-start; flex-direction: column; padding: 16px 18px; }
      .nav { flex-wrap: wrap; gap: 12px; }
      main { padding: 24px 18px 42px; }
      h1 { font-size: 36px; }
      .metrics-grid, .detail-grid, .data-grid { grid-template-columns: 1fr; }
      .wide { grid-column: auto; }
    }
  </style>
</head>
<body>
  <header class="topbar">
    <a class="brand" href="/"><span class="mark">DT</span><span>Deal Threads</span></a>
    <nav class="nav" aria-label="Primary">
      <a href="/">Buyer demo</a>
      <a href="/pilot-close-kit">Pilot kit</a>
      <a href="/pilot-agreement">Pilot agreement</a>
      <a href="/business-case">Business case</a>
      <a href="/implementation-guide">Implementation</a>
      <a href="/crm-handoff-guide">CRM handoff</a>
      <a href="/sample-profile">Sample profile</a>
      <a href="/admin">Operator login</a>
    </nav>
  </header>
  <main>
    <section class="hero">
      <div class="eyebrow">Public security center</div>
      <h1>Data controls for a low-friction beta install.</h1>
      <p class="lede">Deal Threads can be evaluated with a single script tag, explicit consent, providerless enrichment by default, dry-run CRM handoff, and protected operator access for real buyer profiles.</p>
      <div class="actions">
        <a class="button" href="/pilot-close-kit">Review pilot kit</a>
        <a class="button secondary" href="/pilot-agreement">Pilot agreement</a>
        <a class="button secondary" href="/business-case">Business case</a>
          <a class="button secondary" href="/implementation-guide">Implementation guide</a>
        <a class="button secondary" href="/crm-handoff-guide">CRM handoff guide</a>
        <a class="button secondary" href="/sample-profile">View sample profile</a>
        <a class="button secondary" href="/">Try buyer intake</a>
      </div>
    </section>
    <section class="metrics-grid">
      <div class="metric"><span>Trust score</span><b>${trust.score}/100</b></div>
      <div class="metric"><span>Hardening</span><b>${hardening.score}/100</b></div>
      <div class="metric"><span>Paid lookups now</span><b>${buildPlan.paid_escalation_policy.recommended_paid_lookups_now}</b></div>
      <div class="metric"><span>External default</span><b>${externalProcessors.length ? "Review" : "Off"}</b></div>
    </section>
    <div class="disclosure"><ul>${disclosureRows}</ul></div>
    <section class="detail-grid">
      <article class="panel wide">
        <h2>What data is used</h2>
        <div class="data-grid">${dataCategoryRows}</div>
      </article>
      <article class="panel wide">
        <h2>Processor posture</h2>
        <table><thead><tr><th>Processor</th><th>Mode</th><th>Default send</th><th>Condition</th></tr></thead><tbody>${processorRows}</tbody></table>
      </article>
      <article class="panel">
        <h2>Access and privacy controls</h2>
        <div class="status-list">${controlRows}</div>
      </article>
      <article class="panel">
        <h2>Runtime hardening</h2>
        <div class="status-list">${hardeningRows}</div>
      </article>
      <article class="panel wide">
        <h2>Providerless enrichment gate</h2>
        <p>${escapeHtml(buildPlan.recommendation)}</p>
        <table><thead><tr><th>Field</th><th>Rep pain</th><th>Coverage</th><th>Decision</th><th>Paid-provider trigger</th></tr></thead><tbody>${fieldRows}</tbody></table>
      </article>
      <article class="panel wide">
        <h2>Install boundary</h2>
        <ul>
          <li>Public website only needs the async widget script after the beta domain is allowlisted.</li>
          <li>Visitor chat and fallback submission require explicit consent before a lead profile is created.</li>
          <li>Rep-ready profiles, CRM handoffs, beta reports, tenant data export, and deletion controls stay behind admin authentication.</li>
          <li>Live CRM sync, email webhooks, OpenAI extraction, and paid enrichment remain optional configuration choices for the beta.</li>
        </ul>
      </article>
    </section>
    <div class="footer">
      <span>Public security center: no operator forms, no protected exports, no real beta profile exposure.</span>
      <span>Trust: ${escapeHtml(trust.status_label)} · Hardening: ${escapeHtml(humanizeEnum(hardening.status))} · Readiness: ${escapeHtml(humanizeEnum(readiness.status))}</span>
    </div>
  </main>
</body>
</html>`;
}

function publicSampleLead() {
  return allLeadsSorted().find((lead) => lead.demo_scenario_id === MID_MARKET_DEMO_SCENARIO_ID || lead.source?.demo_scenario_id === MID_MARKET_DEMO_SCENARIO_ID) || null;
}

function renderSampleProfilePage(baseUrl = "") {
  const lead = publicSampleLead();
  const readiness = midMarketReadinessSummary(baseUrl, new URLSearchParams([["days", "14"]]));
  const hardening = productionHardeningSummary();

  if (!lead) {
    return sampleProfileShell(
      `<section class="sample-empty">
        <h1>Sample rep-ready buyer profile</h1>
        <p>The public sample room is waiting for marked demo data. Load the mid-market demo scenario from the protected readiness room, or start a live buyer-profile chat from the homepage.</p>
        <div class="actions"><a class="button" href="/">Open buyer demo</a></div>
      </section>`,
      { readiness, hardening }
    );
  }

  const brief = buildRepReadyBrief(lead, baseUrl);
  const committeeRows = brief.buyer_profile.buying_committee.length
    ? brief.buyer_profile.buying_committee
        .map((item) => `<li><b>${escapeHtml(item.title || item.role || item.value || "Stakeholder")}</b><span>${escapeHtml(item.reason || item.source || "Likely stakeholder")}</span></li>`)
        .join("")
    : `<li><b>No committee captured yet</b><span>The widget will keep asking for missing buying-context fields.</span></li>`;
  const triggerRows = brief.buyer_profile.buying_triggers.length
    ? brief.buyer_profile.buying_triggers.map((item) => `<li>${escapeHtml(item.value || item.title || "Trigger captured")}</li>`).join("")
    : `<li>No buying triggers captured yet.</li>`;
  const evidenceRows = brief.evidence.research_evidence.length
    ? brief.evidence.research_evidence
        .map((item) => `<li><b>${escapeHtml(item.label || item.source_label || "Evidence")}</b><span>${escapeHtml(item.value || "")}</span></li>`)
        .join("")
    : `<li><b>Providerless evidence</b><span>Company memory, website signals, and operator-sourced evidence appear here.</span></li>`;
  const callPlanRows = brief.call_plan.map((item, index) => `<li><b>${index + 1}. ${escapeHtml(item)}</b></li>`).join("");
  const questionRows = brief.discovery_questions.map((item) => `<li>${escapeHtml(item)}</li>`).join("");
  const flags = brief.quality_flags.length ? brief.quality_flags.map((item) => `<li>${escapeHtml(item)}</li>`).join("") : `<li>No quality flags open.</li>`;
  const techStack = brief.evidence.tech_stack.length ? brief.evidence.tech_stack.join(", ") : "No tech stack detected yet";
  const paidProvider = brief.evidence.paid_provider_used ? "Yes" : "No";
  const expectedValue = `$${Math.round(Number(brief.outcome.expected_value || 0)).toLocaleString("en-US")}`;

  return sampleProfileShell(
    `<section class="hero-card">
      <div>
        <div class="eyebrow">Public sample output</div>
        <h1>What your rep sees before the first touch</h1>
        <p>${escapeHtml(brief.executive_summary)}</p>
        <div class="actions">
          <a class="button" href="/">Try the intake widget</a>
          <a class="button secondary" href="#call-plan">Review call plan</a>
        </div>
      </div>
      <aside class="profile-summary">
        <span>Priority</span>
        <b>${escapeHtml(humanizeEnum(brief.priority.level))} · ${brief.priority.score}/100</b>
        <span>Owner</span>
        <b>${escapeHtml(brief.owner.email || "Unassigned")}</b>
        <span>Expected value</span>
        <b>${escapeHtml(expectedValue)}</b>
      </aside>
    </section>
    <section class="metrics-grid">
      <div class="metric"><span>Contact</span><b>${escapeHtml(brief.contact.name || "Unknown")}</b><small>${escapeHtml(brief.contact.email || "No email")}</small></div>
      <div class="metric"><span>Company</span><b>${escapeHtml(brief.company.name || brief.company.domain || "Unknown")}</b><small>${escapeHtml(brief.company.domain || "No domain")}</small></div>
      <div class="metric"><span>Timeline</span><b>${escapeHtml(brief.qualification.timeline_label)}</b><small>${escapeHtml(brief.qualification.business_need)}</small></div>
      <div class="metric"><span>Paid provider used</span><b>${escapeHtml(paidProvider)}</b><small>${Math.round(brief.evidence.confidence * 100)}% confidence</small></div>
    </section>
    <section class="detail-grid">
      <article class="panel wide" id="call-plan">
        <h2>Call plan</h2>
        <ol>${callPlanRows}</ol>
      </article>
      <article class="panel">
        <h2>Opening angle</h2>
        <p>${escapeHtml(brief.buyer_profile.opening_angle || brief.call_plan[1] || "Confirm pain, urgency, and next step.")}</p>
      </article>
      <article class="panel">
        <h2>CRM context</h2>
        <dl>
          <dt>CRM</dt><dd>${escapeHtml(brief.qualification.crm_label)}</dd>
          <dt>Budget</dt><dd>${escapeHtml(brief.qualification.budget_label)} · ${escapeHtml(humanizeEnum(brief.qualification.budget_range))}</dd>
          <dt>Authority</dt><dd>${escapeHtml(humanizeEnum(brief.qualification.authority_signal))}</dd>
          <dt>Tech stack</dt><dd>${escapeHtml(techStack)}</dd>
        </dl>
      </article>
      <article class="panel">
        <h2>Likely buying committee</h2>
        <ul class="signal-list">${committeeRows}</ul>
      </article>
      <article class="panel">
        <h2>Buying triggers</h2>
        <ul>${triggerRows}</ul>
      </article>
      <article class="panel wide">
        <h2>Providerless evidence</h2>
        <ul class="signal-list">${evidenceRows}</ul>
      </article>
      <article class="panel">
        <h2>Discovery questions</h2>
        <ul>${questionRows}</ul>
      </article>
      <article class="panel">
        <h2>Quality flags</h2>
        <ul>${flags}</ul>
      </article>
      <article class="panel wide">
        <h2>Copy block</h2>
        <p>${escapeHtml(brief.copy_blocks.email_opener)}</p>
      </article>
    </section>
    <section class="disclosure">
      This is a marked synthetic demo profile from the mid-market buyer scenario. Real beta profiles remain protected in the operator CRM.
    </section>`,
    { readiness, hardening }
  );
}

