function readinessCheckClass(status) {
  if (status === "pass") return "healthy";
  if (status === "warning") return "warning";
  return "blocked";
}

function liveProofGateClass(status) {
  if (status === "ready") return "healthy";
  if (status === "ready_with_disclosures") return "warning";
  return "blocked";
}

function formatProofComparison(comparison) {
  if (!comparison || comparison.status === "unavailable") return "Needs baseline";
  if (comparison.unit === "rate") {
    return `${formatRate(comparison.current)} vs ${formatRate(comparison.baseline)} (${formatSignedPoints(comparison.delta_points)})`;
  }
  return `${formatMinutes(comparison.current)} vs ${formatMinutes(comparison.baseline)} (${formatSignedMinutes(-comparison.delta)} saved)`;
}

function formatRate(value) {
  if (value === null || value === undefined) return "-";
  return `${roundNumber(Number(value) * 100, 1)}%`;
}

function formatSignedPoints(value) {
  if (value === null || value === undefined) return "-";
  const prefix = Number(value) > 0 ? "+" : "";
  return `${prefix}${roundNumber(value, 1)} pts`;
}

function formatMinutes(value) {
  if (value === null || value === undefined) return "-";
  return `${roundNumber(value, 1)}m`;
}

function formatSignedMinutes(value) {
  if (value === null || value === undefined) return "-";
  const prefix = Number(value) > 0 ? "+" : "";
  return `${prefix}${roundNumber(value, 1)}m`;
}

function formatTrendValue(metric, value) {
  if (value === null || value === undefined) return "-";
  if (["paid_provider_spend", "opportunity_value", "expected_value", "closed_won_value"].includes(metric)) return `$${Number(value || 0).toFixed(2)}`;
  if (["average_minutes_to_first_contact", "average_minutes_to_meeting"].includes(metric)) return `${value}m`;
  return String(value);
}

function formatTrendDelta(metric, delta) {
  if (delta === null || delta === undefined) return "-";
  const prefix = Number(delta) > 0 ? "+" : "";
  if (["paid_provider_spend", "opportunity_value", "expected_value", "closed_won_value"].includes(metric)) return `${prefix}$${Number(delta || 0).toFixed(2)}`;
  if (["average_minutes_to_first_contact", "average_minutes_to_meeting"].includes(metric)) return `${prefix}${delta}m`;
  return `${prefix}${delta}`;
}

function renderCrmMetrics(analytics) {
  return `<section class="metrics-grid">
    <div class="metric-card"><span>Total leads</span><b>${analytics.total}</b></div>
    <div class="metric-card urgent"><span>Overdue</span><b>${analytics.by_sla.overdue}</b></div>
    <div class="metric-card soon"><span>Due soon</span><b>${analytics.by_sla.due_soon}</b></div>
    <div class="metric-card"><span>Open</span><b>${analytics.open}</b></div>
    <div class="metric-card"><span>High priority</span><b>${analytics.by_priority.high}</b></div>
    <div class="metric-card"><span>Meetings</span><b>${analytics.conversion.meeting_booked}</b></div>
    <div class="metric-card"><span>Opportunities</span><b>${analytics.conversion.opportunities_created}</b></div>
    <div class="metric-card"><span>Pipeline value</span><b>$${Number(analytics.pipeline.opportunity_value || 0).toFixed(0)}</b></div>
    <div class="metric-card"><span>Expected value</span><b>$${Number(analytics.pipeline.expected_value || 0).toFixed(0)}</b></div>
    <div class="metric-card"><span>Closed won</span><b>${analytics.conversion.closed_won}</b></div>
    <div class="metric-card"><span>Avg first touch</span><b>${analytics.response.average_minutes_to_first_contact ?? "-"}m</b></div>
    <div class="metric-card"><span>Avg meeting</span><b>${analytics.response.average_minutes_to_meeting ?? "-"}m</b></div>
  </section>`;
}

