function filterOption(value, label, selected) {
  return `<option value="${escapeHtml(value)}" ${value === selected ? "selected" : ""}>${escapeHtml(label)}</option>`;
}

function enrichmentReviewStatusOptions(selected) {
  return ENRICHMENT_REVIEW_STATUSES.filter((status) => status !== "not_needed")
    .map((status) => filterOption(status, ENRICHMENT_REVIEW_LABELS[status], selected))
    .join("");
}

function betaReportApiHref(report, format = "") {
  const base = report.beta_client
    ? `/api/v1/beta-clients/${encodeURIComponent(report.beta_client.id)}/report`
    : "/api/v1/reports/beta-summary";
  const params = new URLSearchParams({ days: String(report.period.days) });
  if (format) params.set("format", format);
  return `${base}?${params.toString()}`;
}

