function publicInstallStatusClass(status) {
  if (status === "pass" || status === "ready") return "healthy";
  if (status === "blocker" || status === "needs_attention") return "blocked";
  return "warning";
}

function renderPublicInstallStatusPanel(status) {
  const stepRows = status.steps
    .map(
      (step) => `<div class="status-row" data-status-step="${escapeHtml(step.key)}">
        <span><b>${escapeHtml(step.label)}</b><br><span class="mini" data-status-detail="${escapeHtml(step.key)}">${escapeHtml(step.detail)}</span></span>
        <span class="risk ${escapeHtml(publicInstallStatusClass(step.status))}" data-status-state="${escapeHtml(step.key)}">${escapeHtml(step.status_label)}</span>
      </div>`
    )
    .join("");
  const nextRows = status.next_actions.map((action) => `<li>${escapeHtml(action)}</li>`).join("");
  return `<section class="card wide" data-public-install-status>
    <div class="workflow-header">
      <div>
        <h2>Public install status</h2>
        <p>Buyer-safe proof that the beta widget loads, starts sessions, captures profiles, and gets rep feedback without exposing protected CRM data.</p>
      </div>
      <span class="risk ${escapeHtml(publicInstallStatusClass(status.status))}" data-status-overall>${escapeHtml(status.status_label)}</span>
    </div>
    <div class="workflow-summary">
      <div><span>Client-domain loads</span><b data-status-metric="client_page_config_loads">${status.install_activity.client_page_config_loads}</b></div>
      <div><span>Hosted/test loads</span><b data-status-metric="hosted_config_loads">${status.install_activity.hosted_config_loads}</b></div>
      <div><span>Sessions</span><b data-status-metric="session_starts">${status.install_activity.session_starts}</b></div>
      <div><span>Buyer profiles</span><b data-status-metric="buyer_profiles">${status.buyer_profiles.count}</b></div>
    </div>
    <div class="status-list">${stepRows}</div>
    <h3>Next public actions</h3>
    <ul class="signals" data-status-next-actions>${nextRows || "<li>No public install actions are open.</li>"}</ul>
    <p class="mini">This status endpoint returns counts, timestamps, and setup state only. It does not expose lead IDs, CRM profile links, reports, operator actions, tenant exports, or live CRM controls.</p>
  </section>`;
}

function renderPublicInstallStatusScript(statusUrl) {
  return `<script>
(() => {
  const statusUrl = ${JSON.stringify(statusUrl)};
  const statusClass = (status) => {
    if (status === "pass" || status === "ready") return "risk healthy";
    if (status === "blocker" || status === "needs_attention") return "risk blocked";
    return "risk warning";
  };
  const setText = (selector, value) => {
    const node = document.querySelector(selector);
    if (node) node.textContent = value == null || value === "" ? "-" : String(value);
  };
  const refresh = async () => {
    try {
      const response = await fetch(statusUrl);
      if (!response.ok) return;
      const status = await response.json();
      setText('[data-status-metric="client_page_config_loads"]', status.install_activity?.client_page_config_loads ?? 0);
      setText('[data-status-metric="hosted_config_loads"]', status.install_activity?.hosted_config_loads ?? 0);
      setText('[data-status-metric="session_starts"]', status.install_activity?.session_starts ?? 0);
      setText('[data-status-metric="buyer_profiles"]', status.buyer_profiles?.count ?? 0);
      setText('[data-status-metric="rep_reviews"]', status.rep_feedback?.reviewed_profiles ?? 0);
      const overall = document.querySelector("[data-status-overall]");
      if (overall) {
        overall.textContent = status.status_label || "Waiting";
        overall.className = statusClass(status.status);
      }
      for (const step of status.steps || []) {
        const detail = document.querySelector('[data-status-detail="' + step.key + '"]');
        const state = document.querySelector('[data-status-state="' + step.key + '"]');
        if (detail) detail.textContent = step.detail || "";
        if (state) {
          state.textContent = step.status_label || step.status || "";
          state.className = statusClass(step.status);
        }
      }
      const next = document.querySelector("[data-status-next-actions]");
      if (next) {
        const actions = status.next_actions?.length ? status.next_actions : ["No public install actions are open."];
        next.innerHTML = "";
        for (const action of actions) {
          const item = document.createElement("li");
          item.textContent = action;
          next.appendChild(item);
        }
      }
    } catch {
      // Public status refresh is best-effort; the static page remains usable.
    }
  };
  window.setTimeout(refresh, 900);
  window.setInterval(refresh, 5000);
})();
</script>`;
}

function renderPublicRepFeedbackRoom(client, baseUrl, options = {}) {
  const detail = betaClientDetail(client, baseUrl);
  const leads = allLeadsSorted().filter((lead) => lead.source?.beta_client_id === detail.id);
  const feedback = leadAnalytics(leads).rep_feedback;
  const submittedLead = options.submitted ? leads.find((lead) => lead.id === options.submitted) : null;
  const submittedBanner = submittedLead
    ? `<div class="banner ok">Feedback saved for ${escapeHtml(submittedLead.contact?.name || submittedLead.company?.name || submittedLead.id)}.</div>`
    : "";
  const errorBanner = options.error ? `<div class="banner err">${escapeHtml(options.error)}</div>` : "";
  const leadCards = leads.map((lead) => renderPublicRepFeedbackLeadCard(detail, lead)).join("");

  return crmShell(
    `${detail.name} rep feedback`,
    `<div class="toolbar">
      <div>
        <h1>Deal Threads rep feedback room</h1>
        <p>${escapeHtml(detail.name)} · ${escapeHtml(detail.domain || "No domain configured")}</p>
      </div>
      <div><a href="/">Deal Threads</a></div>
    </div>
    ${submittedBanner}
    ${errorBanner}
    <section class="metrics-grid">
      <div class="metric-card"><span>Buyer profiles</span><b>${leads.length}</b></div>
      <div class="metric-card"><span>Reviewed</span><b>${feedback.reviewed_profiles}</b></div>
      <div class="metric-card"><span>Helpful</span><b>${feedback.helpful_profiles}</b></div>
      <div class="metric-card"><span>Avg usefulness</span><b>${feedback.average_usefulness_score ?? "-"}/5</b></div>
    </section>
    <section class="card wide">
      <h2>Score profile usefulness</h2>
      <p>This tokenized room lets reps score buyer profiles captured for ${escapeHtml(detail.name)}. It updates the protected proof dashboard and helps decide whether the conversation flow needs better questions before any paid enrichment provider is added.</p>
      <p><a href="${escapeHtml(detail.public_crm_export_url)}">Download manual CRM CSV</a> · <a href="${escapeHtml(
        detail.public_crm_export_markdown_url
      )}">Open CRM import notes</a> · <a href="${escapeHtml(detail.public_beta_proof_url)}">Open beta proof report</a></p>
      <p class="mini">This page does not expose protected CRM profile links, operator controls, reports, tenant data exports, or live CRM actions.</p>
    </section>
    <div class="detail-grid">
      ${
        leadCards ||
        `<section class="card wide">
          <h2>No beta buyer profiles yet</h2>
          <p>Once the client-specific widget captures a test or live buyer profile, reps can score it here without needing operator access.</p>
        </section>`
      }
    </div>`
  );
}

function renderPublicRepFeedbackLeadCard(client, lead) {
  const feedback = ensureRepFeedback(lead);
  const statusOptions = REP_FEEDBACK_STATUSES.map(
    (status) => `<option value="${escapeHtml(status)}" ${status === feedback.status ? "selected" : ""}>${escapeHtml(REP_FEEDBACK_LABELS[status])}</option>`
  ).join("");
  const confidenceOptions = REP_CONFIDENCE_LEVELS.map(
    (level) => `<option value="${escapeHtml(level)}" ${level === feedback.rep_confidence ? "selected" : ""}>${escapeHtml(REP_CONFIDENCE_LABELS[level])}</option>`
  ).join("");
  const missingFieldControls = REP_FEEDBACK_MISSING_FIELDS.map(
    ([key, label]) =>
      `<label><input type="checkbox" name="missingField_${escapeHtml(key)}" value="true" ${feedback.missing_fields.includes(key) ? "checked" : ""}> ${escapeHtml(label)}</label>`
  ).join("");
  const score = Number(lead.score?.total || lead.score?.icp_fit || 0);
  const priority = lead.score?.priority || "unknown";
  const statusClass = priority === "high" ? "high" : priority === "medium" ? "medium" : "low";
  const contact = [lead.contact?.name, lead.contact?.email].filter(Boolean).join(" · ") || "No contact captured";
  const company = lead.company?.name || lead.company?.domain || "Unknown company";
  const domain = lead.company?.domain || normalizeDomain(lead.company?.website || lead.contact?.email || "");
  const handoffUrl = publicBetaLeadHandoffUrl(client, lead, "");
  return `<section class="card wide" id="${escapeHtml(lead.id)}">
    <div class="workflow-header">
      <div>
        <h2>${escapeHtml(company)}</h2>
        <p>${escapeHtml(contact)} · ${escapeHtml(formatDateTime(lead.created_at))}</p>
      </div>
      <div class="score ${escapeHtml(statusClass)}"><b>${score}</b><span>${escapeHtml(priority)}</span></div>
    </div>
    <dl>
      <dt>Domain</dt><dd>${escapeHtml(domain || "Unknown")}</dd>
      <dt>Need</dt><dd>${escapeHtml(lead.qualification?.business_need || "Not captured")}</dd>
      <dt>Timeline</dt><dd>${escapeHtml(humanizeEnum(lead.qualification?.timeline || "unknown"))}</dd>
      <dt>Budget</dt><dd>${escapeHtml(humanizeEnum(lead.qualification?.budget_status || "unknown"))} / ${escapeHtml(humanizeEnum(lead.qualification?.budget_range || "unknown"))}</dd>
      <dt>CRM</dt><dd>${escapeHtml(displayCrm(lead.qualification?.crm || client.crm || "unknown"))}</dd>
      <dt>Owner</dt><dd>${escapeHtml(lead.routing?.assigned_owner_email || "Unassigned")}</dd>
    </dl>
    <p class="mini"><a href="${escapeHtml(handoffUrl)}">Open rep handoff packet</a> · <a href="${escapeHtml(`${handoffUrl}?format=markdown`)}">Download Markdown</a></p>
    <form class="workflow-form" method="POST" action="/feedback/${escapeHtml(client.handoff_token)}/${escapeHtml(lead.id)}">
      <label>Reviewer name or email</label>
      <input name="reviewerName" value="${escapeHtml(feedback.reviewed_by?.replace(/^customer_rep:/, "") || "")}" placeholder="Alex from sales">
      <label>Profile usefulness</label>
      <select name="status">${statusOptions}</select>
      <label>Usefulness score</label>
      <input name="usefulnessScore" type="number" min="0" max="5" step="0.5" value="${escapeHtml(feedback.usefulness_score ?? "")}" placeholder="4">
      <label>Rep confidence</label>
      <select name="repConfidence">${confidenceOptions}</select>
      <label><input type="checkbox" name="usedOnCall" value="true" ${feedback.used_on_call ? "checked" : ""}> Used this profile on the first call</label>
      <div class="check-grid">${missingFieldControls}</div>
      <label>Missing context or follow-up note</label>
      <textarea name="missingContextNote" placeholder="What was missing, misleading, or useful before the rep followed up?">${escapeHtml(
        feedback.missing_context_note || ""
      )}</textarea>
      <button type="submit">Save profile feedback</button>
    </form>
  </section>`;
}

