function validatePublicProspectConfirmation(lead, body = {}) {
  const targetPageUrl = stringFromBody(body, "targetPageUrl", "target_page_url", "testedPageUrl", "tested_page_url");
  const implementationOwnerEmail = stringFromBody(body, "implementationOwnerEmail", "implementation_owner_email");
  const crmOwnerEmail = stringFromBody(body, "crmOwnerEmail", "crm_owner_email");
  const routingOwnerEmail = stringFromBody(body, "routingOwnerEmail", "routing_owner_email");
  const reportRecipients = normalizeOptionalList(firstDefined(body, "reportRecipients", "report_recipients")) || [];
  if (!targetPageUrl || !implementationOwnerEmail || !crmOwnerEmail || !routingOwnerEmail || !reportRecipients.length) {
    return "Target page, implementation owner email, CRM owner email, routing owner email, and report recipients are required.";
  }
  const normalizedUrl = normalizeWebsiteUrl(targetPageUrl);
  const expectedDomain = betaClientConversionDomain(lead);
  const targetDomain = normalizeDomain(normalizedUrl);
  if (expectedDomain && (!targetDomain || (targetDomain !== expectedDomain && !targetDomain.endsWith(`.${expectedDomain}`)))) {
    return `Use a page on ${expectedDomain} so the pilot install matches the buyer domain.`;
  }
  return "";
}

function validatePublicProspectConfirmationProgress(lead, body = {}) {
  const targetPageUrl = stringFromBody(body, "targetPageUrl", "target_page_url", "testedPageUrl", "tested_page_url");
  if (!targetPageUrl) return "";
  const normalizedUrl = normalizeWebsiteUrl(targetPageUrl);
  const expectedDomain = betaClientConversionDomain(lead);
  const targetDomain = normalizeDomain(normalizedUrl);
  if (expectedDomain && (!targetDomain || (targetDomain !== expectedDomain && !targetDomain.endsWith(`.${expectedDomain}`)))) {
    return `Use a page on ${expectedDomain} so the pilot install matches the buyer domain.`;
  }
  return "";
}

